def _sensitive_takeover_message(entry_surface: Any) -> str:
    """The direct-entry handoff text for the surface whose control needs the value."""
    if str(entry_surface or "").strip().lower() == "desktop":
        return _SENSITIVE_DESKTOP_TAKEOVER_MESSAGE
    return _SENSITIVE_BROWSER_TAKEOVER_MESSAGE


def _value_free_diagnostic(text: Any, value: Any) -> str:
    """A classifier's own words, kept for diagnosis only when they cannot carry the typed value.

    Separators are ignored and any 5-character run of the value found in the text drops the text
    entirely (fail closed): a paraphrase that quotes part of a value is never retained.
    """
    trimmed = _safe_trim(text, 600)
    if not trimmed:
        return ""
    probe = re.sub(r"[\s\-_.:/]", "", str(value or "")).casefold()
    if not probe:
        return trimmed
    folded = re.sub(r"[\s\-_.:/]", "", trimmed).casefold()
    window = min(len(probe), 5)
    if any(probe[index:index + window] in folded for index in range(0, len(probe) - window + 1)):
        return ""
    return trimmed
