class _ReadinessAuditSkipped(Exception):
    """Internal control flow: a generic task carries no application completeness audit."""


class _RunCancelled(Exception):
    """Raised internally when a live run is interrupted while a phase is in progress."""


@contextmanager
def final_action_lifecycle_guard():
    """Serialize final-action claim against in-process lifecycle cancellation."""
    with _FINAL_ACTION_CLAIM_LOCK:
        yield


def final_action_execution_in_progress(run: Any) -> bool:
    state = dict(getattr(run, "confidence_state", None) or {})
    pending = dict(state.get(_PENDING_FINAL_ACTION_KEY) or {})
    return str(pending.get("status") or "") == "executing"


_PLAN_OPEN_MARK = re.compile(r"^\s*(?:[-*]\s*)?(?:\d+[.)]\s*)?\[(?:\s?|now|todo|open|next)\]", re.IGNORECASE)


def _plan_open_items(plan: str) -> list[str]:
    """The lines of the brain's plan it marked open ("[ ]" or "[now]", the convention the plan field
    asks for). Unmarked lines are not counted: only the brain says what is open."""
    return [line.strip() for line in str(plan or "").splitlines() if _PLAN_OPEN_MARK.match(line)]


def _redact_otp_text(text: str) -> str:
    try:
        from app.security import redact_otp_codes

        return str(redact_otp_codes(text))
    except Exception:  # noqa: BLE001 - nothing stored rather than an unscrubbed copy
        return ""


def _exception_summary(exc: BaseException) -> str:
    """Return a non-empty, compact exception description for run state and events."""
    message = str(exc).strip()
    if message:
        return f"{type(exc).__name__}: {message}"
    rendered = "".join(traceback.format_exception_only(type(exc), exc)).strip()
    return rendered or type(exc).__name__


def _discard_late_task_result(completed: asyncio.Future[Any]) -> None:
    """Drain an abandoned read-only worker without allowing its late result to affect the run."""

    try:
        completed.exception()
    except asyncio.CancelledError:
        pass
    except Exception:
        pass


async def _await_with_progress(
    awaitable: Awaitable[Any],
    *,
    narrate: Callable[[str, dict[str, Any]], Awaitable[None]],
    kind: str,
    data: dict[str, Any],
    timeout_seconds: float,
    should_cancel: Callable[[], bool | str | None] | None = None,
) -> Any:
    """Await a browser/model phase with visible heartbeats and a hard time bound.

    The body/brain contract stays generic: this only reports liveness and prevents a run from sitting
    silently in RUNNING forever when Chrome, the extension transport, or the model call stalls.
    """
    started = time.monotonic()
    task = asyncio.ensure_future(awaitable)
    try:
        await narrate(kind, {**data, "elapsed_seconds": 0})
        while True:
            interruption = await _interruption_requested(should_cancel)
            if interruption:
                task.cancel()
                raise _RunCancelled(interruption)
            elapsed = time.monotonic() - started
            remaining = timeout_seconds - elapsed
            if remaining <= 0:
                task.cancel()
                raise asyncio.TimeoutError(f"{kind} timed out after {timeout_seconds:.0f}s")
            try:
                return await asyncio.wait_for(asyncio.shield(task), timeout=min(_HEARTBEAT_INTERVAL_SECONDS, remaining))
            except asyncio.TimeoutError:
                if task.done():
                    return await task
                elapsed = time.monotonic() - started
                if elapsed >= timeout_seconds:
                    task.cancel()
                    raise asyncio.TimeoutError(f"{kind} timed out after {timeout_seconds:.0f}s")
                interruption = await _interruption_requested(should_cancel)
                if interruption:
                    task.cancel()
                    raise _RunCancelled(interruption)
                await narrate(kind, {**data, "elapsed_seconds": int(elapsed)})
    except asyncio.CancelledError:
        # An outside cancel (the stall watchdog, shutdown) only reaches the shield above; without this
        # the body call it wraps kept running and could finish a click after the run had ended. A
        # caller that must let its worker finish passes its own shield and a discard callback.
        task.cancel()
        raise


async def _navigate_with_progress(
    body: Any,
    url: str | None,
    narrate: Callable[[str, dict[str, Any]], Awaitable[None]],
    *,
    should_cancel: Callable[[], bool | str | None] | None = None,
) -> Any:
    return await _await_with_progress(
        body.navigate(url),
        narrate=narrate,
        kind="browser_wait",
        data={"summary": "Waiting for the page to open.", "action": "navigate"},
        timeout_seconds=_BODY_NAVIGATE_TIMEOUT_SECONDS,
        should_cancel=should_cancel,
    )


def _native_dialog_in_shot(shot: dict[str, Any] | None) -> dict[str, Any]:
    """The browser dialog the body reported open over this observation, if any (raw fields)."""
    if not isinstance(shot, dict):
        return {}
    raw = shot.get("native_dialog")
    if not isinstance(raw, dict):
        evidence = shot.get("page_evidence")
        raw = evidence.get("native_dialog") if isinstance(evidence, dict) else None
    if not isinstance(raw, dict) or not raw.get("type"):
        return {}
    return {
        "type": _safe_trim(raw.get("type"), 24),
        "message": _safe_trim(raw.get("message"), 600),
        "default_prompt": _safe_trim(raw.get("default_prompt"), 200),
    }


# A drag's waypoints are bounded at 40 by the action schema and the bodies; its route adds the two
# ends. The step feedback shows at most this many of the route's points (ends always kept).
_DRAG_WAYPOINT_LIMIT = 40
_DRAG_ROUTE_FEEDBACK_MAX_POINTS = 12


def _drag_path_pairs(path: Any, *, limit: int = _DRAG_WAYPOINT_LIMIT) -> list[list[int]]:
    """A drag's waypoints as [x, y] pairs in the model's screenshot pixels, bounded."""
    pairs: list[list[int]] = []
    for point in (path if isinstance(path, list) else [])[: max(0, int(limit))]:
        if not isinstance(point, dict):
            continue
        try:
            pairs.append([int(point.get("x") or 0), int(point.get("y") or 0)])
        except (TypeError, ValueError):
            continue
    return pairs


def _drag_execution_receipt(
    body_route: list[tuple[int, int]],
    *,
    coord_scale: float,
    page_dpr: Any,
    result: dict[str, Any],
) -> dict[str, Any]:
    """What a drag did, in the model's screenshot pixels.

    The route is the press point, waypoints, and release point the body was sent (body pixels are
    model pixels * coord_scale). The browser body reports the distance it moved the held pointer in
    CSS pixels (body pixels / devicePixelRatio), so it is converted back the same way.
    """
    scale = float(coord_scale or 1.0) or 1.0
    receipt: dict[str, Any] = {
        "drag_route": [
            [int(round(float(x) / scale)), int(round(float(y) / scale))]
            for x, y in body_route[: _DRAG_WAYPOINT_LIMIT + 2]
        ]
    }
    distance = result.get("drag_distance_px")
    if isinstance(distance, (int, float)) and not isinstance(distance, bool) and math.isfinite(float(distance)):
        try:
            dpr = float(page_dpr or 1.0)
        except (TypeError, ValueError):
            dpr = 1.0
        if not math.isfinite(dpr) or dpr <= 0:
            dpr = 1.0
        receipt["drag_distance_model_px"] = max(0, int(round(float(distance) * dpr / scale)))
    return receipt


def _drag_trace_hint(result: dict[str, Any]) -> str:
    """The executed drag in the brain's own frame: its route, the elements under the press and the
    release, and how far the pointer moved. Raw execution facts; whether it hit is the brain's call."""
    route = [
        point
        for point in (result.get("drag_route") if isinstance(result.get("drag_route"), list) else [])
        if isinstance(point, (list, tuple))
        and len(point) == 2
        and all(isinstance(axis, int) and not isinstance(axis, bool) for axis in point)
    ]
    if len(route) < 2:
        return ""
    shown = route
    if len(route) > _DRAG_ROUTE_FEEDBACK_MAX_POINTS:
        stride = (len(route) - 1) / (_DRAG_ROUTE_FEEDBACK_MAX_POINTS - 1)
        shown = [route[int(round(index * stride))] for index in range(_DRAG_ROUTE_FEEDBACK_MAX_POINTS)]
    text = "pointer route in screenshot pixels " + " -> ".join(
        f"({int(point[0])},{int(point[1])})" for point in shown
    )
    if len(shown) < len(route):
        text += f" ({len(shown)} of {len(route)} points shown)"
    from_tag = _safe_trim(result.get("drag_from_tag"), 24).lower()
    to_tag = _safe_trim(result.get("drag_to_tag"), 24).lower()
    if from_tag or to_tag:
        text += f"; pressed on <{from_tag or '?'}>, released on <{to_tag or '?'}>"
    distance = result.get("drag_distance_model_px")
    if isinstance(distance, int) and not isinstance(distance, bool):
        text += f"; the held pointer moved {distance}px"
    if result.get("native_drag_intercepted") is True:
        text += "; the page started a native drag-and-drop, dropped at the release point"
    return text


_OPEN_FILE_REFUSAL_HINTS = {
    "open_file_not_downloaded": "file not opened (open_file_not_downloaded): target is not the exact path of a file in downloads",
    "open_file_download_incomplete": (
        "file not opened (open_file_download_incomplete): it is still downloading; wait until downloads shows it complete"
    ),
    "open_file_type_not_allowed": (
        "file not opened (open_file_type_not_allowed): only documents and images open (pdf, txt, csv, json, xml, md, "
        "html, png, jpg, gif, webp, docx, xlsx, pptx, odt, ods); programs, scripts, shortcuts, and archives never do"
    ),
    "open_file_needs_desktop_surface": (
        "file not opened (open_file_needs_desktop_surface): the file opens as a window on the real screen; "
        "switch_surface target=desktop first"
    ),
    "read_download_not_downloaded": "file not read (read_download_not_downloaded): target is not a file in this run's downloads (use its listed name or exact path, or latest)",
    "read_download_incomplete": "file not read (read_download_incomplete): it is still downloading; wait until downloads shows it complete",
    "read_download_type_not_allowed": "file not read (read_download_type_not_allowed): only text files and PDF/DOCX documents read (txt, csv, json, md, xml, log, tsv, pdf, docx)",
    "read_download_unreadable": "file not read (read_download_unreadable): the file could not be read as text",
    "open_file_unavailable": "file not opened (open_file_unavailable): this run cannot open files on this computer",
}


def _vision_result_hint(result: dict[str, Any] | None) -> str:
    if not isinstance(result, dict):
        return ""
    parts: list[str] = []
    if result.get("action") == "watch":
        values = [item for item in (result.get("values") or []) if isinstance(item, dict)]
        if result.get("ok") and values:
            shown = " | ".join(
                f"{float(item.get('t_ms') or 0) / 1000:.1f}s {_safe_trim(item.get('text'), 60)!r}" for item in values[:60]
            )
            parts.append(
                f"watched for {float(result.get('watched_ms') or 0) / 1000:.1f}s: {len(values)} distinct value(s) in "
                f"order: {shown}"
            )
        elif not result.get("ok"):
            parts.append(f"watch failed ({_safe_trim(result.get('failure_reason'), 60) or 'unavailable'})")
    if result.get("clipboard_changed") is True:
        parts.append("the clipboard changed under this action (read_clipboard reads it)")
    if result.get("action") == "read_clipboard":
        if result.get("ok"):
            # The text itself rides only in clipboard_text (scrubbed of one-time codes), never in this line.
            parts.append(
                f"clipboard read: {int(result.get('chars') or 0)} characters, shown in clipboard_text"
                + (" (cut to the first part)" if result.get("truncated") else "")
            )
        else:
            parts.append(
                f"clipboard not read ({_safe_trim(result.get('failure_reason'), 60) or 'clipboard_unavailable'})"
            )
    if result.get("action") == "switch_surface":
        surface = str(result.get("surface") or "")
        if result.get("ok") and surface == "desktop":
            parts.append(
                "now on the desktop surface: the next screenshot is the real screen (every window and the "
                "browser's own UI), operated with the OS mouse and keyboard; switch_surface target=browser "
                "returns to page-precise control"
            )
        elif result.get("ok") and surface == "browser":
            parts.append("now on the browser surface: the next screenshot is the page itself")
        elif not result.get("ok"):
            parts.append(f"surface not switched ({_safe_trim(result.get('failure_reason'), 60) or 'unavailable'})")
    if result.get("action") == "select_text":
        # What the body actually selected, so a failed or partial selection is never taken for done.
        if result.get("ok") and result.get("mode") == "screen_text":
            # Found on screen by OCR and dragged across; pixels cannot say exactly what got selected.
            parts.append(
                f"dragged across the on-screen text {_safe_trim(result.get('selected_text'), 120)!r}, found by "
                "reading the screen"
                + (" (a word read one letter off)" if result.get("read_approximately") else "")
                + (
                    "; the screen changed there (check the highlight covers exactly that text)"
                    if result.get("highlight_changed")
                    else "; nothing changed on screen there, so it may not be selectable text"
                )
                + ("; the screen also changed elsewhere: check nothing moved" if result.get("changed_outside_text") else "")
            )
        elif result.get("ok"):
            parts.append(
                f"selected exactly {_safe_trim(result.get('selected_text'), 120)!r}"
                + (" in the field" if result.get("mode") == "field_selection" else "")
                + "; a type with at_caret=true replaces just this selection"
            )
        elif result.get("failure_reason") == "select_text_mismatch":
            parts.append(f"text selection came out as {_safe_trim(result.get('selected_text'), 120)!r}, not the text asked for")
        elif result.get("failure_reason") == "select_text_not_text":
            parts.append(
                f"text not selected: it is on a {_safe_trim(result.get('control_type'), 40) or 'control'} that a press "
                "would act on (open, drag, or toggle), not text to select"
            )
        elif result.get("mode") == "screen_text":
            parts.append(
                f"text not selected ({_safe_trim(result.get('failure_reason'), 60) or 'unavailable'}): no words "
                "read on screen near that point spell exactly that"
            )
        else:
            parts.append(
                f"text not selected ({_safe_trim(result.get('failure_reason'), 60) or 'unavailable'}): no visible "
                "page text or field value reads exactly that"
            )
    if result.get("action") == "read_download":
        if result.get("ok"):
            parts.append(
                f"downloaded file read: {int(result.get('chars') or 0)} characters, shown in downloaded_file_text"
                + (" (cut to the first part)" if result.get("truncated") else "")
            )
        else:
            parts.append(f"file not read ({_safe_trim(result.get('failure_reason'), 60) or 'unavailable'})")
    if result.get("action") == "read_print_view":
        if result.get("ok"):
            parts.append(
                f"print view read: {int(result.get('chars') or 0)} characters, shown in print_view_text"
                + (" (cut to the first part)" if result.get("truncated") else "")
            )
        else:
            parts.append(f"print view not read ({_safe_trim(result.get('failure_reason'), 60) or 'unavailable'})")
    if result.get("action") == "read_form":
        if result.get("ok"):
            parts.append(
                f"form read: {int(result.get('controls') or 0)} controls, shown in form_outline"
                + (" (cut to the first part)" if result.get("truncated") else "")
            )
        else:
            parts.append(f"form not read ({_safe_trim(result.get('failure_reason'), 60) or 'unavailable'})")
    if result.get("action") == "open_file":
        if result.get("ok"):
            title = _safe_trim(result.get("new_window_title"), 80)
            parts.append(
                f"opened {_safe_trim(result.get('opened_file'), 120)!r} in its default app"
                + (
                    f" in the new window {title!r}"
                    if title
                    else "; no new window appeared yet (it may have opened in a window that was already open, or be loading)"
                )
            )
        else:
            reason = str(result.get("failure_reason") or "")
            parts.append(_OPEN_FILE_REFUSAL_HINTS.get(reason, f"file not opened ({_safe_trim(reason, 60) or 'unavailable'})"))
    drag_trace = _drag_trace_hint(result)
    if drag_trace:
        parts.append(drag_trace)
    if result.get("url_changed"):
        parts.append("page URL changed")
    elif result.get("title_changed"):
        parts.append("page title changed")
    if result.get("adopted_new_tab"):
        parts.append("followed new active tab")
    if result.get("action") == "navigate" and result.get("ok") and result.get("opened_new_tab"):
        parts.append("opened in a new tab of this task; the previous tab is unchanged in browser_tabs")
    if result.get("action") == "key" and int(result.get("presses") or 0) > 1:
        parts.append(f"pressed {int(result.get('presses') or 0)} times")
    if result.get("typed_where_caret_is"):
        parts.append(
            "typed where the caret was: that field exposes no readable value, so confirm the text in the "
            "screenshot"
        )
    if (
        isinstance(result.get("edited_line_after"), str)
        and result.get("active_value_matches_expected") is True
        and result.get("active_value_redacted") is not True
    ):
        # The selection was replaced exactly; the whole line still shows what was left around it (a character
        # outside the selection stays). A mismatch is reported by the type mismatch feedback instead.
        parts.append(
            f"edited line {str(result.get('edited_line_before') or '')[:160]!r} now reads "
            f"{str(result.get('edited_line_after'))[:160]!r}"
        )
    commit = _edit_commit_view(result) if result.get("action") == "key" else None
    if commit:
        editor = f" in the editor {commit['editor_hint']!r}" if commit.get("editor_hint") else ""
        if commit.get("editor_still_focused"):
            after = commit.get("editor_value_after", "")
            parts.append(
                f"{result.get('key')} pressed{editor}: the editor is still focused"
                + (
                    f" and still reads {after!r}; nothing was committed or left the field"
                    if after == commit["edit_value"]
                    else f" and now reads {after!r} (it held {commit['edit_value']!r} before)"
                )
            )
        elif commit.get("edit_value_visible_after") is True:
            parts.append(
                f"{result.get('key')} pressed{editor}: focus left the editor and its text {commit['edit_value']!r} "
                "is visible on the page (committed)"
            )
        elif commit.get("edit_value_visible_after") is False:
            parts.append(
                f"{result.get('key')} pressed{editor}: focus left the editor and its text {commit['edit_value']!r} "
                "is not visible on the page, so the edit may have been discarded or reformatted; check the cell"
            )
        else:
            parts.append(
                f"{result.get('key')} pressed{editor}: focus left the editor holding {commit['edit_value']!r}; "
                "whether it committed could not be read back, check the screenshot"
            )
    if result.get("action") == "key" and result.get("focus_changed"):
        parts.append("keyboard focus moved to another element")
    if result.get("action") == "key" and result.get("selection_changed"):
        parts.append(f"text selection changed ({int(result.get('selection_length') or 0)} characters selected)")
    caret = result.get("caret") if isinstance(result.get("caret"), dict) else {}
    if caret.get("line_text") is not None and "column" in caret:
        # A caret move barely changes the screen: say where the caret is, so a landed click is not
        # repeated and the next key or type starts from a known position.
        selected = int(caret.get("selection_length") or 0)
        selected_text = str(caret.get("selected_text") or "")[:80]
        parts.append(
            f"caret at column {int(caret.get('column') or 0)} of the line {_safe_trim(caret.get('line_text'), 160)!r}"
            + (
                (
                    f" with {selected} characters selected after it"
                    + (f" (exactly {selected_text!r})" if selected_text else "")
                    + " (typing in this document replaces just the "
                    "selection)"
                    if caret.get("document")
                    else f" with {selected} characters selected after it"
                    + (f" (exactly {selected_text!r})" if selected_text else "")
                    + " (type with at_caret=true replaces just "
                    "the selection; a plain type replaces the field's whole content)"
                )
                if selected
                else ""
            )
        )
    if result.get("surface_changed"):
        parts.append("visible page surface changed")
    if result.get("selection_committed"):
        selected = _safe_trim(result.get("selected_value"), 100)
        parts.append(f"choice committed{f' ({selected})' if selected else ''}")
    elif result.get("expansion_changed"):
        # A tab / disclosure header is activated, not chosen: report the state it now has.
        parts.append(
            "header now expanded" if str(result.get("target_expanded_after")) == "true" else "header now collapsed"
        )
    elif result.get("visual_observed_value") and result.get("visual_verification_status") == "failed":
        intended = _safe_trim(result.get("visual_intended_value"), 100)
        parts.append(
            f"visual read-back: the control shows {_safe_trim(result.get('visual_observed_value'), 100)!r}"
            + (f", not exactly the intended {intended!r}" if intended else "")
            + "; the value is not verified"
        )
    if result.get("failure_reason") == "control_not_at_resolved_point" and result.get("hit_tag"):
        hit_name = str(result.get("hit_tag"))
        if result.get("hit_id"):
            hit_name += "#" + _safe_trim(result.get("hit_id"), 40)
        elif result.get("hit_class"):
            hit_name += "." + _safe_trim(result.get("hit_class"), 60)
        hit_text = _safe_trim(result.get("hit_text"), 80)
        parts.append(
            "control_not_at_resolved_point: nothing was clicked; the point is covered by "
            + hit_name
            + (f" {hit_text!r}" if hit_text else "")
            + (" (covers the whole viewport)" if result.get("hit_covers_viewport") else " (a different control)")
        )
    if result.get("focus_unverified"):
        parts.append("this window does not report which control has keyboard focus; check on screen that the text landed")
    if result.get("failure_reason") == "type_focus_unverified":
        parts.append(
            "nothing was typed: this window does not say which control has keyboard focus, and your last click was "
            "not on the field you named; click that field, then type (both in one sequence)"
        )
    if result.get("failure_reason") == "type_focus_elsewhere":
        parts.append(
            "nothing was typed: keyboard focus is on another control, not at the point you named; click the field "
            "first (a dropdown or radio is set by clicking it and its option, not by typing)"
        )
    if result.get("failure_reason") == "label_elsewhere":
        point = result.get("label_point_model") or []
        parts.append(
            f"nothing was clicked: the label {_safe_trim(result.get('label_text'), 80)!r} is drawn on another control"
            + (f", at ({int(point[0])}, {int(point[1])}) in your screenshot" if len(point) == 2 else "")
            + ", not where you aimed; click it there if that is the option you mean"
        )
    elif result.get("label_bound") is True:
        parts.append(
            f"clicked on the label {_safe_trim(result.get('label_text'), 80)!r} of the control you aimed at; check it took"
        )
    elif result.get("label_bound") is False:
        parts.append(
            f"no single label reading exactly {_safe_trim(result.get('label_text'), 80)!r} near your point, so the click "
            "landed where you aimed"
        )
    if isinstance(result.get("wheel_keys_held"), list):
        held = [str(item).capitalize() for item in result.get("wheel_keys_held") or []]
        parts.append(
            f"the wheel turned with {'+'.join(held)} held" if held else "the wheel turned with no key held"
        )
    if result.get("scroll_changed"):
        before_position = result.get("before_scroll_position")
        after_position = result.get("scroll_position")
        if isinstance(before_position, (int, float)) and isinstance(after_position, (int, float)):
            # Raw distances, so the next scroll can be sized instead of guessed.
            in_container = result.get("scroll_target_kind") == "container"
            region = "scrollable region" if in_container else "page"
            direction = ""
            if result.get("scroll_axis") == "horizontal":
                direction = " right" if after_position >= before_position else " left"
            detail = f"{region} scrolled{direction} {int(before_position)}->{int(after_position)}px"
            # Which mechanism moved it: a wheel goes through the page's own wheel handlers, a
            # direct scroll (like dragging the scrollbar) does not.
            mechanism = {"wheel_scroll": " by the mouse wheel", "element_scroll": " directly, as by its scrollbar"}.get(
                str(result.get("mode") or ""), ""
            )
            total, shown = _scroll_axis_extent(result, in_container)
            if isinstance(total, (int, float)) and isinstance(shown, (int, float)) and total > 0:
                detail += f" of {int(total)}px ({int(shown)}px visible at once)"
            parts.append(detail + mechanism)
        else:
            parts.append("scroll position changed")
    elif result.get("scroll_attempted") and "scroll_changed" in result:
        # State where the region actually is: "did not move" at the top of a region with room
        # below means the scroll went the wrong way or was absorbed, not that it hit an end.
        in_container = result.get("scroll_target_kind") == "container"
        position = result.get("scroll_position")
        total, shown = _scroll_axis_extent(result, in_container)
        if all(isinstance(value, (int, float)) for value in (position, total, shown)) and total > 0 and shown > 0:
            where = "top" if position <= 0 else ("bottom" if position + shown >= total - 1 else "middle")
            region = "scrollable region" if in_container else "page"
            parts.append(
                f"scroll did not move: the {region} stays at {int(position)}px of {int(total)}px "
                f"({int(shown)}px visible), at its {where}"
            )
        else:
            parts.append("scroll did not move: that region is already at its end in that direction")
    if result.get("active_typable"):
        hint = str(result.get("active_hint") or result.get("active_tag") or "field").strip()
        parts.append(f"focused typable field{f' ({hint})' if hint else ''}")
        if result.get("active_has_value") and str(result.get("action") or "") != "type":
            # After a click it tells the brain the field was not empty; after a type it is only the
            # value just typed, and brains read it as a warning about pre-existing content.
            parts.append("field already has text")
        if _vision_result_control_invalid(result):
            parts.append("browser reports the control is invalid")
    elif result.get("active_tag"):
        parts.append(f"focused {str(result.get('active_tag'))[:24]}")
    if result.get("file_input_files_contains_filename") or result.get("page_filename_visible") or result.get("upload_success_text_visible") or result.get("observed_present"):
        target = _safe_trim(result.get("target_label") or result.get("upload_target_label") or "", 80)
        filename = _safe_trim(result.get("filename") or result.get("observed_filename") or "", 80)
        detail = f"document upload visible{f' in {target}' if target else ''}{f' file={filename}' if filename else ''}"
        parts.append(detail)
    if result.get("error"):
        parts.append(f"error: {str(result.get('error'))[:80]}")
    clipboard_events = result.get("clipboard_events")
    if isinstance(clipboard_events, list):
        for event in clipboard_events[:3]:
            if isinstance(event, dict) and event.get("type") in {"copy", "cut", "paste"}:
                length = event.get("selection_length")
                detail = f" ({int(length)} characters selected)" if isinstance(length, int) and event.get("type") != "paste" else ""
                parts.append(f"the page received a {event.get('type')} event{detail}")
    opened_dialog = result.get("native_dialog")
    if isinstance(opened_dialog, dict) and opened_dialog.get("type"):
        parts.append(
            f"a browser {_safe_trim(opened_dialog.get('type'), 24)} dialog is open: "
            f"{_safe_trim(opened_dialog.get('message'), 160)!r}"
        )
    answered_dialog = result.get("native_dialog_answered")
    if isinstance(answered_dialog, dict) and answered_dialog.get("type"):
        parts.append(
            f"browser {_safe_trim(answered_dialog.get('type'), 24)} dialog answered "
            f"{'OK' if answered_dialog.get('accepted') else 'Cancel'}"
        )
    if result.get("mode") == "keystrokes_to_focused_control" and result.get("ok"):
        parts.append(
            f"sent {int(result.get('keys_sent') or 0)} keystrokes to the focused "
            f"{_safe_trim(result.get('active_tag'), 24) or 'control'}; it has no field value to read back, "
            "so check the screenshot for what it shows"
        )
    if result.get("mode") == "scroll_to_text":
        if result.get("ok"):
            listed = [
                f"#{int(item.get('occurrence') or 0)} {_safe_trim(item.get('text'), 60)!r}"
                + (" (was already in view)" if item.get("in_view") else "")
                for item in (result.get("match_texts") or [])[:6]
                if isinstance(item, dict)
            ]
            parts.append(
                f"found the text {int(result.get('matches') or 0)} time(s)"
                + (f" [{'; '.join(listed)}]" if listed else "")
                + f"; brought match {int(result.get('occurrence') or 1)} into view"
                + ("" if result.get("in_view") else " (it is still outside the viewport)")
                + "; set amount to another occurrence number to bring that one into view instead"
            )
        elif result.get("failure_reason") == "scroll_text_not_found":
            parts.append("that exact text is not rendered anywhere on the page")
    options = result.get("select_options")
    if isinstance(options, list) and options:
        # The select's real options, so the next decision can name one exactly.
        listed = " | ".join(_safe_trim(option, 60) for option in options[:40] if str(option or "").strip())
        parts.append(f"this select's options: {listed[:600]}")
    failure = _safe_trim(result.get("failure_reason"), 80)
    if result.get("ok") is False and failure and not any(failure in part for part in parts):
        # A failed action says why: an OSWorld type of "Montreal" with an accent read only "FAIL" (the body
        # had said osworld_non_ascii_text_unsupported), and the brain could not tell what to change.
        detail = _safe_trim(result.get("failure_detail"), 200)
        parts.append(f"failed: {failure}" + (f" ({detail})" if detail else ""))
    return "; ".join(parts)


def _vision_result_control_invalid(result: dict[str, Any] | None) -> bool:
    """Read raw browser validation state without interpreting what the control means."""
    if not isinstance(result, dict):
        return False
    aria_invalid = str(result.get("active_aria_invalid") or "").strip().lower()
    return bool(
        aria_invalid == "true"
        or result.get("active_validity_valid") is False
    )


def _type_read_back_contradicts(action: dict[str, Any] | None, result: dict[str, Any]) -> bool:
    """A type whose field was actually read back and holds something other than the intended text.
    Surfaces that cannot read the field (a native rich-text editor: empty ``active_value`` with
    ``value_read_back`` false) have nothing to contradict, so they never count as a mismatch."""
    if result.get("value_read_back") is False:
        return False
    if result.get("active_value_redacted") is True:
        return result.get("active_value_matches_expected") is False
    observed = str(result.get("active_value_ledger") or result.get("active_value") or "")
    if not observed:
        return False
    if action is None:
        # Without the intended text only the body's own verdict on a real read-back can contradict.
        return result.get("value_read_back") is True and result.get("active_value_matches_expected") is False
    return _type_read_back_failed(action, result)


def _vision_action_verified(
    kind: str, result: dict[str, Any] | None, action: dict[str, Any] | None = None
) -> bool:
    if not isinstance(result, dict):
        return False
    if kind == "click":
        # selected/checked state is raw browser evidence and does not need a deterministic
        # option-role classifier before it can verify a click.
        if result.get("selection_committed") or result.get("target_selected_before"):
            return True
        if result.get("target_option_like"):
            # A popup opening or closing proves a pointer effect, not a committed value. Raw option
            # state or accessibility-linked owner read-back is the trust floor for a choice click.
            return False
        return bool(
            result.get("url_changed")
            or result.get("title_changed")
            or result.get("surface_changed")
            or result.get("document_lifecycle_changed")
            or result.get("active_typable")
            # The target's own state attributes changed (aria-pressed, class, data-state): a toggled option button.
            or result.get("target_state_changed")
            # A value beside or linked to the target changed (a quantity next to a stepper button).
            or result.get("linked_value_changed")
            # A Copy button or menu entry: the desktop saw the clipboard change under the click.
            or result.get("clipboard_changed")
        )
    if kind == "type":
        if _vision_result_control_invalid(result):
            return False
        # Reading the intended value back out of the control is the strongest evidence a
        # type took, and on some surfaces the only one: native rich-text editors never
        # report their focused element as typable, so requiring that flag scored a
        # correct, read-back-confirmed type as unverified.
        # The loose fallback (a typable field holding some value) is for surfaces with no read-back; a
        # field read back as holding something other than the intended text is never verified by it.
        if _type_read_back_contradicts(action, result):
            return False
        return bool(
            result.get("active_value_matches_expected")
            or (result.get("active_typable") and result.get("active_has_value"))
        )
    if kind == "scroll" and result.get("mode") == "scroll_to_text":
        return bool(result.get("ok") and result.get("in_view"))
    if kind == "scroll":
        before = result.get("before_scroll_position")
        after = result.get("scroll_position")
        if before is None or after is None:
            before = result.get("before_scroll_y")
            after = result.get("scroll_y")
        return before is not None and after is not None and before != after
    if kind == "key":
        return bool(
            result.get("ok")
            and (
                result.get("url_changed")
                or result.get("title_changed")
                or result.get("surface_changed")
                or result.get("scroll_changed")
                or result.get("focus_changed")
                # A selection (select-all, shift+arrows) is an observed effect with no pixels either.
                or result.get("selection_changed")
                # The desktop saw the clipboard change under the keystroke (a copy or cut).
                or result.get("clipboard_changed")
                # A copy/cut/paste the page itself received is an observed effect with no pixels.
                or any(
                    isinstance(event, dict) and event.get("type") in {"copy", "cut", "paste"}
                    for event in (result.get("clipboard_events") or [])
                )
            )
        )
    if kind == "upload":
        return bool(result.get("value_present") or result.get("observed_present") or result.get("file_input_files_contains_filename") or result.get("page_filename_visible") or result.get("upload_success_text_visible"))
    if kind in {"launch_app", "open_file"}:
        return bool(result.get("ok") and (result.get("new_window_id") or result.get("surface_changed") or result.get("title_changed")))
    if kind == "focus_window":
        return bool(result.get("ok") and result.get("focus_changed"))
    if kind == "switch_surface":
        # The router's own read-back: the surface it now routes to is the one asked for.
        return bool(result.get("ok") and result.get("surface"))
    if kind == "watch":
        return bool(result.get("ok") and result.get("values"))
    if kind == "wait":
        return bool(result.get("ok"))
    if kind == "zoom":
        return bool(result.get("ok") and result.get("zoomed"))
    if kind in {"read_clipboard", "read_download", "read_print_view", "read_form"}:
        # The loop moves the text out of the result before verification; the count stays.
        return bool(result.get("ok") and isinstance(result.get("chars"), int))
    if kind == "switch_tab":
        return bool(result.get("ok") and result.get("switched"))
    if kind == "navigate":
        # The tab now shows a different address (or a new tab of this task was opened).
        return bool(result.get("ok") and (result.get("url_changed") or result.get("opened_new_tab")))
    if kind == "reload":
        return bool(result.get("ok") and result.get("reloaded"))
    if kind in {"drag", "hover"}:
        # The gesture ran and the page visibly reacted; the next observation shows what changed.
        return bool(result.get("ok") and (result.get("surface_changed") or result.get("url_changed")))
    return False


# Bare waits totalling up to this long stay transparent between an unverified click and an index/point click.
_CHAIN_BARE_WAIT_TRANSPARENT_MS = 3000


def _action_observes_reaction(action: dict[str, Any] | None, execution_surface: str) -> bool:
    """Whether a chained step can see a page react: a watch, or a wait for text, on the browser
    surface. On the desktop surface a watch is unavailable and a wait's text is dropped (it only
    sleeps), so neither observes anything."""
    kind = str((action or {}).get("action") or "")
    if execution_surface != "browser":
        return False
    return kind == "watch" or (kind == "wait" and bool(_safe_trim((action or {}).get("text"), 200)))


def _observation_saw_reaction(kind: str, result: dict[str, Any] | None) -> bool:
    """Whether a watch or a wait for text saw the page react: a watch that read at least two distinct
    values (it always reports the first reading, changed or not), or a wait whose text appeared."""
    if not isinstance(result, dict) or not result.get("ok"):
        return False
    if kind == "watch":
        texts = {
            " ".join(str(item.get("text") or "").split())
            for item in (result.get("values") or [])
            if isinstance(item, dict)
        }
        texts.discard("")
        return len(texts) >= 2
    if kind == "wait":
        return result.get("text_matched") is True
    return False


def _normalized_control_identity_text(value: Any, *, limit: int = 120) -> str:
    """Normalize opaque control text for identity only; never infer page meaning from it.

    Characters that draw nothing as text are not part of what the control says: an icon font's
    private-use glyph (" Mumbai (BOM)") and format marks (a clock's left-to-right mark). A model
    naming the option by what it reads on screen was refused as click_target_text_mismatch."""
    text = "".join(char for char in str(value or "") if unicodedata.category(char) not in {"Co", "Cf"})
    return re.sub(r"\s+", " ", text).strip().casefold()[:limit]


_ACCESSIBLE_NAME_RELATIONS = ("label", "aria-labelledby", "aria-label")


def _control_accessible_name(control: dict[str, Any] | None) -> str:
    """The browser's own name for this control, read from raw accessibility relations.

    A <label for>, aria-labelledby, or aria-label names exactly one control; a button or
    link is named by its own text (the platform's name-from-content rule). Surrounding
    section text is shared by every sibling, so it can never be an identity on its own.
    This reads accessibility data the page declared; it does not infer meaning.
    """
    if not isinstance(control, dict):
        return ""
    entries = control.get("accessibility_context")
    if isinstance(entries, list):
        for relation in _ACCESSIBLE_NAME_RELATIONS:
            for entry in entries:
                if isinstance(entry, dict) and str(entry.get("relation") or "") == relation:
                    text = re.sub(r"\s+", " ", str(entry.get("text") or "")).strip()
                    if text:
                        return text
    for key in ("label", "aria_label"):
        text = re.sub(r"\s+", " ", str(control.get(key) or "")).strip()
        if text:
            return text
    # ARIA's name-from-content roles too: a <div role="button"> folder named "Archive" is "Archive", not the
    # sidebar text around it (v6_mail run 1786 recorded an Archive click as "Finance | Inbox | 8").
    if (
        str(control.get("tag") or "").strip().lower() in {"button", "a"}
        or str(control.get("role") or "").strip().lower() in _NAME_FROM_CONTENT_ROLES
    ):
        return re.sub(r"\s+", " ", str(control.get("text") or "")).strip()
    return ""


_NAME_FROM_CONTENT_ROLES = frozenset(
    {"button", "link", "menuitem", "menuitemcheckbox", "menuitemradio", "tab", "option", "treeitem", "switch"}
)


def _control_label(control: dict[str, Any] | None, *, limit: int = 80) -> str:
    if not isinstance(control, dict):
        return ""
    own_name = _control_accessible_name(control)
    if own_name:
        return own_name[:limit]
    # An unlabelled radio/checkbox names itself by its own value ("Female"), never by the neighbouring text a
    # sibling choice shares ("Male | Gender"): the receipt must say which option was clicked.
    if str(control.get("type") or "").strip().lower() in {"radio", "checkbox"} or str(control.get("kind") or "").lower() in {"input/radio", "input/checkbox"}:
        own_value = re.sub(r"\s+", " ", str(control.get("value") or "")).strip()
        if len(own_value) >= 2 and own_value.lower() not in {"on", "[redacted]"} and any(ch.isalpha() for ch in own_value):
            return own_value[:limit]
    for key in ("context_text", "nearby_text", "label", "aria_label", "text", "placeholder", "name"):
        text = re.sub(r"\s+", " ", str(control.get(key) or "")).strip()
        if text:
            return text[:limit]
    # Each part once: an accessibility tree names tag, type, and role alike ("check-box/check-box/check-box").
    parts: list[str] = []
    for key in ("tag", "type", "role"):
        part = str(control.get(key) or "").strip()
        if part and part not in parts:
            parts.append(part)
    return ("/".join(parts) or "control")[:limit]


def _choice_question_label(control: dict[str, Any] | None, *, limit: int = 160) -> str:
    if not isinstance(control, dict):
        return ""
    own = _normal_grounding_text(control.get("text"))
    for key in ("context_text", "nearby_text", "label", "aria_label", "placeholder"):
        text = re.sub(r"\s+", " ", str(control.get(key) or "")).strip()
        if text and _normal_grounding_text(text) != own:
            return text[:limit]
    return ""


def _control_kind(control: dict[str, Any] | None) -> str:
    if not isinstance(control, dict):
        return ""
    parts = [_normalized_control_identity_text(control.get(key), limit=40) for key in ("tag", "type", "role")]
    return "/".join(part for part in parts if part)[:120]


def _control_signature(control: dict[str, Any] | None) -> str:
    """Return a stable opaque identity from raw control kind plus label/context text."""
    if not isinstance(control, dict):
        return ""
    label = _normalized_control_identity_text(_control_accessible_name(control), limit=120)
    if not label:
        for key in ("context_text", "nearby_text", "label", "aria_label", "text", "placeholder"):
            label = _normalized_control_identity_text(control.get(key), limit=120)
            if label:
                break
    raw = "|".join(
        [
            _normalized_control_identity_text(control.get("tag"), limit=40),
            _normalized_control_identity_text(control.get("type"), limit=40),
            _normalized_control_identity_text(control.get("role"), limit=40),
            label,
        ]
    )
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:16] if raw.strip("|") else ""


def _control_execution_identity(
    control: dict[str, Any] | None,
    shot: dict[str, Any] | None,
) -> str:
    """Bind run-local state to one exact raw control on one observed page state.

    This is opaque execution identity only. It does not infer what the page or
    control means.
    """
    if not isinstance(control, dict) or not isinstance(shot, dict):
        return ""
    evidence = (
        shot.get("page_evidence")
        if isinstance(shot.get("page_evidence"), dict)
        else {}
    )
    selector = str(control.get("selector") or "").strip()
    element_ref = str(
        control.get("element_ref")
        or control.get("stable_ref")
        or control.get("ref")
        or ""
    ).strip()
    observer_index = control.get("index")
    has_observer_index = (
        type(observer_index) is int and observer_index > 0
    )
    bounds = [
        control.get("x"),
        control.get("y"),
        control.get("width"),
        control.get("height"),
    ]
    has_usable_bounds = (
        all(
            isinstance(value, (int, float)) and not isinstance(value, bool)
            for value in bounds
        )
        and float(bounds[2]) > 0
        and float(bounds[3]) > 0
    )
    if not (
        selector
        or element_ref
        or (has_observer_index and has_usable_bounds)
    ):
        return ""
    identity = {
        "page_state": _page_state_fingerprint(shot),
        "url": shot.get("url") or evidence.get("url"),
        "title": shot.get("title") or evidence.get("title"),
        "surface": (
            control.get("surface_id")
            or control.get("frame_id")
            or control.get("frame_path")
            or evidence.get("surface_id")
        ),
        "selector": selector,
        "element_ref": element_ref,
        "observer_index": observer_index,
        "bounds": bounds,
    }
    raw = json.dumps(
        identity,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _raw_control_index(value: Any) -> int:
    try:
        return max(0, int(value or 0))
    except (TypeError, ValueError):
        return 0


def _exact_visible_raw_control(
    page_evidence: dict[str, Any] | None,
    control_index: int,
) -> dict[str, Any] | None:
    """Resolve one current raw control by its opaque observer index."""
    if control_index <= 0:
        return None
    controls = (page_evidence or {}).get("controls") if isinstance(page_evidence, dict) else []
    if not isinstance(controls, list):
        return None
    matches: list[dict[str, Any]] = []
    for raw in controls:
        if not isinstance(raw, dict) or _raw_control_index(raw.get("index")) != control_index:
            continue
        try:
            width = float(raw.get("width"))
            height = float(raw.get("height"))
        except (TypeError, ValueError):
            continue
        if width > 0 and height > 0:
            matches.append(raw)
    return dict(matches[0]) if len(matches) == 1 else None


def _optional_skip_control_state_signature(control: dict[str, Any] | None) -> str:
    """Hash the exact raw control state without interpreting its page meaning."""
    if not isinstance(control, dict):
        return ""
    try:
        serialized = json.dumps(control, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    except Exception:  # noqa: BLE001 - an unhashable control cannot support an exact skip binding
        return ""
    return hashlib.sha256(serialized.encode("utf-8")).hexdigest()


def _vision_observation_identity(
    observation_ref: dict[str, Any] | None,
    image: dict[str, Any] | None,
    *,
    fallback_step: int,
) -> dict[str, Any]:
    """Identify the exact screenshot observation even when artifact persistence is unavailable."""
    ref = observation_ref if isinstance(observation_ref, dict) else {}
    screenshot_sha256 = str(ref.get("screenshot_sha256") or "").strip().lower()
    if not screenshot_sha256:
        try:
            raw_image = base64.b64decode(str((image or {}).get("data") or ""), validate=True)
            screenshot_sha256 = hashlib.sha256(raw_image).hexdigest() if raw_image else ""
        except Exception:  # noqa: BLE001 - missing screenshot identity must fail the skip binding closed
            screenshot_sha256 = ""
    try:
        observation_step = max(0, int(ref.get("step") or fallback_step))
    except (TypeError, ValueError):
        observation_step = max(0, int(fallback_step or 0))
    return {
        "screenshot_sha256": screenshot_sha256,
        "step": observation_step,
    }


def _bind_model_optional_skip(
    skipped: dict[str, Any],
    *,
    raw_page_evidence: dict[str, Any] | None,
    model_page_evidence: dict[str, Any] | None,
    observation_identity: dict[str, Any] | None,
) -> tuple[dict[str, Any] | None, str]:
    """Bind one model-owned skip to one control in the exact current observation."""
    control_index = _raw_control_index((skipped or {}).get("control"))
    if not control_index:
        return None, "missing_current_control_index"
    try:
        from app.vision_agent import compact_control_inventory

        model_controls = compact_control_inventory(model_page_evidence or {}, limit=56)
    except Exception:  # noqa: BLE001 - no model-visible inventory means no safe binding
        return None, "current_control_inventory_unavailable"
    visible_matches = [
        control
        for control in model_controls
        if isinstance(control, dict) and _raw_control_index(control.get("index")) == control_index
    ]
    if len(visible_matches) != 1:
        return None, "control_index_not_unique_in_current_inventory"
    raw_control = _exact_visible_raw_control(raw_page_evidence, control_index)
    if raw_control is None:
        return None, "control_index_missing_or_ambiguous_in_current_observation"
    control_signature = _control_signature(raw_control)
    control_state_signature = _optional_skip_control_state_signature(raw_control)
    screenshot_sha256 = str((observation_identity or {}).get("screenshot_sha256") or "").strip().lower()
    observation_step = _raw_control_index((observation_identity or {}).get("step"))
    if not control_signature or not control_state_signature:
        return None, "current_control_identity_unavailable"
    if not screenshot_sha256 or not observation_step:
        return None, "current_observation_identity_unavailable"
    return (
        {
            "control": control_index,
            "question": _safe_trim((skipped or {}).get("question"), 500),
            "reason": _safe_trim((skipped or {}).get("reason"), 500),
            "control_signature": control_signature,
            "control_state_signature": control_state_signature,
            "observation_screenshot_sha256": screenshot_sha256,
            "observation_step": observation_step,
        },
        "",
    )


def _control_matches_model_optional_skip(
    control: dict[str, Any],
    *,
    page_evidence: dict[str, Any] | None,
    bindings: list[dict[str, Any]] | None,
    observation_identity: dict[str, Any] | None,
) -> bool:
    """Match only the exact unchanged control in the exact bound observation."""
    if not bindings:
        return False
    control_index = _raw_control_index((control or {}).get("index"))
    current_control = _exact_visible_raw_control(page_evidence, control_index)
    if current_control is None:
        return False
    screenshot_sha256 = str((observation_identity or {}).get("screenshot_sha256") or "").strip().lower()
    observation_step = _raw_control_index((observation_identity or {}).get("step"))
    control_signature = _control_signature(current_control)
    control_state_signature = _optional_skip_control_state_signature(current_control)
    if not screenshot_sha256 or not observation_step or not control_signature or not control_state_signature:
        return False
    return any(
        _raw_control_index(binding.get("control")) == control_index
        and str(binding.get("observation_screenshot_sha256") or "").strip().lower() == screenshot_sha256
        and _raw_control_index(binding.get("observation_step")) == observation_step
        and str(binding.get("control_signature") or "") == control_signature
        and str(binding.get("control_state_signature") or "") == control_state_signature
        for binding in bindings
        if isinstance(binding, dict)
    )


def _scroll_axis_extent(result: dict[str, Any], in_container: bool) -> tuple[Any, Any]:
    """(total, visible) px along the axis the scroll moved: widths for a left/right scroll, heights otherwise,
    so a horizontal position is never read against a vertical total."""
    if result.get("scroll_axis") == "horizontal":
        return (
            result.get("scroll_container_scroll_width" if in_container else "scroll_width"),
            result.get("scroll_container_client_width" if in_container else "inner_w"),
        )
    return (
        result.get("scroll_container_scroll_height" if in_container else "scroll_height"),
        result.get("scroll_container_client_height" if in_container else "inner_h"),
    )


def _add_horizontal_scroll_view(view: dict[str, Any], shot: dict[str, Any]) -> None:
    """scroll_x / scroll_width join the brain's viewport only when the page is wider than the window."""
    try:
        scroll_width = int(float(shot.get("scroll_width") or 0))
        inner_w = int(float(shot.get("inner_w") or 0))
        scroll_x = int(float(shot.get("scroll_x") or 0))
    except (TypeError, ValueError):
        return
    if inner_w > 0 and scroll_width > inner_w:
        view["scroll_x"] = scroll_x
        view["scroll_width"] = scroll_width


def _css_px_scale_field(coord_scale: Any, page_visible_px: int, dpr: Any = 1.0) -> dict[str, float]:
    """Page text states positions in CSS pixels; tell the brain the screenshot-to-CSS ratio when it is not 1.
    coord_scale maps screenshot px to capture (device) px, so CSS px per screenshot px is coord_scale / dpr.
    Browser captures only (desktop captures carry no inner_h, so page_visible_px is 0 there)."""
    try:
        ratio = float(dpr or 1.0)
        scale = float(coord_scale or 1.0) / (ratio if ratio > 0 else 1.0)
    except (TypeError, ValueError):
        return {}
    if page_visible_px > 0 and abs(scale - 1.0) >= 0.005:
        return {"css_px_per_screenshot_px": round(scale, 2)}
    return {}


def _bind_action_control(action: dict[str, Any], page_evidence: dict[str, Any] | None, coord_scale: float) -> dict[str, Any] | None:
    """Bind model image coordinates to the smallest raw observed control box containing the point."""
    controls = (page_evidence or {}).get("controls") if isinstance(page_evidence, dict) else []
    if not isinstance(controls, list):
        return None
    try:
        px = float(action.get("x") or 0) * float(coord_scale or 1.0)
        py = float(action.get("y") or 0) * float(coord_scale or 1.0)
    except (TypeError, ValueError):
        return None
    best: tuple[tuple[int, float], dict[str, Any]] | None = None
    for raw in controls:
        if not isinstance(raw, dict):
            continue
        try:
            x = float(raw.get("x"))
            y = float(raw.get("y"))
            width = float(raw.get("width"))
            height = float(raw.get("height"))
        except (TypeError, ValueError):
            continue
        if width <= 0 or height <= 0:
            continue
        if raw.get("covered") is True or raw.get("behind_modal") is True:
            # Not the topmost hit at its centre: a point inside its box may land on whatever is drawn
            # over it (an open popup), so it never binds; the click stays point-only for the body to hit-test.
            continue
        if x <= px <= x + width and y <= py <= y + height:
            # A control something else is painted over (the observer's raw hit test) loses to
            # one that is actually on top at its center; then the smallest box wins.
            rank = (1 if raw.get("occluded") is True else 0, width * height)
            if best is None or rank < best[0]:
                best = (rank, raw)
    return dict(best[1]) if best else None


def _controls_share_execution_identity(
    first: dict[str, Any] | None,
    second: dict[str, Any] | None,
) -> bool:
    """Compare raw execution identities without interpreting what either control means."""
    if not isinstance(first, dict) or not isinstance(second, dict):
        return False
    first_selector = _safe_control_selector(first.get("selector"))
    second_selector = _safe_control_selector(second.get("selector"))
    if first_selector and second_selector:
        return first_selector == second_selector
    first_signature = _control_signature(first)
    second_signature = _control_signature(second)
    return bool(first_signature and second_signature and first_signature == second_signature)


_ACCESSIBILITY_IDENTITY_LABEL_RELATIONS = frozenset(
    {"label", "aria-label", "aria-labelledby"}
)


def _control_identity_text_values(
    control: dict[str, Any] | None,
    *,
    limit: int = 180,
    include_shown_label: bool = False,
) -> list[str]:
    """Return exact raw text that directly identifies one enumerated control.

    Native/ARIA label relationships are browser-owned accessibility identity, not inferred page
    meaning. Nearby text, DOM context, placeholders, and descriptions deliberately remain excluded.
    With include_shown_label, a custom radio/checkbox/option's own words read through its slots
    (`derived_label` the body marks `derived_label_visible`) also name it: a model naming the "Yes"
    radio whose value attribute is "1" names that radio (runs 68-75). Attribute or class-name words the
    body derives are never visible-marked and never count.
    """
    if not isinstance(control, dict):
        return []
    values: list[str] = []
    seen: set[str] = set()

    def _append(value: Any) -> None:
        text = _safe_trim(value, limit)
        normalized = _normalized_control_identity_text(text, limit=limit)
        if not normalized or normalized in seen:
            return
        seen.add(normalized)
        values.append(text)

    for key in ("text", "value", "aria_label", "label"):
        _append(control.get(key))
    for entry in control.get("accessibility_context") or []:
        if not isinstance(entry, dict):
            continue
        relation = _normalized_control_identity_text(entry.get("relation"), limit=40)
        if relation in _ACCESSIBILITY_IDENTITY_LABEL_RELATIONS:
            _append(entry.get("text"))
    if include_shown_label and control.get("derived_label_visible") is True:
        _append(control.get("derived_label"))
    return values


def _control_own_text_exact_match(
    control: dict[str, Any] | None,
    value: Any,
    *,
    include_shown_label: bool = False,
) -> bool:
    """Match a model-supplied target label against exact raw control identity text."""
    expected = _normalized_control_identity_text(value, limit=180)
    if not expected:
        return False
    return any(
        _normalized_control_identity_text(candidate, limit=180) == expected
        for candidate in _control_identity_text_values(control, limit=180, include_shown_label=include_shown_label)
    )


# Roles of a control that holds several options of its own (one row for the whole list).
_OPTION_CONTAINER_ROLES = frozenset(
    {"listbox", "menu", "menubar", "radiogroup", "tablist", "grid", "tree", "list", "toolbar", "group", "combobox"}
)


def _control_holds_option_text(control: dict[str, Any] | None, value: Any) -> bool:
    """Whether a container control's own text holds the named option as whole words (structure only)."""
    if not isinstance(control, dict):
        return False
    kinds = " ".join(
        str(control.get(key) or "") for key in ("role", "kind", "tag", "type")
    ).replace("/", " ").casefold().split()
    if not any(kind in _OPTION_CONTAINER_ROLES for kind in kinds):
        return False
    expected = _normalized_control_identity_text(value, limit=180)
    if not expected:
        return False
    for candidate in _control_identity_text_values(control, limit=400):
        own = _normalized_control_identity_text(candidate, limit=400)
        if own and own != expected and f" {expected} " in f" {own} ":
            return True
    return False


# Roles and tags of controls that never take typed text.
_NO_TEXT_ROLES = frozenset({"button", "link", "a", "menuitem", "tab", "option", "checkbox", "radio", "switch", "img", "image"})


def _control_plainly_takes_no_text(control: dict[str, Any] | None) -> bool:
    """A button, link, tab, option, or toggle that is not editable: typing into it reaches no field."""
    if not isinstance(control, dict):
        return False
    if any(control.get(key) is True for key in ("editable", "accepts_text", "contenteditable")):
        return False
    tag = str(control.get("tag") or "").strip().casefold()
    role = str(control.get("role") or "").strip().casefold()
    if tag in {"input", "textarea", "select"} or role in {"textbox", "searchbox", "combobox", "edit", "document"}:
        return False
    return tag in _NO_TEXT_ROLES or role in _NO_TEXT_ROLES


def _control_text_names_value(control: dict[str, Any] | None, value: Any) -> bool:
    """Whether the control's own text holds the named value as whole words (at least two characters)."""
    def words(text: Any) -> str:
        # Punctuation separates words here ("Seat 10C, aisle" holds the word "10C").
        return " ".join(re.sub(r"[^\w]+", " ", _normalized_control_identity_text(text, limit=400)).split())

    expected = words(value)
    if len(expected.replace(" ", "")) < 2:
        return False
    return any(
        own and f" {expected} " in f" {own} "
        for own in (
            words(candidate) for candidate in _control_identity_text_values(control, limit=400, include_shown_label=True)
        )
    )


def _control_toggle_state(control: dict[str, Any] | None) -> str:
    """"checked" or "unchecked" for a checkbox or switch, "" for anything else (structure only)."""
    if not isinstance(control, dict):
        return ""
    tag = str(control.get("tag") or "").casefold()
    kind = str(control.get("type") or "").casefold()
    role = str(control.get("role") or "").casefold()
    if not ((tag == "input" and kind == "checkbox") or role in {"checkbox", "switch", "menuitemcheckbox"}):
        return ""
    checked = control.get("checked") is True or str(control.get("aria_checked") or "").casefold() == "true"
    return "checked" if checked else "unchecked"


def _control_is_checked_toggle(control: dict[str, Any] | None) -> bool:
    """A checkbox or switch that is ticked now (structure only)."""
    return _control_toggle_state(control) == "checked"


def _click_target_identity_check(
    action: dict[str, Any] | None,
    control: dict[str, Any] | None,
) -> dict[str, Any]:
    """Fail closed when a model-named click value resolves to a different live element.

    This compares two explicit execution identities; it does not infer what the control means or
    choose another target. A fresh model turn owns recovery when the selector/index is stale. A refusal
    says in one line how to fix it (_click_target_mismatch_feedback; with the current inventory, the one
    listed control whose own text is the named value).
    """
    if str((action or {}).get("action") or "").strip().lower() != "click":
        return {"ok": True, "source": "not_click"}
    expected = _safe_trim((action or {}).get("text"), 180)
    if not expected or not isinstance(control, dict):
        return {"ok": True, "source": "unnamed_target"}
    own_values = _control_identity_text_values(control, limit=180, include_shown_label=True)
    if not own_values and any(str(control.get(key) or "").strip() for key in ("text", "value", "aria_label", "label")):
        # Its only text is glyphs that draw no text (an icon font): nothing it says can match a named click,
        # which stays a mismatch as before identity ignored such glyphs (review).
        return {
            "ok": False,
            "source": "glyph_only_live_identity",
            "reason": "click_target_text_mismatch",
            "feedback": (
                "invalid_model_action:click_target_text_mismatch. The bound control shows only an icon, not the "
                f"text '{_safe_trim(expected, 80)}'. Send this click again with text empty (an icon button is "
                "clicked by its control id alone)."
            ),
        }
    if not own_values or _control_own_text_exact_match(control, expected, include_shown_label=True):
        return {"ok": True, "source": "exact_live_identity" if own_values else "no_live_identity_text"}
    if _control_text_names_value(control, expected):
        # A short value naming the control's own label in whole words: "SEA" on "SEA - Seattle, Washington",
        # "10C" on "Seat 10C, aisle, available" (v6_travel's brain was refused both and learned the full labels
        # only from the error).
        return {"ok": True, "source": "value_within_live_identity"}
    if _control_holds_option_text(control, expected):
        # A list of options enumerated as one control (a custom listbox "30 min 45 min 60 min 90 min"): the
        # named option is one of its own parts, and the click lands at the model's point inside it (v6_calendar
        # run 1783 was refused eight times in a row for naming the option it pointed at).
        return {"ok": True, "source": "option_within_live_control"}
    shown = (
        _safe_trim(control.get("derived_label"), 120) if control.get("derived_label_visible") is True else ""
    ) or own_values[0]
    return {
        "ok": False,
        "reason": "click_target_text_mismatch",
        "expected_text": expected,
        "observed_text": shown,
        "feedback": _click_target_mismatch_feedback(expected, shown, control, None),
    }


def _click_target_mismatch_feedback(
    expected: str,
    shown: str,
    control: dict[str, Any] | None,
    control_index_map: dict[int, dict[str, Any]] | None,
) -> str:
    return (
        "invalid_model_action:click_target_text_mismatch. NOT RUN: the click names "
        f"'{_safe_trim(expected, 80)}', but the control it binds reads '{_safe_trim(shown, 120)}'. "
        + _click_text_mismatch_fix(expected, control, control_index_map)
    )


def _click_text_mismatch_fix(
    expected: str,
    control: dict[str, Any] | None,
    control_index_map: dict[int, dict[str, Any]] | None,
) -> str:
    """One repair line for a click whose value names other text than its bound control (structure only).

    The one listed control whose own text is exactly the named value is named by id, and the model fixes
    the id next step. It is never rebound here: the id and the text disagree, and which of them is wrong is
    the model's call. Several matches are listed for the model to choose by section; none means no listed
    control's own text is the named value."""
    bound_selector = _safe_control_selector((control or {}).get("selector"))
    matches: list[int] = []
    for index, ref in (control_index_map or {}).items():
        candidate = ref.get("control") if isinstance(ref, dict) else None
        if not isinstance(candidate, dict):
            continue
        if bound_selector and _safe_control_selector(candidate.get("selector")) == bound_selector:
            continue
        if _control_own_text_exact_match(candidate, expected, include_shown_label=True):
            matches.append(int(index))
    named = _safe_trim(expected, 80)
    if len(matches) == 1:
        return f"'{named}' is control {matches[0]}: send control={matches[0]} (no x,y needed) to click it."
    if matches:
        ids = ", ".join(str(index) for index in sorted(matches)[:6])
        return (
            f"Several listed controls read '{named}' (controls {ids}): send the id of the one you mean, in the "
            "section the task names."
        )
    if _control_opens_options(control):
        return (
            "That control opens a list: click it with text empty to open the list, then click the option "
            f"'{named}' once it is listed (or type it into the control)."
        )
    return (
        ("No listed control reads that text. " if control_index_map is not None else "")
        + "If you mean this control, send the click again with text empty (a choice is checked by its own label); "
        "if you mean another control, send that control's id."
    )


def _control_opens_options(control: dict[str, Any] | None) -> bool:
    """A control that owns a popup of options: a combobox, or one whose aria-controls/aria-owns names one."""
    if not isinstance(control, dict):
        return False
    if str(control.get("role") or "").strip().casefold() in {"combobox", "listbox"}:
        return True
    return bool(str(control.get("aria_controls") or "").strip() or str(control.get("aria_owns") or "").strip())


def _control_box_nested_within(inner: dict[str, Any] | None, outer: dict[str, Any] | None) -> bool:
    """Whether one observed control's box lies entirely inside another's (capture pixels)."""
    try:
        ix, iy = float(inner.get("x") or 0), float(inner.get("y") or 0)
        iw, ih = float(inner.get("width") or 0), float(inner.get("height") or 0)
        ox, oy = float(outer.get("x") or 0), float(outer.get("y") or 0)
        ow, oh = float(outer.get("width") or 0), float(outer.get("height") or 0)
    except (AttributeError, TypeError, ValueError):
        return False
    if iw <= 0 or ih <= 0 or ow <= 0 or oh <= 0:
        return False
    return ox <= ix and oy <= iy and ix + iw <= ox + ow and iy + ih <= oy + oh


def _controls_one_item_by_box_and_text(first: dict[str, Any] | None, second: dict[str, Any] | None) -> bool:
    """Two listed controls that are one item: the same box (within a few pixels; an element and the one
    nested in it that fills it) and a shared exact identity text (a menu's wrapper and its item). Raw
    geometry and text only. A smaller control inside a larger one is not this: that conflict is arbitrated."""
    try:
        same_box = all(
            abs(float(first.get(key) or 0) - float(second.get(key) or 0)) <= 3 for key in ("x", "y", "width", "height")
        ) and float(first.get("width") or 0) > 0 and float(first.get("height") or 0) > 0
    except (AttributeError, TypeError, ValueError):
        return False
    if not same_box:
        return False
    first_texts = {_normalized_control_identity_text(t, limit=180) for t in _control_identity_text_values(first, limit=180)}
    second_texts = {_normalized_control_identity_text(t, limit=180) for t in _control_identity_text_values(second, limit=180)}
    first_texts.discard("")
    return bool(first_texts & second_texts)


def _control_index_listed(page_evidence: dict[str, Any] | None, index: int) -> bool:
    """Whether the current observation lists a control under this id at all (selector or not)."""
    controls = (page_evidence or {}).get("controls") if isinstance(page_evidence, dict) else None
    if not isinstance(controls, list) or not index:
        return False
    for raw in controls:
        if not isinstance(raw, dict):
            continue
        try:
            if int(raw.get("index") or 0) == index:
                return True
        except (TypeError, ValueError):
            continue
    return False


def _remembered_control_row(page_evidence: dict[str, Any] | None, index: int) -> dict[str, Any] | None:
    """The body's record of a control with this stable id seen earlier on this document and not listed now:
    selector and structural identity (tag, role, type, accessible name). None when the id is not known."""
    rows = (page_evidence or {}).get("remembered_controls") if isinstance(page_evidence, dict) else None
    if not isinstance(rows, list) or not index:
        return None
    for row in rows:
        if not isinstance(row, dict):
            continue
        try:
            if int(row.get("index") or 0) != index:
                continue
        except (TypeError, ValueError):
            continue
        if _safe_control_selector(row.get("selector")):
            return row
    return None


def _unresolved_control_reference_detail(page_evidence: dict[str, Any] | None, index: int) -> str:
    """Why a cited control id names nothing the body can act on now, in the brain's terms."""
    remembered = _remembered_control_row(page_evidence, index)
    if remembered:
        name = _safe_trim(remembered.get("name"), 60)
        return (
            f"control {index}" + (f" ('{name}')" if name else "")
            + " is off screen right now (it was listed earlier on this page). Cite it as the PRIMARY action of its "
            "own reply: the body scrolls it into view, re-checks it is the same element, and the action then runs "
            "through every gate on the fresh view. Follow-ups in a chain cannot name an off-screen control."
        )
    return (
        f"control {index} is not on this page: it is in neither control_inventory nor control_memory, so it names "
        "no control the body can act on (ids are stable only on the page they were listed on). Pick a control "
        "from control_inventory, or scroll to find it."
    )


def _listed_control_row(page_evidence: dict[str, Any] | None, index: int) -> dict[str, Any] | None:
    """The current observation's row listed under this id (selector or not), else None."""
    controls = (page_evidence or {}).get("controls") if isinstance(page_evidence, dict) else None
    if not isinstance(controls, list) or not index:
        return None
    for raw in controls:
        if isinstance(raw, dict) and _raw_control_index(raw.get("index")) == index:
            return raw
    return None


def _primary_point_on_listed_control(
    action: dict[str, Any] | None,
    page_evidence: dict[str, Any] | None,
    index: int,
    coord_scale: float,
    *,
    batch_index: int,
    kind: str,
) -> bool:
    """The first action of a chain names a listed control the body has no selector for, with a point inside
    that row's own box: the id and the point name one place in this screenshot, so the point is the target as
    it is for a lone action (the coordinate click's own page-context and pixel checks run at dispatch).
    Follow-ups keep the strict rule: their point may be stale after the step before them."""
    if batch_index != 0 or kind not in {"click", "type", "upload"} or not _action_point(action):
        return False
    row = _listed_control_row(page_evidence, index)
    if not isinstance(row, dict) or _safe_control_selector(row.get("selector")):
        return False
    if _point_distance_to_control_box(_action_point(action), row, coord_scale) is None:
        return False
    return not _point_outside_control_box(action, row, coord_scale)


def _listed_unresolvable_control_detail(
    page_evidence: dict[str, Any] | None, index: int, kind: str, coord_scale: float
) -> str:
    """Why a listed control id cannot be acted on by id, with the one way to reach it."""
    row = _listed_control_row(page_evidence, index)
    if not isinstance(row, dict) or _safe_control_selector(row.get("selector")) or kind == "use_credential":
        # A credential goes only into one exact selector-bound control: there is no point route to offer.
        return f"control={index} is not resolvable in the current control_inventory."
    name = _control_label(row, limit=60)
    center = _control_center_point(row, coord_scale)
    at = f"x,y at its box centre ({center[0]},{center[1]})" if center else "x,y inside its box"
    if kind == "type":
        how = (
            f"To type into it, click it by point (control=0, {at}) and put the type in that reply's then with "
            "control=0: the text goes to the field the click focused."
        )
    else:
        how = f"Act on it by point alone: control=0 with {at}."
    return (
        f"control {index} ('{name}') is listed, but the body has no selector for it, so it cannot be targeted by "
        f"id. {how}"
    )


_OFF_SCREEN_SCROLL_REASONS = {
    "control_not_found": "it is no longer on the page",
    "control_selector_ambiguous": "its selector now matches more than one element",
    "control_identity_changed": "it is no longer the same kind of element",
}


def _sequence_invalid_feedback_text(label: str, reason: str, detail: str = "") -> str:
    suffix = f". {detail}" if detail else ""
    return f"sequence_invalid at {label}: {reason}{suffix}"


async def _scroll_remembered_control_into_view(
    body: Any,
    action: dict[str, Any],
    *,
    page_evidence: dict[str, Any] | None,
    control_index_map: dict[int, dict[str, Any]],
    attempts: dict[int, int],
    step_index: int,
) -> dict[str, Any] | None:
    """The primary action cites a stable control id that is off screen: scroll that one element into view
    (nearest) so the next observation lists it, and withhold the whole reply (nothing else runs). None when
    the id is listed, unknown, or the action kind takes no control.

    The scroll only moves the viewport. The control is trusted again only when the next observation lists the
    same id (the registry reissues an id only for the same selector, tag, role, type and accessible name), and
    the re-issued action then runs through every gate on that fresh view (binding, grounding, consequence,
    secret, payment, final-action). An id still absent after one scroll is refused, never scrolled for again."""
    kind = str((action or {}).get("action") or "").strip().lower()
    index = _action_control_index(action)
    if kind not in {"click", "type", "use_credential", "upload"} or not index:
        return None
    if index in (control_index_map or {}) or _control_index_listed(page_evidence, index):
        return None
    row = _remembered_control_row(page_evidence, index)
    if row is None:
        return None
    name = _safe_trim(row.get("name"), 60)
    named = f"control {index}" + (f" ('{name}')" if name else "")
    scroller = getattr(body, "vision_scroll_into_view", None)
    base = {"ok": False, "label": "primary", "action": action, "kind": kind, "control_index": index, "observation_stale": True}
    if attempts.get(index) is not None:
        return {
            **base,
            "reason": "control_off_screen_unreachable",
            "observation_stale": False,
            "feedback": _sequence_invalid_feedback_text(
                "primary",
                "control_off_screen_unreachable",
                f"{named} was scrolled into view at step {attempts[index]} and the next observation does not list it "
                "(it changed identity, was removed, or is hidden). Do not cite it again; choose from control_inventory.",
            ),
        }
    if not callable(scroller):
        return None
    try:
        result = await scroller(
            _safe_control_selector(row.get("selector")),
            expected_target_identity={key: row.get(key) or "" for key in ("tag", "role", "type")},
        )
    except Exception as exc:  # noqa: BLE001 - a lost body leaves the reply refused, nothing ran
        result = {"ok": False, "failure_reason": "scroll_execution_failed", "error": _exception_summary(exc)}
    attempts[index] = step_index + 1
    if isinstance(result, dict) and result.get("ok") and result.get("in_view") is not False:
        return {
            **base,
            "reason": "control_scrolled_into_view",
            "feedback": _sequence_invalid_feedback_text(
                "primary",
                "control_scrolled_into_view",
                f"{named} was off screen; the body scrolled it into view (scrolled into view, nearest). NOT RUN: nothing "
                "else in this reply ran. Re-issue the same action with the same control id from the fresh observation; "
                "it runs through every gate there.",
            ),
        }
    reason_key = (
        str(result.get("failure_reason") or "scroll_execution_failed") if isinstance(result, dict) else "scroll_execution_failed"
    )
    why = _OFF_SCREEN_SCROLL_REASONS.get(reason_key) or "the body could not bring it into view"
    return {
        **base,
        "reason": f"control_off_screen_{reason_key}"[:80],
        "observation_stale": False,
        "feedback": _sequence_invalid_feedback_text(
            "primary",
            "control_off_screen",
            f"{named} is not on this page any more: {why}. Nothing ran. Choose a control from control_inventory.",
        ),
    }


def _followup_index_identity_resolves(
    indexed_control: dict[str, Any] | None,
    control_index_map: dict[int, dict[str, Any]],
) -> bool:
    """A chained follow-up bound by control id names its control by identity, and the body re-resolves that
    control in the live page at its turn (selector, then its own identity gate). The id is stable across
    observations, so it still names the same element after the layout moved, while the point the brain wrote
    beside it was read off a screen that no longer matches (a dropdown that covered the field, a banner that
    pushed the page). True when that identity is addressable and exactly one: a selector the inventory lists
    for this control alone, and the control not known to be disabled."""
    if not isinstance(indexed_control, dict) or indexed_control.get("disabled") is True:
        return False
    selector = _safe_control_selector(indexed_control.get("selector"))
    if not selector:
        return False
    owners = sum(
        1
        for ref in (control_index_map or {}).values()
        if isinstance(ref, dict) and _safe_control_selector(ref.get("selector")) == selector
    )
    return owners == 1


def _reconcile_action_control_references(
    action: dict[str, Any],
    *,
    indexed_control: dict[str, Any] | None,
    coordinate_control: dict[str, Any] | None,
) -> dict[str, Any]:
    """Reconcile two explicit model target references without choosing browser strategy.

    A control index and screenshot point are two encodings of the same proposed target. When they
    disagree, a value-setting click can be repaired only if the model's exact option text identifies
    exactly one of the two raw controls. Every other conflict fails closed for a fresh model turn.
    """
    if not isinstance(indexed_control, dict):
        return {"ok": True, "control": coordinate_control, "source": "coordinate_only"}
    if not isinstance(coordinate_control, dict) or _controls_share_execution_identity(indexed_control, coordinate_control):
        return {"ok": True, "control": indexed_control, "source": "index"}

    kind = str((action or {}).get("action") or "").strip().lower()
    if kind == "type" and _control_box_nested_within(coordinate_control, indexed_control):
        # The point's control lies inside the indexed one (a combobox's edit box, a field's inner
        # editor): both references name one target, and the inner control is its text receiver.
        return {"ok": True, "control": coordinate_control, "source": "coordinate_nested_in_index"}
    if kind == "click" and _controls_one_item_by_box_and_text(indexed_control, coordinate_control):
        # The point's control fills the indexed control's box and reads the same text: one item seen as
        # nested elements (a menu's li and its item), not two candidates.
        return {"ok": True, "control": indexed_control, "source": "index_contains_point"}
    action_text = (action or {}).get("text")
    indexed_matches = kind == "click" and _control_own_text_exact_match(
        indexed_control, action_text, include_shown_label=True
    )
    coordinate_matches = kind == "click" and _control_own_text_exact_match(
        coordinate_control, action_text, include_shown_label=True
    )
    if coordinate_matches and not indexed_matches:
        return {
            "ok": True,
            "control": coordinate_control,
            "source": "coordinate_exact_text",
            "rejected_control": indexed_control,
        }
    if indexed_matches and not coordinate_matches:
        return {
            "ok": True,
            "control": indexed_control,
            "source": "index_exact_text",
            "rejected_control": coordinate_control,
        }
    return {
        "ok": False,
        "reason": "target_reference_conflict",
        "indexed_control": indexed_control,
        "coordinate_control": coordinate_control,
        "feedback": (
            "invalid_model_action:target_reference_conflict. The control index and screenshot point resolve to "
            "different current controls, and the exact action text does not uniquely identify one of them. "
            "NOT RUN. Send the one you mean: its control id alone (no x,y needed), or control=0 with a point on it."
        ),
    }


def _safe_control_selector(value: Any) -> str:
    selector = str(value or "").strip()
    if not selector or len(selector) > 200:
        return ""
    return selector


_SENSITIVE_AUTOCOMPLETE_TOKENS = {
    "current-password",
    "new-password",
    "one-time-code",
    "transaction-amount",
    "transaction-currency",
    "webauthn",
}
_FINAL_TARGET_IDENTITY_FIELDS = (
    "target_selector",
    "target_text",
    "target_tag",
    "target_type",
    "target_role",
    "dispatch_path",
    "page_url",
)


def _control_has_sensitive_value_structure(control: dict[str, Any] | None) -> bool:
    """Classify secret-bearing controls from browser structure, never label meaning."""
    if not isinstance(control, dict):
        return False
    if bool(control.get("value_redacted")):
        return True
    tag = str(control.get("tag") or "").strip().lower()
    input_type = str(control.get("type") or control.get("input_type") or "").strip().lower()
    if tag == "input" and input_type == "password":
        return True
    autocomplete = str(control.get("autocomplete") or "").strip().lower()
    tokens = {token for token in re.split(r"\s+", autocomplete) if token}
    return any(token in _SENSITIVE_AUTOCOMPLETE_TOKENS or token.startswith("cc-") for token in tokens)


def _redacted_sensitive_action_evidence(action: dict[str, Any] | None) -> dict[str, Any]:
    """Return an evidence-only action projection with secret-bearing prose removed."""
    source = dict(action or {})
    raw_text = str(source.get("text") or "")
    for key in (
        "text",
        "reason",
        "question",
        "grounding_quote",
        "proposed_answer",
        "display_reason",
        "value",
    ):
        if source.get(key) not in (None, ""):
            source[key] = "[REDACTED]"
    source["sensitive_value_redacted"] = True
    source["sensitive_value_length"] = len(raw_text)
    return source


_SENSITIVE_TYPE_FAILURE_REASONS = frozenset(
    {
        "page_context_drift",
        "page_context_required",
        "control_not_found",
        "control_selector_ambiguous",
        "control_target_drift",
        "control_not_typable",
        "control_focus_failed",
        "credential_event_dispatch_failed",
        "credential_local_verification_failed",
        "credential_replay_failed",
        "credential_value_set_failed",
        # The extension's own credential receipt vocabulary (credentialReplayCommandReceipt).
        "control_identity_required",
        "credential_replay_page_context_drift",
        "credential_replay_target_drift",
        "credential_replay_post_context_unavailable",
        "credential_replay_post_context_drift",
        "page_context_unavailable",
    }
)
_SENSITIVE_TYPE_MISMATCH_FIELDS = frozenset(
    {
        "url",
        "document_lifecycle_token",
        "document_state_signature",
        "stable_surface_signature",
        "surface_signature",
        "surface_probe",
        "target_selector",
        "target_text",
        "target_tag",
        "target_type",
        "target_role",
        "dispatch_path",
        "page_url",
    }
)


def _redact_sensitive_type_result(
    result: dict[str, Any] | None,
    *,
    expected_text: Any,
    redaction_reason: str = "sensitive_input_structure",
) -> dict[str, Any]:
    """Construct a value-free verification projection for sensitive typing.

    Browser results are adversarial at this boundary.  Copying the result and
    deleting known value fields is unsafe because a page can reflect a secret
    through any newly added label/name/id/selector field.  Keep only exact
    booleans plus a runtime-derived length; never derive equality from a raw
    browser value or forward browser-controlled strings.
    """

    raw = result if isinstance(result, dict) else {}
    expected = str(expected_text or "")
    matches_expected = raw.get("active_value_matches_expected") is True
    safe: dict[str, Any] = {
        "ok": raw.get("ok") is True,
        "active_typable": raw.get("active_typable") is True,
        "active_has_value": raw.get("active_has_value") is True,
        "active_value_matches_expected": matches_expected,
        "active_value_length": len(expected) if matches_expected else 0,
    }
    for key in (
        "focus_attempted",
        "active_validity_valid",
    ):
        if raw.get(key) is True:
            safe[key] = True
        elif raw.get(key) is False:
            safe[key] = False
    aria_invalid = str(raw.get("active_aria_invalid") or "").strip().lower()
    if aria_invalid in {"true", "false"}:
        safe["active_aria_invalid"] = aria_invalid
    if raw.get("error") not in (None, "", [], {}):
        safe["error"] = "sensitive_type_body_error"
    # Why the body refused, from a fixed vocabulary only (run 1793's login typing failed five times with
    # no recorded reason). Any other browser string stays out.
    if str(raw.get("failure_reason") or "") in _SENSITIVE_TYPE_FAILURE_REASONS:
        safe["failure_reason"] = str(raw["failure_reason"])
    for key in ("page_context_mismatch_field", "target_identity_mismatch_field", "mismatch_field"):
        if str(raw.get(key) or "") in _SENSITIVE_TYPE_MISMATCH_FIELDS:
            safe[key] = str(raw[key])
    # Diagnostics: leading characters of extension-generated random lifecycle tokens, hex only.
    for key in ("lifecycle_expected_prefix", "lifecycle_live_prefix"):
        if re.fullmatch(r"[0-9a-f]{8}", str(raw.get(key) or "")):
            safe[key] = str(raw[key])
    safe["active_value_redacted"] = True
    safe["active_value_redaction_reason"] = (
        "credential_replay"
        if redaction_reason == "credential_replay"
        else "sensitive_input_structure"
    )
    return safe


def _final_target_identity(source: dict[str, Any] | None) -> dict[str, str]:
    raw = source if isinstance(source, dict) else {}
    detection = raw.get("submit_detection") if isinstance(raw.get("submit_detection"), dict) else {}
    return {
        "target_selector": _safe_control_selector(raw.get("target_selector") or raw.get("selector")),
        "target_text": _safe_trim(raw.get("target_text") or detection.get("text"), 180),
        "target_tag": _safe_trim(raw.get("target_tag") or raw.get("tag") or detection.get("tag"), 40).lower(),
        # A probe's own target_type is the raw type attribute ("" for a typeless button); the
        # detection's resolved_type ("submit") is semantics the live probe never reports, so it may
        # only fill in when no probe identity exists at all.
        "target_type": _safe_trim(
            raw.get("target_type")
            if "target_type" in raw
            else (raw.get("type") or detection.get("resolved_type")),
            40,
        ).lower(),
        "target_role": _safe_trim(raw.get("target_role") or detection.get("role"), 80).lower(),
        "dispatch_path": _safe_trim(raw.get("dispatch_path"), 40),
        "page_url": _safe_trim(raw.get("page_url"), 1000),
    }


def _final_target_identity_complete(identity: dict[str, Any] | None) -> bool:
    if not isinstance(identity, dict):
        return False
    if not all(field in identity for field in _FINAL_TARGET_IDENTITY_FIELDS):
        return False
    return bool(
        _safe_control_selector(identity.get("target_selector"))
        and _safe_trim(identity.get("target_tag"), 40)
        and _safe_trim(identity.get("dispatch_path"), 40)
        and _safe_trim(identity.get("page_url"), 1000)
    )


def _observed_control_identity_text(raw: dict[str, Any]) -> str:
    """The text that names an enumerated control, in the order a person would use: its own text,
    then its accessible name (aria-label, associated label). A control's current value never names
    it: the value is what an action changes (a slider's 0 becomes 67), and neither the observer's
    text nor any in-page probe reads it, so an unlabeled control with a value could never match."""
    for key in ("text", "aria_label", "label"):
        if raw.get(key) not in (None, "", "[REDACTED]"):
            return _safe_trim(raw.get(key), 180)
    for entry in raw.get("accessibility_context") or []:
        if not isinstance(entry, dict):
            continue
        relation = _normalized_control_identity_text(entry.get("relation"), limit=40)
        if relation in _ACCESSIBILITY_IDENTITY_LABEL_RELATIONS and entry.get("text") not in (None, "", "[REDACTED]"):
            return _safe_trim(entry.get("text"), 180)
    return ""

def _observed_control_identity_names(raw: dict[str, Any]) -> list[str]:
    """Every raw name the observation recorded for this one control: its own text, accessible
    label relations, aria-label, placeholder, and name attribute. In-page probes derive a single
    name with differing fallback orders (a labelled input with a placeholder is "0.00" to one and
    "Amount" to another); any of these names still identifies this exact control. Typed values
    are excluded because they change as the control is used."""
    names: list[str] = []
    seen: set[str] = set()

    def _append(value: Any) -> None:
        text = _safe_trim(value, 180)
        # Only exact repeats merge: the in-page checks compare names case-sensitively, so a label "Email"
        # beside a name attribute "email" are two names (run 49: dropping "Email" refused every Workable
        # email action as drift).
        key = " ".join(text.split())
        if not _normalized_control_identity_text(text, limit=180) or text == "[REDACTED]" or key in seen:
            return
        seen.add(key)
        names.append(text)

    for key in ("text", "aria_label", "label", "placeholder", "name"):
        _append(raw.get(key))
    for entry in raw.get("accessibility_context") or []:
        if isinstance(entry, dict):
            _append(entry.get("text"))
    return names[:8]


def _observed_control_target_identity(
    control: dict[str, Any] | None,
    *,
    selector: Any = "",
    page_url: Any = "",
) -> dict[str, Any]:
    raw = control if isinstance(control, dict) else {}
    target_text = _observed_control_identity_text(raw)
    tag = _safe_trim(raw.get("tag"), 40).lower()
    # The observer records the dispatch path with the click's own closest("canvas,svg") rule (an
    # SVG descendant is cdp_trusted_click); the tag rule is only the fallback for a control the
    # observer did not stamp.
    observed_path = _safe_trim(raw.get("dispatch_path"), 40)
    dispatch_path = (
        observed_path
        if observed_path in {"cdp_trusted_click", "dom_activation"}
        else ("cdp_trusted_click" if tag in {"canvas", "svg"} else "dom_activation")
    )
    identity: dict[str, Any] = _final_target_identity(
        {
            "target_selector": _safe_control_selector(selector or raw.get("selector")),
            "target_text": target_text,
            "target_tag": tag,
            "target_type": raw.get("type") or raw.get("input_type"),
            "target_role": raw.get("role"),
            "dispatch_path": dispatch_path,
            "page_url": page_url,
        }
    )
    names = _observed_control_identity_names(raw)
    if names:
        identity["target_names"] = names
    # Where the control was observed (capture pixels, the space point-judging bodies work in): a body
    # may use it to tell an unnamed control from another at the same tree position. Others ignore it.
    try:
        box = [float(raw.get(key) or 0) for key in ("x", "y", "width", "height")]
    except (TypeError, ValueError):
        box = []
    if len(box) == 4 and box[2] > 0 and box[3] > 0:
        identity["target_box"] = [int(round(v)) for v in box]
    return identity


def _final_page_context(shot: dict[str, Any] | None) -> dict[str, str]:
    source = shot if isinstance(shot, dict) else {}
    screenshot_sha256 = _safe_trim(source.get("screenshot_sha256"), 128).lower()
    if not screenshot_sha256:
        try:
            raw_image = base64.b64decode(str(source.get("image") or ""), validate=True)
            screenshot_sha256 = hashlib.sha256(raw_image).hexdigest() if raw_image else ""
        except Exception:
            screenshot_sha256 = ""
    return {
        "url": _safe_trim(source.get("url"), 1000),
        "surface_signature": _safe_trim(source.get("surface_signature"), 160),
        "stable_surface_signature": _safe_trim(source.get("stable_surface_signature"), 160),
        "document_state_signature": _safe_trim(source.get("document_state_signature"), 160),
        # What a submit would carry (field values only): guarded intermediates on live pages bind to it.
        "document_value_signature": _safe_trim(
            source.get("document_value_signature")
            or (
                (source.get("page_evidence") or {}).get("document_value_signature")
                if isinstance(source.get("page_evidence"), dict)
                else ""
            ),
            160,
        ),
        # Every control's label, value, and state without DOM ids or the order of buttons and
        # links: what a page that re-renders itself with fresh ids keeps the same.
        "document_semantic_signature": _safe_trim(
            source.get("document_semantic_signature")
            or (
                (source.get("page_evidence") or {}).get("document_semantic_signature")
                if isinstance(source.get("page_evidence"), dict)
                else ""
            ),
            160,
        ),
        "document_lifecycle_token": _safe_trim(
            source.get("document_lifecycle_token")
            or (
                (source.get("page_evidence") or {}).get("document_lifecycle_token")
                if isinstance(source.get("page_evidence"), dict)
                else ""
            ),
            160,
        ),
        "state_fingerprint": _page_state_fingerprint(source),
        "screenshot_sha256": screenshot_sha256,
        "screenshot_mode": _safe_trim(source.get("screenshot_mode"), 80),
        "screenshot_quality": _safe_trim(source.get("screenshot_quality"), 8),
    }


_ROW_DIGEST_LIMIT = 240


def _safe_row_digests(value: Any) -> list[dict[str, Any]]:
    """Per-row digests of the observed document, shape-checked and bounded.

    The extension digests each rendered control row (its selector, whether it sits in a frame, and a hash of
    the row) and the title. Anything malformed, repeated, or over the limit returns an empty list, which the
    extension reads as "no row proof" and so keeps the strict whole-page check."""
    if not isinstance(value, list) or len(value) > _ROW_DIGEST_LIMIT + 1:
        return []
    rows: list[dict[str, Any]] = []
    for item in value:
        if not isinstance(item, dict):
            return []
        selector = item.get("selector")
        digest = item.get("digest")
        frame = item.get("frame")
        if not isinstance(selector, str) or len(selector) > 400:
            return []
        if not isinstance(digest, str) or not digest or len(digest) > 80:
            return []
        if type(frame) is not int or frame not in (0, 1):
            return []
        rows.append({"selector": selector, "frame": frame, "digest": digest})
    return rows


def _type_expected_page_context(shot: dict[str, Any] | None, *, credential_replay: bool) -> dict[str, Any]:
    """The page context a type action is revalidated against.

    A credential also carries the observation's per-row digests, so the extension can accept a drift that
    is confined to the named field (and nothing else). Other types keep the plain page context."""
    page_context = _final_page_context(shot)
    if credential_replay and isinstance(shot, dict):
        page_context["document_row_digests"] = _safe_row_digests(shot.get("document_row_digests"))
    return page_context


_CHAIN_PRIOR_CLICK_RADIUS_PX = 64
_CHAIN_PRIOR_CLICK_MAX_BOX_AREA = 40000


def _chain_prior_click_regions(
    prior_prepared: list[dict[str, Any]],
    coord_scale: float,
) -> list[dict[str, int]]:
    """Where the earlier clicks of this chain landed, in screenshot pixels: the drawn mark an earlier
    click leaves (a selection highlight, a ticked box) is the only pixel change the next coordinate click
    may tolerate. A small bound control contributes its box; anything larger (a whole canvas) contributes a
    small square around the point, so the tolerated area never grows to the surface."""
    regions: list[dict[str, int]] = []
    for item in prior_prepared:
        action = item.get("action") if isinstance(item.get("action"), dict) else {}
        if action.get("action") != "click":
            continue
        try:
            px = int(round(float(action.get("x")) * coord_scale))
            py = int(round(float(action.get("y")) * coord_scale))
        except (TypeError, ValueError):
            continue
        region = {
            "x": px - _CHAIN_PRIOR_CLICK_RADIUS_PX,
            "y": py - _CHAIN_PRIOR_CLICK_RADIUS_PX,
            "width": _CHAIN_PRIOR_CLICK_RADIUS_PX * 2,
            "height": _CHAIN_PRIOR_CLICK_RADIUS_PX * 2,
        }
        control = item.get("bound_control") if isinstance(item.get("bound_control"), dict) else None
        if control:
            try:
                cx, cy = int(control.get("x")), int(control.get("y"))
                cw, ch = int(control.get("width")), int(control.get("height"))
            except (TypeError, ValueError):
                cw = ch = 0
            if 0 < cw * ch <= _CHAIN_PRIOR_CLICK_MAX_BOX_AREA:
                region = {"x": cx, "y": cy, "width": cw, "height": ch}
        regions.append(region)
    return regions[:8]


def _final_page_context_matches(expected: dict[str, Any] | None, shot: dict[str, Any] | None) -> bool:
    if not isinstance(expected, dict):
        return False
    live = _final_page_context(shot)
    if not expected.get("url") or expected.get("url") != live.get("url"):
        return False
    expected_document_lifecycle = str(expected.get("document_lifecycle_token") or "")
    if (
        expected_document_lifecycle
        and expected_document_lifecycle != str(live.get("document_lifecycle_token") or "")
    ):
        return False
    document_state_signature = str(expected.get("document_state_signature") or "")
    stable_surface_signature = str(expected.get("stable_surface_signature") or "")
    stable_fields = (
        ("document_state_signature",)
        if document_state_signature
        else (("stable_surface_signature",) if stable_surface_signature else ())
    )
    expected_semantic = str(expected.get("document_semantic_signature") or "")
    for field in stable_fields:
        if str(expected.get(field) or "") != str(live.get(field) or ""):
            # Same document and every control still shows the same label, value, and state: only
            # DOM ids or the order of buttons and links changed (a page re-rendering itself). The
            # extension re-proves this immediately before dispatch and binds the one exact twin.
            if (
                field == "document_state_signature"
                and expected_semantic
                and expected_semantic == str(live.get("document_semantic_signature") or "")
            ):
                continue
            return False
    # The document-state signature is geometry- and viewport-independent, so approval survives a
    # scroll or resize while actual control/value state remains bound. Older extension builds fall
    # back to the stricter viewport structure, server state fingerprint, and pixel hash. The
    # extension still re-resolves the selector and requires the complete live target identity
    # immediately before activation.
    if not stable_fields:
        for field in ("surface_signature", "state_fingerprint", "screenshot_sha256"):
            expected_value = str(expected.get(field) or "")
            if expected_value and expected_value != str(live.get(field) or ""):
                return False
    return True


def _focus_moving_key(value: Any) -> bool:
    """Tab with any modifiers (Shift+Tab, Ctrl+Tab, Alt+Tab) moves keyboard focus -- to another field, tab or
    window -- whether or not the body reported where it went."""
    parts = [part for part in re.split(r"[\s+]+", str(value or "").casefold()) if part]
    return bool(parts) and parts[-1] == "tab"


def _activation_capable_key(value: Any) -> bool:
    """Recognize browser key primitives that can activate the currently focused control."""
    raw = str(value or "")
    if raw in {" ", "\r", "\n", "\r\n"}:
        return True
    token = re.sub(r"[\s_-]+", "", raw).casefold()
    if token in {"enter", "return", "numpadenter", "space", "spacebar"}:
        return True
    # A chord ending in one of them (Ctrl+Enter sends a message in many apps) activates as much (review).
    parts = [part for part in re.split(r"[\s+]+", raw.casefold()) if part]
    return len(parts) > 1 and re.sub(r"[_-]+", "", parts[-1]) in {"enter", "return", "numpadenter", "space", "spacebar"}


_KEYED_TEXT_INPUT_TYPES = frozenset(
    {"", "text", "search", "email", "url", "tel", "password"}
)


def _printable_key_chars(action: dict[str, Any] | None) -> str:
    """The characters a key action types: one printable character (Shift alone just shifts it), or the
    space key, times its repeat count. Empty for named keys, chords with Ctrl/Alt/Meta, and Enter/Tab."""
    raw = str((action or {}).get("key") or "")
    if not raw:
        return ""
    held = set(_gesture_modifiers(action))
    if held - {"shift"}:
        return ""
    if raw == " " or re.sub(r"[\s_-]+", "", raw).casefold() in {"space", "spacebar"}:
        char = " "
    else:
        parts = [raw] if len(raw) == 1 else raw.split("+")
        if len(parts) > 1 and parts[-1] == "":
            parts = [*parts[:-2], "+"]
        lead = {part.strip().casefold() for part in parts[:-1]}
        if lead - {"shift"}:
            return ""
        char = parts[-1]
        if len(char) != 1 or not char.isprintable():
            return ""
        if "shift" in held or "shift" in lead:
            char = char.upper()
    return char * max(1, _gesture_int(action, "amount", cap=200))


def _is_paste_chord(action: dict[str, Any] | None) -> bool:
    """Ctrl/Meta+V, Ctrl+Shift+V, and Shift+Insert (the key text or the modifiers field): a paste inserts
    whatever the clipboard holds, which is typing that text."""
    raw = str((action or {}).get("key") or "")
    if not raw:
        return False
    parts = [raw] if len(raw) == 1 else raw.split("+")
    if len(parts) > 1 and parts[-1] == "":
        parts = [*parts[:-2], "+"]
    last = re.sub(r"[\s_-]+", "", parts[-1]).casefold()
    lead = {re.sub(r"[\s_-]+", "", part).casefold() for part in parts[:-1]} | set(_gesture_modifiers(action))
    command = bool(lead & {"ctrl", "control", "meta", "cmd", "command", "super", "win", "windows"})
    return (last == "v" and command) or (last in {"insert", "ins"} and "shift" in lead)


_FRAME_FOCUS_TAGS = frozenset({"iframe", "frame", "object", "embed"})


def _control_is_frame(control: dict[str, Any] | None) -> bool:
    """Focus sits on a frame element: keys go to a field inside it that this page cannot see."""
    return isinstance(control, dict) and str(control.get("tag") or "").strip().casefold() in _FRAME_FOCUS_TAGS


def _keyed_text_toward_quote(text: str, quote: Any) -> str:
    """The keyed text carried to the end of the word it is part of in the cited quote (case-insensitive,
    beginning at a word start); the text itself when the quote does not hold it that way."""
    quote_text = str(quote or "")
    if not text or not quote_text:
        return text
    folded_quote = quote_text.casefold()
    folded = text.casefold()
    start = folded_quote.find(folded)
    while start != -1:
        if start == 0 or not folded_quote[start - 1].isalnum():
            end = start + len(text)
            while end < len(quote_text) and not quote_text[end].isspace():
                end += 1
            return quote_text[start:end]
        start = folded_quote.find(folded, start + 1)
    return text


def _control_is_editable_text(control: dict[str, Any] | None) -> bool:
    """A text-entry target by structure: textarea, text-like input (password included), contenteditable,
    or a textbox/searchbox role. Spinbuttons, sliders, canvases, buttons, and the page body are not."""
    if not isinstance(control, dict):
        return False
    tag = str(control.get("tag") or "").strip().casefold()
    role = str(control.get("role") or "").strip().casefold()
    input_type = str(control.get("type") or control.get("input_type") or "").strip().casefold()
    if role in {"spinbutton", "slider", "scrollbar"} or tag in {"canvas", "body", "html", "button", "select", "video", "audio"}:
        return False
    if control.get("value_redacted") is True:
        return True
    if tag == "textarea":
        return True
    if tag == "input":
        return input_type in _KEYED_TEXT_INPUT_TYPES
    if any(control.get(key) is True for key in ("editable", "accepts_text", "contenteditable")):
        return True
    return role in {"textbox", "searchbox"}


def _final_action_mode_for_user(user_id: int) -> str:
    if not user_id:
        return "approval"
    with SessionLocal() as db:
        mode = str(
            get_agent_settings(db, user_id).get("final_action_mode") or "approval"
        ).strip().lower()
    return mode if mode in {"approval", "autonomous"} else "approval"


_STANDING_ATTESTATION_QUESTION = (
    "Attestations asking me to confirm I have read or agree to something (for example terms, "
    "policies, or acknowledgements)"
)
_STANDING_ATTESTATION_ANSWER = (
    "Yes. In autonomous mode, confirm read/agree attestations on my behalf without asking me."
)


_STANDING_RELAY_CONSENT = (
    "Standing user authorization (full autonomy): carrying values between the task page and the desktop "
    "applications it opens, in either direction, and among those applications, is part of my task - including "
    "reference codes and IDs such an application shows for the task. Passwords and other credentials, API keys and "
    "tokens, private keys and seed phrases, one-time, verification, recovery, and backup codes, and payment data "
    "stay secret."
)


def _standing_relay_consent(user_id: int, final_action_mode: str) -> str:
    """The user's standing consent to page<->app relays, as trusted task text; empty when not given."""
    if final_action_mode != "autonomous":
        return ""
    try:
        from app.agent_settings import get_agent_settings

        with SessionLocal() as db:
            settings = get_agent_settings(db, user_id)
    except Exception:  # noqa: BLE001 - no standing consent is the safe default
        return ""
    return _STANDING_RELAY_CONSENT if settings.get("autonomous_relay_consent") else ""


def _standing_user_authorizations(user_id: int, final_action_mode: str) -> list[dict[str, str]]:
    """The user's standing answers that apply to this run, as human answers the model may cite."""
    if final_action_mode != "autonomous":
        return []
    try:
        from app.agent_settings import get_agent_settings

        with SessionLocal() as db:
            settings = get_agent_settings(db, user_id)
    except Exception:  # noqa: BLE001 - no standing answer is the safe default
        return []
    if not settings.get("autonomous_attestation_consent"):
        return []
    return [
        {
            "question": _STANDING_ATTESTATION_QUESTION,
            "answer": _STANDING_ATTESTATION_ANSWER,
            "source": "standing_user_authorization",
        }
    ]


def _final_action_mode_for_run(run_id: int, user_id: int) -> str:
    """Return the run-owned approval policy, falling back safely for legacy runs."""
    if run_id:
        from app import models

        with SessionLocal() as db:
            run = db.get(models.OperatorRun, run_id)
            state = dict((run.confidence_state or {}) if run else {})
            run_policy = (
                dict(state.get("final_action_policy") or {})
                if isinstance(state.get("final_action_policy"), dict)
                else {}
            )
            task = state.get("browser_task")
            task_policy = (
                dict(task.get("safety_policy") or {})
                if isinstance(task, dict) and isinstance(task.get("safety_policy"), dict)
                else {}
            )
            policy = run_policy or task_policy
            snapshotted = str(policy.get("final_action_mode") or "").strip().lower()
            if snapshotted in {"approval", "autonomous"}:
                return snapshotted
            if policy.get("consequential_actions") == "human_approval_required":
                return "approval"
    return _final_action_mode_for_user(user_id)


def _run_requires_final_action_handoff(run_id: int) -> bool:
    if not run_id:
        return False
    from app import models

    with SessionLocal() as db:
        run = db.get(models.OperatorRun, run_id)
        state = dict((run.confidence_state or {}) if run else {})
        workspace = dict(state.get("end_to_end") or {})
        raw_browser_task = state.get("browser_task")
        browser_task = dict(raw_browser_task) if isinstance(raw_browser_task, dict) else {}
        policy = dict(browser_task.get("safety_policy") or {})
        if _final_action_mode_for_run(run_id, int(getattr(run, "user_id", 0) or 0)) == "autonomous":
            return False
        return (
            str(workspace.get("submission_mode") or "").upper() in {"APPROVE_ONCE", "VERIFIED_SUBMIT", "FULL_AUTO_TRUSTED"}
            or policy.get("consequential_actions") == "human_approval_required"
        )


def _visible_payment_control_hit(page_evidence: dict[str, Any] | None) -> tuple[bool, str]:
    controls = (page_evidence or {}).get("controls") if isinstance(page_evidence, dict) else []
    if not isinstance(controls, list):
        return False, ""
    for raw in controls:
        if not isinstance(raw, dict):
            continue
        autocomplete = str(raw.get("autocomplete") or "").strip().lower()
        if autocomplete.startswith("cc-"):
            return True, f"autocomplete:{autocomplete[:40]}"
        control_type = str(raw.get("type") or "").strip().lower()
        if control_type in {"cc-number", "cc-exp", "cc-csc", "credit-card", "card-number", "card"}:
            return True, f"type:{control_type[:40]}"
    return False, ""


def _judge_final_action_payment(user_id: int, *, viewport_text: str, submit_label: str) -> dict[str, Any]:
    if (ablated := eval_ablation.benign_verdict("payment_floor_judge", "final_action_payment")) is not None:
        return ablated
    try:
        from app.lumen_model import LumenModelClient

        with SessionLocal() as db:
            return LumenModelClient(db, user_id=user_id).judge_payment_final_action(
                viewport_text=viewport_text,
                submit_label=submit_label,
            )
    except Exception as exc:  # noqa: BLE001 - mandatory floor fails closed
        return {
            "payment": True,
            "summary": "This final action may involve a payment or booking.",
            "reason": _exception_summary(exc),
            "metadata": {},
            "fail_closed": True,
        }


def _text_drawn_near_click(shot: dict[str, Any] | None, x: int, y: int, bound_control: dict[str, Any] | None) -> list[str]:
    """The text drawn around a desktop click on a control with no accessible name, read from the
    screenshot's own pixels (OCR of a band around the point), nearest line first. A Tk window exposes every
    radio, field, and button as an unnamed "Button": without this the click judge cannot tell an Approve
    radio from Submit (v5_memory Sonnet brain, 2026-10-06). Raw text only; the judge decides."""
    try:
        evidence = (shot or {}).get("page_evidence") if isinstance((shot or {}).get("page_evidence"), dict) else {}
        if str(evidence.get("execution_surface") or "") != "desktop":
            return []
        control = bound_control if isinstance(bound_control, dict) else {}
        if any(str(control.get(key) or "").strip() for key in ("text", "label", "aria_label", "context_text")):
            return []
        import io

        from PIL import Image

        from app import screen_ocr

        raw = base64.b64decode(str((shot or {}).get("image") or ""), validate=False)
        if not raw:
            return []
        with Image.open(io.BytesIO(raw)) as picture:
            left, top = max(0, int(x) - 220), max(0, int(y) - 40)
            region = (left, top, min(picture.width, int(x) + 220), min(picture.height, int(y) + 40))
            if region[2] - region[0] < 16 or region[3] - region[1] < 16:
                return []
            buffer = io.BytesIO()
            picture.convert("RGB").crop(region).save(buffer, format="PNG")
        lines = (screen_ocr.read_lines([buffer.getvalue()]) or [[]])[0]
        return [_safe_trim(line, 120) for line in lines[:6] if str(line).strip()]
    except Exception:  # noqa: BLE001 - no reading: the judge has the screenshot
        return []


_CLICK_JUDGE_SIBLING_LIMIT = 12
_CLICK_JUDGE_OTHER_LABEL_LIMIT = 30
_CLICK_JUDGE_VIEWPORT_TEXT = 1400
_CLICK_JUDGE_DIALOG_ROLES = {"dialog", "alertdialog"}


def _click_judge_in_dialog(row: dict[str, Any]) -> bool:
    """Raw evidence that the control sits in a dialog/modal layer (role, aria-modal, ancestor chain)."""

    if not isinstance(row, dict):
        return False
    if str(row.get("role") or "").lower() in _CLICK_JUDGE_DIALOG_ROLES:
        return True
    if str(row.get("aria_modal") or "").lower() == "true":
        return True
    chain = row.get("ancestor_chain")
    if isinstance(chain, list):
        for item in chain:
            if not isinstance(item, dict):
                continue
            if str(item.get("role") or "").lower() in _CLICK_JUDGE_DIALOG_ROLES:
                return True
            if str(item.get("aria_modal") or item.get("aria-modal") or "").lower() == "true":
                return True
            if str(item.get("tag") or "").lower() == "dialog":
                return True
    try:
        return float(row.get("stack_layer") or 0) > 0
    except (TypeError, ValueError):
        return False


def _click_judge_viewport_text(raw_text: Any, target: dict[str, Any], limit: int) -> tuple[str, bool]:
    """The viewport text trimmed to `limit` around the target (its container's text first), then the page head.

    Portal modals come last in DOM order, so a plain head cut loses the consequence wording that sits
    right before a bare "Confirm". Returns the text and whether anything was cut.
    """

    text = " ".join(str(raw_text or "").split())
    if len(text) <= limit:
        return text, False
    needle = ""
    for key in ("context_text", "text", "aria_label", "label"):
        candidate = " ".join(str(target.get(key) or "").split())
        if len(candidate) >= 2 and text.rfind(candidate) >= 0:
            needle = candidate
            break
    if not needle:
        window_size = limit // 2
        return text[: limit - window_size - 5] + " ... " + text[-window_size:], True
    pos = text.rfind(needle)
    window_size = (limit * 3) // 5
    start = max(0, min(pos + len(needle) + window_size // 4 - window_size, len(text) - window_size))
    window = text[start : start + window_size]
    head_room = limit - len(window) - 5
    head = text[:head_room] if start > head_room else ""
    return (f"{window} ... {head}" if head else window), True


def _click_judge_control_label(row: dict[str, Any], limit: int = 80) -> str:
    for key in ("text", "aria_label", "label", "value", "placeholder"):
        text = " ".join(str(row.get(key) or "").split())
        if text:
            return text[:limit]
    return ""


def _click_judge_box_center(row: dict[str, Any]) -> tuple[float, float]:
    try:
        return (
            float(row.get("x") or 0) + float(row.get("width") or 0) / 2.0,
            float(row.get("y") or 0) + float(row.get("height") or 0) / 2.0,
        )
    except (TypeError, ValueError):
        return (0.0, 0.0)


def _click_judge_container_ids(row: dict[str, Any]) -> set[str]:
    chain = row.get("ancestor_chain")
    if not isinstance(chain, list):
        return set()
    return {
        str(item.get("id") or "").strip()
        for item in chain
        if isinstance(item, dict) and str(item.get("id") or "").strip()
    }


def _click_consequence_evidence(
    shot: dict[str, Any] | None,
    bound_control: dict[str, Any] | None,
    *,
    drawn_text: bool = False,
) -> tuple[dict[str, Any], bool]:
    """The page evidence the click-consequence judge reads, and whether it also needs the screenshot.

    Context-window management, not perception: the selected control in full, the controls that share
    its container (same container id or surrounding text first, then the nearest on screen), a one-line
    label for every other control (so a Submit elsewhere on the page is still known), and the visible
    text (dialog and section headings, confirmation wording). The screenshot is kept whenever the
    control has no accessible text of its own, is occluded, is canvas-like, is not one of the listed
    controls, or the surface is a native window; the evidence stays complete for every such case.
    """

    from app.vision_agent import compact_page_evidence

    evidence = (shot or {}).get("page_evidence") if isinstance((shot or {}).get("page_evidence"), dict) else {}
    base = compact_page_evidence(
        {key: value for key, value in evidence.items() if key != "controls"},
        viewport_text_limit=_CLICK_JUDGE_VIEWPORT_TEXT,
    )
    raw_controls = [row for row in (evidence.get("controls") or []) if isinstance(row, dict)]
    target = bound_control if isinstance(bound_control, dict) else {}
    viewport_text, text_truncated = _click_judge_viewport_text(
        evidence.get("viewport_text"), target, _CLICK_JUDGE_VIEWPORT_TEXT
    )
    if viewport_text:
        base["viewport_text"] = viewport_text
    target_listed: dict[str, Any] | None = None
    if target:
        for row in raw_controls:
            if (
                row.get("index") is not None
                and row.get("index") == target.get("index")
                and row.get("x") == target.get("x")
                and row.get("y") == target.get("y")
            ):
                target_listed = row
                break
    others = [row for row in raw_controls if row is not target_listed]
    tx, ty = _click_judge_box_center(target)
    target_ids = _click_judge_container_ids(target)
    target_context = " ".join(str(target.get("context_text") or "").split())

    def _rank(row: dict[str, Any]) -> tuple[int, float]:
        cx, cy = _click_judge_box_center(row)
        shares_container = bool(
            (target_ids and target_ids & _click_judge_container_ids(row))
            or (target_context and target_context == " ".join(str(row.get("context_text") or "").split()))
        )
        return (0 if shares_container else 1, (cx - tx) ** 2 + (cy - ty) ** 2)

    ranked = sorted(others, key=_rank)
    siblings = sorted(
        ranked[:_CLICK_JUDGE_SIBLING_LIMIT],
        key=lambda row: (_click_judge_box_center(row)[1], _click_judge_box_center(row)[0]),
    )
    sibling_rows: list[dict[str, Any]] = []
    for row in siblings:
        slim: dict[str, Any] = {"index": row.get("index")}
        for key in ("tag", "role", "type"):
            if row.get(key):
                slim[key] = row[key]
        label = _click_judge_control_label(row)
        if label:
            slim["text"] = label
        for key in ("disabled", "checked", "selected"):
            if row.get(key):
                slim[key] = row[key]
        for key in ("href", "form_action"):
            if row.get(key):
                slim[key] = " ".join(str(row[key]).split())[:200]
        slim["box"] = [row.get("x"), row.get("y"), row.get("width"), row.get("height")]
        sibling_rows.append(slim)
    listed = {id(row) for row in siblings}
    other_labels = [
        f"{row.get('index')}|{str(row.get('tag') or '')}{('/' + str(row['type'])) if row.get('type') else ''}|"
        f"{_click_judge_control_label(row, 40)}"
        for row in others
        if id(row) not in listed and _click_judge_control_label(row, 40)
    ][:_CLICK_JUDGE_OTHER_LABEL_LIMIT]
    page: dict[str, Any] = dict(base)
    page["controls_in_target_container"] = sibling_rows
    if other_labels:
        page["other_controls_on_page"] = other_labels
    page["evidence_scope"] = (
        "Trimmed: viewport text, the selected control in full, its container's controls, and a one-line "
        "label for the other controls; not the full control inventory."
    )
    source = target_listed or target
    accessible = any(
        sum(ch.isalnum() for ch in str(source.get(key) or "")) >= 2 for key in ("text", "aria_label", "label")
    )
    surface = str(evidence.get("execution_surface") or "")
    needs_image = bool(
        not target
        or not accessible
        or drawn_text
        or text_truncated
        or surface == "desktop"
        or target.get("_destination_unknown") is True
        or any(
            row.get("occluded") is True
            or str(row.get("tag") or "").lower() in {"canvas", "svg", "img", "object", "embed", "iframe"}
            for row in (target, source)
        )
        or any(_click_judge_in_dialog(row) for row in (target, source))
        or not raw_controls
    )
    return page, needs_image


def _judge_click_consequence_unfloored(
    user_id: int,
    *,
    goal: str,
    safety_policy: dict[str, Any],
    shot: dict[str, Any],
    action: dict[str, Any],
    bound_control: dict[str, Any] | None,
    selector: str,
    x: int,
    y: int,
    recent_verified_history: list[dict[str, Any]],
    operator_instructions: list[dict[str, Any]],
    preceding_step: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Ask the brain what the exact selected click would do before any browser activation.

    The runtime supplies raw evidence and validates only the returned schema. It never infers
    consequence from a label, URL, element type, or the user's goal text.
    """

    if (ablated := eval_ablation.benign_verdict("click_consequence_judge", "preflight", user_id=user_id, page_evidence=(shot or {}).get("page_evidence"))) is not None:
        return ablated
    try:
        from app.lumen_model import LumenModelClient
        from app.vision_agent import compact_page_evidence

        drawn = _text_drawn_near_click(shot, x, y, bound_control)
        trimmed_page, needs_image = _click_consequence_evidence(shot, bound_control, drawn_text=bool(drawn))
        image_data = str((shot or {}).get("image") or "")
        image = {"media_type": "image/jpeg", "data": image_data} if image_data and needs_image else None
        raw_control = compact_page_evidence(
            {"controls": [bound_control]} if isinstance(bound_control, dict) else {},
            control_limit=1,
        ).get("controls") or []
        if raw_control and isinstance(bound_control, dict):
            # What the control leads to or belongs to, which the compact inventory leaves out.
            for key in ("href", "form_action", "row_text", "affordances"):
                if bound_control.get(key):
                    raw_control[0][key] = (
                        bound_control[key]
                        if key == "affordances"
                        else " ".join(str(bound_control[key]).split())[:300]
                    )
        payload = {
            "evaluation_stage": "before_browser_activation",
            "goal": _safe_trim(goal, 4000),
            "safety_policy": dict(safety_policy or {}),
            "operator_instructions": [
                dict(item)
                for item in (operator_instructions or [])[-6:]
                if isinstance(item, dict)
            ],
            "page": {
                "url": _safe_trim((shot or {}).get("url"), 1000),
                "title": _safe_trim((shot or {}).get("title"), 240),
                "raw_observation": trimmed_page,
            },
            "selected_click": {
                "control_index": _action_control_index(action),
                "selector": _safe_control_selector(selector),
                "control_signature": _control_signature(bound_control),
                "x": int(x or 0),
                "y": int(y or 0),
                "explicit_text": _safe_trim((action or {}).get("text"), 180),
                "reason": _safe_trim((action or {}).get("reason"), 500),
                "raw_control": raw_control[0] if raw_control else {},
                **({"text_drawn_near_click": drawn} if drawn else {}),
                # A chained click runs after another step of the same decision (a typed confirmation
                # phrase, a code): the judge rules on the observation from before that step.
                **({"runs_after": dict(preceding_step)} if isinstance(preceding_step, dict) and preceding_step else {}),
            },
            "recent_verified_history": [
                dict(item)
                for item in (recent_verified_history or [])[-6:]
                if isinstance(item, dict)
            ],
        }
        with SessionLocal() as db:
            return LumenModelClient(db, user_id=user_id).judge_blocked_click_semantics(payload, image=image)
    except Exception as exc:  # noqa: BLE001 - model/provider failure must withhold the click
        return {
            "classification": "uncertain",
            "confidence": 0.0,
            "evidence": _exception_summary(exc),
            "metadata": {},
            "fail_closed": True,
        }


def _judge_click_consequence(
    user_id: int,
    *,
    goal: str,
    safety_policy: dict[str, Any],
    shot: dict[str, Any],
    action: dict[str, Any],
    bound_control: dict[str, Any] | None,
    selector: str,
    x: int,
    y: int,
    recent_verified_history: list[dict[str, Any]],
    operator_instructions: list[dict[str, Any]],
    preceding_step: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """The click-consequence verdict under the run's monotonic floor: a control judged stricter
    earlier in the run is never later judged more leniently (model flip-flops must not steer the gate)."""

    verdict = _judge_click_consequence_unfloored(
        user_id,
        goal=goal,
        safety_policy=safety_policy,
        shot=shot,
        action=action,
        bound_control=bound_control,
        selector=selector,
        x=x,
        y=y,
        recent_verified_history=recent_verified_history,
        operator_instructions=operator_instructions,
        preceding_step=preceding_step,
    )
    run_id = model_call_ledger.current_run()
    key = consequence_floor.control_key(
        url=(shot or {}).get("url") if isinstance(shot, dict) else "",
        selector=selector,
        control=bound_control,
    )
    verdict, override = consequence_floor.enforce_click(run_id, key, verdict)
    if override and run_id:
        try:
            _db_event(
                run_id,
                "CLICK_CONSEQUENCE_MONOTONIC_OVERRIDE",
                {**override, "control_signature": _control_signature(bound_control)},
            )
        except Exception:  # noqa: BLE001 - the stricter verdict already stands
            pass
    return verdict


def _judge_blocked_click_semantics(
    user_id: int,
    *,
    goal: str,
    shot: dict[str, Any],
    action: dict[str, Any],
    blocked_result: dict[str, Any],
) -> dict[str, Any]:
    """Ask the brain what one conservatively intercepted click means; fail closed."""

    if (ablated := eval_ablation.benign_verdict("click_consequence_judge", "intercepted_click", user_id=user_id, page_evidence=(shot or {}).get("page_evidence"))) is not None:
        return ablated
    try:
        from app.lumen_model import LumenModelClient
        from app.vision_agent import compact_page_evidence

        image_data = str((shot or {}).get("image") or "")
        image = {"media_type": "image/jpeg", "data": image_data} if image_data else None
        raw_detection = blocked_result.get("submit_detection") if isinstance(blocked_result, dict) else {}
        detection = {
            key: raw_detection.get(key)
            for key in (
                "tag",
                "type_attribute",
                "resolved_type",
                "role",
                "inside_form",
                "form_owner",
                "href",
                "text",
                "form_field_count",
            )
            if isinstance(raw_detection, dict) and raw_detection.get(key) not in (None, "")
        }
        payload = {
            "goal": _safe_trim(goal, 500),
            "page": {
                "url": _safe_trim((shot or {}).get("url"), 500),
                "title": _safe_trim((shot or {}).get("title"), 200),
                "evidence": compact_page_evidence((shot or {}).get("page_evidence") or {}, control_limit=24),
            },
            "planned_action": {
                "reason": _safe_trim((action or {}).get("reason"), 500),
                "grounding_source": _safe_trim((action or {}).get("grounding_source"), 80),
                "grounding_quote": _safe_trim((action or {}).get("grounding_quote"), 300),
                "control_index": (action or {}).get("control_index"),
            },
            "intercepted_control": {
                "label": _safe_trim((blocked_result or {}).get("target_label") or (blocked_result or {}).get("label"), 120),
                "detection_basis": _safe_trim((blocked_result or {}).get("submit_detection_basis"), 40),
                "selector_present": bool(_safe_control_selector((blocked_result or {}).get("selector"))),
                "raw_structure": detection,
            },
        }
        with SessionLocal() as db:
            return LumenModelClient(db, user_id=user_id).judge_blocked_click_semantics(payload, image=image)
    except Exception as exc:  # noqa: BLE001 - ambiguous intercepted clicks stay behind approval
        return {
            "classification": "uncertain",
            "confidence": 0.0,
            "evidence": _exception_summary(exc),
            "metadata": {},
        }


def _payment_floor_verdict(
    user_id: int,
    *,
    page_evidence: dict[str, Any] | None,
    submit_label: str,
    selector: str = "",
) -> dict[str, Any]:
    """Payment verdict, sticky toward payment per control for the run (see consequence_floor)."""
    verdict = _payment_floor_verdict_unfloored(user_id, page_evidence=page_evidence, submit_label=submit_label)
    run_id = model_call_ledger.current_run()
    url = (page_evidence or {}).get("url") if isinstance(page_evidence, dict) else ""
    key = consequence_floor.payment_key(url=url, selector=selector, label=submit_label)
    verdict, overridden = consequence_floor.enforce_payment(run_id, key, verdict)
    if overridden and run_id:
        try:
            _db_event(run_id, "PAYMENT_FLOOR_MONOTONIC_OVERRIDE", {"label": _safe_trim(submit_label, 120)})
        except Exception:  # noqa: BLE001 - the sticky verdict already stands
            pass
    return verdict


def _payment_floor_verdict_unfloored(
    user_id: int, *, page_evidence: dict[str, Any] | None, submit_label: str
) -> dict[str, Any]:
    deterministic_hit, deterministic_reason = _visible_payment_control_hit(page_evidence)
    viewport_text = str((page_evidence or {}).get("viewport_text") or "")[:1200] if isinstance(page_evidence, dict) else ""
    judge = _judge_final_action_payment(user_id, viewport_text=viewport_text, submit_label=submit_label)
    judge_payment = (judge or {}).get("payment")
    judge_fail_closed = bool((judge or {}).get("fail_closed"))
    judge_unknown = bool(judge_fail_closed or judge_payment not in {True, False})
    # Classifier uncertainty still withholds the final action behind the normal
    # exact-action approval floor. It must not be rendered as affirmative evidence
    # that a payment, booking, or default payment method exists.
    payment = bool(deterministic_hit or (judge_payment is True and not judge_fail_closed))
    payment_unknown = bool(not deterministic_hit and judge_unknown)
    summary = _safe_trim((judge or {}).get("summary"), 200) if payment else ""
    if payment and not summary:
        summary = "This final action may involve a payment or booking."
    return {
        "payment": payment,
        "payment_unknown": payment_unknown,
        "deterministic_hit": bool(deterministic_hit),
        "deterministic_reason": deterministic_reason,
        "judge_payment": judge_payment if isinstance(judge_payment, bool) else None,
        "judge_reason": (judge or {}).get("reason") or "",
        "summary": summary,
        "metadata": (judge or {}).get("metadata") if isinstance((judge or {}).get("metadata"), dict) else {},
        "fail_closed": judge_unknown,
    }


def _load_pending_final_action(run_id: int) -> dict[str, Any] | None:
    if not run_id:
        return None
    from app import models

    with SessionLocal() as db:
        run = db.get(models.OperatorRun, run_id)
        if not run:
            return None
        pending = (run.confidence_state or {}).get(_PENDING_FINAL_ACTION_KEY)
        return dict(pending) if isinstance(pending, dict) else None


def _persist_pending_final_action(
    run_id: int,
    pending: dict[str, Any],
    *,
    replace: bool = False,
) -> None:
    if not run_id:
        return
    from app import models

    with SessionLocal() as db:
        run = db.get(models.OperatorRun, run_id)
        if not run:
            return
        state = dict(run.confidence_state or {})
        # Status patches merge into the current lifecycle record. A newly intercepted exact action
        # replaces it completely so consumed authorization, failure diagnostics, and stale page
        # bindings can never leak into a fresh approval.
        current = {} if replace else dict(state.get(_PENDING_FINAL_ACTION_KEY) or {})
        current.update({key: value for key, value in pending.items() if value is not None})
        state[_PENDING_FINAL_ACTION_KEY] = current
        run.confidence_state = state
        run.updated_at = utcnow()
        db.commit()


def _update_pending_final_action_status(run_id: int, status: str, patch: dict[str, Any] | None = None) -> None:
    if not run_id:
        return
    patch = dict(patch or {})
    patch.update({"status": status, "updated_at": utcnow().isoformat()})
    _persist_pending_final_action(run_id, patch)


def _claim_approved_final_action(run_id: int) -> dict[str, Any] | None:
    """Atomically claim one approved final action inside this runtime process.

    The persistent ``executing`` state is intentionally not auto-retried after a crash because the
    click may already have happened even if its response was lost.
    """
    if not run_id:
        return None
    from app import models
    from sqlalchemy import update

    with _FINAL_ACTION_CLAIM_LOCK:
        # Retry one benign optimistic-version collision. A lifecycle transition out of the live
        # states, or any loss of approved status, remains an immediate fail-closed rejection.
        for _attempt in range(2):
            with SessionLocal() as db:
                run = db.get(models.OperatorRun, run_id)
                if not run:
                    return None
                db.refresh(run)
                if str(run.current_state or "").upper() not in {"RUNNING", "WAITING_FOR_USER"}:
                    return None
                state = dict(run.confidence_state or {})
                pending = dict(state.get(_PENDING_FINAL_ACTION_KEY) or {})
                if str(pending.get("status") or "") != "approved":
                    return None
                authorization = (
                    dict(pending.get("authorization") or {})
                    if isinstance(pending.get("authorization"), dict)
                    else {}
                )
                try:
                    authorization_question_id = int(authorization.get("question_id") or 0)
                    pending_question_id = int(pending.get("question_id") or 0)
                except (TypeError, ValueError):
                    authorization_question_id = 0
                    pending_question_id = 0
                if (
                    str(authorization.get("source") or "")
                    not in {"human_chat", "question_answer_endpoint"}
                    or not pending.get("approval_token")
                    or not pending_question_id
                    or authorization_question_id != pending_question_id
                    or pending.get("retry_source")
                    or pending.get("retry_instruction_id")
                ):
                    # Stale retry-shaped or unbound approval state is never executable.
                    return None
                pending.update(
                    {
                        "status": "executing",
                        "execution_id": secrets.token_urlsafe(18),
                        "execution_started_at": utcnow().isoformat(),
                    }
                )
                state[_PENDING_FINAL_ACTION_KEY] = pending
                claimed = db.execute(
                    update(models.OperatorRun)
                    .where(
                        models.OperatorRun.id == run_id,
                        models.OperatorRun.current_state.in_(("RUNNING", "WAITING_FOR_USER")),
                        models.OperatorRun.updated_at == run.updated_at,
                    )
                    .values(confidence_state=state, updated_at=utcnow())
                )
                if claimed.rowcount == 1:
                    db.commit()
                    return pending
                db.rollback()
        return None


def _validated_final_approval_context(
    target: dict[str, Any],
    *,
    page_evidence: dict[str, Any] | None,
    receipts: list[dict[str, Any]],
) -> dict[str, Any]:
    """Validate provenance without deterministically interpreting the page."""
    summary = _safe_trim(target.get("approval_context_summary"), 800)
    raw_quotes = target.get("approval_context_evidence")
    quotes = [
        _safe_trim(item, 240)
        for item in (raw_quotes if isinstance(raw_quotes, list) else [])
        if _safe_trim(item, 240)
    ][:6]
    verified_receipts = [
        item
        for item in _recent_verified_receipt_history(receipts, limit=12)
        if str(item.get("outcome") or "") == "verified_succeeded"
    ]
    page_blob = " ".join(
        json.dumps(page_evidence or {}, ensure_ascii=False, sort_keys=True, default=str).split()
    ).casefold()
    receipt_blob = " ".join(
        json.dumps(verified_receipts, ensure_ascii=False, sort_keys=True, default=str).split()
    ).casefold()
    # The brain reads receipts as rendered one-line text (receipt_view), so a quote of that text counts too.
    # Only the facts (what was read back or observed), never the head: a target label is the click's own
    # nomination, not evidence of the page.
    from app.receipt_view import receipt_parts

    rendered_blob = " | ".join(
        " ".join(fact.split())
        for fact_list in (
            receipt_parts(item, detailed=detailed)[1]
            for item in (receipts or [])[-12:]
            if isinstance(item, dict) and item.get("outcome") == "verified_succeeded"
            for detailed in (True, False)
        )
        for fact in fact_list
    ).casefold()
    evidence_blob = f"{page_blob} {receipt_blob} {rendered_blob}".strip()
    unmatched = [
        quote
        for quote in quotes
        if " ".join(quote.split()).casefold() not in evidence_blob
    ]
    quotes_valid = bool(quotes) and not unmatched
    if summary and quotes_valid:
        return {
            "summary": summary,
            "evidence": quotes,
            "source": "model_grounded_current_evidence",
            "valid": True,
        }
    # What was missing, so the refusal feedback can name the exact repair.
    return {
        "summary": "",
        "evidence": [],
        "source": "missing_grounded_approval_context",
        "valid": False,
        "summary_missing": not summary,
        "evidence_missing": not quotes,
        "unmatched_evidence": unmatched,
    }


def _final_approval_context_feedback(
    target: dict[str, Any],
    approval_context: dict[str, Any],
    *,
    refusal: int,
    limit: int,
) -> str:
    """Why a consequential click was withheld for ungrounded approval context, and what a renomination carries."""
    label = _safe_trim(target.get("label") or "final action", 80)
    control_index = target.get("control_index")
    control = f" (control {control_index})" if isinstance(control_index, int) and control_index > 0 else ""
    classification = _safe_trim(target.get("risk_classification"), 40)
    risk_evidence = _safe_trim(target.get("risk_evidence"), 200)
    if classification:
        why = f"its consequence check rated it {classification}" + (f' ("{risk_evidence}")' if risk_evidence else "")
    else:
        why = "the browser identified it as a final submit control"
    gaps: list[str] = []
    if approval_context.get("summary_missing"):
        gaps.append("approval_context_summary was empty")
    if approval_context.get("evidence_missing"):
        gaps.append("approval_context_evidence was empty")
    unmatched = [
        _safe_trim(quote, 80)
        for quote in (approval_context.get("unmatched_evidence") or [])
        if _safe_trim(quote, 80)
    ][:3]
    if unmatched:
        gaps.append(
            "these approval_context_evidence quotes are not verbatim in page_evidence or verified_receipts: "
            + json.dumps(unmatched, ensure_ascii=False)
        )
    return (
        f"final_approval_context_ungrounded (refusal {refusal} of {limit}): your click on \"{label}\"{control} was "
        f"withheld before execution because {why}, and a consequential click must state what it commits, grounded "
        f"in current evidence. {'; '.join(gaps) or 'The approval context was not grounded'}. If this click is still "
        "the right next step, nominate it again with approval_context_summary set to one sentence on what it "
        "commits and approval_context_evidence set to one to six short quotes copied character for character from "
        "page_evidence text or verified_receipts (text visible only in the screenshot does not count). If it is "
        "not the right step, choose a different action. Nothing was clicked."
    )


def _blocked_submit_target(
    result: dict[str, Any] | None,
    *,
    action: dict[str, Any] | None,
    bound_label: str | None,
    control_selector: str | None,
    x: int,
    y: int,
) -> dict[str, Any]:
    result = result if isinstance(result, dict) else {}
    label = _safe_trim(result.get("target_label") or result.get("label") or bound_label or (action or {}).get("reason") or "final action", 120)
    selector = _safe_control_selector(result.get("selector")) or _safe_control_selector(control_selector)
    identity = _final_target_identity({**result, "selector": selector})
    return {
        "selector": selector,
        "label": label or "final action",
        "x": int(result.get("x") or x or 0),
        "y": int(result.get("y") or y or 0),
        "target_identity": identity,
        "approval_context_summary": _safe_trim((action or {}).get("approval_context_summary"), 800),
        "approval_context_evidence": [
            _safe_trim(item, 240)
            for item in (
                (action or {}).get("approval_context_evidence")
                if isinstance((action or {}).get("approval_context_evidence"), list)
                else []
            )
            if _safe_trim(item, 240)
        ][:6],
        "submit_detection_basis": _safe_trim(result.get("submit_detection_basis"), 40),
        "submit_detection": dict(result.get("submit_detection") or {}) if isinstance(result.get("submit_detection"), dict) else {},
    }


def _final_action_approval_prompt(label: Any) -> str:
    target = _safe_trim(label or "final action", 120)
    return f'Lumen reached the final action and paused for your approval. Should I execute "{target}" now?'


def _front_window_text_entry(shot: dict[str, Any] | None) -> dict[str, Any]:
    """The real screen's front window read from its own pixels ({"window_text": [lines]}), or {}.

    A native window drawn by a toolkit such as Tk exposes nothing to UI Automation: its result (a status
    line saying the request was dispatched) shows only in pixels, and an outcome verifier comparing control
    trees saw before and after as identical on every submit (v5_memory runs 1704/1711). The screenshot the
    verifier gets already shows these pixels; this is the same text, read exactly.
    """
    lines = _front_window_text_lines(shot)
    return {"window_text": [_safe_trim(line["text"], 160) for line in lines[:40]]} if lines else {}


def _front_window_text_lines(shot: dict[str, Any] | None) -> list[dict[str, Any]]:
    """The front window's OCR lines, each {"text", "words": [{"t", "x", "y", "w", "h"}]} with its word
    boxes in the capture's pixels (the shot image the model's screenshot is scaled from), top first;
    [] off the desktop, for a browser page, or when nothing reads."""
    try:
        from app import screen_ocr

        evidence = (shot or {}).get("page_evidence") if isinstance((shot or {}).get("page_evidence"), dict) else {}
        if str(evidence.get("execution_surface") or "") != "desktop":
            return []
        active = next(
            (item for item in (evidence.get("windows") or []) if isinstance(item, dict) and item.get("active")),
            None,
        )
        box = (active or {}).get("image_box") if isinstance(active, dict) else None
        if not (isinstance(box, list) and len(box) == 4) or active.get("document_url"):
            return []
        # Only the window's own pixels: whatever other windows draw over it (a toast, an always-on-top
        # tool) is blacked out, and unknown stacking reads nothing.
        crop = _window_view_crop(
            {"title": active.get("title"), "image_box": box, "drawn_over": active.get("drawn_over")},
            {"data": (shot or {}).get("image")},
        )
        if not crop:
            return []
        png, (origin_x, origin_y) = crop
        images = [png]
        highlighted = _highlights_inverted_png(png)
        if highlighted:
            # OCR does not read light text on a selection color: a Tk combobox keeps its chosen value
            # white on blue, and v5_memory run 1723 could not tell which route it had picked. The
            # recolored view has the crop's own size, so its boxes share the crop's pixels.
            images.append(highlighted)
        readings = screen_ocr.read_text_lines(images) or [[]]
        lines = [line for line in readings[0] if isinstance(line, dict)]
        seen = {" ".join(str(line.get("text") or "").split()).lower() for line in lines}
        for line in readings[1] if len(readings) > 1 else []:
            key = " ".join(str((line or {}).get("text") or "").split()).lower() if isinstance(line, dict) else ""
            if key and key not in seen:
                seen.add(key)
                lines.append(line)
        return [
            {
                "text": str(line.get("text") or ""),
                "words": [
                    {
                        "t": str(word.get("t") or ""),
                        "x": float(word.get("x") or 0) + origin_x,
                        "y": float(word.get("y") or 0) + origin_y,
                        "w": float(word.get("w") or 0),
                        "h": float(word.get("h") or 0),
                    }
                    for word in (line.get("words") or [])
                    if isinstance(word, dict)
                ],
            }
            for line in lines
            if str(line.get("text") or "").strip()
        ]
    except Exception:  # noqa: BLE001 - no reading: the verifier has the screenshot
        return []


# The brain's front_window_text: at most this many drawn runs, each this long.
_FRONT_WINDOW_TEXT_LINES = 40
_FRONT_WINDOW_TEXT_CHARS = 140
# A gap wider than this many word heights between two words of one OCR line parts them: two buttons
# side by side ("Cancel   Submit") read as one line, and one box around both centers between them.
_FRONT_WINDOW_RUN_GAP = 1.2


def _front_window_text_for_model(lines: list[dict[str, Any]], coord_scale: float) -> list[str]:
    """The front window's OCR lines as the brain reads them: "[x,y,w,h] text", the box where that text
    is drawn in the model's screenshot pixels (capture pixels / coord_scale, as control boxes are
    projected). A line whose words stand far apart is split into its runs, each with its own box. Only
    a reading: no box is a control the runtime binds or evidence a fact is grounded in."""
    try:
        scale = float(coord_scale or 1.0)
    except (TypeError, ValueError):
        scale = 1.0
    if not math.isfinite(scale) or scale <= 0:
        scale = 1.0
    entries: list[str] = []
    for line in lines or []:
        words = [word for word in (line.get("words") or []) if isinstance(word, dict) and str(word.get("t") or "")]
        if not words:
            continue
        heights = sorted(float(word.get("h") or 0) for word in words)
        reach = max(1.0, heights[len(heights) // 2]) * _FRONT_WINDOW_RUN_GAP
        runs: list[list[dict[str, Any]]] = [[words[0]]]
        for word in words[1:]:
            last = runs[-1][-1]
            gap = float(word.get("x") or 0) - (float(last.get("x") or 0) + float(last.get("w") or 0))
            if gap > reach:
                runs.append([word])
            else:
                runs[-1].append(word)
        whole = len(runs) == 1
        for run in runs:
            left = min(float(word.get("x") or 0) for word in run)
            top = min(float(word.get("y") or 0) for word in run)
            right = max(float(word.get("x") or 0) + float(word.get("w") or 0) for word in run)
            bottom = max(float(word.get("y") or 0) + float(word.get("h") or 0) for word in run)
            text = str(line.get("text") or "") if whole else " ".join(str(word.get("t")) for word in run)
            text = " ".join(text.split())[:_FRONT_WINDOW_TEXT_CHARS]
            x, y = int(round(left / scale)), int(round(top / scale))
            width = max(1, int(round(right / scale)) - x)
            height = max(1, int(round(bottom / scale)) - y)
            entries.append(f"[{x},{y},{width},{height}] {text}")
            if len(entries) >= _FRONT_WINDOW_TEXT_LINES:
                return entries
    return entries


def _highlights_inverted_png(png: bytes) -> bytes:
    """The window view with its selection highlights as dark text on white, or b"" when it has none."""
    try:
        import io

        from PIL import Image

        from app.desktop_body import _highlights_inverted

        with Image.open(io.BytesIO(png)) as image:
            inverted = _highlights_inverted(image.convert("RGB"))
        if inverted is None:
            return b""
        buffer = io.BytesIO()
        inverted.save(buffer, format="PNG")
        return buffer.getvalue()
    except Exception:  # noqa: BLE001 - one reading only
        return b""


# The outcome verifier's page packet (final action, reversible-click readback, expected effect). It judges
# one action's effect from the screenshot, the visible text and the controls' own state, so each control row
# keeps only what names it and what state it shows: no DOM context, ancestor chain, nearby/context text,
# CSS colors, classes, ARIA wiring or boxes (the visible text already carries the page's words, and these
# made a row ~2 KB: 40 rows were ~90% of the verifier's input). The text those rows carried from outside the
# viewport is kept once per page (context_text). The text window is wider than the brain's compact one so a
# message lower on the page stays in view.
_OUTCOME_VIEWPORT_TEXT_CHARS = 2400
_OUTCOME_CONTEXT_TEXT_CHARS = 1600
_OUTCOME_PAGE_KEYS = (
    "url",
    "title",
    "viewport_text",
    "scroll_y",
    "scroll_height",
    "below_fold_change",
    "caret",
    "focused_text_lines",
    "folder_view",
)
_OUTCOME_CONTROL_KEYS = (
    "index",
    "tag",
    "role",
    "type",
    "name",
    "text",
    "value",
    "label",
    "aria_label",
    "placeholder",
    "checked",
    "selected",
    "aria_checked",
    "aria_pressed",
    "aria_selected",
    "data_state",
    "data_selected",
    "data_checked",
    "disabled",
    "painted",
)
_OUTCOME_CHOICE_ROLES = frozenset(
    {"checkbox", "radio", "switch", "option", "tab", "menuitemcheckbox", "menuitemradio", "treeitem", "gridcell", "row"}
)


def _outcome_control_row(row: dict[str, Any]) -> dict[str, Any]:
    """One control as the outcome verifier reads it: identity and state, empty fields left out. A choice
    control keeps an explicit false checked/selected (unselected is evidence); disabled is kept only when true."""
    choice = (
        str(row.get("type") or "").lower() in {"checkbox", "radio"}
        or str(row.get("role") or "").lower() in _OUTCOME_CHOICE_ROLES
        or str(row.get("tag") or "").lower() == "option"
    )
    slim: dict[str, Any] = {}
    for key in _OUTCOME_CONTROL_KEYS:
        value = row.get(key)
        if value is None or value == "" or value == [] or value == {}:
            continue
        if value is False and not (choice and key in {"checked", "selected"}):
            continue
        slim[key] = value
    return slim


def _outcome_context_text(page: dict[str, Any]) -> list[str]:
    """The distinct text around the controls (their DOM siblings and accessible descriptions) that the
    viewport text does not already hold, each once: a task card or status banner scrolled out of view, or
    a field's described-by error. Per row this repeated on every control; once per page it is a few hundred
    characters, and without it a "Review rejected" card above the fold read as no message at all."""

    def norm(value: Any) -> str:
        return " ".join(str(value or "").split())

    viewport = norm(page.get("viewport_text")).casefold()
    kept: list[str] = []
    seen: list[str] = []
    total = 0
    for row in page.get("controls") or []:
        if not isinstance(row, dict):
            continue
        for field in ("dom_context", "accessibility_context"):
            entries = row.get(field)
            for entry in entries if isinstance(entries, list) else []:
                text = norm(entry.get("text")) if isinstance(entry, dict) else ""
                key = text.casefold()
                if len(key) < 3 or key in viewport or any(key in other for other in seen):
                    continue
                if total + len(text) > _OUTCOME_CONTEXT_TEXT_CHARS:
                    return kept
                seen.append(key)
                kept.append(text)
                total += len(text)
    return kept


def _outcome_page(page: dict[str, Any] | None) -> dict[str, Any]:
    """Slim an already-compacted page (compact_page_evidence output, or a stored before entry's page) to
    the outcome verifier's packet. Idempotent."""
    source = page if isinstance(page, dict) else {}
    slim = {key: source[key] for key in _OUTCOME_PAGE_KEYS if key in source}
    context = source.get("context_text") if isinstance(source.get("context_text"), list) else _outcome_context_text(source)
    if context:
        slim["context_text"] = context
    controls = source.get("controls")
    if isinstance(controls, list):
        slim["controls"] = [_outcome_control_row(row) for row in controls if isinstance(row, dict)]
    return slim


def _outcome_page_evidence(page_evidence: dict[str, Any] | None, *, control_limit: int = 20) -> dict[str, Any]:
    """A raw observation's page evidence as the outcome verifier reads it."""
    from app.vision_agent import compact_page_evidence

    return _outcome_page(
        compact_page_evidence(
            page_evidence or {},
            control_limit=control_limit,
            viewport_text_limit=_OUTCOME_VIEWPORT_TEXT_CHARS,
        )
    )


def _final_action_before_entry(before_shot: dict[str, Any] | None) -> dict[str, Any]:
    """The state a final action started from, as its outcome verifier reads it. A shot carrying
    `recorded_before` (the entry an unverified attempt stored) is that entry; an empty shot is {}."""
    shot = before_shot if isinstance(before_shot, dict) else {}
    if isinstance(shot.get("recorded_before"), dict):
        recorded = dict(shot["recorded_before"])
        if isinstance(recorded.get("page"), dict):
            # An entry stored before the outcome packet was slimmed still carries full control rows.
            recorded["page"] = _outcome_page(recorded["page"])
        return recorded
    if not shot:
        return {}
    return {
        "url": shot.get("url"),
        "title": shot.get("title"),
        "page": _outcome_page_evidence(shot.get("page_evidence"), control_limit=20),
        **_front_window_text_entry(shot),
    }


def _final_state_unchanged(before_shot: dict[str, Any] | None, post_shot: dict[str, Any] | None) -> bool:
    """Whether the page after a final click shows nothing different from before it (url, title, viewport
    text). Without a comparable before state it counts as unchanged: an unproven change proves nothing."""
    before = before_shot if isinstance(before_shot, dict) else {}
    after = post_shot if isinstance(post_shot, dict) else {}
    recorded = before.get("recorded_before") if isinstance(before.get("recorded_before"), dict) else None
    if recorded is not None:
        before_url, before_title = recorded.get("url"), recorded.get("title")
        page = recorded.get("page") if isinstance(recorded.get("page"), dict) else {}
        before_text = page.get("viewport_text")
    else:
        before_url, before_title = before.get("url"), before.get("title")
        before_text = (before.get("page_evidence") or {}).get("viewport_text") if isinstance(before.get("page_evidence"), dict) else None
    if before_url is None and before_text is None:
        return True
    after_text = (after.get("page_evidence") or {}).get("viewport_text") if isinstance(after.get("page_evidence"), dict) else None

    def norm(value: Any) -> str:
        return " ".join(str(value or "").split())

    return (
        norm(before_url) == norm(after.get("url"))
        and norm(before_title) == norm(after.get("title"))
        and norm(before_text) == norm(after_text)
    )


def _final_action_verifier_identity(pending: dict[str, Any]) -> dict[str, Any]:
    """The clicked control as its outcome verifier reads it. A bare glyph label ("x") names no control: the
    selector (an aria-label such as Remove role Developer), tag, and the consequence judge's own reading
    say which one was clicked, so the verifier judges that control's effect and not a look-alike's."""
    identity = pending.get("target_identity") if isinstance(pending.get("target_identity"), dict) else {}
    entry: dict[str, Any] = {
        "label": _safe_trim(pending.get("label"), 120),
        "source": pending.get("authorization") or pending.get("decision") or "",
    }
    for key, value, limit in (
        ("selector", identity.get("target_selector") or pending.get("selector"), 240),
        ("tag", identity.get("target_tag"), 40),
        ("role", identity.get("target_role"), 80),
        ("what_it_does", pending.get("risk_evidence"), 240),
    ):
        text = _safe_trim(value, limit)
        if text:
            entry[key] = text
    return entry


def _final_action_outcome_verdict(
    user_id: int,
    *,
    goal: str,
    pending: dict[str, Any],
    before_shot: dict[str, Any],
    result: dict[str, Any] | None,
    post_shot: dict[str, Any] | None,
    verification_mode: str = "post_action_comparison",
) -> dict[str, Any]:
    """Verify the final outcome from fresh evidence; never grant execution authority here."""
    if (ablated := eval_ablation.benign_verdict("final_action_outcome_verification", verification_mode)) is not None:
        return ablated
    try:
        from app.lumen_model import LumenModelClient

        after = post_shot if isinstance(post_shot, dict) else {}
        image_data = str(after.get("image") or "")
        image = {"media_type": "image/jpeg", "data": image_data} if image_data else None
        with SessionLocal() as db:
            return LumenModelClient(db, user_id=user_id).verify_final_action_outcome(
                {
                    "verification_mode": verification_mode,
                    "goal": _safe_trim(goal, 500),
                    "final_action": _final_action_verifier_identity(pending),
                    "execution": {
                        "ok": bool((result or {}).get("ok")),
                        "url_changed": bool((result or {}).get("url_changed")),
                        "title_changed": bool((result or {}).get("title_changed")),
                        "surface_changed": bool((result or {}).get("surface_changed")),
                        "adopted_new_tab": bool((result or {}).get("adopted_new_tab")),
                    },
                    "before": _final_action_before_entry(before_shot),
                    "after": {
                        "url": after.get("url"),
                        "title": after.get("title"),
                        "page": _outcome_page_evidence(after.get("page_evidence"), control_limit=20),
                        **_front_window_text_entry(after),
                    },
                },
                image=image,
            )
    except Exception as exc:  # noqa: BLE001 - irreversible action verification fails closed
        return {
            "status": "uncertain",
            "confidence": 0.0,
            "evidence": _exception_summary(exc),
            "metadata": {},
        }


def _reversible_click_visual_verdict(
    user_id: int,
    *,
    goal: str,
    action: dict[str, Any],
    bound_label: str | None,
    before_shot: dict[str, Any],
    result: dict[str, Any] | None,
    post_shot: dict[str, Any] | None,
) -> dict[str, Any]:
    """Ask the vision brain to read a choice state that raw browser semantics do not expose."""
    if (ablated := eval_ablation.benign_verdict("visual_readback_judge", "reversible_click", intended_value=(action or {}).get("text"))) is not None:
        return ablated
    try:
        from app.lumen_model import LumenModelClient

        after = post_shot if isinstance(post_shot, dict) else {}
        image_data = str(after.get("image") or "")
        image = {"media_type": "image/jpeg", "data": image_data} if image_data else None
        with SessionLocal() as db:
            return LumenModelClient(db, user_id=user_id).verify_final_action_outcome(
                {
                    "verification_mode": "reversible_click_visual_readback",
                    "goal": _safe_trim(goal, 500),
                    "requested_control": {
                        "question": _safe_trim(action.get("question") or bound_label, 240),
                        "label": _safe_trim(bound_label, 160),
                        "intended_value": _safe_trim(action.get("text") or bound_label, 160),
                    },
                    "execution": {
                        "ok": bool((result or {}).get("ok")),
                        "activation_attempted": bool((result or {}).get("activation_attempted")),
                        "activation_count": int((result or {}).get("activation_count") or 0),
                    },
                    "before": {
                        "url": before_shot.get("url"),
                        "title": before_shot.get("title"),
                        "page": _outcome_page_evidence(before_shot.get("page_evidence"), control_limit=20),
                    },
                    "after": {
                        "url": after.get("url"),
                        "title": after.get("title"),
                        "page": _outcome_page_evidence(after.get("page_evidence"), control_limit=20),
                    },
                },
                image=image,
            )
    except Exception as exc:  # noqa: BLE001 - reversible visual verification remains fail-closed
        return {
            "status": "uncertain",
            "confidence": 0.0,
            "evidence": _exception_summary(exc),
            "metadata": {},
        }


def _apply_reversible_click_visual_verdict(
    result: dict[str, Any] | None,
    *,
    action: dict[str, Any],
    verdict: dict[str, Any] | None,
    context_shot: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Translate a model-owned visual verdict into the body's generic verification protocol.

    The verdict's own `observed_value` (the value the control shows, verbatim) must equal the intended
    value: a "succeeded" whose read-back is a near-miss ("East Gate Free Port" for "Eastgate Free Port")
    is a failed read-back, recorded with what the control shows. A verdict without one keeps its status.
    """
    updated = dict(result or {})
    verdict = verdict if isinstance(verdict, dict) else {}
    status = str(verdict.get("status") or "uncertain").strip().lower()
    try:
        confidence = max(0.0, min(1.0, float(verdict.get("confidence") or 0.0)))
    except (TypeError, ValueError):
        confidence = 0.0
    evidence = _safe_trim(verdict.get("evidence"), 320)
    raw_observed = verdict.get("observed_value")
    observed_value = _visual_readback_text(raw_observed) if isinstance(raw_observed, str) else ""
    intended_text = str(action.get("text") or "") if isinstance(action, dict) else ""
    if observed_value:
        updated["visual_observed_value"] = observed_value[:160]
        if _visual_readback_text(intended_text) and not _visual_readback_matches(intended_text, observed_value):
            day_pick = _day_pick_readback(
                intended_text,
                observed_value,
                " ".join(
                    [_shot_page_text(context_shot)]
                    + [str(action.get(key) or "") for key in ("derivation", "grounding_quote", "value", "reason", "question")]
                ),
            )
            if day_pick == "day_only":
                if status == "succeeded":
                    status = "uncertain"
                    evidence = _safe_trim(f"day matches, month unverified: the field shows '{observed_value}'. {evidence}", 320)
            elif day_pick != "match":
                updated["visual_intended_value"] = _safe_trim(intended_text, 160)
                if status == "succeeded":
                    status = "failed"
                    updated["visual_readback_mismatch"] = True
    updated["visual_verification_status"] = status if status in {"succeeded", "failed", "uncertain"} else "uncertain"
    updated["visual_verification_confidence"] = confidence
    updated["visual_verification_evidence"] = evidence
    updated["visual_verification_required"] = updated["visual_verification_status"] == "uncertain"
    if updated["visual_verification_status"] == "succeeded" and confidence >= 0.75:
        intended_value = _safe_trim(action.get("text"), 160)
        updated.update(
            {
                "selection_committed": True,
                "selected_value": intended_value or "choice committed",
                "selection_evidence": "model_visual_readback",
                "target_selected_after": True,
                "verification_state": "model_visual_readback",
                "visual_selection_committed": True,
                "visual_verification_required": False,
            }
        )
    return updated


def _click_opened_popup(result: Any) -> bool:
    """A click receipt that shows it opened a choice popup: the body's own option-menu report, or the
    clicked control flipping to expanded (an opener button's aria-expanded; the body's listbox check only
    sees clicks landing inside a popup, so a button that opens a portal listbox never sets it)."""
    if not isinstance(result, dict):
        return False
    if result.get("option_menu_open_after") is True:
        return True
    return (
        str(result.get("target_expanded_after") or "").strip().lower() == "true"
        and str(result.get("target_expanded_before") or "").strip().lower() != "true"
        and result.get("target_disclosure") is not False
    )


_POPUP_ROLES = {"listbox", "menu", "grid", "tree", "menubar", "combobox"}


def _popup_owner_still_holds(
    owner: dict[str, Any],
    option: dict[str, Any] | None,
    opened_url: str,
    current_url: str,
    page_evidence: dict[str, Any] | None,
    before_selectors: Any = None,
) -> bool:
    """Whether an option belongs to the popup the remembered opener expanded: the page is the one it was
    opened on, the opener can be re-observed and is not collapsed (an opener that cannot be seen counts as
    collapsed), and the option sits inside the popup the opener controls (its aria-controls/aria-owns id among
    the option's ancestors). With no such link the option must sit inside some listbox/menu and must be newly
    present: its selector was not on the page when the opener was clicked."""
    if opened_url and current_url and opened_url != current_url:
        return False
    selector = _safe_control_selector(owner.get("selector"))
    fresh = _observed_control_by_execution_identity(page_evidence, selector=selector) if selector else None
    if not isinstance(fresh, dict) or str(fresh.get("aria_expanded") or "").strip().lower() == "false":
        return False
    if not isinstance(option, dict):
        return False
    chain = [item for item in (option.get("ancestor_chain") or []) if isinstance(item, dict)]
    owned = {
        token
        for key in ("aria_controls", "aria_owns")
        for token in str(owner.get(key) or fresh.get(key) or "").split()
        if token
    }
    chain_ids = {str(item.get("id") or "") for item in chain if item.get("id")}
    if owned and chain_ids:
        return bool(owned & chain_ids)
    if not any(str(item.get("role") or "").strip().lower() in _POPUP_ROLES for item in chain):
        return False
    option_selector = _safe_control_selector(option.get("selector"))
    return bool(option_selector) and option_selector not in (before_selectors or ())


def _visual_readback_text(value: Any) -> str:
    """A read-back value as text: canonical Unicode composition, whitespace runs collapsed."""
    return unicodedata.normalize("NFC", re.sub(r"\s+", " ", str(value or "")).strip())


def _visual_readback_matches(intended: Any, observed: Any) -> bool:
    """Exact equality of an intended value and the value a visual read-back saw.

    Spelling, spacing between words, and punctuation must match: a lookalike option differs from the
    intended one by exactly those ("East Gate" for "Eastgate", "Freeport", "Terminal II"). Letter case
    does not count: rendered text is often case-transformed by styling (an uppercase button label), and
    the browser read-backs (`_loose_value_equal`) ignore case too.
    """
    return _visual_readback_text(intended).casefold() == _visual_readback_text(observed).casefold()


_MONTH_NUMBERS = {
    **{name.casefold(): i for i, name in enumerate(calendar.month_name) if name},
    **{name.casefold(): i for i, name in enumerate(calendar.month_abbr) if name},
}
_MONTH_WORDS = "|".join(sorted(_MONTH_NUMBERS, key=len, reverse=True))
_ISO_DATE_RE = re.compile(r"(?<!\d)(\d{4})-(\d{1,2})-(\d{1,2})(?!\d)")
_MONTH_FIRST_DATE_RE = re.compile(
    rf"(?<![A-Za-z])({_MONTH_WORDS})\.?\s+(\d{{1,2}})(?:st|nd|rd|th)?(?!\d)(?:,?\s+(\d{{4}})(?!\d))?", re.IGNORECASE
)
_DAY_FIRST_DATE_RE = re.compile(
    rf"(?<!\d)(\d{{1,2}})(?:st|nd|rd|th)?\s+(?:of\s+)?({_MONTH_WORDS})(?![A-Za-z])(?:,?\s+(\d{{4}})(?!\d))?", re.IGNORECASE
)
_MONTH_YEAR_RE = re.compile(rf"(?<![A-Za-z])({_MONTH_WORDS})\.?,?\s+(\d{{4}})(?!\d)", re.IGNORECASE)


def _dates_in_text(text: str) -> set[tuple[int | None, int, int]]:
    """(year or None, month, day) for every date whose day position is unambiguous (ISO, or a month name)."""
    found: set[tuple[int | None, int, int]] = set()
    for m in _ISO_DATE_RE.finditer(text):
        found.add((int(m.group(1)), int(m.group(2)), int(m.group(3))))
    for m in _MONTH_FIRST_DATE_RE.finditer(text):
        found.add((int(m.group(3)) if m.group(3) else None, _MONTH_NUMBERS[m.group(1).casefold()], int(m.group(2))))
    for m in _DAY_FIRST_DATE_RE.finditer(text):
        found.add((int(m.group(3)) if m.group(3) else None, _MONTH_NUMBERS[m.group(2).casefold()], int(m.group(1))))
    return found


def _expected_months(context: str) -> set[tuple[int | None, int]]:
    """Months the pick was meant for: full dates in the brain's own words, else the calendar header(s) shown."""
    full = {(y, mo) for y, mo, _d in _dates_in_text(context) if y is not None}
    if full:
        return full
    return {(int(m.group(2)), _MONTH_NUMBERS[m.group(1).casefold()]) for m in _MONTH_YEAR_RE.finditer(context)}


def _day_pick_readback(intended: Any, observed: Any, context: Any = "") -> str:
    """A calendar day-number pick (`25`) read back as the field's resulting date (`2027-10-25`,
    `October 25, 2027`, `25 Oct 2027`). Returns "mismatch" (not a day pick, wrong day, or the field's
    month/year differs from the month the pick was made in), "match" (day and month/year both agree), or
    "day_only" (the day agrees but no single intended month/year is available, so the month is unverified).
    Only dates whose day position is unambiguous (ISO, or written with a month name) count."""
    day = _visual_readback_text(intended)
    if not re.fullmatch(r"\d{1,2}", day):
        return "mismatch"
    dates = _dates_in_text(_visual_readback_text(observed))
    if len({d for _y, _m, d in dates}) != 1 or {d for _y, _m, d in dates} != {int(day)}:
        return "mismatch"
    expected = _expected_months(_visual_readback_text(context))
    if len(expected) != 1:
        return "day_only"
    exp_year, exp_month = next(iter(expected))
    for year, month, _d in dates:
        if month != exp_month or (year is not None and exp_year is not None and year != exp_year):
            return "mismatch"
    return "match"


def _shot_page_text(shot: Any) -> str:
    """Visible text of a screenshot's page evidence (title plus every string in it), for calendar headers."""
    if not isinstance(shot, dict):
        return ""
    parts: list[str] = [str(shot.get("title") or "")]

    def walk(node: Any, depth: int = 0) -> None:
        if depth > 6 or len(parts) > 4000:
            return
        if isinstance(node, str):
            parts.append(node)
        elif isinstance(node, dict):
            for value in node.values():
                walk(value, depth + 1)
        elif isinstance(node, (list, tuple)):
            for value in node:
                walk(value, depth + 1)

    walk(shot.get("page_evidence"))
    return " ".join(parts)


def _needs_reversible_click_visual_readback(
    kind: str,
    action: dict[str, Any] | None,
    result: dict[str, Any] | None,
) -> bool:
    """Require model read-back when a grounded click or drag sets a value but native state is opaque."""
    if kind not in {"click", "drag"} or not isinstance(result, dict) or not result.get("ok"):
        return False
    if not _safe_trim((action or {}).get("text"), 160) and not result.get("target_option_like"):
        # An option or menu-command click that names its target by control (no `text`) still needs the
        # visible-effect read-back: its label is the intended value (run 1799: an Assign menu's Reviewer).
        return False
    if result.get("selection_committed") or result.get("target_selected_before"):
        return False
    if result.get("owner_matches_target_after") or result.get("owner_readback_changed"):
        return False
    return bool(
        result.get("visual_verification_required")
        or result.get("activation_attempted")
        or int(result.get("activation_count") or 0) > 0
    )


def _final_action_verifier_metadata(metadata: Any) -> dict[str, Any]:
    """Keep diagnosis-critical provider facts without persisting prompts or raw model output."""
    source = metadata if isinstance(metadata, dict) else {}
    compact = {
        key: source.get(key)
        for key in (
            "provider",
            "provider_display_name",
            "provider_id",
            "model",
            "purpose",
            "latency_ms",
            "total_latency_ms",
            "parse_status",
            "raw_output_empty",
            "raw_output_chars",
            "finish_reason",
            "attempt_count",
            "max_tokens",
            "timeout_seconds",
            "error",
        )
        if source.get(key) not in (None, "")
    }
    if isinstance(source.get("normalization"), dict):
        compact["normalization"] = dict(source["normalization"])
    if isinstance(source.get("attempts"), list):
        compact["attempts"] = [dict(item) for item in source["attempts"][:3] if isinstance(item, dict)]
    return compact


def _persist_final_action_verification_artifacts(
    run_id: int,
    *,
    pending: dict[str, Any],
    before_shot: dict[str, Any],
    result: dict[str, Any] | None,
    post_shot: dict[str, Any] | None,
    verdict: dict[str, Any],
    verification_mode: str,
) -> dict[str, str]:
    """Persist bounded local evidence only when irreversible-action verification is not green."""
    from app.vision_agent import compact_page_evidence

    if not run_id:
        return {}
    artifact_root = get_settings().artifact_root / "runs" / str(run_id) / "final-action-verification"
    artifact_root.mkdir(parents=True, exist_ok=True)
    execution_token = re.sub(r"[^a-zA-Z0-9_-]+", "", str(pending.get("execution_id") or ""))[:48]
    execution_token = execution_token or "verification"
    token = f"{execution_token}-{utcnow().strftime('%Y%m%dT%H%M%S%f')}"
    paths: dict[str, str] = {}

    def _save_image(name: str, shot: Any) -> None:
        image_data = str((shot or {}).get("image") or "") if isinstance(shot, dict) else ""
        if not image_data:
            return
        try:
            raw = base64.b64decode(image_data, validate=True)
        except Exception:
            return
        path = artifact_root / f"{token}-{name}.jpg"
        path.write_bytes(raw)
        paths[f"{name}_screenshot"] = str(path)

    _save_image("before", before_shot)
    _save_image("after", post_shot)
    after = post_shot if isinstance(post_shot, dict) else {}
    manifest = {
        "run_id": run_id,
        "recorded_at": utcnow().isoformat(),
        "verification_mode": verification_mode,
        "final_action": {
            "label": _safe_trim(pending.get("label"), 120),
            "source": _safe_trim(pending.get("source") or pending.get("decision"), 80),
        },
        "execution": {
            "ok": bool((result or {}).get("ok")),
            "failure_reason": _safe_trim((result or {}).get("failure_reason"), 160),
            "url_changed": bool((result or {}).get("url_changed")),
            "title_changed": bool((result or {}).get("title_changed")),
            "surface_changed": bool((result or {}).get("surface_changed")),
        },
        "before": {
            "url": _safe_trim(before_shot.get("url"), 1000),
            "title": _safe_trim(before_shot.get("title"), 240),
            "page": compact_page_evidence(before_shot.get("page_evidence") or {}, control_limit=20),
        },
        "after": {
            "capture_ok": bool(after.get("ok")),
            "capture_error": _safe_trim(after.get("error"), 240),
            "url": _safe_trim(after.get("url"), 1000),
            "title": _safe_trim(after.get("title"), 240),
            "page": compact_page_evidence(after.get("page_evidence") or {}, control_limit=20),
        },
        "verdict": {
            "status": str(verdict.get("status") or "uncertain"),
            "confidence": float(verdict.get("confidence") or 0.0),
            "evidence": _safe_trim(verdict.get("evidence"), 500),
            "provider": _final_action_verifier_metadata(verdict.get("metadata")),
        },
        "verification_observations": [
            {
                "attempt": int(item.get("attempt") or 0),
                "capture_ok": bool(item.get("capture_ok")),
                "capture_error": _safe_trim(item.get("capture_error"), 240),
                "url": _safe_trim(item.get("url"), 1000),
                "title": _safe_trim(item.get("title"), 240),
                "status": str(item.get("status") or "uncertain"),
                "confidence": float(item.get("confidence") or 0.0),
                "evidence": _safe_trim(item.get("evidence"), 500),
                "provider": dict(item.get("provider") or {}),
            }
            for item in (verdict.get("observation_attempts") or [])
            if isinstance(item, dict)
        ],
        "screenshots": dict(paths),
    }
    manifest_path = artifact_root / f"{token}-manifest.json"
    manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
    paths["manifest"] = str(manifest_path)
    return paths


def _persist_vision_observation_artifacts(
    run_id: int,
    *,
    step: int,
    shot: dict[str, Any],
    image_b64: str,
    view: dict[str, Any],
) -> dict[str, Any]:
    """Retain one raw browser observation and its normal-size prepared screenshot.

    A separate per-model-attempt artifact records the exact normal or reduced image and
    sanitized prompt that were actually sent. These artifacts are evidence only.
    """
    if not run_id:
        return {"ok": False, "error": "run_id_missing"}
    try:
        raw_image = base64.b64decode(str(image_b64 or ""), validate=True)
        if not raw_image:
            return {"ok": False, "error": "screenshot_empty"}
        captured_at = utcnow()
        screenshot_sha256 = hashlib.sha256(raw_image).hexdigest()
        token = f"{captured_at.strftime('%Y%m%dT%H%M%S%f')}-step-{max(0, int(step)):03d}-{screenshot_sha256[:12]}"
        artifact_root = get_settings().artifact_root / "runs" / str(int(run_id)) / "vision-trajectory"
        artifact_root.mkdir(parents=True, exist_ok=True)
        screenshot_path = artifact_root / f"{token}.jpg"
        observation_path = artifact_root / f"{token}.json"
        manifest_path = artifact_root / "manifest.jsonl"
        _atomic_write_bytes(screenshot_path, raw_image)
        capture_metadata = {
            str(key): value
            for key, value in dict(shot or {}).items()
            if key not in {"image", "page_evidence"}
        }
        observation = {
            "run_id": int(run_id),
            "step": max(0, int(step)),
            "captured_at": captured_at.isoformat(),
            "runtime_build": _VISION_RUNTIME_BUILD,
            "view": dict(view or {}),
            "capture": capture_metadata,
            "page_evidence": dict((shot or {}).get("page_evidence") or {}),
            "screenshot": {
                "path": str(screenshot_path),
                "media_type": "image/jpeg",
                "sha256": screenshot_sha256,
                "bytes": len(raw_image),
            },
        }
        observation_text = json.dumps(observation, ensure_ascii=False, indent=2, default=str)
        observation_file_sha256 = hashlib.sha256(observation_text.encode("utf-8")).hexdigest()
        _atomic_write_text(observation_path, observation_text)
        manifest_record = {
            "run_id": int(run_id),
            "step": max(0, int(step)),
            "captured_at": captured_at.isoformat(),
            "screenshot_path": str(screenshot_path),
            "observation_path": str(observation_path),
            "observation_file_sha256": observation_file_sha256,
            "screenshot_sha256": screenshot_sha256,
            "screenshot_bytes": len(raw_image),
            "view": dict(view or {}),
            "runtime_build": _VISION_RUNTIME_BUILD,
        }
        _append_jsonl_record_atomic(manifest_path, manifest_record)
        return {
            "ok": True,
            **manifest_record,
            "manifest_path": str(manifest_path),
            "reused": False,
        }
    except Exception as exc:  # noqa: BLE001 - evidence failure must be reported without breaking the browser body
        return {"ok": False, "error": _exception_summary(exc)}


def _atomic_write_bytes(path: Any, data: bytes) -> None:
    temporary = path.with_name(f"{path.name}.tmp-{secrets.token_hex(6)}")
    try:
        temporary.write_bytes(data)
        temporary.replace(path)
    finally:
        try:
            if temporary.exists():
                temporary.unlink()
        except OSError:
            pass


def _atomic_write_text(path: Any, text: str) -> None:
    _atomic_write_bytes(path, text.encode("utf-8"))


def _append_jsonl_record_atomic(path: Any, record: dict[str, Any]) -> None:
    previous = path.read_bytes() if path.is_file() else b""
    encoded = json.dumps(record, ensure_ascii=False, default=str).encode("utf-8") + b"\n"
    _atomic_write_bytes(path, previous + encoded)


def _persist_vision_model_input_artifacts(
    run_id: int,
    *,
    step: int,
    payload_mode: str,
    image: dict[str, Any],
    view: dict[str, Any],
    context: dict[str, Any],
    source_observation_ref: dict[str, Any] | None = None,
    source_observation_reused: bool = False,
) -> dict[str, Any]:
    """Retain the sanitized prompt envelope and exact image for one model attempt."""

    if not run_id:
        return {"ok": False, "error": "run_id_missing"}
    try:
        from app import vision_agent
        from app.model_provider import _redact_prompt_for_transport

        image_data = str((image or {}).get("data") or "")
        raw_image = base64.b64decode(image_data, validate=True)
        if not raw_image:
            return {"ok": False, "error": "model_screenshot_empty"}
        prepared = (context or {}).get("_prepared_model_input")
        prompt_envelope = (
            {
                "system": prepared.get("system"),
                "prompt": prepared.get("prompt"),
                "schema": prepared.get("schema"),
                **({"history": prepared["history"]} if prepared.get("history") else {}),
            }
            if isinstance(prepared, dict)
            else vision_agent.prepare_model_input(dict(view or {}), dict(context or {}))
        )
        if (
            not isinstance(prompt_envelope.get("system"), str)
            or not isinstance(prompt_envelope.get("prompt"), dict)
            or not isinstance(prompt_envelope.get("schema"), dict)
        ):
            return {"ok": False, "error": "prepared_model_input_invalid"}
        # model_provider.call_model_json redacts only the prompt before transport (page-rendered
        # sections ride with their screenshot unredacted); the system instruction and schema pass
        # through unchanged. Mirror that boundary exactly here.
        sanitized_envelope = {
            **prompt_envelope,
            "prompt": _redact_prompt_for_transport(prompt_envelope["prompt"], screenshot_attached=True),
        }
        serialized = json.dumps(
            sanitized_envelope,
            ensure_ascii=False,
            indent=2,
            sort_keys=True,
            default=str,
        )
        def _component_sha256(value: Any) -> str:
            canonical = json.dumps(
                value,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
                default=str,
            ).encode("utf-8")
            return hashlib.sha256(canonical).hexdigest()

        created_at = utcnow()
        screenshot_sha256 = hashlib.sha256(raw_image).hexdigest()
        model_input_envelope_sha256 = hashlib.sha256(serialized.encode("utf-8")).hexdigest()
        model_system_sha256 = hashlib.sha256(str(sanitized_envelope["system"]).encode("utf-8")).hexdigest()
        model_prompt_sha256 = _component_sha256(sanitized_envelope["prompt"])
        model_schema_sha256 = _component_sha256(sanitized_envelope["schema"])
        safe_mode = re.sub(r"[^a-z0-9_-]+", "-", str(payload_mode or "normal").lower()).strip("-") or "normal"
        token = (
            f"{created_at.strftime('%Y%m%dT%H%M%S%f')}-step-{max(0, int(step)):03d}-"
            f"{safe_mode}-{screenshot_sha256[:12]}"
        )
        artifact_root = get_settings().artifact_root / "runs" / str(int(run_id)) / "vision-trajectory"
        artifact_root.mkdir(parents=True, exist_ok=True)
        screenshot_path = artifact_root / f"{token}-model.jpg"
        model_input_path = artifact_root / f"{token}-model-input.json"
        manifest_path = artifact_root / "model-input-manifest.jsonl"
        _atomic_write_bytes(screenshot_path, raw_image)
        record = {
            "run_id": int(run_id),
            "step": max(0, int(step)),
            "created_at": created_at.isoformat(),
            "payload_mode": str(payload_mode or "normal"),
            "runtime_build": _VISION_RUNTIME_BUILD,
            "view": dict(view or {}),
            "source_observation_ref": {
                key: (source_observation_ref or {}).get(key)
                for key in (
                    "step",
                    "captured_at",
                    "screenshot_path",
                    "observation_path",
                    "observation_file_sha256",
                    "screenshot_sha256",
                )
                if (source_observation_ref or {}).get(key) not in (None, "")
            },
            "source_observation_reused": bool(source_observation_reused),
            "model_screenshot": {
                "path": str(screenshot_path),
                "media_type": str((image or {}).get("media_type") or "image/jpeg"),
                "sha256": screenshot_sha256,
                "bytes": len(raw_image),
            },
            "model_input": {
                "path": str(model_input_path),
                "sha256": model_input_envelope_sha256,
                "envelope_sha256": model_input_envelope_sha256,
                "system_sha256": model_system_sha256,
                "prompt_sha256": model_prompt_sha256,
                "schema_sha256": model_schema_sha256,
                "otp_redaction_applied": sanitized_envelope != prompt_envelope,
                "retention_boundary": "model_client_input_before_provider_serialization",
                "envelope": sanitized_envelope,
            },
        }
        model_input_text = json.dumps(record, ensure_ascii=False, indent=2, default=str)
        model_input_file_sha256 = hashlib.sha256(model_input_text.encode("utf-8")).hexdigest()
        _atomic_write_text(model_input_path, model_input_text)
        manifest_record = {
            "run_id": int(run_id),
            "step": max(0, int(step)),
            "created_at": created_at.isoformat(),
            "payload_mode": str(payload_mode or "normal"),
            # The A/B record: whether message history was on for this request and how many earlier turns it carried.
            "message_history_mode": "on" if vision_agent.message_history_enabled() else "off",
            "message_history_turns": len(prepared.get("history") or []) if isinstance(prepared, dict) else 0,
            "model_screenshot_path": str(screenshot_path),
            "model_screenshot_sha256": screenshot_sha256,
            "model_screenshot_bytes": len(raw_image),
            "model_input_path": str(model_input_path),
            # Backward-compatible alias for the application-level model-input envelope.
            "model_input_sha256": model_input_envelope_sha256,
            "model_input_envelope_sha256": model_input_envelope_sha256,
            "model_input_file_sha256": model_input_file_sha256,
            "model_system_sha256": model_system_sha256,
            "model_prompt_sha256": model_prompt_sha256,
            "model_schema_sha256": model_schema_sha256,
            "retention_boundary": "model_client_input_before_provider_serialization",
            "source_observation_reused": bool(source_observation_reused),
            "source_observation_ref": record["source_observation_ref"],
            "runtime_build": _VISION_RUNTIME_BUILD,
        }
        _append_jsonl_record_atomic(manifest_path, manifest_record)
        return {
            "ok": True,
            **manifest_record,
            "manifest_path": str(manifest_path),
        }
    except Exception as exc:  # noqa: BLE001 - caller decides whether evidence is mandatory
        return {"ok": False, "error": _exception_summary(exc)}


def _run_requires_vision_evidence(run_id: int) -> bool:
    """Require durable evidence for runs actually routed to a connected Chrome body."""

    if not run_id:
        return False
    try:
        from app import models

        with SessionLocal() as db:
            run = db.get(models.OperatorRun, int(run_id))
            in_browser = (run.confidence_state or {}).get("in_browser") if run else {}
            return bool(isinstance(in_browser, dict) and str(in_browser.get("device_id") or "").strip())
    except Exception:
        return True


def _action_control_index(action: dict[str, Any] | None) -> int:
    if not isinstance(action, dict):
        return 0
    try:
        return max(0, int(action.get("control") or 0))
    except (TypeError, ValueError):
        return 0


def _control_inventory_index_map(page_evidence: dict[str, Any] | None, *, source_limit: int = 24) -> dict[int, dict[str, Any]]:
    """Map model-visible nonzero control_inventory indices to raw controls and body selectors."""
    controls = (page_evidence or {}).get("controls") if isinstance(page_evidence, dict) else []
    if not isinstance(controls, list):
        return {}
    candidates: list[tuple[float, float, dict[str, Any]]] = []
    # Exactly the rows the model's control_inventory shows, so every index it can cite resolves.
    for raw in _model_visible_control_rows(
        controls,
        limit=source_limit,
        viewport_height=(page_evidence or {}).get("viewport_height"),
        grow_to_on_screen=True,
    ):
        if not isinstance(raw, dict):
            continue
        try:
            x = float(raw.get("x"))
            y = float(raw.get("y"))
            width = float(raw.get("width"))
            height = float(raw.get("height"))
        except (TypeError, ValueError):
            continue
        if width <= 0 or height <= 0:
            continue
        control = dict(raw)
        control["_inventory_box"] = [x, y, width, height]
        candidates.append((y, x, control))
    candidates.sort(key=lambda item: (item[0], item[1]))
    mapped: dict[int, dict[str, Any]] = {}
    for _, _, control in candidates:
        try:
            index = max(0, int(control.get("index") or 0))
        except (TypeError, ValueError):
            index = 0
        if not index:
            continue
        selector = _safe_control_selector(control.get("selector"))
        if not selector:
            continue
        control["_control_inventory_index"] = index
        mapped[index] = {"selector": selector, "control": control, "box": control.get("_inventory_box") or []}
    return mapped


def _native_select_option_key(value: Any) -> str:
    """Option text as the browser's select match reads it: whitespace collapsed, case folded."""
    return re.sub(r"\s+", " ", str(value or "")).strip().lower()


def _native_select_click_option(
    action: dict[str, Any] | None,
    *,
    control_index: int,
    control_index_map: dict[int, dict[str, Any]],
    page_evidence: dict[str, Any] | None,
    coord_scale: float,
    execution_surface: str,
) -> str:
    """The option a click on a native <select> names, when its text names exactly one option of that select.

    A native select draws its option list outside the page, so a click meant to pick an option lands on whatever
    control lies under it (run 1794 clicked "No" for Q9 nine times). The same intent is one type of that option's
    text into the select, which the browser sets directly. Returns "" unless the click is bound to a native
    single-select (by its inventory id, or by its point when it has none) and its text matches exactly one of the
    select's options; every other click keeps the refusal that tells the brain to type. The caller then prepares
    the converted type through the type path's own gates.
    """
    action = action if isinstance(action, dict) else {}
    if str(action.get("action") or "").strip().lower() != "click" or execution_surface == "desktop":
        return ""
    wanted = _native_select_option_key(action.get("text"))
    if not wanted:
        return ""
    indexed: dict[str, Any] | None = None
    ref = control_index_map.get(control_index) if control_index else None
    if isinstance(ref, dict) and isinstance(ref.get("control"), dict):
        indexed = dict(ref["control"])
    point = (
        _bind_action_control(action, page_evidence, coord_scale)
        if (action.get("x") or action.get("y"))
        else None
    )
    if indexed and point and not _controls_share_execution_identity(indexed, point):
        return ""
    bound = indexed or point
    if not isinstance(bound, dict) or str(bound.get("tag") or "").strip().lower() != "select":
        return ""
    if "selected_values" in bound:
        # A multi-select's row lists every selected option; a single type would replace the whole selection.
        return ""
    options = bound.get("options")
    if not isinstance(options, list):
        return ""
    matches = [option for option in options if isinstance(option, str) and _native_select_option_key(option) == wanted]
    return matches[0] if len(matches) == 1 else ""


def _native_select_conversion_hint(prepared: dict[str, Any] | None, *, sensitive: bool = False) -> str:
    """The receipt line for a click that was sent as a select option type (empty for any other action). It
    names the option only when the converted type is not sensitive: a sensitive select's option (a card expiry,
    a date of birth) is never echoed. It states that the option was sent, never that it ran: the outcome the
    result carries says whether it was verified."""
    if not isinstance(prepared, dict) or prepared.get("converted_from") != "click":
        return ""
    if sensitive:
        return "click on native select was sent as a select option (value withheld: sensitive field)"
    option = _safe_trim(prepared.get("converted_option"), 80)
    if not option:
        return ""
    return f"click on native select was sent as select option '{option}'"


def _final_binding_repair_text(target: dict[str, Any] | None, page_evidence: dict[str, Any] | None) -> str:
    """Repair line for a final/destructive action with no bindable control: name the one inventory row that
    carries the label the brain addressed (by target_text or point), else say how to list it."""
    base = (
        "Final and destructive actions must be bound to a listed control: resend with control=<id> from "
        "control_inventory (scroll it into view first if it is not listed); target_text and bare x,y cannot "
        "carry a final click."
    )
    label_key = _control_label_key((target or {}).get("label"))
    if not label_key:
        return base
    try:
        mapped = _control_inventory_index_map(page_evidence, source_limit=56)
    except Exception:
        return base
    matches = sorted(
        index
        for index, entry in mapped.items()
        if label_key in {
            _control_label_key((entry.get("control") or {}).get(key))
            for key in ("text", "label", "aria_label", "value")
        }
    )
    if len(matches) == 1:
        return f"{base} The listed control labelled '{_safe_trim((target or {}).get('label'), 60)}' is control={matches[0]}."
    return base


def _control_label_key(value: Any) -> str:
    return re.sub(r"[^0-9a-z]+", "", str(value or "").casefold())


def _bind_active_result_control(result: dict[str, Any] | None, page_evidence: dict[str, Any] | None) -> dict[str, Any] | None:
    """Bind type receipts to the raw control that actually received text."""
    if not isinstance(result, dict):
        return None
    controls = (page_evidence or {}).get("controls") if isinstance(page_evidence, dict) else []
    if not isinstance(controls, list):
        return None
    active_selector = _safe_control_selector(result.get("active_selector"))
    if active_selector:
        for raw in controls:
            if isinstance(raw, dict) and _safe_control_selector(raw.get("selector")) == active_selector:
                return dict(raw)
    active_label_key = _control_label_key(result.get("active_label"))
    if active_label_key:
        for raw in controls:
            if not isinstance(raw, dict):
                continue
            candidates = [
                _control_label(raw, limit=160),
                raw.get("label"),
                raw.get("aria_label"),
                raw.get("placeholder"),
                raw.get("context_text"),
                raw.get("nearby_text"),
                raw.get("text"),
            ]
            if any(_control_label_key(candidate) == active_label_key for candidate in candidates if candidate not in (None, "", [], {})):
                return dict(raw)
    active_name_key = _control_label_key(result.get("active_name"))
    if active_name_key:
        for raw in controls:
            if isinstance(raw, dict) and _control_label_key(raw.get("name")) == active_name_key:
                return dict(raw)
    return None


def _ensure_pending_ledger_control(
    ledger: dict[str, dict[str, Any]],
    *,
    signature: str,
    control: dict[str, Any],
    action_kind: str,
    step: int,
    outcome: str,
) -> dict[str, Any] | None:
    if not signature:
        return None
    entry = dict(ledger.get(signature) or {})
    entry.setdefault("label", _control_label(control, limit=80))
    entry.setdefault("kind", _control_kind(control))
    entry.setdefault("verified_value", None)
    entry["last_action"] = action_kind
    entry["attempts"] = int(entry.get("attempts") or 0) + 1
    entry["last_step"] = step
    entry["last_outcome"] = outcome
    ledger[signature] = entry
    return entry


def _vision_length_retry_budget(metadata: dict[str, Any] | None) -> int:
    raw = (metadata or {}).get("max_tokens") if isinstance(metadata, dict) else None
    try:
        base = int(raw or _VISION_AGENT_STEP_DEFAULT_MAX_TOKENS)
    except (TypeError, ValueError):
        base = _VISION_AGENT_STEP_DEFAULT_MAX_TOKENS
    base = max(base, _VISION_AGENT_STEP_MIN_TOKENS)
    return min(base * 2, _VISION_AGENT_STEP_RETRY_MAX_TOKENS)


def _clamp_number(value: int | float, low: int | float, high: int | float) -> float:
    return float(min(max(value, low), high))


def _vision_step_timeout_seconds(
    timeout_seconds_override: int | float | None = None, *, seat: str = external_brain.BRAIN
) -> float:
    if external_brain.handles("vision_agent_step", seat):
        return external_brain.wait_seconds()
    if timeout_seconds_override is None:
        return _VISION_AGENT_STEP_DEFAULT_TIMEOUT_SECONDS
    try:
        override = float(timeout_seconds_override)
    except (TypeError, ValueError):
        return _VISION_AGENT_STEP_DEFAULT_TIMEOUT_SECONDS
    if override <= 0:
        return _VISION_AGENT_STEP_DEFAULT_TIMEOUT_SECONDS
    return min(override, _VISION_AGENT_STEP_RETRY_MAX_TIMEOUT_SECONDS)


def _vision_latency_ring(raw: Any) -> list[float]:
    if not isinstance(raw, list):
        return []
    values: list[float] = []
    for item in raw[-_VISION_DECISION_LATENCY_RING_LIMIT:]:
        try:
            latency = float(item)
        except (TypeError, ValueError):
            continue
        if latency > 0:
            values.append(round(latency, 3))
    return values[-_VISION_DECISION_LATENCY_RING_LIMIT:]


def _vision_record_success_latency(profile: dict[str, Any], latency_seconds: int | float) -> None:
    try:
        latency = float(latency_seconds)
    except (TypeError, ValueError):
        return
    if latency <= 0:
        return
    ring = _vision_latency_ring((profile or {}).get("latency_ring_seconds"))
    ring.append(round(latency, 3))
    profile["latency_ring_seconds"] = ring[-_VISION_DECISION_LATENCY_RING_LIMIT:]
    profile["ewma_latency_seconds"] = _vision_latency_ewma(
        (profile or {}).get("ewma_latency_seconds"),
        latency,
    )


def _vision_attempt1_timeout_from_ewma(ewma_latency_seconds: int | float | None, latency_ring_seconds: Any = None) -> int:
    ring = _vision_latency_ring(latency_ring_seconds)
    if not ring:
        return int(_VISION_AGENT_STEP_DEFAULT_TIMEOUT_SECONDS)
    estimated = math.ceil(1.25 * max(ring))
    return int(round(_clamp_number(estimated, _VISION_AGENT_STEP_DEFAULT_TIMEOUT_SECONDS, _VISION_AGENT_STEP_RETRY_MAX_TIMEOUT_SECONDS)))


def _vision_attempt1_timeout_from_profile(profile: dict[str, Any] | None) -> int:
    profile = profile or {}
    return _vision_attempt1_timeout_from_ewma(profile.get("ewma_latency_seconds"), profile.get("latency_ring_seconds"))


def _vision_latency_ewma(previous: int | float | None, latency_seconds: int | float) -> float:
    try:
        latency = float(latency_seconds)
    except (TypeError, ValueError):
        return float(previous or 0)
    if latency <= 0:
        return float(previous or 0)
    try:
        current = float(previous or 0)
    except (TypeError, ValueError):
        current = 0.0
    if current <= 0:
        return latency
    alpha = _VISION_DECISION_EWMA_ALPHA
    return (alpha * latency) + ((1.0 - alpha) * current)


def _vision_timeout_retry_budget(timed_out_attempts: int, base_timeout_seconds: int | float | None = None) -> int:
    try:
        attempts = max(1, int(timed_out_attempts))
    except (TypeError, ValueError):
        attempts = 1
    try:
        base = float(base_timeout_seconds or _VISION_AGENT_STEP_DEFAULT_TIMEOUT_SECONDS)
    except (TypeError, ValueError):
        base = _VISION_AGENT_STEP_DEFAULT_TIMEOUT_SECONDS
    base = _clamp_number(base, _VISION_AGENT_STEP_DEFAULT_TIMEOUT_SECONDS, _VISION_AGENT_STEP_RETRY_MAX_TIMEOUT_SECONDS)
    escalated = base * (2 ** attempts)
    return int(min(escalated, _VISION_AGENT_STEP_RETRY_MAX_TIMEOUT_SECONDS))


def _vision_outer_decision_timeout_seconds(
    inner_timeout_seconds: int | float | None, *, seat: str = external_brain.BRAIN
) -> float:
    return _vision_step_timeout_seconds(inner_timeout_seconds, seat=seat) + _VISION_DECISION_TIMEOUT_MARGIN_SECONDS


def _control_fingerprint(page_evidence: dict[str, Any] | None) -> str:
    """Hash visible raw control identities for scroll-loop governance."""
    controls = (page_evidence or {}).get("controls") if isinstance(page_evidence, dict) else []
    if not isinstance(controls, list):
        controls = []
    signatures = sorted(sig for sig in (_control_signature(item) for item in controls if isinstance(item, dict)) if sig)
    raw = "|".join(signatures) or "no-controls"
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:16]


def _page_state_fingerprint(shot: dict[str, Any] | None) -> str:
    """Hash raw observable state so varied actions cannot hide a two-state browser loop.

    This is identity bookkeeping, not page interpretation: URL/title/scroll, visible text, and raw
    control identity/value state are retained without deciding what any control means.
    """
    if not isinstance(shot, dict):
        return ""
    evidence = shot.get("page_evidence") if isinstance(shot.get("page_evidence"), dict) else {}
    controls = evidence.get("controls") if isinstance(evidence.get("controls"), list) else []
    raw_controls: list[tuple[Any, ...]] = []
    for control in controls:
        if not isinstance(control, dict):
            continue
        raw_controls.append(
            (
                _control_signature(control),
                _normalized_control_identity_text(control.get("value"), limit=180),
                _normalized_control_identity_text(control.get("text"), limit=180),
                control.get("checked"),
                control.get("selected"),
                _normalized_control_identity_text(control.get("aria_selected"), limit=20),
                _normalized_control_identity_text(control.get("aria_expanded"), limit=20),
                # Keyboard focus is browser state: Tab to another field is a different state.
                control.get("focused") is True,
            )
        )
    # The real screen's state is mostly pixels (a native window's fields rarely expose text): a
    # coarse, quantized thumbnail digest tells a typed or applied field from an unchanged screen,
    # while ignoring compression noise.
    # A web page keeps state in pixels too: a canvas's painted fields, and any change made only by
    # styling (v4_keys run 1668: arrow keys moved a board's highlighted cell, a CSS class, five times;
    # with no text or control change each read as the same state and the cycle guard blocked real
    # progress). Lumen's pointer overlay is hidden for every capture, so the digest never sees it.
    visual_state = _desktop_visual_digest(shot)
    # The caret in a text field moves without visibly changing the screen: a click or key
    # that moved it is a new state; the same line, column, and selection again is the same state.
    raw_caret = evidence.get("caret") if isinstance(evidence.get("caret"), dict) else {}
    caret_state = (
        (
            _normalized_control_identity_text(raw_caret.get("line_text"), limit=200),
            raw_caret.get("column"),
            raw_caret.get("selection_length"),
        )
        if raw_caret
        else None
    )
    # The focused multi-line text's own lines: an edit past the control value's excerpt above is a
    # new state too.
    raw_lines = evidence.get("focused_text_lines") if isinstance(evidence.get("focused_text_lines"), dict) else {}
    lines_state = tuple(
        str(line)[:520] for line in (raw_lines.get("lines") if isinstance(raw_lines.get("lines"), list) else [])[:60]
    )
    # A file renamed in a folder window is a new state, even where the window hides the change.
    raw_folder = evidence.get("folder_view") if isinstance(evidence.get("folder_view"), dict) else {}
    folder_state = tuple(
        str(item)[:160] for item in (raw_folder.get("items") if isinstance(raw_folder.get("items"), list) else [])[:60]
    )
    # An open browser dialog is browser state the page cannot show: a confirm, then a prompt,
    # then that prompt with text typed into it are distinct states over one unchanged page.
    dialog = _native_dialog_in_shot(shot)
    raw_dialog = shot.get("native_dialog") if isinstance(shot.get("native_dialog"), dict) else evidence.get("native_dialog")
    typed_prompt = raw_dialog.get("typed_prompt") if isinstance(raw_dialog, dict) else None
    dialog_state = (
        (
            _safe_trim(dialog.get("type"), 24),
            _normalized_control_identity_text(dialog.get("message"), limit=300),
            None if typed_prompt is None else str(typed_prompt)[:300],
        )
        if dialog
        else None
    )
    raw = repr(
        (
            _normalized_control_identity_text(shot.get("url") or evidence.get("url"), limit=500),
            _normalized_control_identity_text(shot.get("title") or evidence.get("title"), limit=200),
            int(shot.get("scroll_y") or evidence.get("scroll_y") or 0),
            _normalized_control_identity_text(evidence.get("viewport_text"), limit=1600),
            tuple(raw_controls),
            *((dialog_state,) if dialog_state else ()),
            *((visual_state,) if visual_state else ()),
            *((("caret",) + caret_state,) if caret_state else ()),
            *((("focused_text_lines",) + lines_state,) if lines_state else ()),
            *((("folder_view", _safe_trim(raw_folder.get("path"), 260)) + folder_state,) if raw_folder else ()),
        )
    )
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:20]


def _zoom_region_digest(shot: dict[str, Any] | None, region: Any) -> str:
    """A digest of one region of a capture's own pixels (native pixels, exact), "" when unavailable."""
    try:
        import io

        from PIL import Image

        left, top, right, bottom = (int(value) for value in list(region or [])[:4])
        if right <= left or bottom <= top:
            return ""
        raw = base64.b64decode(str((shot or {}).get("image") or ""), validate=False)
        if not raw:
            return ""
        with Image.open(io.BytesIO(raw)) as img:
            crop = img.convert("L").crop((left, top, right, bottom))
            # JPEG noise is not a change: compare at 1/4 size and 32 grey levels.
            small = crop.resize((max(1, crop.width // 4), max(1, crop.height // 4)))
            data = bytes(value >> 3 for value in small.tobytes())
        return hashlib.sha1(data).hexdigest()[:16]
    except Exception:  # noqa: BLE001 - no digest: the crop is dropped
        return ""


def _desktop_visual_digest(shot: dict[str, Any] | None) -> str:
    """A coarse digest of the screen's pixels: 96x60 grayscale, 16 levels."""
    try:
        import io

        from PIL import Image

        raw = base64.b64decode(str((shot or {}).get("image") or ""), validate=False)
        if not raw:
            return ""
        with Image.open(io.BytesIO(raw)) as img:
            grey = img.convert("L")
            thumb = grey.resize((96, 60))
            data = bytes(value >> 4 for value in thumb.tobytes())
            # The front window at its own scale too: a small window's change (the next invoice in a
            # 600 px viewer, v5_reconcile run 1706) moves no cell of the whole-screen thumbnail, and
            # each Prev click read as the same state and was withheld as a repeat.
            evidence = (shot or {}).get("page_evidence") if isinstance((shot or {}).get("page_evidence"), dict) else {}
            active = next(
                (item for item in (evidence.get("windows") or []) if isinstance(item, dict) and item.get("active")),
                None,
            )
            box = (active or {}).get("image_box") if isinstance(active, dict) else None
            if isinstance(box, list) and len(box) == 4 and int(box[2]) > 0 and int(box[3]) > 0:
                left, top = max(0, int(box[0])), max(0, int(box[1]))
                right, bottom = min(grey.width, int(box[0]) + int(box[2])), min(grey.height, int(box[1]) + int(box[3]))
                if right - left >= 32 and bottom - top >= 32:
                    # A quarter of its own size: a changed digit moves several cells.
                    window = grey.crop((left, top, right, bottom))
                    window = window.resize((max(8, window.width // 4), max(8, window.height // 4)))
                    data += bytes(value >> 4 for value in window.tobytes())
        return hashlib.sha1(data).hexdigest()[:16]
    except Exception:  # noqa: BLE001 - no digest: the text evidence alone stands
        return ""


_LOOSE_CURRENCY_SYMBOLS = "$€£¥₹₩₽₺₪฿"
_LOOSE_THOUSANDS_RE = re.compile(r"(?<![\d.,])\d{1,3}(?:,\d{3})+(?![\d,])|(?<![\d.,])\d{1,2}(?:,\d{2})+,\d{3}(?![\d,])")
_LOOSE_NUMBER_RE = re.compile(r"([+-]?)(\d+)?(?:\.(\d+))?")
_LOOSE_PHONE_RE = re.compile(r"[+\d\s().\-–]+")


_LOOSE_CURRENCY_CODES = "usd|eur|gbp|jpy|cad|aud|chf|cny|inr|mxn|brl|krw|rub|sek|nok|dkk|nzd|sgd|hkd|pln|zar"
_LOOSE_CODE_LEAD_RE = re.compile(rf"({_LOOSE_CURRENCY_CODES})\s*(?=[\d.+-])")
_LOOSE_CODE_TRAIL_RE = re.compile(rf"(?<=[\d.])\s*({_LOOSE_CURRENCY_CODES})$")
_LOOSE_QUANTITY_RE = re.compile(r"([+-]?[\d.][\d\s.,]*?)\s*([^\d\s.,+-][^\d]*)?")
_LOOSE_EMAIL_RE = re.compile(r"[^\s@]+@[^\s@]+\.[^\s@]+")
_LOOSE_URL_RE = re.compile(r"(?:[a-z][a-z0-9+.-]*://|www\.)\S+")
_LOOSE_ISO_DATE_RE = re.compile(r"\d{4}-\d{1,2}-\d{1,2}")


def _loose_number_body(body: str) -> tuple[str, bool] | None:
    """A number's digits as a plain "123.45" string (sign excluded) and whether it is ambiguous
    between an English decimal and a thousands group (one dot and exactly three digits after it:
    "1.000"). Reads English ("1,234.56"), European ("1.234,56") and space-grouped ("1 234,56")
    formats; a lone comma with one or two digits ("1,5") is not read as a decimal. None when the
    text is not one number."""
    if re.fullmatch(r"\d{1,3}(?: \d{3})+(?:[.,]\d+)?", body):
        body = body.replace(" ", "")
        if "," in body:
            body = body.replace(",", ".")
    if "." in body and "," in body and body.rindex(",") > body.rindex("."):
        if not re.fullmatch(r"\d{1,3}(?:\.\d{3})+,\d+", body):
            return None
        return body.replace(".", "").replace(",", "."), False
    if body.count(".") >= 2 and re.fullmatch(r"\d{1,3}(?:\.\d{3}){2,}", body):
        return body.replace(".", ""), False
    body = _LOOSE_THOUSANDS_RE.sub(lambda match: match.group().replace(",", ""), body)
    match = _LOOSE_NUMBER_RE.fullmatch(body)
    if not match or not (match.group(2) or match.group(3)) or match.group(1):
        return None
    integer, fraction = match.group(2) or "", match.group(3) or ""
    ambiguous = len(fraction) == 3 and 1 <= len(integer) <= 3 and not integer.startswith("0")
    return f"{integer or '0'}.{fraction or '0'}", ambiguous


def _loose_quantity(text: str) -> dict[str, Any] | None:
    """A text that is one number with optional currency symbol or code, accounting parentheses, sign and
    trailing unit ("2.5 kg", "(5)", "$1.234,56", "5 USD"); None when it is anything else."""
    text = text.replace("−", "-")
    negative = False
    wrapped = re.fullmatch(r"\((.+)\)", text)
    if wrapped:
        text, negative = wrapped.group(1), True
    text = "".join(char for char in text if char not in _LOOSE_CURRENCY_SYMBOLS)
    text = re.sub(r"\s+", " ", text).strip()
    code = ""
    for pattern in (_LOOSE_CODE_LEAD_RE, _LOOSE_CODE_TRAIL_RE):
        match = pattern.search(text)
        if match and (pattern is _LOOSE_CODE_TRAIL_RE or match.start() == 0):
            code = match.group(1)
            text = (text[: match.start()] + text[match.end():]).strip()
            break
    match = _LOOSE_QUANTITY_RE.fullmatch(text)
    if not match:
        return None
    signed, unit = match.group(1).strip(), match.group(2) or ""
    parsed = _loose_number_body(signed.lstrip("+-"))
    if parsed is None:
        return None
    digits, ambiguous = parsed
    negate = signed.startswith("-") != negative
    integer = digits.split(".")[0]
    return {
        "value": -Decimal(digits) if negate else Decimal(digits),
        "identifier": len(integer) > 1 and integer.startswith("0"),
        "ambiguous": ambiguous,
        "literal": f"{'-' if negate else ''}{digits}",
        "unit": re.sub(r"[^\w%°/]", "", unit),
        "code": code,
    }


def _loose_alnum_form(text: str) -> str:
    """Letters and digits, plus what changes meaning: a decimal point or comma between digits, a hyphen
    between digits ("3-4" is not "34"), a leading minus before a digit, and the symbols + # % /
    ("C++" is not "C", "3/4" is not "34"). Every other mark is mask. A phone-like text (7+ digits, only
    digits, spaces, brackets, dots and dashes) or an ISO date is all mask, so its dots and dashes go."""
    text = _LOOSE_THOUSANDS_RE.sub(lambda match: match.group().replace(",", ""), text)
    mask = (bool(_LOOSE_PHONE_RE.fullmatch(text)) and sum(char.isdigit() for char in text) >= 7) or bool(
        _LOOSE_ISO_DATE_RE.fullmatch(text.strip())
    )
    lead = 0
    while lead < len(text) and (text[lead] in _LOOSE_CURRENCY_SYMBOLS or text[lead].isspace()):
        lead += 1
    out: list[str] = []
    for index, char in enumerate(text):
        before = text[index - 1] if index > 0 else ""
        after = text[index + 1] if index + 1 < len(text) else ""
        if char.isalnum():
            out.append(char)
        elif mask:
            continue
        elif char in ".," and before.isdigit() and after.isdigit():
            out.append(char)
        elif char in "-−–" and ((index == lead and after.isdigit()) or (before.isdigit() and not after.isalpha())):
            out.append("-")
        elif char in "+#%/":
            out.append(char)
    return "".join(out)


def _loose_value_equal(left: Any, right: Any) -> bool:
    """Compare intended vs observed field values while tolerating formatting-only changes. By kind:
    an email address or URL matches only itself, ignoring letter case ("a.b@x.com" is not "ab@x.com");
    a single number with optional currency, sign, accounting parentheses and unit compares by value,
    reading English, European and space-grouped formats ("1.234,56" is "1234.56", "$1,000.00" is
    "1000", "(5)" is "-5", "2.5 kg" is "2.50 kg"); a unit must agree, and a unit on only one side
    differs ("5" is not "5%"), while a currency code or symbol may be absent on one side ("5 USD" is
    "5"); anything else compares as text ignoring case, whitespace, punctuation and masks
    ("(555) 123-4567" is "5551234567"), where meaning-bearing marks stay (+ # % /, a decimal point or
    hyphen between digits, a leading minus: "C++" is not "C", "3-4" is not "34"). A decimal point's
    position, a sign, a different digit, a leading zero on an identifier ("02134" vs "2134") and an
    ambiguous "1.000" (decimal one or a thousand) against any other spelling differ, as do accents
    ("Sao" is not "São"). Dates are not converted between formats ("01/02" vs "1/2", "2024-01-05" vs
    "01/05/2024" differ); only an ISO date's separators are mask ("2024-01-05" is "20240105")."""
    left_text = re.sub(r"\s+", " ", str(left or "")).strip().casefold()
    right_text = re.sub(r"\s+", " ", str(right or "")).strip().casefold()
    for shape in (_LOOSE_EMAIL_RE, _LOOSE_URL_RE):
        if shape.fullmatch(left_text) or shape.fullmatch(right_text):
            return left_text == right_text
    left_number, right_number = _loose_quantity(left_text), _loose_quantity(right_text)
    if left_number and right_number:
        if left_number["code"] and right_number["code"] and left_number["code"] != right_number["code"]:
            return False
        if left_number["unit"] != right_number["unit"]:
            return False
        if any(number["identifier"] or number["ambiguous"] for number in (left_number, right_number)):
            # An identifier-shaped or ambiguous number: the digits themselves must agree.
            return left_number["literal"] == right_number["literal"]
        return left_number["value"] == right_number["value"]
    left_normalized = _loose_alnum_form(left_text)
    right_normalized = _loose_alnum_form(right_text)
    if left_normalized or right_normalized:
        return left_normalized == right_normalized
    return left_text == right_text


def _matching_control_readback(control: dict[str, Any] | None, intended: Any) -> str:
    """Return an exact-format raw read-back matching an already-grounded intended value."""
    if not isinstance(control, dict) or not str(intended or "").strip():
        return ""
    for key in ("value", "text", "aria_value_text"):
        observed = " ".join(str(control.get(key) or "").split())
        if observed and _loose_value_equal(intended, observed):
            return observed[:160]
    return ""


_TYPE_READ_BACK_LEDGER_CAP = 4000


def _exact_type_text(action: dict[str, Any] | None, *, sensitive: bool = False) -> str:
    """What a type dispatches: the brain's verbatim text_exact only when it differs from the gated
    text by surrounding plain spaces alone (U+0020; a newline, tab or other whitespace a body may send as a
    key would act as Enter/Tab and bypass the final-action gate); secrets and credentials always type the
    gated text."""
    text = str((action or {}).get("text") or "")
    exact = (action or {}).get("text_exact")
    if sensitive or not isinstance(exact, str) or not exact:
        return text
    if exact.strip(" ") != text or exact.strip() != text:
        return text
    return exact


def _type_read_back_matches(action: dict[str, Any] | None, result: dict[str, Any] | None) -> bool:
    """Whether a type's raw read-back shows the intended text: loose equality with the field's value, or,
    for an at-caret edit inside a document (the whole document is never the typed text), the body's own
    comparison of the edited span. The body's verdict alone is not enough elsewhere: the desktop body
    counts "contains" (a typed "San Francisco" reading back "San Francisco, CA")."""
    if not isinstance(result, dict):
        return False
    if result.get("active_value_redacted") is True:
        # A sensitive value never leaves the page: the body compared it there, exactly.
        return result.get("active_value_matches_expected") is True
    if "active_value" not in result:
        return False
    intended = _exact_type_text(action)
    # active_value is capped at 500 characters for the model; the ledger copy carries up to 4000.
    observed = str(result.get("active_value_ledger") or result.get("active_value") or "")
    if _loose_value_equal(intended, observed):
        return True
    normalized = result.get("normalized_expected_value")
    if isinstance(normalized, str) and normalized and result.get("active_input_type"):
        # A date/time/month/week/range/color input stores one canonical string: the body converted
        # the typed text and read the stored value back against that form.
        return observed == normalized and result.get("active_value_matches_expected") is True
    if (
        len(observed) >= _TYPE_READ_BACK_LEDGER_CAP
        and intended.startswith(observed)
        and result.get("active_value_length") == len(intended)
    ):
        # Longer than the body reads back: everything it did read is exactly the intended text, and the
        # field's full length is the intended length (a maxlength cut at 4000 is not a match).
        return True
    at_caret = bool(result.get("typed_at_caret") or (action or {}).get("at_caret"))
    return bool(at_caret and result.get("active_value_matches_expected") is True)


def _type_read_back_failed(action: dict[str, Any] | None, result: dict[str, Any] | None) -> bool:
    """A type whose field was read back and holds something other than the intended text (truncated,
    masked, autocompleted). No read-back at all is not a failure here: there is nothing to contradict."""
    if not isinstance(result, dict):
        return False
    if result.get("active_value_redacted") is True:
        return result.get("active_value_matches_expected") is False
    return "active_value" in result and not _type_read_back_matches(action, result)


def _type_whitespace_only_note(action: dict[str, Any] | None, result: dict[str, Any] | None) -> str:
    """A read-back that matches loosely but differs from the typed text in whitespace only (a trailing
    space, a collapsed run, newlines): say so, since "matches" would claim an exact copy."""
    if not isinstance(result, dict) or result.get("active_value_redacted") is True or "active_value" not in result:
        return ""
    if result.get("typed_at_caret") or (action or {}).get("at_caret"):
        return ""
    intended = str((action or {}).get("text") or "")
    observed = str(result.get("active_value_ledger") or result.get("active_value") or "")
    if intended == observed or "".join(intended.split()) != "".join(observed.split()):
        return ""
    return (
        f"value matches except whitespace: typed {_safe_repr(intended)} but the field holds {_safe_repr(observed)}; "
        "if the exact spacing matters, fix it."
    )


def _safe_repr(text: str) -> str:
    return repr(text if len(text) <= 120 else text[:120] + "...")


def _type_value_mismatch_feedback(action: dict[str, Any], result: dict[str, Any] | None) -> str:
    if not isinstance(result, dict):
        return ""
    if result.get("typed_control_replaced") is True:
        return (
            "control replaced after typing (likely accepted): the page removed the field, so the typed value is "
            "unverified, not failed; check the screenshot for the page's response before retyping."
        )
    intended = str((action or {}).get("text") or "")
    exact_note = _type_whitespace_only_note(action, result)
    if exact_note:
        return exact_note
    line_after = result.get("edited_line_after")
    if (
        isinstance(line_after, str)
        and result.get("active_value_redacted") is not True
        and result.get("active_value_matches_expected") is not True
    ):
        # The body read the edited line itself (the caret's paragraph, or the changed text around the edit):
        # show exactly what it was and what it is now, spaces kept, instead of the whole document.
        line_before = str(result.get("edited_line_before") or "")
        return (
            f"the edited line was {line_before[:200]!r} and now reads {line_after[:200]!r} "
            f"(intended {intended[:120]!r} in place of what was selected); use the line as it now reads as "
            "truth and decide whether to fix it, retry, or ask_user."
        )
    if "active_value" not in result or (
        result.get("value_read_back") is False and not str(result.get("active_value") or "")
    ):
        # A field that exposes no readable value (a Tk entry) reads back as '': "field now shows ''... use
        # the observed value as truth" told the brain its typing was lost, and v5_memory run 1721 zoomed
        # into the field over and over to recheck it. The receipt already says to confirm it in the screenshot.
        return ""
    observed = str(result.get("active_value") or "")
    if _type_read_back_matches(action, result):
        # v3_paperwork from the brain seat: an at-caret Container ID typed exactly into the declaration
        # drew "field now shows <whole document> (intended ...); decide whether to retry" -- an
        # invitation to retype into a document that was already right.
        return ""
    return (
        f"field now shows '{_safe_trim(observed, 120)}' "
        f"(intended '{_safe_trim(intended, 120)}'); use the observed value as truth and decide whether to retry, translate, or ask_user."
    )


def _ledger_entry_for_context(entry: dict[str, Any]) -> dict[str, Any]:
    projection = {
        "control": _safe_trim(entry.get("label"), 80),
        "action": _safe_trim(entry.get("last_action"), 40),
        "attempts": int(entry.get("attempts") or 0),
        "value": _safe_trim(entry.get("verified_value"), 120) if entry.get("verified_value") is not None else None,
    }
    if entry.get("value_redacted"):
        projection.update(
            {
                "value": "[REDACTED]",
                "value_redacted": True,
                "value_length": int(entry.get("verified_value_length") or 0),
                "value_matches_expected": bool(entry.get("verified_value_matches_expected")),
            }
        )
    return projection


def _session_ledger_context(ledger: dict[str, dict[str, Any]], *, limit: int = 20) -> list[dict[str, Any]]:
    """Return oldest-to-newest compact ledger entries for the model context."""
    entries = [entry for entry in ledger.values() if isinstance(entry, dict)]
    entries.sort(key=lambda item: int(item.get("last_step") or 0))
    return [_ledger_entry_for_context(entry) for entry in entries[-max(limit, 0) :]]


def _trim_session_ledger(raw_entries: Any, *, limit: int, text_limit: int) -> list[dict[str, Any]]:
    if not isinstance(raw_entries, list):
        return []
    entries: list[dict[str, Any]] = []
    for raw in raw_entries[-max(limit, 0) :]:
        if not isinstance(raw, dict):
            continue
        entry: dict[str, Any] = {}
        if "control" in raw:
            entry["control"] = _safe_trim(raw.get("control"), min(text_limit, 80))
        if "action" in raw:
            entry["action"] = _safe_trim(raw.get("action"), 40)
        if "attempts" in raw:
            try:
                entry["attempts"] = int(raw.get("attempts") or 0)
            except (TypeError, ValueError):
                entry["attempts"] = 0
        if "value" in raw:
            value = raw.get("value")
            entry["value"] = _safe_trim(value, text_limit) if value is not None else None
        if entry:
            entries.append(entry)
    return entries


def _load_session_ledger_for_run(run_id: int | None) -> dict[str, dict[str, Any]]:
    if not run_id:
        return {}
    try:
        from app import models

        with SessionLocal() as db:
            run = db.get(models.OperatorRun, int(run_id))
            state = dict(run.confidence_state or {}) if run else {}
            raw = state.get("vision_session_ledger")
            if not isinstance(raw, dict):
                return {}
            ledger: dict[str, dict[str, Any]] = {}
            for signature, entry in raw.items():
                if isinstance(signature, str) and isinstance(entry, dict):
                    ledger[signature] = dict(entry)
            return ledger
    except Exception:
        return {}


def _load_session_document_lifecycle_token_for_run(run_id: int | None) -> str:
    if not run_id:
        return ""
    try:
        from app import models

        with SessionLocal() as db:
            run = db.get(models.OperatorRun, int(run_id))
            state = dict(run.confidence_state or {}) if run else {}
            return _safe_trim(state.get("vision_session_document_lifecycle_token"), 160)
    except Exception:
        return ""


def _session_document_lifecycle_transition(
    ledger: dict[str, dict[str, Any]],
    stored_token: str | None,
    observed_token: str | None,
) -> tuple[dict[str, dict[str, Any]], str, str]:
    """Bind browser-state memory to one live document without interpreting page meaning."""

    previous = _safe_trim(stored_token, 160)
    observed = _safe_trim(observed_token, 160)
    current = {
        signature: dict(entry)
        for signature, entry in ledger.items()
        if isinstance(signature, str) and isinstance(entry, dict)
    }
    if not observed:
        return current, previous, ""
    if not previous:
        if current:
            return {}, observed, "legacy_unbound_ledger"
        return current, observed, "initialized"
    if previous != observed:
        return {}, observed, "document_changed"
    return current, previous, ""


def _persist_session_ledger_for_run(
    run_id: int | None,
    ledger: dict[str, dict[str, Any]],
    document_lifecycle_token: str | None = None,
) -> None:
    if not run_id:
        return
    try:
        from app import models

        entries = sorted(
            ((signature, entry) for signature, entry in ledger.items() if isinstance(entry, dict)),
            key=lambda item: int(item[1].get("last_step") or 0),
        )[-80:]
        with SessionLocal() as db:
            run = db.get(models.OperatorRun, int(run_id))
            if not run:
                return
            state = dict(run.confidence_state or {})
            state["vision_session_ledger"] = {signature: dict(entry) for signature, entry in entries}
            if document_lifecycle_token is not None:
                token = _safe_trim(document_lifecycle_token, 160)
                if token:
                    state["vision_session_document_lifecycle_token"] = token
                else:
                    state.pop("vision_session_document_lifecycle_token", None)
            run.confidence_state = state
            run.updated_at = utcnow()
            db.commit()
    except Exception:
        return


def _load_satisfied_control_readbacks_for_run(run_id: int | None) -> dict[str, dict[str, Any]]:
    """Verified choice read-backs are per-document runtime memory, like the session ledger.

    Without persistence every resume forgets which questions the browser already proved
    committed, so the readiness audit re-reports them pending from partial viewports and
    the run can never converge on the final action across resumes.
    """
    if not run_id:
        return {}
    try:
        from app import models

        with SessionLocal() as db:
            run = db.get(models.OperatorRun, int(run_id))
            state = dict(run.confidence_state or {}) if run else {}
            raw = state.get("vision_satisfied_control_readbacks")
            if not isinstance(raw, dict):
                return {}
            return {
                scope: dict(entry)
                for scope, entry in raw.items()
                if isinstance(scope, str) and isinstance(entry, dict)
            }
    except Exception:
        return {}


def _persist_satisfied_control_readbacks_for_run(
    run_id: int | None,
    readbacks: dict[str, dict[str, Any]],
) -> None:
    if not run_id:
        return
    try:
        from app import models

        entries = list(readbacks.items())[-40:]
        with SessionLocal() as db:
            run = db.get(models.OperatorRun, int(run_id))
            if not run:
                return
            state = dict(run.confidence_state or {})
            state["vision_satisfied_control_readbacks"] = {
                scope: dict(entry) for scope, entry in entries if isinstance(entry, dict)
            }
            run.confidence_state = state
            run.updated_at = utcnow()
            db.commit()
    except Exception:
        return


def _load_session_context_for_run(run_id: int | None) -> dict[str, Any]:
    from app.session_context import coerce_state, new_state

