# The brain's run journal: its working notes, its plan, and the page views it left. Every pause
# (ask_user, an approval, a payment prompt) and every restart ends the loop, and a resumed loop used to
# start with none of them: v5_memory lost the briefing and v5_reconcile the invoices it had paged through.
_RUN_JOURNAL_STATE_KEY = "vision_run_journal"
_RUN_JOURNAL_PAGE_MEMORY_ENTRIES = 24
# Unverified auto-mode values kept (and listed in the summary); the count past the cap is kept exactly.
_UNVERIFIED_VALUES_KEPT = 50
_UNVERIFIED_VALUES_LISTED = 20


def _budget_spent_from(raw: Any) -> dict[str, Any]:
    """Seconds, tokens and cost earlier loops of a run used. `cost_known_usd` is the sum of the cost figures
    there were and `cost_unknown_calls` counts the calls without one; `cost_usd` is None once any call had
    none (the exact cost is unknown, but at least the known part). A journal written before the split has
    only `cost_usd`: a number is all known, None counts as one unknown call."""
    raw = raw if isinstance(raw, dict) else {}
    try:
        seconds = max(0.0, float(raw.get("seconds") or 0.0))
        tokens = max(0, int(raw.get("tokens") or 0))
        cost = raw.get("cost_usd", 0.0)
        cost = None if cost is None else max(0.0, float(cost))
        if "cost_known_usd" in raw or "cost_unknown_calls" in raw:
            known = max(0.0, float(raw.get("cost_known_usd") or 0.0))
            unknown = max(0, int(raw.get("cost_unknown_calls") or 0))
            if cost is None and not unknown:
                unknown = 1
        else:
            known, unknown = (0.0, 1) if cost is None else (cost, 0)
    except (TypeError, ValueError):
        seconds, tokens, known, unknown = 0.0, 0, 0.0, 0
    return {
        "seconds": seconds,
        "tokens": tokens,
        "cost_usd": None if unknown else known,
        "cost_known_usd": known,
        "cost_unknown_calls": unknown,
    }


def _load_run_journal_for_run(run_id: int | None) -> dict[str, Any]:
    """Notes, plan, page memory, and the steps earlier loops of this run took (labels continue)."""
    from app import vision_agent

    empty: dict[str, Any] = {
        "notes": [], "plan": "", "page_memory": [], "control_memory": [], "verified_receipts": [], "steps_before": 0,
        "delivered_answer": "", "pending_answer": "", "unverified_values": [], "unverified_total": 0,
        "budget_spent": _budget_spent_from(None),
        "escalation": {}, "self_recoveries": 0,
    }
    if not run_id:
        return empty
    try:
        from app import models

        with SessionLocal() as db:
            run = db.get(models.OperatorRun, int(run_id))
            raw = dict(run.confidence_state or {}).get(_RUN_JOURNAL_STATE_KEY) if run else None
    except Exception:
        return empty
    if not isinstance(raw, dict):
        return empty
    notes = [
        {"step": int(note.get("step") or 0), "text": str(note.get("text") or "")}
        for note in (raw.get("notes") if isinstance(raw.get("notes"), list) else [])
        if isinstance(note, dict) and str(note.get("text") or "").strip()
    ]
    while len(notes) > 1 and sum(len(note["text"]) for note in notes) > vision_agent.NOTES_KEPT_CHARS:
        del notes[0]
    page_memory = [
        {
            "url": str(entry.get("url") or "")[:500],
            "title": str(entry.get("title") or "")[:160],
            "scroll_y": entry.get("scroll_y"),
            "text": str(entry.get("text") or "")[:_PAGE_MEMORY_ENTRY_CHARS],
        }
        for entry in (raw.get("page_memory") if isinstance(raw.get("page_memory"), list) else [])
        if isinstance(entry, dict) and str(entry.get("text") or "").strip()
    ][-_RUN_JOURNAL_PAGE_MEMORY_ENTRIES:]
    try:
        steps_before = max(0, int(raw.get("steps_before") or 0))
    except (TypeError, ValueError):
        steps_before = 0
    # Controls that left the screen and what earlier loops verified: a resumed loop still knows them.
    control_memory = [
        dict(entry) for entry in (raw.get("control_memory") if isinstance(raw.get("control_memory"), list) else [])
        if isinstance(entry, dict)
    ][-8:]
    verified_receipts = [
        dict(receipt) for receipt in (raw.get("verified_receipts") if isinstance(raw.get("verified_receipts"), list) else [])
        if isinstance(receipt, dict) and receipt.get("outcome") == "verified_succeeded"
    ][-12:]
    # Auto-mode values typed without verification, recorded by earlier loops of this run: a resumed loop
    # still reports them, and the exact total survives the cap on the stored list.
    unverified_values = [
        {"label": str(item.get("label") or "")[:80], "reason": str(item.get("reason") or "")[:60]}
        for item in (raw.get("unverified_values") if isinstance(raw.get("unverified_values"), list) else [])
        if isinstance(item, dict)
    ][:_UNVERIFIED_VALUES_KEPT]
    try:
        unverified_total = max(len(unverified_values), int(raw.get("unverified_total") or 0))
    except (TypeError, ValueError):
        unverified_total = len(unverified_values)
    return {
        "notes": notes,
        "unverified_values": unverified_values,
        "unverified_total": unverified_total,
        "plan": str(raw.get("plan") or "")[: vision_agent.PLAN_MAX_CHARS],
        "page_memory": page_memory,
        "control_memory": control_memory,
        "verified_receipts": verified_receipts,
        "steps_before": steps_before,
        "delivered_answer": str(raw.get("delivered_answer") or "")[:_ANSWER_MAX_CHARS],
        "pending_answer": str(raw.get("pending_answer") or "")[:_ANSWER_MAX_CHARS],
        "budget_spent": _budget_spent_from(raw.get("budget_spent")),
        "escalation": dict(raw.get("escalation")) if isinstance(raw.get("escalation"), dict) else {},
        "self_recoveries": _bounded_self_recoveries(raw.get("self_recoveries")),
    }


# Set by run_vision_loop; the loop registers a callable returning its spend so the outer finally can persist it.
_RUN_SPEND_PROBE: contextvars.ContextVar[dict[str, Any] | None] = contextvars.ContextVar("lumen_run_spend_probe", default=None)


def _persist_spend_for_run(run_id: int | None, spend: dict[str, Any]) -> None:
    """Write only the spend (and step count) into the run journal, leaving everything else as persisted."""
    if not run_id:
        return
    from app import models

    with SessionLocal() as db:
        run = db.get(models.OperatorRun, int(run_id))
        if not run:
            return
        state = dict(run.confidence_state or {})
        journal = dict(state.get(_RUN_JOURNAL_STATE_KEY) or {})
        # Spend only grows: never let a late write replace a larger figure already persisted.
        new_spent = _budget_spent_from(spend.get("budget_spent"))
        old_spent = _budget_spent_from(journal.get("budget_spent"))
        if (new_spent["tokens"], new_spent["seconds"]) >= (old_spent["tokens"], old_spent["seconds"]):
            journal["budget_spent"] = new_spent
        journal["steps_before"] = max(int(journal.get("steps_before") or 0), int(spend.get("steps_before") or 0))
        state[_RUN_JOURNAL_STATE_KEY] = journal
        run.confidence_state = state
        run.updated_at = utcnow()
        db.commit()


def _bounded_self_recoveries(value: Any) -> int:
    """In-loop self-recoveries this run has spent (brain_escalation.SELF_RECOVERY_LIMIT per run)."""
    try:
        return min(max(0, int(value or 0)), SELF_RECOVERY_LIMIT)
    except (TypeError, ValueError):
        return 0


def _persist_run_journal_for_run(run_id: int | None, journal: dict[str, Any]) -> None:
    if not run_id:
        return
    try:
        from app import models

        with SessionLocal() as db:
            run = db.get(models.OperatorRun, int(run_id))
            if not run:
                return
            state = dict(run.confidence_state or {})
            state[_RUN_JOURNAL_STATE_KEY] = {
                "notes": [dict(note) for note in journal.get("notes") or [] if isinstance(note, dict)],
                "plan": str(journal.get("plan") or ""),
                "page_memory": [
                    dict(entry) for entry in (journal.get("page_memory") or [])[-_RUN_JOURNAL_PAGE_MEMORY_ENTRIES:]
                    if isinstance(entry, dict)
                ],
                "control_memory": [
                    dict(entry) for entry in (journal.get("control_memory") or [])[-8:] if isinstance(entry, dict)
                ],
                "verified_receipts": [
                    dict(receipt) for receipt in (journal.get("verified_receipts") or [])[-12:] if isinstance(receipt, dict)
                ],
                "steps_before": int(journal.get("steps_before") or 0),
                "self_recoveries": _bounded_self_recoveries(journal.get("self_recoveries")),
                "delivered_answer": str(journal.get("delivered_answer") or "")[:_ANSWER_MAX_CHARS],
                "pending_answer": str(journal.get("pending_answer") or "")[:_ANSWER_MAX_CHARS],
                "unverified_values": [
                    dict(item) for item in (journal.get("unverified_values") or [])[:_UNVERIFIED_VALUES_KEPT]
                    if isinstance(item, dict)
                ],
                "unverified_total": int(journal.get("unverified_total") or 0),
                "budget_spent": _budget_spent_from(journal.get("budget_spent")),
                "escalation": dict(journal.get("escalation") or {}),
            }
            run.confidence_state = state
            run.updated_at = utcnow()
            db.commit()
    except Exception:
        return


