def _http_origin(url: Any) -> str:
    """scheme://host:port of a page URL (default ports filled in); "" when it has none."""
    try:
        parsed = urlparse(str(url or ""))
        scheme = (parsed.scheme or "").lower()
        host = (parsed.hostname or "").lower()
        port = parsed.port or {"http": 80, "https": 443}.get(scheme)
        return f"{scheme}://{host}:{port}" if scheme and host and port else ""
    except Exception:  # noqa: BLE001
        return ""


def _call_candidate_scope_judge(user_id: int, *, goal: str, scopes: list[str]) -> dict[str, Any]:
    from app.lumen_model import LumenModelClient

