def _field_subject_scope(page_url: Any, bound_control: dict[str, Any] | None, page_evidence: Any) -> tuple[str, str, str]:
    """Where the field sits: page origin + path, the owning form, the document lifecycle."""
    from urllib.parse import urlsplit

    parts = urlsplit(str(page_url or ""))
    where = f"{parts.scheme}://{parts.netloc}{parts.path}"
    form_id = _safe_trim((bound_control or {}).get("form_id"), 40) if isinstance(bound_control, dict) else ""
    lifecycle = _safe_trim((page_evidence or {}).get("document_lifecycle_token"), 160) if isinstance(page_evidence, dict) else ""
    return where, form_id, lifecycle


async def _field_subject(
    *,
    run_id: int,
    user_id: int,
    goal: str,
    action: dict[str, Any],
    value: str,
    cited_source: str,
    bound_control: dict[str, Any] | None,
    bound_label: str | None,
    label: str,
    scope: tuple[str, str, str],
    step: Any = None,
    checked_source: str = "",
) -> str:
    """Whose fact the field asks for (user | third_party | not_personal), judged by the fail-closed model.

    Unavailable, timed-out or invalid verdicts are "user".
    Verdicts are cached per run, field, value, page and form, and each is logged."""

    if not value:
        return "not_personal"
    field = _safe_trim(bound_label or action.get("question") or label, 160)
    context_bits = [
        _control_label(bound_control, limit=200) if isinstance(bound_control, dict) else "",
        _safe_trim((bound_control or {}).get("context_text"), 200) if isinstance(bound_control, dict) else "",
        _safe_trim(action.get("question"), 200),
    ]
    control_context = " | ".join(bit for bit in context_bits if bit)
    quote = str(action.get("grounding_quote") or "")
    key = (
        run_id,
        _normal_grounding_text(field),
        _normal_grounding_text(value),
        _normal_grounding_text(control_context),
        *scope,
    )
    verdict = _FIELD_SUBJECT_CACHE.get(key)
    if verdict is not None and verdict.get("fail_closed") and verdict.get("_step") != step:
        # A fail-closed verdict (unavailable, timed out) holds for the rest of the step that got it; the next step retries.
        verdict = None
    cached = verdict is not None
    if verdict is None:
        try:
            verdict = await asyncio.wait_for(
                asyncio.to_thread(
                    _call_field_subject_judge,
                    user_id,
                    field=field,
                    goal=goal,
                    quote=quote,
                    proposed_value=value,
                    control_context=control_context,
                ),
                timeout=_judge_wall(_FIELD_SUBJECT_JUDGE_TIMEOUT_SECONDS),
            )
        except Exception:  # noqa: BLE001 - fails toward the user
            verdict = {"subject": "user", "reason": "field_subject_judge_failed", "fail_closed": True}
        if not isinstance(verdict, dict):
            verdict = {"subject": "user", "reason": "field_subject_judge_invalid", "fail_closed": True}
        if len(_FIELD_SUBJECT_CACHE) > 512:
            _FIELD_SUBJECT_CACHE.clear()
        _FIELD_SUBJECT_CACHE[key] = {**verdict, "_step": step} if verdict.get("fail_closed") else verdict
    subject = verdict.get("subject") if verdict.get("subject") in {"user", "third_party", "not_personal"} else "user"
    try:
        await asyncio.to_thread(
            _db_event,
            run_id,
            "VISION_FIELD_SUBJECT_VERDICT",
            {
                "subject": subject,
                "fail_closed": bool(verdict.get("fail_closed")) or verdict.get("subject") != subject,
                "cached": cached,
                "control": _safe_trim(bound_label, 80),
                "reason": _safe_trim(verdict.get("reason"), 160),
                "cited_source": cited_source,
                "checked_source": checked_source or cited_source,
                "sequence_label": label,
                "runtime_build": _VISION_RUNTIME_BUILD,
            },
        )
    except Exception:  # noqa: BLE001 - the verdict still binds
        pass
    return subject


_GOAL_PAGE_VALUE_RE = re.compile(
    r"\b(?:read|copy|note|take|use|find|get|look\s+up|enter|type)\b[^.;\n]{0,80}?"
    r"\b(?:on|from|in|shown\s+on|displayed\s+on|printed\s+on)\s+(?:the|this|that)\s+"
    r"(?:page|screen|site|web\s*page|window|dialog|form|app|email|message|document)\b",
    re.IGNORECASE,
)


def _goal_directs_value_from_page(goal: Any) -> bool:
    """Whether the user's goal itself tells Lumen to take a value from what is shown ('read the visit code on the
    page, type it into the code box'). Read from the trusted goal only, never from page text."""
    return bool(_GOAL_PAGE_VALUE_RE.search(str(goal or "")))


def _field_subject_rejection(action: dict[str, Any]) -> dict[str, Any]:
    return {
        "ok": False,
        "reason": "page_value_about_user",
        "source": "page",
        "whose_fact_user": True,
        "feedback": _vision_grounding_citation_feedback(action, "page_value_about_user", "page"),
    }


async def _whose_fact_gate(
    *,
    run_id: int,
    user_id: int,
    goal: str,
    action: dict[str, Any],
    citation_check: dict[str, Any],
    bound_control: dict[str, Any] | None,
    bound_label: str | None,
    label: str,
    scope: tuple[str, str, str],
    step: Any = None,
) -> dict[str, Any]:
    """Owner policy 2026-10-07: a page-cited typed or chosen value never fills a field that asks for a fact about the user.

    The model decides whose fact the field asks for; the code enforces it. Returns citation_check, replaced by a
    failure on a user verdict (unavailable and invalid verdicts count as the user)."""

    value = str(action.get("text") or "").strip() or str(citation_check.get("derived_choice_text") or "").strip()
    if (
        _normalize_grounding_source(citation_check.get("source")) == "page"
        and citation_check.get("ok") is not False
        and _goal_directs_value_from_page(goal)
    ):
        # The user's own goal says to read this value off the page ("read the visit code on the page and type
        # it"): the page is the source the user named, so it is not an ungrounded fact about the user. Only the
        # trusted goal can say so; page text never can.
        try:
            await asyncio.to_thread(
                _db_event, run_id, "VISION_FIELD_SUBJECT_GOAL_DIRECTED",
                {"sequence_label": label, "runtime_build": _VISION_RUNTIME_BUILD},
            )
        except Exception:  # noqa: BLE001 - logging never changes the outcome
            pass
        return citation_check
    subject = await _field_subject(
        run_id=run_id, user_id=user_id, goal=goal, action=action, value=value,
        cited_source=_normalize_grounding_source(action.get("grounding_source")) or "page",
        checked_source=_normalize_grounding_source(citation_check.get("source")) or "page",
        bound_control=bound_control, bound_label=bound_label, label=label, scope=scope, step=step,
    )
    return _field_subject_rejection(action) if subject == "user" else citation_check


