def _db_run_interruption(run_id: int | None) -> str | None:
    """Return the backend-owned lifecycle signal for an active browser drive.

    ``WAITING_FOR_USER`` alone is not an interruption because ordinary model questions use that
    state too. Only the explicit ``session_control`` written by Pause interrupts the in-flight
    turn. Cancellation remains a distinct terminal result.
    """
    if not run_id:
        return None
    try:
        from app import models

        with SessionLocal() as db:
            run = db.get(models.OperatorRun, int(run_id))
            if not run:
                return None
            state = str(run.current_state or "").upper()
            session_control = (run.confidence_state or {}).get("session_control") if isinstance(run.confidence_state, dict) else {}
            control_status = str((session_control or {}).get("status") or "").lower()
            if state == "CANCELLED" or control_status == "stopped":
                return "user_cancelled"
            if control_status == "paused":
                return "session_paused"
            return None
    except Exception:
        return None


async def _interruption_requested(should_cancel: Callable[[], bool | str | None] | None) -> str | None:
    if should_cancel is None:
        return None
    try:
        raw = await asyncio.to_thread(should_cancel)
    except Exception:
        return None
    if isinstance(raw, str):
        normalized = raw.strip().lower()
        if not normalized:
            return None
        if normalized in {"session_paused", "paused"}:
            return "session_paused"
        if normalized in {"user_cancelled", "cancelled", "canceled", "stopped"}:
            return "user_cancelled"
        # Unknown truthy interruption signals fail closed as cancellation instead of allowing an
        # in-flight mutation to continue under an unrecognized lifecycle state.
        return "user_cancelled"
    return "user_cancelled" if bool(raw) else None


def _interruption_state(reason: str | None) -> str:
    return "WAITING_FOR_USER" if reason == "session_paused" else "CANCELLED"


def _resume_facts_for_user(db: Any, user_id: int) -> dict[str, Any]:
    """The user's real resume text (parsed) so the brain answers form questions from actual
    experience — not 'examples are not detailed in my profile'. Empty when no text is available."""
    resume = active_base_resume(db, user_id)
    text = ((resume.base_resume_text if resume else "") or "").strip()
    return {"resume_text": text[:12000]} if text else {}


def _candidate_retrieval_context_for_user(
    user_id: int,
    run_id: int,
    source_scopes: list[str],
) -> dict[str, Any]:
    """Load private candidate sources only after the brain requests `query_candidate`.

    Generic browser runs deliberately omit these sources from the standing vision packet. This
    helper constructs only the explicitly authorized and requested source families, rather than
    loading the complete private context and filtering it afterward.
    """
    from app.candidate_context import CandidateContextEngine

    allowed = {
        str(scope or "").strip().lower()
        for scope in source_scopes
        if str(scope or "").strip().lower() in {"profile", "resume", "memory"}
    }
    result: dict[str, Any] = {}
    with SessionLocal() as db:
        if "profile" in allowed:
            candidate_context = CandidateContextEngine(db).compact_defaults_with_provenance(
                user_id,
                include_seeded_facts=True,
            )
            raw_provenance = candidate_context.get("provenance") or []
            result["profile"] = candidate_context.get("values") or {}
            result["profile_provenance"] = [
                item for item in raw_provenance if isinstance(item, dict)
            ]
        if "resume" in allowed:
            result["resume_facts"] = _resume_facts_for_user(db, user_id)
    if "memory" in allowed:
        result["saved_answers"] = _saved_answers_for_user(user_id)
        result["human_answers"] = _human_answers_for_run(run_id)
    return result


def _resume_evidence_chunks(text: Any, *, lines_per_chunk: int = 7, overlap_lines: int = 2) -> list[dict[str, str]]:
    """Enumerate bounded, overlapping raw resume passages without interpreting their meaning."""
    lines = [re.sub(r"\s+", " ", str(line or "")).strip() for line in str(text or "").splitlines()]
    lines = [line for line in lines if line]
    if not lines:
        return []
    stride = max(1, lines_per_chunk - overlap_lines)
    chunks: list[dict[str, str]] = []
    for start in range(0, len(lines), stride):
        value = _safe_trim(" ".join(lines[start : start + lines_per_chunk]), 900)
        if value:
            chunks.append({"source": "resume", "label": f"resume_lines_{start + 1}_{min(start + lines_per_chunk, len(lines))}", "value": value})
        if start + lines_per_chunk >= len(lines):
            break
    return chunks


def _validated_closed_world_attestation_value(value: Any) -> dict[str, Any] | None:
    """Validate the exact server-authored canonical attestation projection.

    This validates storage provenance and integrity only. It deliberately does not interpret a
    browser question or compare a page entity with the attested member set; that remains the
    grounding model's job.
    """

    if not isinstance(value, str) or not value or len(value) > _CLOSED_WORLD_ATTESTATION_VALUE_MAX_CHARS:
        return None
    try:
        payload = json.loads(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        return None
    if not isinstance(payload, dict) or set(payload) != _CLOSED_WORLD_ATTESTATION_FIELDS:
        return None
    if json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ) != value:
        return None

    attestation_id = payload.get("attestation_id")
    complete_through = payload.get("complete_through")
    version = payload.get("version")
    members = payload.get("members")
    if (
        not isinstance(attestation_id, str)
        or not attestation_id
        or not isinstance(complete_through, str)
        or not complete_through
        or type(version) is not int
        or version < 1
        or not isinstance(members, list)
        or len(members) > 100
        or payload.get("subject") != "employment_history"
        or payload.get("set_key") != "employers"
        or payload.get("set_semantics") != "complete_membership"
        or payload.get("membership_answer") != "Yes"
        or payload.get("absence_answer") != "No"
        or payload.get("exhaustive") is not True
        or payload.get("provenance") != "explicit_user_attestation"
        or payload.get("source") != "profile_attestation_api"
    ):
        return None

    seen_members: set[str] = set()
    for member in members:
        if (
            not isinstance(member, str)
            or not member
            or len(member) > 240
            or re.sub(r"\s+", " ", member).strip() != member
            or member.casefold() in seen_members
        ):
            return None
        seen_members.add(member.casefold())

    supplied_hash = payload.get("attestation_sha256")
    if not isinstance(supplied_hash, str) or not re.fullmatch(r"[0-9a-f]{64}", supplied_hash):
        return None
    unsigned_payload = {
        key: item for key, item in payload.items() if key != "attestation_sha256"
    }
    expected_hash = hashlib.sha256(
        json.dumps(
            unsigned_payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    if not secrets.compare_digest(supplied_hash, expected_hash):
        return None
    return payload


def _closed_world_attestation_contract(memory: Any) -> str:
    """Recognize only the server-owned profile-memory projection of an attestation."""

    if not isinstance(memory, dict):
        return ""
    payload = _validated_closed_world_attestation_value(memory.get("value"))
    if payload is None:
        return ""
    attestation_id = str(payload["attestation_id"])
    if str(memory.get("key") or "").strip() != f"closed_world_attestation.{attestation_id}":
        return ""
    if str(memory.get("source") or "").strip() != (
        "user_profiles.profile_json.closed_world_attestations."
        f"{attestation_id}"
    ):
        return ""
    return _CLOSED_WORLD_ATTESTATION_EVIDENCE_CONTRACT


def _closed_world_attestation_fact_contract(fact: Any) -> str:
    """Validate a propagated fact after its server-owned source path has been compacted."""

    if (
        not isinstance(fact, dict)
        or str(fact.get("evidence_contract") or "")
        != _CLOSED_WORLD_ATTESTATION_EVIDENCE_CONTRACT
        or _normalize_grounding_source(fact.get("source")) != "profile"
    ):
        return ""
    payload = _validated_closed_world_attestation_value(fact.get("value"))
    if payload is None:
        return ""
    expected_label = f"profile_memory.closed_world_attestation.{payload['attestation_id']}"
    if str(fact.get("label") or "").strip() != expected_label:
        return ""
    return _CLOSED_WORLD_ATTESTATION_EVIDENCE_CONTRACT


def _reserved_closed_world_attestation_memory(memory: Any) -> bool:
    if not isinstance(memory, dict):
        return False
    return str(memory.get("key") or "").strip().startswith(
        "closed_world_attestation."
    ) or str(memory.get("source") or "").strip().startswith(
        "user_profiles.profile_json.closed_world_attestations."
    )


def _reserved_closed_world_attestation_fact(fact: Any) -> bool:
    if not isinstance(fact, dict):
        return False
    return (
        str(fact.get("evidence_contract") or "")
        == _CLOSED_WORLD_ATTESTATION_EVIDENCE_CONTRACT
        or str(fact.get("label") or "").strip().startswith(
            "profile_memory.closed_world_attestation."
        )
    )


def _profile_without_invalid_closed_world_attestations(profile: Any) -> dict[str, Any]:
    """Drop corrupted reserved records instead of downgrading them to ordinary profile facts."""

    if not isinstance(profile, dict):
        return {}
    sanitized = dict(profile)
    raw_memory = profile.get("profile_memory")
    if not isinstance(raw_memory, list):
        return sanitized
    sanitized["profile_memory"] = [
        memory
        for memory in raw_memory
        if isinstance(memory, dict)
        and (
            not _reserved_closed_world_attestation_memory(memory)
            or bool(_closed_world_attestation_contract(memory))
        )
    ]
    return sanitized


def _candidate_evidence_entries(context: dict[str, Any], *, source_scope: str) -> list[dict[str, str]]:
    scope = str(source_scope or "all").strip().lower() or "all"
    entries: list[dict[str, str]] = []
    if scope in {"all", "resume"}:
        entries.extend(_resume_evidence_chunks(((context.get("resume_facts") or {}).get("resume_text"))))
    if scope in {"all", "profile", "memory"}:
        allowed = (
            {"profile"}
            if scope == "profile"
            else {"saved_answer", "human_answer"}
            if scope == "memory"
            else {"profile", "saved_answer", "human_answer"}
        )
        candidate_context = dict(context)
        profile = context.get("profile") if isinstance(context.get("profile"), dict) else {}
        profile_memory = [
            item
            for item in (profile.get("profile_memory") or [])
            if isinstance(item, dict)
        ]
        if profile_memory:
            # CandidateContextEngine already exposes each durable memory record as a compact
            # {key, value, source} fact. Enumerate each record once instead of recursively
            # spending the retrieval window on its storage metadata. This is storage-shape
            # normalization only; the retriever/model still decides relevance and meaning.
            candidate_context["profile"] = {
                key: value
                for key, value in profile.items()
                if key != "profile_memory"
            }
        for entry in _vision_user_data_candidates(candidate_context, limit=80):
            if _normalize_grounding_source(entry.get("source")) in allowed:
                entries.append(entry)
        if "profile" in allowed:
            for index, memory in enumerate(profile_memory):
                evidence_contract = _closed_world_attestation_contract(memory)
                if (
                    _reserved_closed_world_attestation_memory(memory)
                    and not evidence_contract
                ):
                    continue
                value = _safe_trim(memory.get("value"), 900)
                if not value:
                    continue
                key = _safe_trim(memory.get("key"), 100) or f"record_{index + 1}"
                entry = {
                    "source": "profile",
                    "label": f"profile_memory.{key}",
                    "value": value,
                }
                if evidence_contract:
                    entry["evidence_contract"] = evidence_contract
                entries.append(entry)
    deduped: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for entry in entries:
        source = _normalize_grounding_source(entry.get("source"))
        value = _safe_trim(entry.get("value"), 900)
        key = (source, _normal_grounding_text(value))
        if source not in _GROUNDING_USER_DATA_SOURCES or not value or key in seen:
            continue
        seen.add(key)
        normalized_entry = {
            "source": source,
            "label": _safe_trim(entry.get("label"), 120),
            "value": value,
        }
        evidence_contract = _closed_world_attestation_fact_contract(entry)
        if evidence_contract:
            normalized_entry["evidence_contract"] = evidence_contract
        deduped.append(normalized_entry)
    if scope != "all":
        return deduped[:_CANDIDATE_EVIDENCE_MAX_ENTRIES]

    # Preserve bounded representation from every authorized source family. This is source-shape
    # scheduling only: relevance and meaning remain model-owned. Without it, a long resume can
    # consume the entire packet before raw profile or memory entries are exposed to the retriever.
    source_families: dict[str, list[dict[str, str]]] = {
        "profile": [],
        "resume": [],
        "memory": [],
    }
    for entry in deduped:
        source = _normalize_grounding_source(entry.get("source"))
        family = (
            "profile"
            if source == "profile"
            else "resume"
            if source == "resume"
            else "memory"
        )
        source_families[family].append(entry)
    family_order = ("profile", "resume", "memory")
    quotas = {family: 0 for family in family_order}
    remaining = min(
        _CANDIDATE_EVIDENCE_MAX_ENTRIES,
        sum(len(items) for items in source_families.values()),
    )
    while remaining:
        added = False
        for family in family_order:
            if quotas[family] >= len(source_families[family]):
                continue
            quotas[family] += 1
            remaining -= 1
            added = True
            if not remaining:
                break
        if not added:
            break

    sampled_families: dict[str, list[dict[str, str]]] = {}
    for family in family_order:
        family_entries = source_families[family]
        quota = quotas[family]
        if quota <= 0:
            sampled_families[family] = []
        elif quota >= len(family_entries):
            sampled_families[family] = family_entries
        elif quota == 1:
            sampled_families[family] = [family_entries[0]]
        else:
            # Even structural sampling retains both ends of a long source family instead of
            # silently preferring whichever facts its storage serializer happened to emit first.
            indexes = [
                (sample_index * (len(family_entries) - 1)) // (quota - 1)
                for sample_index in range(quota)
            ]
            sampled_families[family] = [family_entries[index] for index in indexes]
    balanced: list[dict[str, str]] = []
    offsets = {family: 0 for family in family_order}
    while len(balanced) < _CANDIDATE_EVIDENCE_MAX_ENTRIES:
        added = False
        for family in family_order:
            offset = offsets[family]
            family_entries = sampled_families[family]
            if offset >= len(family_entries):
                continue
            balanced.append(family_entries[offset])
            offsets[family] = offset + 1
            added = True
            if len(balanced) >= _CANDIDATE_EVIDENCE_MAX_ENTRIES:
                break
        if not added:
            break
    return balanced


def _call_candidate_evidence_retriever(
    user_id: int,
    *,
    query: str,
    entries: list[dict[str, str]],
    task_context: dict[str, Any] | None = None,
    limit: int | None = None,
) -> dict[str, Any]:
    from app.lumen_model import LumenModelClient

    with SessionLocal() as db:
        return LumenModelClient(db, user_id=user_id).retrieve_candidate_evidence(
            query=query,
            entries=entries,
            limit=limit or _CANDIDATE_QUERY_MAX_RESULTS,
            task_context=task_context,
        )


def _retrieve_candidate_evidence(
    user_id: int,
    *,
    query: str,
    source_scope: str,
    context: dict[str, Any],
    excluded_facts: list[dict[str, str]] | None = None,
    task_context: dict[str, Any] | None = None,
    page: int = 0,
) -> dict[str, Any]:
    all_entries = _candidate_evidence_entries(context, source_scope=source_scope)
    page = max(0, int(page or 0))
    source_entry_counts = {"profile": 0, "resume": 0, "memory": 0}
    for entry in all_entries:
        source = _normalize_grounding_source(entry.get("source"))
        family = (
            "profile"
            if source == "profile"
            else "resume"
            if source == "resume"
            else "memory"
        )
        source_entry_counts[family] += 1
    excluded_signatures = {
        (
            _normalize_grounding_source(item.get("source")),
            _normal_grounding_text(item.get("value")),
        )
        for item in (excluded_facts or [])
        if isinstance(item, dict)
    }
    entries = [
        entry
        for entry in all_entries
        if (
            _normalize_grounding_source(entry.get("source")),
            _normal_grounding_text(entry.get("value")),
        )
        not in excluded_signatures
    ]
    if not entries:
        return {
            "facts": [],
            "reason": "No candidate passages were available in that source scope.",
            "metadata": {},
            "fallback": False,
            "retrieval_succeeded": not bool(all_entries),
            "candidate_count": len(all_entries),
            "eligible_candidate_count": 0,
            "model_visible_candidate_count": 0,
            "source_entry_counts": source_entry_counts,
        }
    verdict = _call_candidate_evidence_retriever(
        user_id,
        query=query,
        entries=entries,
        task_context=task_context,
        # one page past the one asked for, so the reply can say how many more facts match
        limit=min(_CANDIDATE_QUERY_MAX_FETCH, _CANDIDATE_QUERY_MAX_RESULTS * (page + 2)),
    )
    indexes = [int(index) for index in (verdict.get("indexes") or []) if isinstance(index, int) or str(index).isdigit()]
    ranked_facts = [entries[index] for index in indexes if 0 <= index < len(entries)]
    page_start = page * _CANDIDATE_QUERY_MAX_RESULTS
    facts = ranked_facts[page_start : page_start + _CANDIDATE_QUERY_MAX_RESULTS]
    more_count = max(0, len(ranked_facts) - page_start - _CANDIDATE_QUERY_MAX_RESULTS)
    metadata = dict(verdict.get("metadata") or {})
    parse_status = str(metadata.get("parse_status") or "").strip().lower()
    finish_reason = str(metadata.get("finish_reason") or "").strip().lower()
    retrieval_succeeded = bool(
        isinstance(verdict.get("indexes"), list)
        and (metadata.get("provider") or metadata.get("model"))
        and not metadata.get("error")
        and metadata.get("raw_output_empty") is not True
        and parse_status not in {"empty", "non_json", "invalid", "error"}
        and finish_reason not in {"length", "max_tokens"}
    )
    return {
        "facts": facts,
        "more_count": more_count,
        "page": page,
        "reason": str(verdict.get("reason") or ""),
        "metadata": metadata,
        "fallback": False,
        "retrieval_succeeded": retrieval_succeeded,
        "candidate_count": len(all_entries),
        "eligible_candidate_count": len(entries),
        "model_visible_candidate_count": int(
            verdict.get("candidate_count")
            if isinstance(verdict.get("candidate_count"), int)
            else len(entries)
        ),
        "source_entry_counts": source_entry_counts,
    }


def _merge_candidate_evidence_facts(
    existing: list[dict[str, str]],
    incoming: Any,
    *,
    limit: int = _RETRIEVED_EVIDENCE_LEDGER_LIMIT,
) -> tuple[list[dict[str, str]], int]:
    """Merge raw source-labelled passages without interpreting or ranking their meaning."""
    merged = [dict(item) for item in existing if isinstance(item, dict)]
    seen = {
        (_normalize_grounding_source(item.get("source")), _normal_grounding_text(item.get("value")))
        for item in merged
    }
    new_count = 0
    for fact in incoming or []:
        if not isinstance(fact, dict):
            continue
        evidence_contract = _closed_world_attestation_fact_contract(fact)
        if _reserved_closed_world_attestation_fact(fact) and not evidence_contract:
            continue
        normalized = {
            "source": _normalize_grounding_source(fact.get("source")),
            "label": _safe_trim(fact.get("label"), 120),
            "value": _safe_trim(fact.get("value"), 900),
        }
        if evidence_contract:
            normalized["evidence_contract"] = evidence_contract
        signature = (normalized["source"], _normal_grounding_text(normalized["value"]))
        if normalized["source"] not in _GROUNDING_USER_DATA_SOURCES or not normalized["value"] or signature in seen:
            continue
        seen.add(signature)
        merged.append(normalized)
        new_count += 1
    return merged[-max(1, int(limit or _RETRIEVED_EVIDENCE_LEDGER_LIMIT)) :], new_count


def _upload_documents_for_user(
    db: Any,
    user_id: int,
    resume_version_id: int | None = None,
    *,
    expected_application_id: int | None = None,
    expected_job_posting_id: int | None = None,
) -> dict[str, dict[str, Any]]:
    import os

    from app import models
    from sqlalchemy import select

    docs: dict[str, dict[str, Any]] = {}
    resume_artifact = selected_resume_artifact(
        db,
        user_id,
        resume_version_id,
        expected_application_id=expected_application_id,
        expected_job_posting_id=expected_job_posting_id,
    )
    resume_path = str((resume_artifact.pdf_path if resume_artifact else "") or "").strip()
    if resume_artifact and resume_path and os.path.isfile(resume_path) and os.access(resume_path, os.R_OK):
        docs["resume"] = {
            "role": "resume",
            "artifact_id": int(resume_artifact.id),
            "resume_id": int(resume_artifact.resume_id),
            "resume_version_id": int(resume_artifact.resume_version_id) if resume_artifact.resume_version_id else None,
            "artifact_type": str(resume_artifact.artifact_type or ""),
            "application_id": int(expected_application_id) if expected_application_id is not None else None,
            "job_posting_id": int(expected_job_posting_id) if expected_job_posting_id is not None else None,
            "download_path": f"/resume-artifacts/{int(resume_artifact.id)}/download",
            # This computer's copy: the extension attaches it by path when the page refuses an injected file, with no
            # download (a download asks "Save As" when the user's Chrome asks where to save each file).
            "local_path": os.path.abspath(resume_path),
            "filename": os.path.basename(resume_path) or "resume.pdf",
            "file_size": getattr(resume_artifact, "file_size", 0),
            "artifact_source": "stored_resume",
        }

    artifacts = db.scalars(
        select(models.ApplicationArtifact)
        .where(
            models.ApplicationArtifact.user_id == user_id,
            models.ApplicationArtifact.status != "deleted",
            models.ApplicationArtifact.storage_path.isnot(None),
        )
        .order_by(models.ApplicationArtifact.id.desc())
    ).all()
    for artifact in artifacts:
        role = normalize_artifact_role(artifact.artifact_kind, default="")
        storage_path = str(artifact.storage_path or "").strip()
        if (
            not role
            or role == "resume"
            or role in docs
            or not storage_path
            or not os.path.isfile(storage_path)
            or not os.access(storage_path, os.R_OK)
        ):
            continue
        docs[role] = {
            "role": role,
            "artifact_id": int(artifact.id),
            "download_path": f"/artifacts/{int(artifact.id)}/download",
            "local_path": os.path.abspath(storage_path),
            "filename": str(artifact.filename or f"{role}.pdf"),
            "display_name": (artifact.metadata_json or {}).get("display_name") or artifact.filename,
            "file_size": getattr(artifact, "file_size", 0),
            "artifact_source": str(artifact.source or "approved_artifact"),
        }
    return docs


def _on_demand_resume_document_for_user(user_id: int) -> dict[str, dict[str, Any]]:
    """Load only the saved resume artifact after the run's resume capability is exercised."""
    with SessionLocal() as db:
        resume_document = dict(_upload_documents_for_user(db, user_id).get("resume") or {})
    return {"resume": resume_document} if resume_document else {}


def _create_in_browser_question_unlocked(run_id: int, field: dict[str, Any]) -> bool:
    """Create a field-approval question for an unresolvable field so it renders in the chat as a
    choice card (reusing the runtime's field-approval task + the question builder)."""
    from app import models
    from app.cognition import OperatorChatService
    from app.runtime import OperatorRuntimeEngine
    from sqlalchemy import select

    label = _compact_text(field.get("label"), _ASK_LABEL_MAX_CHARS)
    if not label:
        raise RuntimeError("in_browser_question_requires_non_empty_label")

    with SessionLocal() as db:
        run = db.get(models.OperatorRun, run_id)
        if not run or str(run.current_state or "").upper() in _QUESTION_TERMINAL_STATES:
            return False
        run_state = dict(run.confidence_state or {})
        session_control = (
            run_state.get("session_control")
            if isinstance(run_state.get("session_control"), dict)
            else {}
        )
        if str((session_control or {}).get("status") or "").lower() == "stopped":
            return False
        from app.form_graph import legacy_required, requiredness

        req = requiredness(field)
        OperatorRuntimeEngine(db)._phase2_upsert_required_field_approval_task(
            run,
            field={
                "node_id": field.get("node_id"),
                "snapshot_id": field.get("snapshot_id"),
                "label": label,
                "options": field.get("options") or [],
                "option_refs": field.get("option_refs") or [],
                "is_choice": bool(field.get("is_choice")),
                # A checkbox group (the ask's multi-select flag) stays a multi-select card; dropping it made
                # every in-browser choice single-choice, so the rest of a "Select 3" set could not be picked.
                "multiple": bool(field.get("multiple")),
                "required": legacy_required(req),
                "requiredness": req,
                # Forward the full live field/control metadata so the task can classify document
                # capability (cover-letter -> upload/generate/choose modes) and bind to the real
                # control. Without these the binding falls back to control_kind="field" and the
                # classifier sees nothing -> the card collapses to reply_text only.
                "role": field.get("role"),
                "control_kind": field.get("control_kind") or field.get("role"),
                "input_type": field.get("input_type"),
                "value_state": field.get("value_state"),
                "section_heading": field.get("section_heading"),
                "field_ref": field.get("field_ref") or {},
                "element_ref": field.get("element_ref") or {},
                "locator_ref": field.get("locator_ref") or {},
                "selector": field.get("selector"),
                "observation_id": field.get("observation_id") or field.get("snapshot_id"),
                "proposed_answer": str(field.get("proposed_answer") or ""),
                "proposed_option": str(field.get("proposed_option") or ""),
                "display_reason": _compact_text(field.get("display_reason"), 500),
                "confirmation_required": bool(field.get("confirmation_required")),
                "evidence_coverage": (
                    dict(field.get("evidence_coverage") or {})
                    if isinstance(field.get("evidence_coverage"), dict)
                    else None
                ),
                "is_unsure": bool(field.get("is_unsure")),
            },
            source="in_browser_field",
        )
        db.commit()
        thread = db.scalars(select(models.ChatThread).where(models.ChatThread.run_id == run_id)).first()
        thread_id = int(thread.id) if thread is not None else None
        OperatorChatService(db).ensure_question_for_run(
            run_id,
            thread_id=thread_id,
            announce=False,
        )
        db.commit()
    return True


def _create_in_browser_question(run_id: int, field: dict[str, Any]) -> bool:
    with final_action_lifecycle_guard():
        return _create_in_browser_question_unlocked(run_id, field)


def _create_final_action_question_unlocked(run_id: int, question: dict[str, Any]) -> bool:
    from app import models
    from sqlalchemy import select

    prompt = _compact_text(question.get("label") or question.get("prompt"), 500)
    if not prompt:
        raise RuntimeError("final_action_question_requires_prompt")
    options = [str(option) for option in (question.get("options") or []) if str(option).strip()]
    schema = dict(question.get("expected_answer_schema") or {})
    if options:
        schema["options"] = options
    schema["question_type"] = "final_action_approval"
    schema["final_action"] = {
        "mode": question.get("mode") or "approval",
        "payment_floor": bool(question.get("payment_floor")),
        "summary": _compact_text(question.get("payment_summary"), 220),
        "submit_label": _compact_text(question.get("submit_label"), 120),
        "approval_token": str(question.get("approval_token") or ""),
        "choices": [
            {"label": label, "decision": "approve" if index == 0 else "decline"}
            for index, label in enumerate(options[:2])
        ],
    }
    with SessionLocal() as db:
        run = db.get(models.OperatorRun, run_id)
        if not run or str(run.current_state or "").upper() in _QUESTION_TERMINAL_STATES:
            return False
        run_state = dict(run.confidence_state or {})
        session_control = (
            run_state.get("session_control")
            if isinstance(run_state.get("session_control"), dict)
            else {}
        )
        if str((session_control or {}).get("status") or "").lower() == "stopped":
            return False
        thread = db.scalars(select(models.ChatThread).where(models.ChatThread.run_id == run_id)).first()
        existing = db.scalars(
            select(models.OperatorQuestion)
            .where(
                models.OperatorQuestion.run_id == run_id,
                models.OperatorQuestion.status == "pending",
                models.OperatorQuestion.question_type == "final_action_approval",
            )
            .order_by(models.OperatorQuestion.id.desc())
        ).first()
        existing_token = str(
            ((((existing.expected_answer_schema or {}).get("final_action") or {}).get("approval_token"))
            if existing else "")
            or ""
        )
        next_token = str(schema["final_action"]["approval_token"] or "")
        if existing and existing_token != next_token:
            existing.status = "superseded"
            existing.updated_at = utcnow()
            existing = None
        if existing:
            existing.thread_id = thread.id if thread else existing.thread_id
            existing.prompt = prompt
            existing.expected_answer_schema = schema
            existing.updated_at = utcnow()
            question_row = existing
        else:
            question_row = models.OperatorQuestion(
                run_id=run_id,
                thread_id=thread.id if thread else None,
                question_type="final_action_approval",
                stuck_phase="FINAL_ACTION",
                stuck_reason=question.get("stuck_reason") or "Lumen needs explicit final-action confirmation.",
                prompt=prompt,
                expected_answer_schema=schema,
                status="pending",
            )
            db.add(question_row)
        db.flush()
        state = dict(run.confidence_state or {})
        pending = dict(state.get(_PENDING_FINAL_ACTION_KEY) or {})
        if not pending.get("approval_token") or pending.get("approval_token") == schema["final_action"]["approval_token"]:
            pending["question_id"] = question_row.id
            state[_PENDING_FINAL_ACTION_KEY] = pending
            run.confidence_state = state
            run.updated_at = utcnow()
        db.commit()
    return True


def _create_final_action_question(run_id: int, question: dict[str, Any]) -> bool:
    with final_action_lifecycle_guard():
        return _create_final_action_question_unlocked(run_id, question)


def _sensitive_screenshot_binding(
    raw: Any,
) -> dict[str, Any] | None:
    """Validate the value-free mask binding persisted across direct-entry handoff.

    The binding contains no browser value and carries no semantic decision. It is only exact
    addressing plus an opaque structural page identity chosen by the extension.
    """
    source = dict(raw or {}) if isinstance(raw, dict) else {}
    mode = str(source.get("mode") or "").strip()
    if mode == "browser_structure":
        return {"mode": mode}
    if mode != "model_bound_selector":
        return None
    raw_selectors = (
        source.get("selectors")
        if isinstance(source.get("selectors"), list)
        else [source.get("selector")]
    )
    selectors: list[str] = []
    for raw_selector in raw_selectors:
        selector = _safe_control_selector(raw_selector)
        if not selector or selector in selectors:
            continue
        selectors.append(selector)
        if len(selectors) >= 24:
            break
    page_context = (
        dict(source.get("page_context") or {})
        if isinstance(source.get("page_context"), dict)
        else {}
    )
    url = _safe_trim(page_context.get("url"), 1000)
    mask_surface_signature = _safe_trim(
        page_context.get("mask_surface_signature"),
        160,
    )
    if not selectors or not url or not mask_surface_signature:
        return None
    binding: dict[str, Any] = {
        "mode": mode,
        "selector": selectors[0],
        "page_context": {
            "url": url,
            "mask_surface_signature": mask_surface_signature,
        },
    }
    if len(selectors) > 1:
        binding["selectors"] = selectors
    return binding


def _sensitive_mask_failure_reason(value: Any) -> str:
    reason = str(value or "").strip()
    if reason in {
        "sensitive_mask_binding_failed",
        "sensitive_mask_binding_unavailable",
        "sensitive_mask_capability_unavailable",
        "sensitive_mask_page_context_drift",
        "sensitive_mask_page_context_required",
        "sensitive_mask_rebind_capability_unavailable",
        "sensitive_mask_rebind_failed",
        "sensitive_mask_rebind_lost_before_capture",
        "sensitive_mask_selector_drift",
        "sensitive_mask_selector_invalid",
        "sensitive_mask_selector_required",
    }:
        return reason
    return "sensitive_mask_rebind_failed"


def continue_sensitive_browser_takeover(
    run_id: int,
    *,
    handoff_id: str,
    db: Any = None,
) -> Any:
    """Consume the text-free sensitive-browser continuation control exactly once.

    The takeover marker is the authority boundary: ordinary chat, a generic resume request,
    or an independently scheduled drive cannot consume it. The marker is committed before the
    browser coroutine is scheduled so the driver can prove an explicit structured control was
    accepted without receiving any user-entered value.
    """

    from app import models

    owns_session = db is None
    session = db or SessionLocal()
    request_id = secrets.token_hex(12)
    try:
        with _SENSITIVE_BROWSER_CONTINUE_LOCK:
            run = session.get(models.OperatorRun, int(run_id))
            if not run:
                raise ValueError("Run not found.")
            session.refresh(run)
            state = dict(run.confidence_state or {})
            takeover = (
                dict(state.get("sensitive_browser_takeover") or {})
                if isinstance(state.get("sensitive_browser_takeover"), dict)
                else {}
            )
            if str(run.current_state or "").upper() != "WAITING_FOR_USER" or not takeover.get("active"):
                raise ValueError("No sensitive browser entry is waiting for confirmation.")
            session_control = (
                dict(state.get("session_control") or {})
                if isinstance(state.get("session_control"), dict)
                else {}
            )
            if str(session_control.get("status") or "").lower() == "paused":
                raise ValueError(
                    "Resume the paused browser session before continuing direct entry."
                )
            if not isinstance(state.get("in_browser"), dict) or not state["in_browser"].get("device_id"):
                raise ValueError("The Chrome browser body is not bound to this run.")
            expected_handoff_id = str(takeover.get("handoff_id") or "")
            supplied_handoff_id = str(handoff_id or "")
            if (
                not expected_handoff_id
                or not supplied_handoff_id
                or not secrets.compare_digest(expected_handoff_id, supplied_handoff_id)
            ):
                raise ValueError("The sensitive browser continuation control is stale.")
            screenshot_binding = _sensitive_screenshot_binding(
                takeover.get("screenshot_mask_binding")
            )
            if screenshot_binding is None:
                raise ValueError(
                    "The sensitive browser screenshot-mask binding is unavailable; continuation was withheld."
                )
            takeover_kind = (
                "credential_vault"
                if str(
                    takeover.get("kind")
                    or takeover.get("takeover_kind")
                    or ""
                )
                == "credential_vault"
                else "direct_entry"
            )

            requested_at = utcnow()
            takeover.update(
                {
                    "active": False,
                    "status": "resume_scheduled",
                    "persist_answer": False,
                    "continue_control": "sensitive_browser_continue",
                    "consumed_handoff_id": expected_handoff_id,
                    "continue_request_id": request_id,
                    "continue_requested_at": requested_at.isoformat(),
                    "screenshot_mask_rebind_required": (
                        screenshot_binding.get("mode") == "model_bound_selector"
                    ),
                }
            )
            state["sensitive_browser_takeover"] = takeover
            run.confidence_state = state
            run.current_state = "RUNNING"
            run.status_message = (
                "Re-observing Chrome before exact-origin credential replay."
                if takeover_kind == "credential_vault"
                else "Re-observing Chrome after direct sensitive entry."
            )
            run.updated_at = requested_at
            emit_event(
                session,
                event_type="SENSITIVE_BROWSER_CONTINUE_ACCEPTED",
                payload={
                    "control": "sensitive_browser_continue",
                    "handoff_id": expected_handoff_id,
                    "request_id": request_id,
                    "user_text_received": False,
                    "answer_persisted": False,
                    "takeover_kind": takeover_kind,
                },
                run_id=run.id,
                actor="human",
                confidence=1,
                risk_level="high",
            )
            session.commit()

        try:
            scheduled = bool(
                schedule_resume_if_in_browser(
                    int(run_id),
                    sensitive_continue_request_id=request_id,
                )
            )
        except Exception:
            scheduled = False
        if scheduled:
            session.refresh(run)
            return run

        with _SENSITIVE_BROWSER_CONTINUE_LOCK:
            session.refresh(run)
            state = dict(run.confidence_state or {})
            takeover = (
                dict(state.get("sensitive_browser_takeover") or {})
                if isinstance(state.get("sensitive_browser_takeover"), dict)
                else {}
            )
            if takeover.get("continue_request_id") == request_id:
                takeover.update(
                    {
                        "active": True,
                        "status": "resume_failed",
                        "resume_failed_at": utcnow().isoformat(),
                    }
                )
                state["sensitive_browser_takeover"] = takeover
                run.confidence_state = state
                run.current_state = "WAITING_FOR_USER"
                run.status_message = (
                    (
                        "The saved credential is still waiting because the Chrome body "
                        "could not resume. Reconnect Chrome, then use Continue again."
                    )
                    if takeover_kind == "credential_vault"
                    else (
                        "The direct browser entry is still waiting because the Chrome body "
                        "could not resume. Reconnect Chrome, then use the Continue button again."
                    )
                )
                run.updated_at = utcnow()
                emit_event(
                    session,
                    event_type="SENSITIVE_BROWSER_CONTINUE_SCHEDULING_FAILED",
                    payload={
                        "control": "sensitive_browser_continue",
                        "handoff_id": expected_handoff_id,
                        "request_id": request_id,
                        "user_text_received": False,
                        "answer_persisted": False,
                        "takeover_kind": takeover_kind,
                    },
                    run_id=run.id,
                    actor="runtime",
                    confidence=1,
                    risk_level="medium",
                )
                session.commit()
        raise ValueError("Chrome could not resume; the sensitive browser entry remains active.")
    finally:
        if owns_session:
            session.close()


_IN_BROWSER_SURFACES = frozenset({"browser", "desktop"})


def run_surface(state: dict[str, Any] | None) -> str | None:
    """The body surface a run was started to drive ("browser" or "desktop"), or None for a run that never
    drove one. Read from the durable browser_task the run was created with, because the in_browser marker
    is only a binding cache and can be absent while the run is still an in-browser run. A run that has a
    marker but no browser_task is read from the marker."""
    state = dict(state or {})
    task = state.get("browser_task")
    if isinstance(task, dict):
        surface = str(task.get("execution_surface") or "browser").strip().lower()
        if surface in _IN_BROWSER_SURFACES:
            return surface
    marker = state.get("in_browser")
    if isinstance(marker, dict):
        surface = str(marker.get("execution_surface") or "browser").strip().lower()
        return surface if surface in _IN_BROWSER_SURFACES else "browser"
    return None


def run_is_in_browser(state: dict[str, Any] | None) -> bool:
    """Whether the run is a live browser or desktop run. Reply routing asks this. It deliberately does not
    ask whether a body is connected right now (a body that reconnects later must still get the reply), and
    it does not depend on the transient in_browser marker being present."""
    return run_surface(state) is not None


def _final_action_open(state: dict[str, Any]) -> bool:
    """Whether the run holds a final action that is awaiting approval, approved, executing, or otherwise not
    closed by a decline. Fail closed: a pending record whose status is unknown counts as open."""
    pending = state.get(_PENDING_FINAL_ACTION_KEY)
    if not isinstance(pending, dict) or not pending:
        return False
    return str(pending.get("status") or "").strip().lower() != "declined"


def _recorded_body_device_id(run: Any, state: dict[str, Any], *, db: Any = None) -> str:
    """The body device this run was last bound to, read from the durable records that keep it: the browser task
    it was created with, then the run's own events, newest first. "" when no device was ever recorded."""
    from app import models
    from sqlalchemy import select

    task = state.get("browser_task")
    if isinstance(task, dict) and str(task.get("device_id") or "").strip():
        return str(task["device_id"]).strip()
    run_id = int(getattr(run, "id", 0) or 0)
    if not run_id:
        return ""
    owns_session = db is None
    session = SessionLocal() if owns_session else db
    try:
        payloads = session.scalars(
            select(models.CognitiveEvent.event_payload)
            .where(models.CognitiveEvent.run_id == run_id)
            .order_by(models.CognitiveEvent.id.desc())
        )
        for payload in payloads:
            if isinstance(payload, dict) and str(payload.get("device_id") or "").strip():
                return str(payload["device_id"]).strip()
    finally:
        if owns_session:
            session.close()
    return ""


def _in_browser_binding_for_resume(run: Any, state: dict[str, Any], thread_id: int, *, db: Any = None) -> dict[str, Any] | None:
    """The body binding a drive needs right now, or None when no body is ready for this run.

    The run's own marker is used as it is. When the marker is missing, the run is rebound the way a fresh
    chat start binds one (route_deferred_chat_run): the Windows desktop when desktop control is on, else
    the thread's body when it is connected and ready for live actions. A run that never drove a body
    has no binding to recover.

    A rebind must reach the body the run was bound to before. When a device was recorded for the run (its
    browser task or its events), only that device is accepted. When no device was recorded but the run holds a
    final action that is still open (awaiting approval, approved, or executing), the rebind is refused: the
    body is not known to be the one that action belongs to. The reply then stays saved for a retry."""
    from app.extension_hub import hub

    marker = state.get("in_browser")
    if isinstance(marker, dict) and marker.get("device_id"):
        return dict(marker)
    surface = run_surface(state)
    if surface is None:
        return None
    target = str(getattr(run, "target_url", "") or "")
    if surface == "desktop":
        from app.desktop_platform import DesktopBody, desktop_control_status

        if not desktop_control_status().get("enabled"):
            return None
        binding = {"url": target or "desktop://windows", "device_id": DesktopBody.device_id, "execution_surface": "desktop"}
    else:
        connection = hub.get_for_thread(thread_id)
        if connection is None:
            return None
        if hasattr(connection, "live_actions_ready") and not bool(connection.live_actions_ready):
            return None
        binding = {"url": target, "device_id": connection.device_id}
    recorded = _recorded_body_device_id(run, state, db=db)
    if recorded:
        return binding if str(binding.get("device_id") or "") == recorded else None
    if _final_action_open(state):
        return None
    return binding


def schedule_resume_if_in_browser(
    run_id: int,
    *,
    sensitive_continue_request_id: str | None = None,
) -> bool:
    """After a chat answer is applied, auto-resume the in-browser loop (re-observe -> the just
    answered field now resolves -> continue). Schedules onto the uvicorn loop from the sync
    answer path. No-op for runs that never drove a body or when no body is ready for them.

    The caller must have committed (its transaction holds no lock on the run row): a rebuilt body
    binding is written from this function's own session before the drive is scheduled."""
    from app import models
    from app.extension_body import ExtensionBody
    from app.extension_hub import hub
    from sqlalchemy import select

    if (
        sensitive_continue_request_id is None
        and int(run_id or 0) in _PARKED_ASKS
        and _parked_question_answered(run_id)
        and _parked_ask_body_reachable(run_id)
        and _wake_parked_ask(run_id)
    ):
        # The loop that asked is still waiting in place: it continues with this human turn. With its
        # body gone the turn takes today's path (a retryable resume) and the park window runs out.
        return True
    if hub.loop is None:
        return False
    with SessionLocal() as db:
        run = db.get(models.OperatorRun, run_id)
        if not run:
            return False
        state = dict(run.confidence_state or {})
        thread = db.scalars(select(models.ChatThread).where(models.ChatThread.run_id == run_id)).first()
        thread_id = thread.id if thread else None
        if thread_id is None:
            return False
        in_browser = _in_browser_binding_for_resume(run, state, thread_id, db=db)
        if not in_browser:
            return False
        device_id = in_browser.get("device_id")
        execution_surface = str(in_browser.get("execution_surface") or "browser").strip().lower()
        if _active_in_browser_run_for_device(db, device_id, exclude_run_id=run_id):
            return False
        if state.get("in_browser") != in_browser:
            # The binding was rebuilt from the live body: keep it on the run, so the drive, the busy check
            # and the next reply all see the body the drive is about to use. If it cannot be kept, the
            # resume is refused (the reply stays saved for retry) rather than driven on a binding the run
            # does not hold.
            state["in_browser"] = in_browser
            run.confidence_state = state
            try:
                db.commit()
            except Exception:  # noqa: BLE001 - an unkept binding must not start a drive
                db.rollback()
                return False
    if execution_surface == "desktop":
        from app.desktop_platform import DesktopBody, desktop_control_status

        if not desktop_control_status().get("enabled"):
            return False
        body = DesktopBody()
        asyncio.run_coroutine_threadsafe(
            drive_in_browser_application(
                body=body,
                run_id=run_id,
                thread_id=thread_id,
                url=None,
                skip_navigate=True,
                sensitive_continue_request_id=sensitive_continue_request_id,
            ),
            hub.loop,
        )
        return True
    connection = hub.get(device_id)
    if not connection:
        return False
    if hasattr(connection, "live_actions_ready") and not bool(connection.live_actions_ready):
        return False
    body = ExtensionBody(connection)
    asyncio.run_coroutine_threadsafe(
        drive_in_browser_application(
            body=body,
            run_id=run_id,
            thread_id=thread_id,
            url=None,
            skip_navigate=True,
            sensitive_continue_request_id=sensitive_continue_request_id,
        ),
        hub.loop,
    )
    return True


# A body (one Chrome tab) is busy while actively driving or waiting for the user's answer.
# A final action that is already approved/executing also reserves the body, but failed or
# inconclusive single-use approvals never remain retryable.
_ACTIVE_IN_BROWSER_STATES = ("RUNNING", "WAITING_FOR_USER")


def _blocked_final_action_reserves_body(run: Any) -> bool:
    if str(getattr(run, "current_state", "") or "").upper() != "BLOCKED":
        return False
    state = dict(getattr(run, "confidence_state", None) or {})
    pending = dict(state.get(_PENDING_FINAL_ACTION_KEY) or {})
    pending_status = str(pending.get("status") or "")
    return pending_status in {"approved", "executing"}


def _active_in_browser_run_for_device(session: Any, device_id: str | None, *, exclude_run_id: int | None = None) -> dict[str, Any] | None:
    """The active or approved-final-action-reserved run occupying this device, or None.
    Identified by the run's own confidence_state.in_browser.device_id so it is never confused about
    which application — and which body — is in flight."""
    from app import models
    from sqlalchemy import select

    if not device_id:
        return None
    runs = session.scalars(
        select(models.OperatorRun).where(
            models.OperatorRun.current_state.in_((*_ACTIVE_IN_BROWSER_STATES, "BLOCKED", "CANCELLED"))
        )
    ).all()
    for run in runs:
        if exclude_run_id is not None and run.id == exclude_run_id:
            continue
        lifecycle = str(run.current_state or "").upper()
        if lifecycle == "BLOCKED" and not _blocked_final_action_reserves_body(run):
            continue
        if lifecycle == "CANCELLED" and not final_action_execution_in_progress(run):
            continue
        in_browser = (run.confidence_state or {}).get("in_browser")
        if isinstance(in_browser, dict) and in_browser.get("device_id") == device_id:
            return {
                "id": run.id,
                "url": run.target_url,
                "host": _host(run.target_url or ""),
                "reserved_final_action": lifecycle in {"BLOCKED", "CANCELLED"},
            }
    return None


def in_browser_body_busy_with(device_id: str | None, *, db: Any = None, exclude_run_id: int | None = None) -> dict[str, Any] | None:
    """Public busy-check for the explicit /operator/extension/apply path: returns the active run
    occupying ``device_id`` ({id, url, host}) or None when the body is free."""
    owns_session = db is None
    session = db or SessionLocal()
    try:
        return _active_in_browser_run_for_device(session, device_id, exclude_run_id=exclude_run_id)
    finally:
        if owns_session:
            session.close()


def end_active_in_browser_run(run_id: int, *, db: Any = None, reason: str = "Ended from chat.") -> bool:
    """Cancel an in-browser run so the body (the user's tab) is freed for the next application.
    Used when the user asks to end/stop the current application from chat ('end it', 'end that and
    start here'). Idempotent: returns False if the run is gone."""
    from app import models

    owns_session = db is None
    session = db or SessionLocal()
    try:
        with _FINAL_ACTION_CLAIM_LOCK:
            run = session.get(models.OperatorRun, run_id)
            if not run:
                return False
            session.refresh(run)
            if final_action_execution_in_progress(run):
                return False
            run.current_state = "CANCELLED"
            run.status_message = reason
            try:
                emit_event(session, event_type="LUMEN_IN_BROWSER_RUN_ENDED", payload={"run_id": run_id, "reason": reason}, run_id=run_id, actor="lumen_chat", confidence=0.9)
            except Exception:  # noqa: BLE001 - event logging must never block freeing the body
                pass
            session.commit()
            return True
    finally:
        if owns_session:
            session.close()


_CHROME_SELF_LAUNCH_RUN_IDS: set[int] = set()
_CHROME_SELF_LAUNCH_LOCK = threading.Lock()
_CHROME_SELF_LAUNCH_CONNECT_TIMEOUT_SECONDS = 60.0


def _chrome_launch_available() -> bool:
    """Chrome self-launch rides the same user switch as every other OS-level action."""
    try:
        from app.desktop_platform import desktop_control_status

        status = desktop_control_status()
        return bool(status.get("available") and status.get("enabled"))
    except Exception:  # noqa: BLE001 - unknown status means no self-launch
        return False


def _launch_chrome_for_extension_body(profile_directory: str = "") -> bool:
    """Open the user's Chrome so the extension body can connect.

    The runtime opens its own body instead of surfacing a button. With an exact
    user-chosen profile directory, chrome.exe is started straight into that profile
    (which also opens a real window — no profile picker, no windowless state). Without
    one, the enumerated app-inventory launcher is preferred and a plain chrome.exe
    start is the fallback. Gated on computer use being available AND enabled, and only
    ever starts Google Chrome: never a URL, never page-directed."""
    if not _chrome_launch_available():
        return False
    clean_profile_directory = str(profile_directory or "").strip()
    if not clean_profile_directory:
        try:
            from app.desktop_platform import launch_application_named

            if launch_application_named("google chrome"):
                return True
        except Exception:  # noqa: BLE001 - fall through to the direct launcher
            pass
    try:
        import os
        import subprocess
        import sys

        if sys.platform == "darwin":
            for bundle in ("/Applications/Google Chrome.app", os.path.expanduser("~/Applications/Google Chrome.app")):
                if os.path.isdir(bundle):
                    arguments = ["/usr/bin/open", "-a", bundle]
                    if clean_profile_directory:
                        arguments += ["--args", f"--profile-directory={clean_profile_directory}"]
                    subprocess.Popen(arguments, close_fds=True)  # noqa: S603 - exact known Chrome bundle + exact user-chosen profile
                    return True
            return False
        candidates = [
            os.path.join(os.environ.get("PROGRAMFILES", ""), "Google", "Chrome", "Application", "chrome.exe"),
            os.path.join(os.environ.get("PROGRAMFILES(X86)", ""), "Google", "Chrome", "Application", "chrome.exe"),
            os.path.join(os.environ.get("LOCALAPPDATA", ""), "Google", "Chrome", "Application", "chrome.exe"),
        ]
        for path in candidates:
            if path and os.path.isfile(path):
                arguments = [path]
                if clean_profile_directory:
                    arguments.append(f"--profile-directory={clean_profile_directory}")
                subprocess.Popen(arguments, close_fds=True)  # noqa: S603 - exact known chrome.exe path + exact user-chosen profile
                return True
    except Exception:  # noqa: BLE001 - launch failure falls back to the blocked message
        pass
    return False


def _pending_chrome_profile_question(session: Any, run_id: int) -> Any | None:
    from app import models
    from sqlalchemy import select

    return session.scalars(
        select(models.OperatorQuestion)
        .where(
            models.OperatorQuestion.run_id == int(run_id),
            models.OperatorQuestion.question_type == "chrome_profile_choice",
            models.OperatorQuestion.status == "pending",
        )
        .order_by(models.OperatorQuestion.id.desc())
        .limit(1)
    ).first()


def _begin_chrome_self_launch_for_run(
    run_id: int,
    thread_id: int,
    *,
    db: Any = None,
) -> dict[str, Any] | None:
    """Open Chrome and adopt the deferred run once the extension body connects.

    Which Chrome profile to use is the USER's decision, never code's: with multiple
    profiles and no standing user choice, the runtime enumerates them (eyes) and asks
    through the run's question machinery; the answer is stored as an agent setting and
    the launch continues into exactly that profile (hands). Returns the route result
    when a launch or question is underway, or None when Chrome cannot be started (the
    caller then blocks with the ordinary no-body message)."""
    from app import models
    from app.agent_settings import get_agent_settings
    from app.cognition import OperatorChatService
    from app.desktop_platform import chrome_profiles
    from app.extension_hub import hub

    if not _chrome_launch_available() or hub.loop is None:
        return None
    already_launching = False
    with _CHROME_SELF_LAUNCH_LOCK:
        if int(run_id) in _CHROME_SELF_LAUNCH_RUN_IDS:
            already_launching = True
    if already_launching:
        return {
            "status": "launching_browser",
            "message": "I'm still opening Chrome — the task starts the moment my extension connects.",
            "active": None,
        }

    profiles = chrome_profiles()
    profile_directory = ""
    message = (
        "Chrome isn't open with my extension connected, so I'm opening Chrome now. "
        "I'll start the task the moment my extension connects."
    )
    owns_session = db is None
    session = db or SessionLocal()
    try:
        run = session.get(models.OperatorRun, run_id)
        if run is None:
            return None
        if len(profiles) > 1:
            settings = get_agent_settings(session, int(run.user_id))
            stored_directory = str(settings.get("chrome_profile_directory") or "").strip()
            known_directories = {profile["directory"] for profile in profiles}
            if stored_directory in known_directories:
                profile_directory = stored_directory
            else:
                pending = _pending_chrome_profile_question(session, run_id)
                if pending is None:
                    names = ", ".join(profile["name"] for profile in profiles)
                    prompt = (
                        f"Your Chrome has {len(profiles)} profiles: {names}. "
                        "Which one should I use for browser tasks? I'll remember your choice."
                    )
                    pending = models.OperatorQuestion(
                        run_id=int(run_id),
                        thread_id=int(thread_id),
                        question_type="chrome_profile_choice",
                        stuck_phase="BROWSER_LAUNCH",
                        stuck_reason="Multiple Chrome profiles are installed and no profile choice is stored.",
                        prompt=prompt,
                        expected_answer_schema={
                            "type": "choice",
                            "options": [profile["name"] for profile in profiles],
                            "profile_options": profiles,
                        },
                        status="pending",
                    )
                    session.add(pending)
                    session.flush()
                    run.status_message = "Waiting for your Chrome profile choice before opening the browser."
                    if owns_session:
                        try:
                            service = OperatorChatService(session)
                            service._add_message(
                                service._thread(thread_id),
                                role="assistant",
                                content=pending.prompt,
                                payload={
                                    "source": "chrome_profile_question",
                                    "run_id": run_id,
                                    "question_id": pending.id,
                                },
                            )
                        except Exception:  # noqa: BLE001 - the pending question is the source of truth
                            pass
                        session.commit()
                    else:
                        session.flush()
                return {
                    "status": "awaiting_profile_choice",
                    "message": pending.prompt,
                    "active": None,
                }
        elif profiles:
            profile_directory = profiles[0]["directory"]

        with _CHROME_SELF_LAUNCH_LOCK:
            _CHROME_SELF_LAUNCH_RUN_IDS.add(int(run_id))
        if not _launch_chrome_for_extension_body(profile_directory):
            with _CHROME_SELF_LAUNCH_LOCK:
                _CHROME_SELF_LAUNCH_RUN_IDS.discard(int(run_id))
            return None
        run.status_message = "Waiting for Chrome — Lumen opened the browser and is waiting for its extension to connect."
        if owns_session:
            try:
                service = OperatorChatService(session)
                service._add_message(
                    service._thread(thread_id),
                    role="assistant",
                    content=message,
                    payload={"source": "chrome_self_launch", "run_id": run_id},
                )
            except Exception:  # noqa: BLE001 - the waiter still adopts the run
                pass
            session.commit()
        else:
            session.flush()
    finally:
        if owns_session:
            session.close()

    async def _adopt_after_chrome_launch() -> None:
        deadline = time.monotonic() + _CHROME_SELF_LAUNCH_CONNECT_TIMEOUT_SECONDS
        try:
            while time.monotonic() < deadline:
                connection = hub.get(None)
                if connection is not None and (
                    not hasattr(connection, "live_actions_ready")
                    or bool(connection.live_actions_ready)
                ):
                    with _CHROME_SELF_LAUNCH_LOCK:
                        _CHROME_SELF_LAUNCH_RUN_IDS.discard(int(run_id))
                    await asyncio.to_thread(
                        route_deferred_chat_run,
                        run_id,
                        thread_id,
                        allow_body_self_launch=False,
                    )
                    return
                await asyncio.sleep(1.0)
            await asyncio.to_thread(
                _block_deferred_run_without_body,
                run_id,
                thread_id,
                reason_code="chrome_self_launch_connect_timeout",
            )
        finally:
            with _CHROME_SELF_LAUNCH_LOCK:
                _CHROME_SELF_LAUNCH_RUN_IDS.discard(int(run_id))

    asyncio.run_coroutine_threadsafe(_adopt_after_chrome_launch(), hub.loop)
    return {"status": "launching_browser", "message": message, "active": None}


def _extension_body_required_message(reason_code: str = "") -> str:
    if reason_code in {
        "desktop_control_unavailable",
        "desktop_control_paused",
        "desktop_loop_unavailable",
        "desktop_route_failed",
        "desktop_run_missing",
    }:
        return desktop_platform.os_text(
            "I cannot start this Windows computer task because Lumen Desktop computer use is "
            + (
                "paused. Enable it from the desktop status bar, then try again."
                if reason_code == "desktop_control_paused"
                else "not available in this runtime. Start the task from the packaged Windows desktop app."
            )
        )
    if reason_code == "desktop_permission_missing":
        return desktop_platform.permission_message()
    if reason_code == "extension_reload_required":
        return (
            "The connected Lumen Chrome extension is from an older or incomplete runtime build. "
            "Reload the extension so its privacy and exact-target capabilities are active, then try again."
        )
    if reason_code == "chrome_self_launch_connect_timeout":
        return (
            "I opened Chrome, but my extension never connected. Make sure the Lumen extension is "
            "installed and enabled at chrome://extensions, then tell me to try again."
        )
    if reason_code == "bench_lane_disconnected":
        return "This benchmark thread's bench lane browser is not connected, so the run cannot start."
    return (
        "I cannot start this browser task because no Lumen Chrome extension body is connected. "
        "Open Chrome with the Lumen extension connected, then try again."
    )


def _block_deferred_run_without_body(
    run_id: int,
    thread_id: int,
    *,
    reason_code: str,
    db: Any = None,
) -> dict[str, Any]:
    from app import models
    from app.cognition import OperatorChatService

    owns_session = db is None
    session = db or SessionLocal()
    message = _extension_body_required_message(reason_code)
    desktop_reason = str(reason_code or "").startswith("desktop_")
    try:
        run = session.get(models.OperatorRun, run_id)
        if run:
            run.current_state = "BLOCKED"
            run.status_message = message
            try:
                emit_event(
                    session,
                    event_type="LUMEN_DESKTOP_BODY_REQUIRED" if desktop_reason else "LUMEN_EXTENSION_BODY_REQUIRED",
                    payload={"run_id": run_id, "thread_id": thread_id, "reason": reason_code},
                    run_id=run_id,
                    application_id=run.application_id,
                    actor="lumen_chat",
                    confidence=1,
                    risk_level="medium",
                )
            except Exception:  # noqa: BLE001 - event logging must not mask fail-closed routing
                pass
        if owns_session:
            try:
                service = OperatorChatService(session)
                service._add_message(
                    service._thread(thread_id),
                    role="assistant",
                    content=message,
                    payload={"source": "in_browser_body_required", "run_id": run_id, "reason": reason_code},
                )
            except Exception:  # noqa: BLE001 - the run state is the source of truth
                pass
            session.commit()
        else:
            session.flush()
        return {"status": "no_body", "message": message, "active": None}
    finally:
        if owns_session:
            session.close()


def _validate_deferred_run_thread_ownership(run_id: int, thread_id: int, *, db: Any = None) -> dict[str, Any]:
    """Read-only fail-closed gate for the exact chat-thread/run/user binding.

    Until that complete binding is proven, neither supplied identifier is trusted enough to
    authorize a state change or a run-scoped audit event. In particular, an unrelated caller must
    not be able to block a victim run merely by presenting its id with a mismatched thread id.
    """

    from app import models

    owns_session = db is None
    session = db or SessionLocal()
    try:
        run = session.get(models.OperatorRun, int(run_id or 0))
        thread = session.get(models.ChatThread, int(thread_id or 0))
        valid = bool(
            run
            and thread
            and int(thread.run_id or 0) == int(run.id)
            and int(thread.user_id or 0) == int(run.user_id)
        )
        if valid:
            return {"ok": True, "run": run, "thread": thread}
        return {
            "ok": False,
            "message": "I could not route this browser task because its chat ownership could not be verified.",
        }
    finally:
        if owns_session:
            session.close()


def route_deferred_chat_run(
    run_id: int,
    thread_id: int,
    *,
    db: Any = None,
    allow_body_self_launch: bool = True,
) -> dict[str, Any]:
    """Decide how a chat-started browser run is carried out, server-side (independent of the
    frontend phrasing). Returns ``{"status": ...}`` where status is:

    - ``"in_browser"`` — a free body is connected: adopt the EXISTING run + thread (no duplicate),
      merge-tag confidence_state.in_browser (preserving consent/budget so chat answers auto-resume
      the same body), and schedule the loop onto the uvicorn loop.
    - ``"busy"`` — a body is connected but already working another application: this run is parked
      (CANCELLED) and the user is told which application holds the body (``message``). The body is
      never asked to run two applications at once and is never confused about which is which.
    - ``"no_body"`` — no body connected (or scheduling failed): the run is blocked. There is no
      alternate browser fallback for live applications.

    Pass ``db`` to reuse a caller session (sync chat path). When ``db`` is omitted (the post-response
    BackgroundTask) the busy notice is posted to the run's thread here; with ``db`` the caller
    delivers ``message`` as the turn reply instead (so the chat shows exactly one message)."""
    from app import models
    from app.cognition import OperatorChatService
    from app.extension_body import ExtensionBody
    from app.extension_hub import hub

    ownership = _validate_deferred_run_thread_ownership(run_id, thread_id, db=db)
    if not ownership.get("ok"):
        return {
            "status": "invalid",
            "message": ownership.get("message"),
            "active": None,
        }
    owned_run = ownership.get("run")
    owned_state = dict((getattr(owned_run, "confidence_state", None) or {}))
    owned_task = (
        dict(owned_state.get("browser_task") or {})
        if isinstance(owned_state.get("browser_task"), dict)
        else {}
    )
    execution_surface = str(owned_task.get("execution_surface") or "browser").strip().lower()
    # A thread pinned to a bench lane runs there and only there: a lane is a headless browser with no
    # real screen, so its runs are browser runs.
    bench_lane = hub.lane_for_thread(thread_id)
    if bench_lane:
        execution_surface = "browser"
    if hub.loop is None:
        return _block_deferred_run_without_body(
            run_id,
            thread_id,
            reason_code="desktop_loop_unavailable" if execution_surface == "desktop" else "extension_loop_unavailable",
            db=db,
        )
    if execution_surface == "desktop":
        from app.desktop_platform import DesktopBody, desktop_control_status

        computer_status = desktop_control_status()
        if not computer_status.get("available"):
            return _block_deferred_run_without_body(
                run_id,
                thread_id,
                reason_code=(
                    "desktop_permission_missing" if computer_status.get("permissions_missing") else "desktop_control_unavailable"
                ),
                db=db,
            )
        if not computer_status.get("enabled"):
            return _block_deferred_run_without_body(
                run_id,
                thread_id,
                reason_code="desktop_control_paused",
                db=db,
            )
        try:
            owns_session = db is None
            session = db or SessionLocal()
            try:
                active = _active_in_browser_run_for_device(
                    session,
                    DesktopBody.device_id,
                    exclude_run_id=run_id,
                )
                if active:
                    message = desktop_platform.os_text(
                        f"A Windows computer task is already running (run #{active['id']}). "
                        "Stop that task before starting another one."
                    )
                    run = session.get(models.OperatorRun, run_id)
                    if run:
                        run.current_state = "CANCELLED"
                        run.status_message = desktop_platform.os_text(f"Not started - Windows computer use is busy with run #{active['id']}.")
                    if owns_session:
                        service = OperatorChatService(session)
                        service._add_message(
                            service._thread(thread_id),
                            role="assistant",
                            content=message,
                            payload={"source": "in_desktop_busy", "active_run_id": active["id"]},
                        )
                        session.commit()
                    else:
                        session.flush()
                    return {"status": "busy", "message": message, "active": active}

                run = session.get(models.OperatorRun, run_id)
                if not run:
                    return _block_deferred_run_without_body(
                        run_id,
                        thread_id,
                        reason_code="desktop_run_missing",
                        db=db,
                    )
                url = str(run.target_url or "desktop://windows")
                state = dict(run.confidence_state or {})
                state["in_browser"] = {
                    "url": url,
                    "device_id": DesktopBody.device_id,
                    "execution_surface": "desktop",
                }
                run.confidence_state = state
                run.current_state = "RUNNING"
                session.commit()
            finally:
                if owns_session:
                    session.close()
            body = DesktopBody()
            asyncio.run_coroutine_threadsafe(
                drive_in_browser_application(
                    body=body,
                    run_id=run_id,
                    thread_id=thread_id,
                    url=None,
                    skip_navigate=True,
                ),
                hub.loop,
            )
            return {"status": "in_desktop", "message": None, "active": None}
        except Exception:
            return _block_deferred_run_without_body(
                run_id,
                thread_id,
                reason_code="desktop_route_failed",
                db=db,
            )
    # The thread's bench lane, else the user's most-recently-connected body; None when not connected.
    connection = hub.get_for_thread(thread_id)
    if not connection and bench_lane:
        return _block_deferred_run_without_body(run_id, thread_id, reason_code="bench_lane_disconnected", db=db)
    if not connection:
        # No button, no babysitting: the runtime opens Chrome itself and adopts the run
        # once the extension body connects. The waiter re-routes with self-launch
        # disabled, so a body that vanishes again blocks normally instead of looping.
        if allow_body_self_launch:
            launching = _begin_chrome_self_launch_for_run(run_id, thread_id, db=db)
            if launching:
                return launching
        return _block_deferred_run_without_body(run_id, thread_id, reason_code="no_connected_extension_body", db=db)
    if hasattr(connection, "live_actions_ready") and not bool(connection.live_actions_ready):
        return _block_deferred_run_without_body(
            run_id,
            thread_id,
            reason_code="extension_reload_required",
            db=db,
        )
    try:
        owns_session = db is None
        session = db or SessionLocal()
        try:
            active = _active_in_browser_run_for_device(session, connection.device_id, exclude_run_id=run_id)
            if active:
                message = (
                    f"You've already got a browser task running on {active['host']} (run #{active['id']}). "
                    "Want me to stop that one and start this instead? Just say so — or tell me to keep it going."
                )
                run = session.get(models.OperatorRun, run_id)
                if run:
                    run.current_state = "CANCELLED"
                    run.status_message = f"Not started — your browser is busy with run #{active['id']} ({active['host']})."
                if owns_session:
                    service = OperatorChatService(session)
                    service._add_message(service._thread(thread_id), role="assistant", content=message, payload={"source": "in_browser_busy", "active_run_id": active["id"]})
                    session.commit()
                else:
                    session.flush()
                return {"status": "busy", "message": message, "active": active}

            run = session.get(models.OperatorRun, run_id)
            if not run or not run.target_url:
                return _block_deferred_run_without_body(run_id, thread_id, reason_code="run_missing_target_url", db=db)
            url = str(run.target_url)
            state = dict(run.confidence_state or {})
            state["in_browser"] = {"url": url, "device_id": connection.device_id}
            run.confidence_state = state
            run.current_state = "RUNNING"
            session.commit()
        finally:
            if owns_session:
                session.close()
        body = ExtensionBody(connection)
        asyncio.run_coroutine_threadsafe(
            drive_in_browser_application(body=body, run_id=run_id, thread_id=thread_id, url=url, skip_navigate=False),
            hub.loop,
        )
        return {"status": "in_browser", "message": None, "active": None}
    except Exception:  # noqa: BLE001 - fail closed; do not route live work to another browser engine
        return _block_deferred_run_without_body(run_id, thread_id, reason_code="extension_route_failed", db=db)


def _downscale_screenshot(b64: str, *, max_width: int = 1280) -> tuple[str, float, int, int]:
    """Vision models place coordinates far more accurately on a ~1280px-wide image than a full-res 1920px
    one (measured: ~12px error at 1280 vs 70px+ at 1920). Downscale before sending; return
    (b64, scale, width, height) where native_coord = model_coord * scale."""
    try:
        import base64 as _b64
        import io as _io

        from PIL import Image

        img = Image.open(_io.BytesIO(_b64.b64decode(b64)))
        w, h = img.size
        if w <= max_width:
            return b64, 1.0, w, h
        scale = w / float(max_width)
        nw, nh = max_width, max(1, int(round(h / scale)))
        out = _io.BytesIO()
        img.resize((nw, nh), Image.LANCZOS).convert("RGB").save(out, "JPEG", quality=72)
        return _b64.b64encode(out.getvalue()).decode(), scale, nw, nh
    except Exception:  # noqa: BLE001 - on any imaging error, send the original at scale 1.0
        return b64, 1.0, 0, 0


_ZOOM_MIN_MODEL_REGION_PX = 8
_ZOOM_TARGET_MIN_WIDTH = 800
_ZOOM_MAX_UPSCALE = 3.0


def _zoom_crop_attachment(
    shot: dict[str, Any],
    action: dict[str, Any],
    coord_scale: float,
) -> dict[str, Any]:
    """Crop the CURRENT full-resolution screenshot to the model's requested region.

    The model asks in its own (downscaled) coordinate space; the crop is cut from the
    pre-downscale capture, so it carries every native pixel the display had — the closer
    look a human gets by leaning in. Small crops are gently upscaled so the vision
    provider's patch grid doesn't swallow the fine print again. Nothing on screen changes.
    """
    try:
        import base64 as _b64
        import io as _io

        from PIL import Image
    except Exception as exc:  # noqa: BLE001 - imaging stack unavailable
        return {"ok": False, "failure_reason": f"zoom_imaging_unavailable:{exc.__class__.__name__}"}
    try:
        raw = _b64.b64decode(str(shot.get("image") or ""), validate=True)
        img = Image.open(_io.BytesIO(raw))
        img.load()
    except Exception:  # noqa: BLE001
        return {"ok": False, "failure_reason": "zoom_screenshot_unreadable"}
    try:
        scale = float(coord_scale or 1.0)
    except (TypeError, ValueError):
        scale = 1.0
    if not math.isfinite(scale) or scale <= 0:
        scale = 1.0
    model_left = int(action.get("x") or 0)
    model_top = int(action.get("y") or 0)
    model_right = int(action.get("to_x") or 0)
    model_bottom = int(action.get("to_y") or 0)
    if model_right - model_left < _ZOOM_MIN_MODEL_REGION_PX or model_bottom - model_top < _ZOOM_MIN_MODEL_REGION_PX:
        return {"ok": False, "failure_reason": "zoom_region_too_small"}
    width, height = img.size
    left = max(0, min(width - 1, int(round(model_left * scale))))
    top = max(0, min(height - 1, int(round(model_top * scale))))
    right = max(left + 1, min(width, int(round(model_right * scale))))
    bottom = max(top + 1, min(height, int(round(model_bottom * scale))))
    if right - left < 4 or bottom - top < 4:
        return {"ok": False, "failure_reason": "zoom_region_outside_screenshot"}
    crop = img.crop((left, top, right, bottom)).convert("RGB")
    crop_width, crop_height = crop.size
    if crop_width < _ZOOM_TARGET_MIN_WIDTH:
        upscale = min(_ZOOM_MAX_UPSCALE, _ZOOM_TARGET_MIN_WIDTH / float(crop_width))
        if upscale > 1.0:
            crop = crop.resize(
                (int(round(crop_width * upscale)), max(1, int(round(crop_height * upscale)))),
                Image.LANCZOS,
            )
    try:
        from PIL import ImageOps

        # Stretch the crop's own tonal range so faint (low-contrast) print reads clearly, like leaning
        # in under better light. On luminance only: a per-channel stretch turned a dark-red arrow
        # black and grey buttons cyan, which misleads any judgment made on colour.
        crop = ImageOps.autocontrast(crop, cutoff=1, preserve_tone=True)
    except Exception:  # noqa: BLE001
        pass
    out = _io.BytesIO()
    crop.save(out, "JPEG", quality=92)
    return {
        "ok": True,
        "zoomed": True,
        "data": _b64.b64encode(out.getvalue()).decode(),
        "region_model": [model_left, model_top, model_right, model_bottom],
        "region_native": [left, top, right, bottom],
        "crop_width": crop.size[0],
        "crop_height": crop.size[1],
    }


# How much of the run's own tab's text last_page_view carries while the run works on the desktop.
_RUN_TAB_TEXT_CHARS = 6000
_RUN_TAB_TEXT_TIMEOUT_SECONDS = 8.0


# last_page_view keys that only the brain reads: the run tab's whole text as re-read on the desktop.
_LAST_PAGE_VIEW_DOCUMENT_KEYS = ("document_text", "document_url", "document_title")


async def _refresh_last_page_view_from_run_tab(body: Any, last_page_view: dict[str, Any]) -> bool:
    """Re-read the run's own browser tab (its whole rendered text, redacted in-page) into
    ``last_page_view["document_text"]`` while the run works on the desktop surface.

    The browser surface only refreshes the view from its visible viewport, so instructions below the
    fold or changed since (a counter, a task list) were lost once the run moved to native windows.
    The whole text is for the brain to read only: ``url``, ``title``, and ``text`` stay what the
    browser surface last showed on screen, and every deterministic check (the grounding blob, the
    secret gate's page provenance) reads those, never text the page kept off screen. The tab's own
    url and title ride as ``document_url``/``document_title`` only when they differ.
    Only the switching body's browser body is asked, and it reads only its own run tab; nothing is
    focused or activated. Fails soft: on any failure the previous view is kept.
    """
    body_for = getattr(body, "body_for", None)
    if not callable(body_for):
        return False
    try:
        browser_body = body_for("browser")
    except Exception:  # noqa: BLE001 - no browser body is simply no refresh
        return False
    read = getattr(browser_body, "read_run_tab_text", None) if browser_body is not None else None
    if not callable(read):
        return False
    try:
        result = await asyncio.wait_for(
            read(max_chars=_RUN_TAB_TEXT_CHARS),
            timeout=_RUN_TAB_TEXT_TIMEOUT_SECONDS + 1.0,
        )
    except Exception:  # noqa: BLE001 - the page view is evidence, never a step failure
        return False
    if not isinstance(result, dict) or result.get("ok") is not True:
        return False
    text = _safe_trim(result.get("text"), _RUN_TAB_TEXT_CHARS)
    if not text:
        return False
    for key in _LAST_PAGE_VIEW_DOCUMENT_KEYS:
        last_page_view.pop(key, None)
    last_page_view["document_text"] = text
    document_url = _safe_trim(result.get("url"), 500)
    if document_url and document_url != str(last_page_view.get("url") or ""):
        last_page_view["document_url"] = document_url
    document_title = _safe_trim(result.get("title"), 200)
    if document_title and document_title != str(last_page_view.get("title") or ""):
        last_page_view["document_title"] = document_title
    return True


def _page_evidence_for_model(
    page_evidence: dict[str, Any] | None,
    coord_scale: float,
) -> dict[str, Any]:
    """Project raw screenshot-pixel boxes into the exact image space shown to the model.

    The extension enumerates geometry in native screenshot pixels. ``_downscale_screenshot``
    defines ``native_coord = model_coord * coord_scale``. Keep the raw observation untouched
    for execution/read-back, while giving the brain boxes in the same coordinate system as its
    image so its index and x/y references describe one target.
    """

    if not isinstance(page_evidence, dict):
        return {}
    try:
        scale = float(coord_scale or 1.0)
    except (TypeError, ValueError):
        scale = 1.0
    if not math.isfinite(scale) or scale <= 0:
        scale = 1.0

    projected = dict(page_evidence)
    # Off-screen distances read in the same pixels as the image the brain sees.
    raw_off_screen = page_evidence.get("off_screen_controls")
    if isinstance(raw_off_screen, list) and scale != 1.0:
        projected["off_screen_controls"] = [
            {**row, "distance": int(round(float(row["distance"]) / scale))}
            if isinstance(row, dict) and isinstance(row.get("distance"), (int, float))
            else row
            for row in raw_off_screen
        ]
    raw_controls = page_evidence.get("controls")
    if not isinstance(raw_controls, list):
        return projected

    controls: list[Any] = []
    for raw in raw_controls:
        if not isinstance(raw, dict):
            controls.append(raw)
            continue
        control = dict(raw)
        for key in ("x", "y", "width", "height"):
            value = raw.get(key)
            try:
                number = float(value)
            except (TypeError, ValueError):
                continue
            if not math.isfinite(number):
                continue
            scaled = int(round(number / scale))
            if key in {"width", "height"} and number > 0:
                scaled = max(1, scaled)
            control[key] = scaled
        controls.append(control)
    projected["controls"] = controls
    return projected


def _decide_vision_action(user_id: int, image: dict[str, Any] | list[dict[str, Any]], view: dict[str, Any], context: dict[str, Any]) -> dict[str, Any] | None:
    """Run the blocking provider call in a worker thread so live browser runs do not freeze the API.

    A failover provider rides in context under _vision_provider_override (like the token/timeout
    overrides) so this signature stays stable for callers and test doubles.
    """
    from app import vision_agent
    from app.lumen_model import LumenModelClient

    with SessionLocal() as db:
        client = LumenModelClient(db, user_id=user_id)
        client.vision_provider_override = (context or {}).get("_vision_provider_override")
        # An escalated part of the task is decided in the escalation seat (its own mailbox when one is set).
        client.vision_seat = str((context or {}).get("_vision_seat") or external_brain.BRAIN)
        client.vision_endpoint_skip = tuple(
            str(host) for host in ((context or {}).get("_vision_endpoint_skip") or ()) if host
        )
        return vision_agent.decide_next_action(client, image, view, context)


async def _whole_page_text_for_completion(body: Any) -> str:
    """The run tab's whole rendered text, scrolled-away parts included, for grading a finished run; ""
    when the body cannot read it. Read-only: nothing is focused or activated."""
    reader = None
    body_for = getattr(body, "body_for", None)
    if callable(body_for):
        try:
            browser_body = body_for("browser")
        except Exception:  # noqa: BLE001 - no browser body, no whole-page text
            browser_body = None
        reader = getattr(browser_body, "read_run_tab_text", None) if browser_body is not None else None
    if not callable(reader):
        reader = getattr(body, "read_run_tab_text", None)
    if not callable(reader):
        return ""
    try:
        result = await asyncio.wait_for(reader(max_chars=_RUN_TAB_TEXT_CHARS), timeout=_RUN_TAB_TEXT_TIMEOUT_SECONDS + 1.0)
    except Exception:  # noqa: BLE001 - the grade falls back to the screen alone
        return ""
    if not isinstance(result, dict) or result.get("ok") is not True:
        return ""
    return _safe_trim(result.get("text"), _RUN_TAB_TEXT_CHARS)


_COMPLETION_SENDBACKS = 2
_COMPLETION_RECEIPTS_CHARS = 4500
_COMPLETION_RECEIPT_LINE_CHARS = 260
_COMPLETION_PAGES_CHARS = 3500
_COMPLETION_PAGE_ENTRY_CHARS = 700
_COMPLETION_PAGES_KEPT = 6
_COMPLETION_PLAN_LINES = 30
_PLAN_DONE_MARK = re.compile(r"^\s*(?:[-*]\s*)?(?:\d+[.)]\s*)?\[\s?(?:done|x|ok)\s?\]", re.IGNORECASE)


def _completion_evidence_text(text: Any, secrets: Any = (), *, limit: int) -> str:
    """Page- or receipt-derived text bound for the grader: values this run typed into sensitive fields are
    blanked, OTP-like codes, key- and token-shaped runs and `password: x` assignments are masked, then the
    length is capped. Emails and digit runs stay (a typed email is legitimate evidence of an entry). Fails to an
    empty string rather than an unscrubbed copy."""
    try:
        out = " ".join(str(text or "").split())
        for secret in secrets or ():
            secret = str(secret or "").strip()
            if len(secret) >= 3:
                out = re.sub(re.escape(secret), "[REDACTED]", out, flags=re.IGNORECASE)
        out = _redact_otp_text(out)
        out = _EVENT_TOKEN_RE.sub("[REDACTED_TOKEN]", out)
        out = _EVENT_SECRET_ASSIGN_RE.sub(lambda m: f"{m.group(1)}{m.group(2)}[REDACTED]", out)
        return _safe_trim(out, limit)
    except Exception:  # noqa: BLE001
        return ""


def _runtime_recorded_evidence(
    receipts: list[dict[str, Any]],
    *,
    restored_receipts: list[dict[str, Any]] | None = None,
    page_memory: list[dict[str, Any]] | None = None,
    secret_texts: Any = (),
) -> dict[str, Any]:
    """What the runtime itself recorded across the whole run, for the grader: the verified receipts of this
    loop and the ones restored from earlier loops (a pause or restart), and the text of pages the run visited
    and left. Work proven on another page or before a pause is evidence even though the current screen no longer
    shows it. Receipt lines come from the receipt view (outcomes the body read back); the agent's own note on a
    click (the stored label) is dropped except for a navigation's URL. Typed secrets are blanked and key-shaped
    runs masked. Bounded: the newest entries win, and what was dropped is counted."""
    entries: list[tuple[str, dict[str, Any]]] = [
        ("earlier_loop_restored", dict(r)) for r in (restored_receipts or []) if isinstance(r, dict) and r.get("outcome") == "verified_succeeded"
    ] + [("this_loop", dict(r)) for r in receipts if isinstance(r, dict) and r.get("outcome") == "verified_succeeded"]
    recorded: list[dict[str, Any]] = []
    used = 0
    for index in range(len(entries) - 1, -1, -1):
        scope, receipt = entries[index]
        target = dict(receipt.get("target") if isinstance(receipt.get("target"), dict) else {})
        if str(receipt.get("type") or "") not in {"navigate", "browser_navigate"}:
            target.pop("label", None)
        line = _completion_evidence_text(
            receipt_line({**receipt, "target": target}, detailed=index >= len(entries) - 4), secret_texts, limit=_COMPLETION_RECEIPT_LINE_CHARS
        )
        if not line:
            continue
        if used + len(line) > _COMPLETION_RECEIPTS_CHARS and recorded:
            break
        used += len(line)
        recorded.append({"n": index + 1, "scope": scope, "verified": line})
    recorded.reverse()
    pages: list[dict[str, Any]] = []
    page_used = 0
    memory = [entry for entry in (page_memory or []) if isinstance(entry, dict) and str(entry.get("text") or "").strip()]
    for entry in reversed(memory[-_COMPLETION_PAGES_KEPT:]):
        text = _completion_evidence_text(entry.get("text"), secret_texts, limit=_COMPLETION_PAGE_ENTRY_CHARS)
        if not text:
            continue
        if page_used + len(text) > _COMPLETION_PAGES_CHARS and pages:
            break
        page_used += len(text)
        pages.append({"url": _safe_trim(entry.get("url"), 200), "title": _safe_trim(entry.get("title"), 100), "text": text})
    pages.reverse()
    out: dict[str, Any] = {}
    if recorded:
        out["receipts"] = recorded
        if len(entries) > len(recorded):
            out["receipts_omitted_older"] = len(entries) - len(recorded)
    if pages:
        out["pages"] = pages
        if len(memory) > len(pages):
            out["pages_omitted_older_or_trimmed"] = len(memory) - len(pages)
    if out:
        out["note"] = (
            "Recorded by the runtime (verified receipts and page text it observed), not model claims; oldest first; "
            "receipt scope says whether an action ran in this loop or in an earlier loop of the same run (restored after a pause)."
        )
    return out


def _plan_lines(plan: str) -> list[dict[str, Any]]:
    """The brain's plan as numbered lines with the mark it gave each ("done", "open" for [ ]/[now], or
    "unmarked"). The mark is the agent's claim."""
    lines: list[dict[str, Any]] = []
    for raw in str(plan or "").splitlines():
        text = raw.strip()
        if not text:
            continue
        marked = "done" if _PLAN_DONE_MARK.match(raw) else "open" if _PLAN_OPEN_MARK.match(raw) else "unmarked"
        lines.append({"n": len(lines) + 1, "marked": marked, "text": _safe_trim(text, 200)})
        if len(lines) >= _COMPLETION_PLAN_LINES:
            break
    return lines


def _apply_plan_verdicts(check: dict[str, Any], plan_lines: list[dict[str, Any]]) -> dict[str, Any]:
    """Fold the grader's per-line verdicts into the grade. A line the agent marked [done] that the grader did
    not confirm, or a line still open that the grader did not confirm or rule out as not a task part, is a gap:
    it is listed in `plan_gaps`, and a whole-goal `complete` is downgraded to `incomplete` with those gaps as
    what is missing (an `incomplete` grade gets them appended). With no usable per-line verdicts (parse failure,
    no plan) the grade is returned as it came."""
    verdicts = check.get("plan_verdicts") if isinstance(check, dict) else None
    if not plan_lines or not isinstance(verdicts, list) or not verdicts:
        return check
    by_line = {item["n"]: item for item in plan_lines if isinstance(item, dict)}
    gaps: list[str] = []
    for entry in verdicts:
        if not isinstance(entry, dict):
            continue
        line = by_line.get(entry.get("n"))
        if not line:
            continue
        verdict = entry.get("verdict")
        if line["marked"] == "done" and verdict == "not_confirmed":
            gaps.append(f"claimed done, not shown: {_safe_trim(line['text'], 100)}" + (f" ({entry.get('reason')})" if entry.get("reason") else ""))
        elif line["marked"] == "open" and verdict in {"not_confirmed", None}:
            gaps.append(f"still open: {_safe_trim(line['text'], 100)}" + (f" ({entry.get('reason')})" if entry.get("reason") else ""))
    graded = dict(check)
    if gaps:
        graded["plan_gaps"] = gaps[:6]
        joined = _safe_trim("; ".join(gaps[:6]), 240)
        if graded.get("verdict") == "complete":
            graded["verdict"] = "incomplete"
            graded["missing"] = joined
            graded["missing_only_delivery"] = False
        elif graded.get("verdict") == "incomplete":
            graded["missing"] = _safe_trim("; ".join(part for part in (str(graded.get("missing") or ""), joined) if part), 240)
    return graded


def _derive_run_outcome(summary: dict[str, Any]) -> str:
    """finished | partial | unconfirmed | blocked, from the run's state and its completion grade.

    COMPLETED -> finished. BLOCKED, FAILED, WAITING_FOR_USER -> blocked. READY_FOR_REVIEW: a `complete` grade ->
    finished, `incomplete` -> partial, anything else (unverified, no or unusable grade, a give-up, an
    application run waiting for its human review) -> unconfirmed; an application run with required fields
    still unfilled -> partial. Any other state (CANCELLED) -> unconfirmed."""
    state = str(summary.get("state") or "").upper()
    if state == "COMPLETED":
        return "finished"
    if state in {"BLOCKED", "FAILED", "WAITING_FOR_USER"}:
        return "blocked"
    if state == "READY_FOR_REVIEW":
        check = summary.get("completion_check") if isinstance(summary.get("completion_check"), dict) else {}
        verdict = str(check.get("verdict") or "")
        if verdict == "complete":
            return "finished"
        if verdict == "incomplete":
            return "partial"
        if any(isinstance(c, dict) and c.get("status") == "required_unfilled" for c in (summary.get("field_census") or [])):
            return "partial"
    return "unconfirmed"


def _task_completion_evidence(
    shot: dict[str, Any],
    *,
    read_backs: list[dict[str, Any]],
    receipts: list[dict[str, Any]],
    whole_page_text: str = "",
    restored_receipts: list[dict[str, Any]] | None = None,
    page_memory: list[dict[str, Any]] | None = None,
    secret_texts: Any = (),
    plan: str = "",
) -> dict[str, Any]:
    """What the run can show about the end state: the current screen, the run tab's whole text (v4_keys
    run 1677 ended scrolled to its last two challenges, and "all seven complete" was graded from those
    two), values the runtime read back, action outcome counts, and `runtime_recorded` (the verified receipts
    of this loop and of earlier loops, and pages visited and left; see `_runtime_recorded_evidence`). The
    agent's reasons and claims stay out. `agent_plan_lines` (the agent's numbered plan) is not evidence: the
    grading call lifts it out of `evidence` into its own field."""
    page = shot.get("page_evidence") if isinstance(shot.get("page_evidence"), dict) else {}
    controls: list[dict[str, Any]] = []
    for raw in (page.get("controls") or [])[:40]:
        if not isinstance(raw, dict):
            continue
        item: dict[str, Any] = {}
        for key in ("text", "role", "context_text"):
            if raw.get(key):
                item[key] = _safe_trim(raw.get(key), 120)
        if raw.get("value") not in (None, "") and str(raw.get("type") or "").lower() != "password":
            item["value"] = _safe_trim(raw.get("value"), 160)
        for key in ("checked", "selected"):
            if raw.get(key) is True:
                item[key] = True
        if item:
            controls.append(item)
    outcomes = Counter(str(receipt.get("outcome") or "") for receipt in receipts if isinstance(receipt, dict))
    return {
        "url": _safe_trim(shot.get("url"), 300),
        "title": _safe_trim(shot.get("title"), 200),
        "screen_text": _safe_trim(page.get("viewport_text"), 3000),
        **({"whole_page_text": _safe_trim(whole_page_text, _RUN_TAB_TEXT_CHARS)} if whole_page_text else {}),
        "controls": controls,
        "read_back_values": [
            {"control": _safe_trim(entry.get("control"), 120), "value": _safe_trim(entry.get("value"), 160)}
            for entry in read_backs[-20:]
            if isinstance(entry, dict)
        ],
        "action_outcomes": {
            "verified": outcomes.get("verified_succeeded", 0),
            "inconclusive": outcomes.get("verification_inconclusive", 0),
            "failed": outcomes.get("execution_failed", 0) + outcomes.get("verification_failed", 0),
        },
        **(
            {"runtime_recorded": recorded}
            if (recorded := _runtime_recorded_evidence(
                receipts, restored_receipts=restored_receipts, page_memory=page_memory, secret_texts=secret_texts
            ))
            else {}
        ),
        **({"agent_plan_lines": plan_lines} if (plan_lines := _plan_lines(plan)) else {}),
    }


def _delivery_only_sendback(label: str, *, pending_answer: str = "") -> str:
    """The send-back for a final action that succeeded and graded incomplete ONLY because the report was never
    handed to the user: the action is done, so the brain must not repeat it, only reply done with the answer."""
    return (
        f"consequential_action_verified: '{_safe_trim(label, 80)}' executed and its outcome was verified: that action "
        "SUCCEEDED and is finished. The only part still missing is giving the user the answer the goal asked for, "
        f"which no click can do. Do NOT click '{_safe_trim(label, 80)}' or repeat any final action (a repeat is refused). "
        "Reply done now with `answer` holding exactly what the goal asked you to report."
        + (" Your earlier done answer was not shown to the user (the run was sent back), so give it again." if pending_answer else "")
    )


_COMPLETION_CHECK_EVENT_KEYS = ("verdict", "verified_summary", "missing", "missing_only_delivery", "plan_verdicts", "plan_gaps")


_EVENT_EMAIL_RE = re.compile(r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+")
# Key-shaped material: provider-prefixed keys (sk-, pk_, ghp_, xox?-, AKIA, AIza), bearer tokens, JWTs (eyJ.x.y),
# a 32+ hex run, and any 24+ character url-safe run mixing upper, lower and digits (snake_case names pass).
_EVENT_TOKEN_RE = re.compile(
    r"(?i:\bbearer\s+[\w.~+/=-]{8,})"
    r"|\beyJ[\w-]{5,}\.[\w-]{5,}(?:\.[\w-]*)?"
    r"|\b(?:sk|pk|rk)[-_][\w-]{12,}"
    r"|\bgh[pousr]_[A-Za-z0-9]{20,}"
    r"|\bxox[abposr]-[\w-]{10,}"
    r"|\bAKIA[0-9A-Z]{12,}\b|\bAIza[\w-]{25,}"
    r"|\b[0-9a-fA-F]{32,}\b"
    r"|(?<![\w/+=-])(?=[A-Za-z0-9+/_=-]*\d)(?=[A-Za-z0-9+/_=-]*[a-z])(?=[A-Za-z0-9+/_=-]*[A-Z])[A-Za-z0-9+/_=-]{24,}(?![\w/+=-])"
)
_EVENT_NUMBER_RE = re.compile(r"\b\d(?:[ -]?\d){8,}\b")
_EVENT_SECRET_ASSIGN_RE = re.compile(
    r"(?i)\b(password|passcode|passwd|secret|token|api[_ -]?key|ssn|card(?: number)?)\b(\s*(?:is|[:=])\s*)(\S+)"
)


def _scrub_event_text(text: Any, secrets: Any = (), *, limit: int = 300) -> str:
    """Model- or exception-derived text bound for a stored event: values this run typed into fields are blanked,
    then OTP-like codes, emails, long digit runs (cards, phone, ids) and `password: x` style assignments are
    masked, then the length is capped. Fails to an empty string rather than an unscrubbed copy."""
    try:
        out = str(text or "")
        for secret in secrets or ():
            secret = str(secret or "").strip()
            if len(secret) >= 3:
                out = re.sub(re.escape(secret), "[REDACTED]", out, flags=re.IGNORECASE)
        out = _redact_otp_text(out)
        out = _EVENT_TOKEN_RE.sub("[REDACTED_TOKEN]", out)
        out = _EVENT_EMAIL_RE.sub("[REDACTED_EMAIL]", out)
        out = _EVENT_NUMBER_RE.sub("[REDACTED_NUMBER]", out)
        out = _EVENT_SECRET_ASSIGN_RE.sub(lambda m: f"{m.group(1)}{m.group(2)}[REDACTED]", out)
        return _safe_trim(out, limit)
    except Exception:  # noqa: BLE001
        return ""


def _completion_check_fields(check: Any, secrets: Any = ()) -> dict[str, Any]:
    """The grade's reportable fields; the raw reply (when parsing failed) and the retry flag ride only when set.
    The raw reply is scrubbed like any stored event text."""
    check = check if isinstance(check, dict) else {}
    fields = {key: check.get(key) for key in _COMPLETION_CHECK_EVENT_KEYS}
    if check.get("raw_reply"):
        fields["raw_reply"] = _scrub_event_text(check.get("raw_reply"), secrets)
    if check.get("retried"):
        fields["retried"] = True
    return fields


def _final_guard_alive(guard: dict[str, Any], url: str, lifecycle: str, typed_form_actions: list[str]) -> bool:
    """A no-repeat guard lives while the page it came from is the page now (same URL and, when both are known, the
    same document) and nothing has been typed into its own form (a search box elsewhere does not count)."""
    if guard["url"] != url:
        return False
    if guard["lifecycle"] and lifecycle and guard["lifecycle"] != lifecycle:
        return False
    if guard["form_id"] and guard["form_id"] in typed_form_actions[guard["typed_forms_seen"]:]:
        return False
    return True


def _key_hits_final_guard(
    guards: list[dict[str, Any]], focus_selector: str, focus_form_id: str, *, native_dialog: bool = False
) -> bool:
    """Whether an Enter/Space (or a native-dialog accept) cleared on standing authority could repeat a guarded
    final action. A dialog accept has no control: any live guard withholds it. Otherwise it hits the guarded control
    itself, a control in the same form (same `form_id`), and anything whose form is unknown: no focused control,
    no ancestor form, or a guarded control with no known form (fail closed)."""
    if native_dialog:
        return bool(guards)
    return any(
        not focus_selector
        or focus_selector == g["selector"]
        or not focus_form_id
        or not g["form_id"]
        or focus_form_id == g["form_id"]
        for g in guards
    )


def _form_id_for_selector(shot: Any, selector: str) -> str:
    """The `form_id` (the owning form's position in the document) the observation lists for the control with this
    selector; "" when it has no ancestor form or the body does not report one (unknown)."""
    page = shot.get("page_evidence") if isinstance(shot, dict) and isinstance(shot.get("page_evidence"), dict) else {}
    if not selector:
        return ""
    for raw in page.get("controls") or []:
        if isinstance(raw, dict) and _safe_control_selector(raw.get("selector")) == selector:
            return _safe_trim(raw.get("form_id"), 40)
    return ""


def _inconclusive_final_sendback(label: str) -> str:
    """A final action succeeded but the completion check could not run or could not say (after one retry). An
    outage is not evidence that anything is missing: no part is claimed undone, and nothing is redone."""
    return (
        f"consequential_action_verified: '{_safe_trim(label, 80)}' executed and its outcome was verified: that action "
        "SUCCEEDED. The completion check could not run, which says nothing about what is missing. Do NOT redo committed "
        f"work: do NOT click '{_safe_trim(label, 80)}' or repeat that final action (a repeat is refused). If every part "
        "of the goal is done, reply done (with `answer` if the goal asked you to report something)."
    )


def _same_final_control(selector: str, label: str, other_selector: str, other_label: str) -> bool:
    """Whether two final-action targets are the same control: equal selectors, else equal labels (fail closed)."""
    if selector and other_selector:
        return selector == other_selector
    norm = lambda text: " ".join(str(text or "").lower().split())  # noqa: E731
    return bool(norm(label)) and norm(label) == norm(other_label)


async def _grade_final_completion(
    user_id: int,
    run_id: Any,
    body: Any,
    *,
    goal: str,
    claim: str,
    shot: dict[str, Any],
    read_backs: list[dict[str, Any]],
    receipts: list[dict[str, Any]],
    after: str,
    send_back: int,
    delivered_answer: str = "",
    secret_texts: Any = (),
    restored_receipts: list[dict[str, Any]] | None = None,
    page_memory: list[dict[str, Any]] | None = None,
    plan: str = "",
    sensitive_texts: Any = None,
) -> dict[str, Any]:
    """Grade a model-declared final in Full autonomy against the current page. Fails closed: only an
    explicit `complete` verdict lets the caller end the run COMPLETED; an error or an unusable reply is
    `unavailable`."""
    try:
        whole_page_text = await _whole_page_text_for_completion(body)
        check = await asyncio.to_thread(
            _verify_task_completion,
            user_id,
            goal=goal,
            claim=claim,
            evidence=_task_completion_evidence(
                shot,
                read_backs=read_backs,
                receipts=receipts,
                whole_page_text=whole_page_text,
                restored_receipts=restored_receipts,
                page_memory=page_memory,
                # Only values typed into sensitive fields are blanked from the evidence: an ordinary typed value
                # is what the receipts prove. `secret_texts` also carries every typed value (event scrubbing).
                secret_texts=sensitive_texts if sensitive_texts is not None else secret_texts,
                plan=plan,
            ),
            delivered_answer=delivered_answer,
            retry_inconclusive=True,
        )
    except Exception as exc:  # noqa: BLE001 - an unreadable grade is "not confirmed", never complete
        check = {"verdict": "unavailable", "verified_summary": "", "missing": "", "raw_reply": _exception_summary(exc)}
    if not isinstance(check, dict):
        check = {"verdict": "unavailable"}
    check = _completion_check_fields(check, secret_texts)
    try:
        await asyncio.to_thread(
            _db_event,
            run_id,
            "TASK_COMPLETION_CHECKED",
            {**check, "after": after, "send_back": send_back, "runtime_build": _VISION_RUNTIME_BUILD},
        )
    except Exception:
        pass
    return check


def _not_confirmed_review_summary(check: dict[str, Any], receipts: list[dict[str, Any]], actions: Any) -> dict[str, Any]:
    return {
        "state": "READY_FOR_REVIEW",
        "reason": "ready_for_review",
        "completion_check": check,
        "message": "The final action was verified, but the whole goal could not be confirmed complete from the page; ready for your review.",
        "receipts": receipts,
        "actions": actions,
        "observer_version": "vision_final_action",
        "runtime_build": _VISION_RUNTIME_BUILD,
    }


def _verify_task_completion(
    user_id: int,
    *,
    goal: str,
    claim: str,
    evidence: dict[str, Any],
    delivered_answer: str = "",
    retry_inconclusive: bool = False,
) -> dict[str, Any]:
    """`delivered_answer` is the answer the user was actually handed (brain-written, so it rides in its own
    field the grader is told is data; `evidence` stays runtime-computed only). Whether one was delivered is a
    run-state fact set here, never by the model."""
    if (ablated := eval_ablation.benign_verdict("task_completion_verification", "done")) is not None:
        return ablated
    from app.lumen_model import LumenModelClient

    delivered = _safe_trim(" ".join(str(delivered_answer or "").split()), _ANSWER_MAX_CHARS)
    evidence = dict(evidence)
    # The agent's numbered plan rides in its own field (agent-authored, never evidence).
    plan_lines = [item for item in (evidence.pop("agent_plan_lines", None) or []) if isinstance(item, dict)]
    with SessionLocal() as db:
        check = LumenModelClient(db, user_id=user_id).verify_task_completion(
            {
                "goal": goal,
                "agent_claim": claim,
                "evidence": {**evidence, "answer_delivered_to_user": bool(delivered)},
                "delivered_answer": delivered,
                "retry_inconclusive": bool(retry_inconclusive),
                **({"agent_plan": plan_lines} if plan_lines else {}),
            }
        )
    return _apply_plan_verdicts(check, plan_lines) if isinstance(check, dict) else check


