def _run_start_prewarm_sync(
    *,
    user_id: int,
    run_id: int,
    provider: Any,
    context: dict[str, Any],
    state: dict[str, Any],
) -> dict[str, Any]:
    """Worker-thread body of the run-start prewarm. Never raises."""
    from app import run_prewarm, vision_agent

    try:
        with SessionLocal() as db:
            settings = get_agent_settings(db, user_id)
        if not run_prewarm.prewarm_enabled(settings):
            return {"kind": "disabled"}
        system = schema = None
        if run_prewarm.prewarm_kind(provider) == "cache":
            try:
                prepared = vision_agent.prepare_model_input({"width": 0, "height": 0, "url": "", "title": ""}, context)
                system, schema = prepared.get("system"), prepared.get("schema")
                state["system_hash"] = run_prewarm.system_fingerprint(str(system or ""))
            except Exception:  # noqa: BLE001 - without the rules block only the connection is warmed
                system = schema = None
        return run_prewarm.run_prewarm(provider, system=system, schema=schema, run_id=run_id)
    except Exception:  # noqa: BLE001 - a prewarm never fails the run
        return {"kind": "error"}


def _start_run_prewarm(
    body: Any,
    *,
    user_id: int,
    run_id: int,
    provider: Any,
    goal: str,
    execution_surface: str,
    candidate_data_access: str,
    candidate_data_scopes: list[str],
    is_generic_browser_task: bool,
    totp_capability: bool,
    state: dict[str, Any],
) -> asyncio.Task | None:
    """Fire-and-forget: warm the provider connection and cache while the first screenshot is taken.
    Returns the task (nothing awaits it) or None when there is no live provider to warm."""
    from app import run_prewarm

    if run_prewarm.prewarm_kind(provider) == "none" or run_prewarm._env_disabled():
        return None
    try:
        available_surfaces = getattr(body, "available_surfaces", None)
        context = {
            "goal": goal,
            "execution_surface": execution_surface,
            "unavailable_actions": _actions_unavailable_on_body(body, execution_surface),
            **({"totp_capability": True} if totp_capability else {}),
            "surfaces": list(available_surfaces()) if callable(available_surfaces) else [execution_surface],
            "application_context": not is_generic_browser_task,
            "generic_browser_task": bool(is_generic_browser_task),
            "candidate_data_access": candidate_data_access,
            "candidate_data_scopes": list(candidate_data_scopes),
            "page_evidence": {},
        }
        task = asyncio.create_task(
            asyncio.to_thread(
                _run_start_prewarm_sync,
                user_id=user_id,
                run_id=run_id,
                provider=provider,
                context=context,
                state=state,
            )
        )
        task.add_done_callback(_discard_late_task_result)
        return task
    except Exception:  # noqa: BLE001 - a prewarm never fails the run
        return None


