# Accessibility roles of rows nothing acts on (UI Automation control types and their ARIA kin).
_STATIC_CONTROL_ROLES = frozenset({"image", "img", "text", "statictext", "separator", "tooltip", "presentation", "none"})
# Rows that take text: never demoted as a container (a password input holding its show/hide eye, a date
# field holding its calendar button) or as static (AT-SPI calls an editable entry "text").
_TEXT_TAKING_ROLES = frozenset({"edit", "document", "textbox", "searchbox", "combobox", "spinbutton", "entry", "textarea"})
_TEXT_TAKING_TAGS = frozenset({"input", "textarea", "select"})


def _row_in_dialog(raw: dict[str, Any]) -> bool:
    """Raw containment evidence that a control sits inside a dialog container (the body's `in_dialog`, or a
    dialog role, aria-modal, or <dialog> among its ancestors). No stacking inference."""
    if raw.get("in_dialog") is True:
        return True
    if str(raw.get("role") or "").lower() in _CLICK_JUDGE_DIALOG_ROLES:
        return True
    chain = raw.get("ancestor_chain")
    for item in chain if isinstance(chain, list) else []:
        if not isinstance(item, dict):
            continue
        if str(item.get("role") or "").lower() in _CLICK_JUDGE_DIALOG_ROLES or str(item.get("tag") or "").lower() == "dialog":
            return True
        if str(item.get("aria_modal") or "").lower() == "true":
            return True
    return False


def _model_visible_control_rows(
    raw_controls: Any, *, limit: int, viewport_height: Any = None, grow_to_on_screen: bool = False
) -> list[Any]:
    """The observed control rows the model is shown, in observation order.

    The control holding keyboard focus always survives the cut: a Save As dialog's toolbars fill
    the first slots top-to-bottom, and the focused File name box at its bottom was dropped
    (v3_paperwork from the brain seat), so typing into focus could not be checked against it. The
    index map that resolves a cited control uses this same selection.

    A control the observer's hit test found covered at its centre (``occluded``: rows a scrolling
    panel clips away, a button under an overlay) is not on screen where its box says, so it takes a
    slot only after every control that is: v4_scroll run 1670's 16 slots went to a list's hidden
    rows, the timeline's "Open" buttons never reached the model, and it clicked the card beside the
    one it meant.

    Among uncovered rows, a row whose box holds another row's box (a window, a pane wrapping a form)
    and a row the accessibility tree calls static (an image, a text label) take slots only after the
    rows inside them: Tk lists its window, title bar, wrapper panes, and label images first, and v5_memory
    run 1721's 16 slots ended before the Approve/Deny radios, the entry fields, and Submit, so the brain
    clicked by eye and missed Submit five times. Structure only, never what a row means. The rows keep
    observation order."""
    if not isinstance(raw_controls, list) or limit <= 0:
        return []

    def covered(raw: Any) -> bool:
        return isinstance(raw, dict) and raw.get("occluded") is True

    def box(raw: Any) -> tuple[float, float, float, float] | None:
        if not isinstance(raw, dict):
            return None
        try:
            x, y = float(raw.get("x")), float(raw.get("y"))
            width, height = float(raw.get("width")), float(raw.get("height"))
        except (TypeError, ValueError):
            return None
        return (x, y, x + width, y + height) if width > 0 and height > 0 else None

    boxes = [box(raw) for raw in raw_controls]

    def holds_another(index: int) -> bool:
        outer = boxes[index]
        if outer is None:
            return False
        for other, inner in enumerate(boxes):
            if other == index or inner is None:
                continue
            inside = outer[0] <= inner[0] and outer[1] <= inner[1] and inner[2] <= outer[2] and inner[3] <= outer[3]
            # Two rows with one box: the later one (the child in tree order) is the leaf.
            if inside and (inner != outer or other > index):
                return True
        return False

    def takes_text(raw: Any) -> bool:
        if not isinstance(raw, dict):
            return False
        if any(raw.get(key) is True for key in ("editable", "accepts_text", "contenteditable", "password")):
            return True
        role = str(raw.get("role") or "").strip().lower()
        tag = str(raw.get("tag") or "").strip().lower()
        return role in _TEXT_TAKING_ROLES or tag in _TEXT_TAKING_TAGS

    def static(raw: Any) -> bool:
        role = str((raw or {}).get("role") or "").strip().lower() if isinstance(raw, dict) else ""
        return role in _STATIC_CONTROL_ROLES

    try:
        screen_height = float(viewport_height) if viewport_height else 0.0
    except (TypeError, ValueError):
        screen_height = 0.0

    def off_screen(index: int) -> bool:
        # Wholly above or below the viewport (v6_travel: a sticky filter panel's rows and two "Start this
        # trip" buttons scrolled away held the slots the results' Select buttons and the form needed).
        bounds = boxes[index]
        return bool(screen_height and bounds and (bounds[3] <= 0 or bounds[1] >= screen_height))

    # With a control holding focus, rows of one tier fill nearest that control first: it is where the brain
    # is working (v6_calendar: twenty-two "New event" grid slots came before the open form, so its Day, Start,
    # and Duration dropdowns never reached the model). Without one, a tier keeps observation order.
    focus_box = next(
        (
            boxes[index]
            for index, raw in enumerate(raw_controls)
            if isinstance(raw, dict) and raw.get("focused") is True and boxes[index] is not None
        ),
        None,
    )

    def distance_to_focus(index: int) -> float:
        bounds = boxes[index]
        if focus_box is None:
            return 0.0
        if bounds is None:
            return float("inf")
        dx = max(focus_box[0] - bounds[2], bounds[0] - focus_box[2], 0.0)
        dy = max(focus_box[1] - bounds[3], bounds[1] - focus_box[3], 0.0)
        return (dx * dx + dy * dy) ** 0.5

    # A spreadsheet-style grid has dozens of cells that would crowd out every other row, yet the cell under
    # the brain's hand is what an edit starts from (v6_sheet run 1795: every edit was by x,y). The few nearest
    # the focused control (a few at the top without one) rank with the other controls; the rest follow them.
    def grid_cell(raw: Any) -> bool:
        if not isinstance(raw, dict):
            return False
        role = str(raw.get("role") or "").strip().lower()
        return not covered(raw) and not takes_text(raw) and (role in {"gridcell", "cell"} or str(raw.get("tag") or "").lower() == "td")

    grid_cells = {index for index, raw in enumerate(raw_controls) if grid_cell(raw)}
    # The page's own grid cells (role gridcell/cell, td) are what an edit starts from: they keep a fair
    # share of slots next to the dense runs found below, which stay at the small share (v6_sheet run 1823:
    # four to eight cells of a forty-row sheet reached the model, the rest of the column unreachable by index).
    real_grid_cells = set(grid_cells)
    # A dense run of tiny, near-identical controls laid out as a grid (a seat map's hundred buttons, a
    # calendar's "New event Mon 08:00" slots) is a grid too: it crowds the page's real buttons out of the
    # cap (v6_travel run 1804: "Continue to traveler details" and "Back to results" were visible and
    # unlisted under 100+ seat buttons; v6_calendar run 1809: 56 slot cells and no Save). A labelled
    # checkbox, radio, or switch is never part of one, nor a control with a record's row text (a card's
    # button), nor a long label: a vertical list of labelled checkboxes is a filter, not a grid. A small
    # share nearest the focus keeps its slots like grid cells.
    def dense_signature(raw: dict[str, Any]) -> str | None:
        label = str(raw.get("text") or raw.get("name") or "").strip()
        if raw.get("row_text"):
            return None
        role = str(raw.get("role") or "").strip().lower()
        input_type = str(raw.get("type") or "").strip().lower()
        if role in {"checkbox", "radio", "switch"} or input_type in {"checkbox", "radio"}:
            if sum(ch.isalpha() for ch in label) >= 3:
                return None
        words = label.split()
        if len(label) > 4:
            if len(label) > 40 or len(words) < 3:
                return None
            return " ".join(words[:2]).lower()
        return ""

    dense_groups: dict[tuple[str, str, str, str], list[int]] = {}
    for index, raw in enumerate(raw_controls):
        if not isinstance(raw, dict) or index in grid_cells or covered(raw) or takes_text(raw) or off_screen(index):
            continue
        first_class = (str(raw.get("class_name") or "").split() or [""])[0]
        signature = dense_signature(raw)
        bounds = boxes[index]
        if signature is None or not first_class or bounds is None:
            continue
        if bounds[3] - bounds[1] > 80 or bounds[2] - bounds[0] > 260:
            continue
        dense_groups.setdefault(
            (str(raw.get("tag") or "").lower(), str(raw.get("role") or "").lower(), first_class, signature), []
        ).append(index)
    for members in dense_groups.values():
        if len(members) <= 12:
            continue
        # Laid out as a grid or a tiled row (never one vertical column), boxes of one size.
        lefts = {round((boxes[i] or (0, 0, 0, 0))[0] / 4) for i in members}
        widths = sorted((boxes[i] or (0, 0, 0, 0))[2] - (boxes[i] or (0, 0, 0, 0))[0] for i in members)
        median_width = widths[len(widths) // 2]
        uniform = all(abs(w - median_width) <= 0.3 * median_width for w in widths)
        if len(lefts) >= 3 and uniform:
            grid_cells.update(members)
    near_grid_cells = set(
        sorted(grid_cells - real_grid_cells, key=lambda index: (distance_to_focus(index), index))[
            : 8 if focus_box is not None else 4
        ]
    ) | set(
        sorted(real_grid_cells, key=lambda index: (distance_to_focus(index), index))[
            : 24 if focus_box is not None else 12
        ]
    )

    def base_tier(index: int) -> int:
        raw = raw_controls[index]
        if covered(raw):
            return 3
        if takes_text(raw):
            return 0
        if index in grid_cells:
            return 0 if index in near_grid_cells else 1
        if holds_another(index):
            return 2
        return 1 if static(raw) else 0

    # The newest overlay: the last run of rows in observation order that sit in a stacking layer above the
    # page (a date picker, a menu, a dialog appended after the page). Its rows fill first, so an open popup's
    # options reach the model (v6_crm run 1790: the picker's "April 28" fell outside the cap). Raw stacking
    # evidence only; a page whose every row is layered has no distinguishable overlay.
    def layered(raw: Any) -> bool:
        try:
            return isinstance(raw, dict) and float(raw.get("stack_layer") or 0) > 0 and not covered(raw)
        except (TypeError, ValueError):
            return False

    overlay_rows: set[int] = set()
    run: list[int] = []
    for index, raw in enumerate(raw_controls):
        if layered(raw):
            run.append(index)
        elif run:
            overlay_rows = set(run)
            run = []
    if run:
        overlay_rows = set(run)
    if len(overlay_rows) >= len(raw_controls):
        overlay_rows = set()
    # The newest open dialog (role dialog / alertdialog, aria-modal, <dialog>), layered or not and with or
    # without focus inside it: a form opened over a grid has its Save and Close first (v6_calendar run 1809:
    # focus fell to body after an option click and the event form never reached the model). The body numbers
    # each dialog container in document order; the highest number is the newest.
    dialog_rows: dict[int, list[int]] = {}
    for index, raw in enumerate(raw_controls):
        if not isinstance(raw, dict) or covered(raw) or off_screen(index) or not _row_in_dialog(raw):
            continue
        try:
            ordinal = int(raw.get("dialog_ordinal") or 0)
        except (TypeError, ValueError):
            ordinal = 0
        dialog_rows.setdefault(ordinal, []).append(index)
    if dialog_rows:
        newest_dialog = set(dialog_rows[max(dialog_rows)])
        if len(newest_dialog) < len(raw_controls):
            overlay_rows = overlay_rows | newest_dialog
    # An open list's options (role option / menuitem) fill first too, layered or not: a suggestion list that
    # renders in the page's flow (v6_travel run 1804: the typed city's option arrived a step late behind
    # the page's other controls). A page with a large permanent option list is left to the ordinary order.
    option_rows = {
        index
        for index, raw in enumerate(raw_controls)
        if isinstance(raw, dict)
        and not covered(raw)
        and str(raw.get("role") or "").strip().lower() in {"option", "menuitem", "menuitemradio", "menuitemcheckbox"}
    }
    if option_rows and len(option_rows) <= 40 and len(option_rows) < len(raw_controls):
        overlay_rows = overlay_rows | option_rows

    def tier(index: int) -> int:
        if index in overlay_rows and not off_screen(index):
            return -1
        return base_tier(index) + (4 if off_screen(index) else 0)

    # A stable sort: rows of one tier at one distance keep observation order.
    priority = sorted(range(len(raw_controls)), key=lambda index: (tier(index), distance_to_focus(index)))
    # Every on-screen, uncovered, ordinary control is listed: the cap orders what is crowded out, it never
    # drops a visible control for one that is not (v6_shop run 1803: 51 controls on screen, a focused Search
    # at the top left put the whole cart column, Coupon and Apply included, beyond 28). A page with more
    # than twice the cap still truncates, nearest the focus first.
    on_screen_ordinary = sum(1 for index in priority if tier(index) <= 0)
    if grow_to_on_screen:
        limit = max(limit, min(on_screen_ordinary, limit * 2))
    chosen = priority[:limit]
    focused_beyond = next(
        (
            index
            for index in priority[limit:]
            if isinstance(raw_controls[index], dict) and raw_controls[index].get("focused") is True
        ),
        None,
    )
    if focused_beyond is not None:
        chosen = [*chosen[: limit - 1], focused_beyond]
    return [raw_controls[index] for index in sorted(chosen)]


def _off_screen_controls_summary(
    raw_controls: Any, shown: Any, viewport_height: Any, off_screen_rows: Any = None
) -> dict[str, Any]:
    """How many controls lie wholly above or below the viewport (not in the inventory), with a "kind: label"
    entry for the first few each side: a cheap raw hint that the page continues and what is there (v6_shop
    run 1791: five Start buttons in the inventory while the shop sat below the fold; v6_insights run 1798: the
    question inputs above a scroll were gone and the brain scrolled back for each answer). The body lists
    off-screen rows itself (`off_screen_controls`); enumerated rows that sit outside the viewport count too.
    Fields and buttons come first, nearest the viewport first. Counts and raw text only."""
    try:
        screen_height = float(viewport_height) if viewport_height else 0.0
    except (TypeError, ValueError):
        screen_height = 0.0
    shown_indexes = {row.get("index") for row in shown if isinstance(row, dict)} if isinstance(shown, list) else set()
    found: dict[str, list[tuple[int, float, str]]] = {"above": [], "below": []}

    def _with_distance(label: str, side: str, distance: float) -> str:
        # Where it lies, so one `scroll` by that amount reaches it: "field: Notes (below 1200px)".
        return f"{label} ({side} {int(round(abs(distance) / 10.0) * 10)}px)"

    def kind_of(tag: str, role: str, input_type: str) -> tuple[int, str]:
        tag, role, input_type = tag.strip().lower(), role.strip().lower(), input_type.strip().lower()
        if role in {"checkbox", "radio", "switch"} or (tag == "input" and input_type in {"checkbox", "radio"}):
            return 1, "checkbox"
        if tag in {"textarea", "select"} or role in _TEXT_TAKING_ROLES or (
            tag == "input" and input_type not in {"button", "submit", "reset", "image"}
        ):
            return 0, "field"
        if tag in {"button", "a"} or role in {"button", "link", "tab", "menuitem"} or input_type in {"button", "submit"}:
            return 1, "button"
        return 2, tag or role or "control"

    if screen_height and isinstance(raw_controls, list):
        for raw in raw_controls:
            if not isinstance(raw, dict) or raw.get("index") in shown_indexes:
                continue
            try:
                top, height = float(raw.get("y")), float(raw.get("height"))
            except (TypeError, ValueError):
                continue
            if height <= 0:
                continue
            side = "above" if top + height <= 0 else "below" if top >= screen_height else ""
            if not side:
                continue
            rank, kind = kind_of(str(raw.get("tag") or ""), str(raw.get("role") or ""), str(raw.get("type") or ""))
            label = _safe_trim(raw.get("text") or raw.get("aria_label") or raw.get("placeholder") or raw.get("name"), 40)
            distance = -(top + height) if side == "above" else top - screen_height
            found[side].append((rank, distance, _with_distance(f"{kind}: {label}" if label else kind, side, distance)))
    if isinstance(off_screen_rows, list):
        for raw in off_screen_rows[:60]:
            if not isinstance(raw, dict) or raw.get("side") not in found:
                continue
            rank, kind = kind_of(str(raw.get("tag") or ""), str(raw.get("role") or ""), str(raw.get("type") or ""))
            label = _safe_trim(raw.get("text"), 40)
            try:
                distance = float(raw.get("distance") or 0)
            except (TypeError, ValueError):
                distance = 0.0
            found[str(raw["side"])].append(
                (rank, distance, _with_distance(f"{kind}: {label}" if label else kind, str(raw["side"]), distance))
            )
    summary: dict[str, Any] = {}
    for side in ("above", "below"):
        entries = found[side]
        if not entries:
            continue
        labels: list[str] = []
        for _rank, _distance, label in sorted(entries, key=lambda entry: (entry[0], entry[1])):
            if label not in labels:
                labels.append(label)
            if len(labels) >= 8:
                break
        summary[side] = {"count": len(entries), "first_labels": labels}
    return summary


_EDITABLE_VALUE_CHARS = 2000


def _control_value_is_editable_text(control: dict[str, Any]) -> bool:
    tag = str(control.get("tag") or "").strip().lower()
    input_type = str(control.get("type") or "").strip().lower()
    if tag == "input" and (input_type in _NON_TEXT_INPUT_TYPES or input_type in {"password", "hidden", "file"}):
        return False  # a checkbox's "on", a file path, a secret: never a verbatim text value
    return (
        tag in {"input", "textarea"}
        or control.get("accepts_text") is True
        or control.get("typable") is True
        or control.get("contenteditable") is True
        or str(control.get("contenteditable") or "").lower() in {"true", "plaintext-only"}
    )


def _trim_observed_controls(
    raw_controls: Any, *, limit: int, text_limit: int, viewport_height: Any = None, grow_to_on_screen: bool = False
) -> list[dict[str, Any]]:
    trimmed_controls: list[dict[str, Any]] = []
    for raw in _model_visible_control_rows(
        raw_controls, limit=limit, viewport_height=viewport_height, grow_to_on_screen=grow_to_on_screen
    ):
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        item.pop("selector", None)
        # `context` is a remembered (compact) row's context_text: trimmed alike, so a remembered
        # control still on screen keeps the live inventory's identity and is deduped out.
        for key in ("text", "value", "nearby_text", "context_text", "context", "label", "aria_label", "placeholder", "name"):
            if key == "value" and key in item and _control_value_is_editable_text(item):
                # An editable text value is verbatim (trailing space, runs, newlines are the task data): cap only.
                whole = item.get(key)
                whole = whole if isinstance(whole, str) else str(whole or "")
                if whole != "[REDACTED]" and (item.get("value_truncated") is True or len(whole) > _EDITABLE_VALUE_CHARS):
                    item["value_truncated"] = True
                    try:
                        item["value_length"] = max(int(item.get("value_length") or 0), len(whole))
                    except (TypeError, ValueError):
                        item["value_length"] = len(whole)
                item[key] = whole[:_EDITABLE_VALUE_CHARS]
            elif key in item:
                item[key] = _safe_trim(item.get(key), text_limit)
        for key in ("accessibility_context", "dom_context"):
            raw_context = item.get(key)
            if not isinstance(raw_context, list):
                item.pop(key, None)
                continue
            bounded_context: list[dict[str, Any]] = []
            for raw_entry in raw_context[:8]:
                if not isinstance(raw_entry, dict):
                    continue
                entry = {
                    "relation": _safe_trim(raw_entry.get("relation"), 40),
                    "text": _safe_trim(raw_entry.get("text"), text_limit),
                }
                if raw_entry.get("depth") is not None:
                    try:
                        entry["depth"] = int(raw_entry.get("depth"))
                    except (TypeError, ValueError):
                        entry["depth"] = 0
                if entry["text"]:
                    bounded_context.append(entry)
            item[key] = bounded_context
        trimmed_controls.append(item)
    return trimmed_controls


# A page header the run has already read, left unchanged at the top of the page text every step, is shown
# short once the text no longer fits: its head stays (the task cards' first words), the rest of the repeat
# is a count, and the room goes to the text after it (v6_crm run 1797: a five-task header filled the
# 1200-character view each step and cut off the contract below it).
_VIEWPORT_HEAD_KEEP_CHARS = 300
_VIEWPORT_PREVIOUS_CHARS = 1600


def _below_fold_change_hint(previous: Any, current: Any, previous_text: Any, current_text: Any) -> str:
    """A one-line hint when content appeared below the viewport while the visible page barely changed (v6_shop
    runs 1791/1803: after Start the shop rendered under the fold and the top looked the same). Compares the
    body's short below-the-fold text pieces with the previous step's; raw strings only."""
    if not isinstance(previous, list) or not isinstance(current, list) or not previous_text or not current_text:
        return ""
    seen = {" ".join(str(item).split()).casefold() for item in previous}
    fresh = [" ".join(str(item).split()) for item in current if " ".join(str(item).split()).casefold() not in seen]
    fresh = [item for item in fresh if item]
    if not fresh:
        return ""
    import difflib

    top_same = difflib.SequenceMatcher(None, str(previous_text)[:1500], str(current_text)[:1500], autojunk=False).quick_ratio()
    if top_same < 0.9:
        return ""
    return f"content changed below the fold: {_safe_trim(fresh[0], 80)}" + (f" (+{len(fresh) - 1} more)" if len(fresh) > 1 else "")


def _inventory_delta_identity(shot: dict[str, Any] | None, execution_surface: str) -> str:
    """What must be unchanged for the control inventory to be sent as a delta: the document (url + lifecycle
    token) in the browser, the front window on the desktop. Empty when the body reports neither."""
    if not isinstance(shot, dict):
        return ""
    evidence = shot.get("page_evidence") if isinstance(shot.get("page_evidence"), dict) else {}
    if execution_surface == "desktop":
        windows = evidence.get("windows") if isinstance(evidence.get("windows"), list) else []
        front = next((w for w in windows if isinstance(w, dict) and w.get("active")), None)
        return f"desktop|{front.get('window_id')}" if isinstance(front, dict) and front.get("window_id") else ""
    token = shot.get("document_lifecycle_token") or evidence.get("document_lifecycle_token") or ""
    url = shot.get("url") or ""
    return f"{url}|{token}" if url else ""


_INVENTORY_DELTA_FAILURE_WORDS = ("fail", "refus", "timeout", "error", "blocked", "rejected", "invalid", "cut_off")


def _inventory_delta_request(
    state: dict[str, Any],
    *,
    identity: str,
    step: int,
    payload_mode: str,
    last_outcome: dict[str, str] | None,
    plan: str,
) -> dict[str, Any]:
    """The loop's account of the previous step for vision_agent.plan_inventory_delta. A resync is forced after a
    reduced payload (timeout or empty-completion retry), after a failed or refused step, and when the page
    identity cannot be read."""
    full_reason = ""
    outcome = str((last_outcome or {}).get("outcome") or "").casefold()
    if not identity:
        full_reason = "identity_unknown"
    elif payload_mode != "normal":
        full_reason = "reduced_payload"
    elif (last_outcome or {}).get("code") or any(word in outcome for word in _INVENTORY_DELTA_FAILURE_WORDS):
        full_reason = "after_failed_action"
    targets = [t for t in state.get("targets") or [] if int(t.get("step", -10)) >= step - 2]
    now_line = next((line for line in str(plan or "").splitlines() if "[now]" in line.casefold()), "")
    return {
        "identity": identity,
        "step": step,
        "previous": {k: state.get(k) for k in ("identity", "step", "sent", "since_full", "fps")},
        "full_reason": full_reason,
        "keep_indices": [t["index"] for t in targets],
        "keep_fingerprints": [t["fp"] for t in targets if t.get("fp")],
        "now_line": now_line,
    }


def _inventory_delta_remember(state: dict[str, Any], request: dict[str, Any]) -> None:
    """After prepare_model_input: this step's rows become the next step's baseline (not yet `sent`)."""
    result = request.get("result")
    if not isinstance(result, dict):
        return
    previous_since = int((request.get("previous") or {}).get("since_full") or 0)
    state.update(
        {
            "identity": request.get("identity"),
            "step": request.get("step"),
            "sent": False,
            "since_full": 0 if result.get("mode") == "full" else previous_since + 1,
            "fps": list(result.get("fingerprints") or []),
            "fp_by_index": dict(result.get("fp_by_index") or {}),
        }
    )


def _inventory_delta_note_decision(state: dict[str, Any], action: dict[str, Any] | None, step: int) -> None:
    """The model's call returned: this step's inventory was sent, and the controls it targeted stay whole next."""
    if not isinstance(action, dict) or _vision_failure_reason(action) or action.get("error"):
        return
    state["sent"] = True
    by_index = state.get("fp_by_index") or {}
    indices: list[Any] = [action.get("control")]
    for item in action.get("then") or []:
        if isinstance(item, dict):
            indices.append(item.get("control"))
    targets = [t for t in state.get("targets") or [] if int(t.get("step", -10)) >= step - 2]
    for index in indices:
        try:
            number = int(index)
        except (TypeError, ValueError):
            continue
        if number > 0:
            targets.append({"step": step, "index": number, "fp": by_index.get(str(number), "")})
    state["targets"] = targets[-12:]


def _viewport_text_without_repeated_head(text: Any, previous: Any, limit: int) -> str:
    """The page text with the stretch it shares with the previous step's text at its start shortened, only
    when the text is longer than ``limit`` and something new follows the repeat. Raw string comparison."""
    current = str(text or "")
    before = str(previous or "")
    if len(current) <= limit or not before:
        return current
    shared = 0
    for left, right in zip(current, before):
        if left != right:
            break
        shared += 1
    if shared < len(current):
        # Back up to a word boundary: a word that differs part-way is new text.
        space = current.rfind(" ", 0, shared)
        shared = space + 1 if space >= 0 else 0
    new_chars = len(current) - shared
    omitted = shared - _VIEWPORT_HEAD_KEEP_CHARS
    if omitted < 150 or new_chars < 80:
        return current
    head = current[:_VIEWPORT_HEAD_KEEP_CHARS].rstrip()
    return f"{head} [... {omitted} characters of page header unchanged since the last step omitted ...] {current[shared:].lstrip()}"


_PAGE_MEMORY_SHINGLE_WORDS = 4
# How much visible text one page-memory snapshot keeps (the extension sends at most 4,500).
_PAGE_MEMORY_ENTRY_CHARS = 4000
_PAGE_MEMORY_MIN_SPAN_WORDS = 3
# A short stretch of still-present words between two departed stretches stays in the snapshot:
# eliding it turns "Show only Middle East & Africa on the chart" into "Show only ... on the chart".
_PAGE_MEMORY_BRIDGE_WORDS = 8


def _page_memory_shingles(words: list[str]) -> set[tuple[str, ...]]:
    size = _PAGE_MEMORY_SHINGLE_WORDS
    if len(words) < size:
        return {tuple(words)} if words else set()
    return {tuple(words[index:index + size]) for index in range(len(words) - size + 1)}


def _departed_page_memory(raw_entries: Any, current_text: Any) -> list[dict[str, Any]]:
    """Compress prior-page snapshots to the text that is no longer on the current page.

    A single-URL wizard or re-rendering app produces near-identical snapshots, so whole
    snapshots crowd each other out of the prompt and a fact stated two screens ago (a note
    for a later step, a code on a previous view) is lost. This is a plain word-shingle text
    diff against the current viewport text and against newer snapshots: it keeps what was
    shown and is gone, in order, and never interprets what that text means.
    """
    if not isinstance(raw_entries, list):
        return []
    size = _PAGE_MEMORY_SHINGLE_WORDS
    seen = _page_memory_shingles(str(current_text or "").split())
    kept: list[dict[str, Any]] = []
    for raw in reversed(raw_entries):
        if not isinstance(raw, dict):
            continue
        words = str(raw.get("text") or "").split()
        if not words:
            continue
        present = [False] * len(words)
        if len(words) < size:
            present = [tuple(words) in seen] * len(words)
        else:
            for index in range(len(words) - size + 1):
                if tuple(words[index:index + size]) in seen:
                    for offset in range(size):
                        present[index + offset] = True
        index = 0
        while index < len(words):
            if not present[index]:
                index += 1
                continue
            end = index
            while end < len(words) and present[end]:
                end += 1
            if 0 < index and end < len(words) and end - index <= _PAGE_MEMORY_BRIDGE_WORDS:
                for position in range(index, end):
                    present[position] = False
            index = end
        spans: list[str] = []
        run: list[str] = []
        for word, is_present in zip(words, present):
            if is_present:
                if len(run) >= _PAGE_MEMORY_MIN_SPAN_WORDS:
                    spans.append(" ".join(run))
                run = []
            else:
                run.append(word)
        if len(run) >= _PAGE_MEMORY_MIN_SPAN_WORDS:
            spans.append(" ".join(run))
        seen |= _page_memory_shingles(words)
        if not spans:
            continue
        item = {key: raw.get(key) for key in ("url", "title", "scroll_y") if key in raw}
        item["text"] = " … ".join(spans)
        kept.append(item)
    kept.reverse()
    return kept


def _trim_page_memory(raw_entries: Any, *, limit: int, text_limit: int) -> list[dict[str, Any]]:
    if not isinstance(raw_entries, list):
        return []
    if limit <= 0:
        return []
    entries: list[dict[str, Any]] = []
    for raw in raw_entries[-limit:]:
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        for key, field_limit in (("text", text_limit), ("title", 160), ("url", 240)):
            if key in item:
                item[key] = _safe_trim(item.get(key), field_limit)
        entries.append(item)
    return entries


def _trim_control_memory(raw_entries: Any, *, limit: int, controls_limit: int, text_limit: int) -> list[dict[str, Any]]:
    if not isinstance(raw_entries, list):
        return []
    if limit <= 0:
        return []
    entries: list[dict[str, Any]] = []
    for raw in raw_entries[-limit:]:
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        if "controls" in item:
            item["controls"] = _trim_observed_controls(item.get("controls"), limit=controls_limit, text_limit=text_limit)
        for key in ("title", "url"):
            if key in item:
                item[key] = _safe_trim(item.get(key), 240)
        entries.append(item)
    return entries


def _trim_answer_items(raw_items: Any, *, limit: int, text_limit: int) -> list[dict[str, str]]:
    if not isinstance(raw_items, list):
        return []
    if limit <= 0:
        return []
    items: list[dict[str, str]] = []
    for raw in raw_items[-limit:]:
        if not isinstance(raw, dict):
            continue
        item: dict[str, str] = {}
        for key in (
            "question",
            "answer",
            "raw_user_answer",
            "source",
            "answer_kind",
            "scope",
            "target_selector",
            "target_binding_key",
            "target_control_signature",
        ):
            if key in raw:
                item[key] = _safe_trim(raw.get(key), text_limit if key not in {"source", "target_selector", "target_binding_key", "target_control_signature"} else 200)
        selected_options = _answer_selected_options(raw.get("selected_options"))
        if selected_options:
            item["selected_options"] = selected_options  # type: ignore[assignment]
        if item:
            items.append(item)
    return items


def _is_checkbox_control(control: dict[str, Any] | None) -> bool:
    return str((control or {}).get("type") or "").lower() == "checkbox" or str(
        (control or {}).get("role") or ""
    ).lower() in {"checkbox", "menuitemcheckbox"}


def _ask_choices_and_suggestions(options: Any, control: dict[str, Any] | None) -> tuple[list[Any], list[Any]]:
    """Split an ask's options into choices and suggestions by the bound control's structure. A text box
    takes any value, so options the brain names for it are suggestions and the user's own reply is the
    answer (1796: "He him" for Pronouns became the lone suggested option "n/a"). A combobox's input is
    the front of a list, so its options stay choices, as do an unbound ask's."""
    named = list(options or []) if isinstance(options, list) else []
    if (
        named
        and _control_is_editable_text(control)
        and str((control or {}).get("role") or "").strip().casefold() != "combobox"
    ):
        return [], named
    return named, []


def _options_are_page_checkboxes(options: list[Any], page_evidence: dict[str, Any] | None) -> bool:
    """True when every option an ask names is the text of a checkbox the body enumerated: a DOM fact,
    so a checkbox group is multi-select even when the brain leaves multi_select off."""

    def norm(value: Any) -> str:
        return " ".join(str(value or "").split()).casefold()

    wanted = {norm(option) for option in options if norm(option)}
    if not wanted:
        return False
    checkbox_labels: set[str] = set()
    for control in (page_evidence or {}).get("controls") or []:
        if isinstance(control, dict) and _is_checkbox_control(control):
            checkbox_labels.update(
                norm(control.get(key)) for key in ("text", "label", "name", "aria_label") if norm(control.get(key))
            )
    return wanted <= checkbox_labels


def _answer_selected_options(raw: Any) -> list[str]:
    """The options of a multi-select human answer, trimmed; [] for any other answer."""
    if not isinstance(raw, list):
        return []
    options = [_safe_trim(option, 200) for option in raw[:20] if str(option or "").strip()]
    return [option for option in dict.fromkeys(options) if option]


def _is_skip_answer_value(value: Any) -> bool:
    return str(value or "").strip() == SKIP_ANSWER_TEXT


def _skip_context_item(*, question: Any, source: str, scope: str = "application", raw_user_answer: Any = "") -> dict[str, str]:
    item = {
        "question": _safe_trim(question, 320),
        "answer": SKIP_ANSWER_TEXT,
        "answer_kind": "skip",
        "scope": "always" if str(scope or "").lower() == "always" else "application",
        "source": _safe_trim(source, 80),
    }
    raw = _safe_trim(raw_user_answer, 500)
    if raw:
        item["raw_user_answer"] = raw
    return item


def _skip_preference_question_keys(context: dict[str, Any] | None) -> list[str]:
    try:
        from app.agent_settings import normalize_question_key
    except Exception:  # noqa: BLE001
        return []
    keys: list[str] = []
    for bucket in ("saved_answers", "human_answers"):
        for item in (context or {}).get(bucket) or []:
            if not isinstance(item, dict):
                continue
            if str(item.get("answer_kind") or "").lower() != "skip" and not _is_skip_answer_value(item.get("answer")):
                continue
            key = normalize_question_key(str(item.get("question") or ""))
            if key and key not in keys:
                keys.append(key)
    return keys


def _control_matches_skip_preference(control: dict[str, Any], skip_question_keys: list[str] | None) -> bool:
    if not skip_question_keys:
        return False
    try:
        from app.agent_settings import normalize_question_key
    except Exception:  # noqa: BLE001
        return False
    candidates = [
        normalize_question_key(control.get("context") or ""),
        normalize_question_key(control.get("text") or ""),
    ]
    for candidate in [item for item in candidates if item]:
        for key in skip_question_keys:
            if key and candidate == key:
                return True
    return False


def _trim_profile_provenance(raw_items: Any, *, limit: int, text_limit: int) -> list[dict[str, Any]]:
    if not isinstance(raw_items, list):
        return []
    items: list[dict[str, Any]] = []
    for raw in raw_items[: max(0, limit)]:
        if not isinstance(raw, dict):
            continue
        item: dict[str, Any] = {}
        for key, value in raw.items():
            item[key] = _safe_trim(value, text_limit) if isinstance(value, str) else value
        items.append(item)
    return items


def _trim_candidate_query_result(
    raw_result: Any,
    *,
    fact_limit: int,
    fact_text_limit: int,
) -> dict[str, Any] | None:
    """Bound one model-authored retrieval result without interpreting its facts."""

    if not isinstance(raw_result, dict):
        return None
    facts: list[dict[str, str]] = []
    for item in list(raw_result.get("facts") or [])[: max(0, fact_limit)]:
        if not isinstance(item, dict):
            continue
        evidence_contract = _closed_world_attestation_fact_contract(item)
        if _reserved_closed_world_attestation_fact(item) and not evidence_contract:
            continue
        value = _safe_trim(
            item.get("value"),
            _CLOSED_WORLD_ATTESTATION_VALUE_MAX_CHARS
            if evidence_contract
            else fact_text_limit,
        )
        if not value:
            continue
        fact = {
            "source": _normalize_grounding_source(item.get("source")),
            "label": _safe_trim(item.get("label"), 120),
            "value": value,
        }
        if evidence_contract:
            fact["evidence_contract"] = evidence_contract
        facts.append(fact)
    selected_labels = [
        _safe_trim(item, 120)
        for item in list(raw_result.get("selected_labels") or [])[: max(0, fact_limit)]
        if _safe_trim(item, 120)
    ]
    try:
        result_count = max(0, int(raw_result.get("result_count") or 0))
    except (TypeError, ValueError):
        result_count = len(facts)
    try:
        new_count = max(0, int(raw_result.get("new_count") or 0))
    except (TypeError, ValueError):
        new_count = 0
    try:
        more_count = max(0, int(raw_result.get("more_count") or 0))
        page = max(0, int(raw_result.get("page") or 0))
    except (TypeError, ValueError):
        more_count, page = 0, 0
    try:
        duplicate_attempt = max(1, int(raw_result.get("duplicate_attempt") or 1))
    except (TypeError, ValueError):
        duplicate_attempt = 1
    evidence_coverage = _candidate_query_evidence_coverage(raw_result)
    return {
        "query": _safe_trim(raw_result.get("query"), 500),
        "source_scope": _safe_trim(raw_result.get("source_scope"), 40),
        "result_count": result_count,
        **({"more_count": more_count} if more_count else {}),
        **({"page": page} if page else {}),
        "new_count": new_count,
        "selected_labels": selected_labels,
        "facts": facts,
        "replayed": bool(raw_result.get("replayed")),
        "duplicate_attempt": duplicate_attempt,
        "evidence_coverage": evidence_coverage,
    }


def _candidate_query_evidence_coverage(raw_result: Any) -> dict[str, Any] | None:
    """Build a bounded, runtime-authored receipt for one candidate-data lookup.

    The receipt reports what source families were enumerated and whether the semantic retriever
    selected a matching passage. This query surface is always bounded and never converts absence
    into a candidate fact. Verified closed-world attestations are positive evidence handled through
    their separate canonical evidence contract; no raw query-result boolean can promote a lookup to
    exhaustive coverage.
    """

    if not isinstance(raw_result, dict):
        return None
    existing_coverage = (
        raw_result.get("evidence_coverage")
        if isinstance(raw_result.get("evidence_coverage"), dict)
        else {}
    )
    coverage_input = {**existing_coverage, **raw_result}
    query = _safe_trim(coverage_input.get("query"), 500)
    requested_scope = _safe_trim(
        coverage_input.get("source_scope")
        or coverage_input.get("requested_scope"),
        40,
    )
    if not query or requested_scope not in {"all", "profile", "resume", "memory"}:
        return None
    searched_scopes = [
        scope
        for scope in ("profile", "resume", "memory")
        if scope
        in {
            str(item or "").strip().lower()
            for item in (
                coverage_input.get("searched_scopes")
                if isinstance(coverage_input.get("searched_scopes"), list)
                else []
            )
        }
    ]
    if not searched_scopes:
        searched_scopes = (
            ["profile", "resume", "memory"]
            if requested_scope == "all"
            else [requested_scope]
        )

    def _count(key: str) -> int:
        try:
            return max(0, int(coverage_input.get(key) or 0))
        except (TypeError, ValueError):
            return 0

    raw_source_counts = (
        coverage_input.get("source_entry_counts")
        if isinstance(coverage_input.get("source_entry_counts"), dict)
        else {}
    )
    source_entry_counts: dict[str, int] = {}
    for scope in searched_scopes:
        try:
            source_entry_counts[scope] = max(
                0, int(raw_source_counts.get(scope) or 0)
            )
        except (TypeError, ValueError):
            source_entry_counts[scope] = 0
    result_count = _count("result_count")
    retrieval_succeeded = coverage_input.get("retrieval_succeeded") is True
    coverage_without_hash = {
        "query": query,
        "requested_scope": requested_scope,
        "searched_scopes": searched_scopes,
        "source_entry_counts": source_entry_counts,
        "candidate_count": _count("candidate_count"),
        "eligible_candidate_count": _count("eligible_candidate_count"),
        "model_visible_candidate_count": _count("model_visible_candidate_count"),
        "result_count": result_count,
        "retrieval_succeeded": retrieval_succeeded,
        "bounded": True,
        "exhaustive": False,
        "matching_fact_found": result_count > 0,
        "absence_authorizes_mutation": False,
    }
    receipt_sha256 = hashlib.sha256(
        json.dumps(
            coverage_without_hash,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return {**coverage_without_hash, "receipt_sha256": receipt_sha256}


def _bounded_coverage_confirmation(
    action: dict[str, Any],
    latest_query_result: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Bind a model-requested confirmation to one successful zero-result coverage receipt.

    This is deliberately shape-only. The model owns whether the visible question is closed-world
    and which visible option it proposes. The runtime merely requires an exact option label, a
    successful non-exhaustive receipt, and an explicit human-confirmation flag. No browser mutation
    receives authority from this result.
    """

    if (
        str((action or {}).get("action") or "").strip().lower() != "ask_user"
        or (action or {}).get("confirmation_required") is not True
        or _safe_trim((action or {}).get("grounding_source"), 40)
        or _safe_trim((action or {}).get("grounding_quote"), 200)
    ):
        return None
    proposed_answer = _safe_trim((action or {}).get("proposed_answer"), 2000)
    options = [
        _safe_trim(option, 300)
        for option in ((action or {}).get("options") or [])
        if _safe_trim(option, 300)
    ]
    if not proposed_answer or not any(
        _normal_grounding_text(option) == _normal_grounding_text(proposed_answer)
        for option in options
    ):
        return None
    coverage = (
        (latest_query_result or {}).get("evidence_coverage")
        if isinstance((latest_query_result or {}).get("evidence_coverage"), dict)
        else _candidate_query_evidence_coverage(latest_query_result)
    )
    if not isinstance(coverage, dict):
        return None
    if (
        coverage.get("retrieval_succeeded") is not True
        or coverage.get("matching_fact_found") is not False
        or coverage.get("exhaustive") is True
        or not coverage.get("searched_scopes")
        or not _safe_trim(coverage.get("receipt_sha256"), 64)
    ):
        return None
    return dict(coverage)


def _bounded_coverage_display_reason(
    coverage: dict[str, Any],
    proposed_answer: str,
) -> str:
    scopes = [
        str(scope).replace("_", " ")
        for scope in (coverage.get("searched_scopes") or [])
        if str(scope).strip()
    ]
    scope_text = ", ".join(scopes) if scopes else "the authorized candidate sources"
    proposal = _safe_trim(proposed_answer, 160)
    return _safe_trim(
        f"I searched {scope_text} for this question and found no matching fact. "
        f"That absence is not proof, so please confirm whether I should use {proposal!r}.",
        500,
    )


def _vision_decision_context(context: dict[str, Any], *, payload_mode: str = "normal") -> dict[str, Any]:
    """Bound the per-step model packet without interpreting page semantics."""
    mode = payload_mode or "normal"
    budget = _VISION_REDUCED_CONTEXT_BUDGET if mode != "normal" else _VISION_NORMAL_CONTEXT_BUDGET
    trimmed = dict(context or {})

    if "resume_facts" in trimmed:
        resume_facts = dict(trimmed.get("resume_facts") or {})
        if resume_facts.get("resume_text") is not None:
            resume_facts["resume_text"] = _safe_trim(resume_facts.get("resume_text"), int(budget["resume_text"]))
        trimmed["resume_facts"] = resume_facts

    evidence = dict(trimmed.get("page_evidence") or {})
    if evidence:
        if evidence.get("viewport_text") is not None:
            evidence["viewport_text"] = _safe_trim(
                _viewport_text_without_repeated_head(
                    evidence.get("viewport_text"), evidence.get("viewport_text_previous"), 1200
                ),
                int(budget["viewport_text"]),
            )
        if "focused_text_lines" in evidence:
            from app.vision_agent import compact_focused_text_lines

            focused_lines = compact_focused_text_lines(
                evidence.get("focused_text_lines"),
                max_lines=int(budget["focused_text_lines"]),
                max_chars=int(budget["focused_text_chars"]),
            )
            if focused_lines:
                evidence["focused_text_lines"] = focused_lines
            else:
                evidence.pop("focused_text_lines", None)
        if "controls" in evidence:
            raw_observed_controls = evidence.get("controls")
            evidence["controls"] = _trim_observed_controls(
                raw_observed_controls,
                limit=int(budget["controls"]),
                text_limit=int(budget["control_text"]),
                viewport_height=evidence.get("viewport_height"),
                grow_to_on_screen=True,
            )
            off_screen_summary = _off_screen_controls_summary(
                raw_observed_controls,
                evidence["controls"],
                evidence.get("viewport_height"),
                evidence.get("off_screen_controls"),
            )
            evidence.pop("off_screen_controls", None)
            if off_screen_summary:
                evidence["controls_off_screen"] = off_screen_summary
        trimmed["page_evidence"] = evidence

    trimmed["page_memory"] = _trim_page_memory(
        _departed_page_memory(
            trimmed.get("page_memory"),
            (context or {}).get("page_evidence", {}).get("viewport_text")
            if isinstance((context or {}).get("page_evidence"), dict)
            else "",
        ),
        limit=int(budget["page_memory"]),
        text_limit=int(budget["page_memory_text"]),
    )
    if mode != "normal" and trimmed.get("web_results"):
        trimmed["web_results"] = [
            {**entry, "text": _safe_trim(entry.get("text"), _WEB_RESULT_OLDER_TEXT_CHARS)} if entry.get("text") else dict(entry)
            for entry in list(trimmed.get("web_results") or [])[-2:]
            if isinstance(entry, dict)
        ]
    trimmed["control_memory"] = _trim_control_memory(
        trimmed.get("control_memory"),
        limit=int(budget["control_memory"]),
        controls_limit=int(budget["control_memory_controls"]),
        text_limit=int(budget["control_text"]),
    )
    trimmed["recent_actions"] = list(trimmed.get("recent_actions") or [])[-int(budget["recent_actions"]) :]
    trimmed_constraints: list[dict[str, Any]] = []
    for item in list(trimmed.get("recovery_constraints") or [])[-4:]:
        if not isinstance(item, dict):
            continue
        rule = _normalized_recovery_constraint_rule(item.get("rule"))
        trimmed_constraints.append(
            {
                "constraint_id": _safe_trim(item.get("constraint_id"), 80),
                "action": _safe_trim(item.get("action"), 20),
                "control": _safe_trim(item.get("control"), 120),
                "progress_class": _safe_trim(item.get("progress_class"), 80),
                "rejection_count": max(0, int(item.get("rejection_count") or 0)),
                "rule": rule,
                "distinct_fingerprint_count": (
                    max(0, int(item.get("distinct_fingerprint_count") or 0))
                    if rule == _RECOVERY_CONSTRAINT_SCOPE_ACTION_KIND
                    else 0
                ),
                "withheld_until": (
                    "durable_progress_elsewhere"
                    if rule == _RECOVERY_CONSTRAINT_SCOPE_ACTION_KIND
                    else "durable_progress"
                ),
            }
        )
    trimmed["recovery_constraints"] = trimmed_constraints
    trimmed["session_ledger"] = _trim_session_ledger(
        trimmed.get("session_ledger"),
        limit=int(budget["session_ledger"]),
        text_limit=int(budget["session_ledger_text"]),
    )
    session_context_view = trimmed.get("session_context")
    if isinstance(session_context_view, dict) and session_context_view.get("summary"):
        trimmed["session_context"] = {
            **session_context_view,
            "summary": _safe_trim(
                session_context_view.get("summary"),
                int(budget["session_context_text"]),
            ),
        }
    elif "session_context" in trimmed:
        trimmed["session_context"] = {}
    trimmed["satisfied_controls"] = [
        {
            "control": _safe_trim(item.get("control"), int(budget["session_ledger_text"])),
            "value": _safe_trim(item.get("value"), int(budget["session_ledger_text"])),
            "source": _safe_trim(item.get("source"), 80),
        }
        for item in list(trimmed.get("satisfied_controls") or [])[-int(budget["session_ledger"]) :]
        if isinstance(item, dict) and _safe_trim(item.get("value"), int(budget["session_ledger_text"]))
    ]
    # The brain reads one line per receipt (receipt_view); the stored receipts keep every field for
    # approval and verification code.
    if trimmed.get("earlier_verified_receipts"):
        trimmed["earlier_verified_receipts"] = brain_receipts(
            trimmed.get("earlier_verified_receipts"), limit=12, detailed=0
        )
    trimmed["verified_receipts"] = brain_receipts(trimmed.get("verified_receipts"), limit=12)
    if "saved_answers" in trimmed:
        trimmed["saved_answers"] = _trim_answer_items(
            trimmed.get("saved_answers"),
            limit=int(budget["saved_answers"]),
            text_limit=int(budget["answer_text"]),
        )
    trimmed["human_answers"] = _trim_answer_items(
        trimmed.get("human_answers"),
        limit=int(budget["human_answers"]),
        text_limit=int(budget["answer_text"]),
    )
    trimmed["already_asked"] = [_safe_trim(item, 180) for item in list(trimmed.get("already_asked") or [])[-int(budget["already_asked"]) :]]
    if "profile_provenance" in trimmed:
        trimmed["profile_provenance"] = _trim_profile_provenance(
            trimmed.get("profile_provenance"),
            limit=int(budget["profile_provenance"]),
            text_limit=int(budget["profile_provenance_text"]),
        )
    trimmed["operator_instructions"] = [
        {
            "instruction": _safe_trim(item.get("instruction"), int(budget["operator_instruction_text"])),
            "source": _safe_trim(item.get("source"), 80),
        }
        for item in list(trimmed.get("operator_instructions") or [])[-int(budget["operator_instructions"]) :]
        if isinstance(item, dict) and _safe_trim(item.get("instruction"), int(budget["operator_instruction_text"]))
    ]
    trimmed_candidate_facts: list[dict[str, str]] = []
    candidate_facts = list(trimmed.get("retrieved_candidate_facts") or [])
    for item in candidate_facts[-int(budget["retrieved_candidate_facts"]) :]:
        if not isinstance(item, dict):
            continue
        evidence_contract = _closed_world_attestation_fact_contract(item)
        if _reserved_closed_world_attestation_fact(item) and not evidence_contract:
            continue
        value = _safe_trim(
            item.get("value"),
            _CLOSED_WORLD_ATTESTATION_VALUE_MAX_CHARS
            if evidence_contract
            else int(budget["retrieved_candidate_fact_text"]),
        )
        if not value:
            continue
        fact = {
            "source": _normalize_grounding_source(item.get("source")),
            "label": _safe_trim(item.get("label"), 120),
            "value": value,
        }
        if evidence_contract:
            fact["evidence_contract"] = evidence_contract
        trimmed_candidate_facts.append(fact)
    trimmed["retrieved_candidate_facts"] = trimmed_candidate_facts
    latest_candidate_query_result = _trim_candidate_query_result(
        trimmed.get("latest_candidate_query_result"),
        fact_limit=int(budget["retrieved_candidate_facts"]),
        fact_text_limit=int(budget["retrieved_candidate_fact_text"]),
    )
    if latest_candidate_query_result is None:
        trimmed.pop("latest_candidate_query_result", None)
    else:
        trimmed["latest_candidate_query_result"] = latest_candidate_query_result
    if mode == "normal":
        trimmed.pop("payload_mode", None)
    else:
        trimmed["payload_mode"] = mode
    return trimmed


def _classify_provider_transport_error(action: dict[str, Any] | None) -> str:
    """Return non_retryable | rate_limit | transient for a failed vision provider call."""
    if not isinstance(action, dict):
        return "transient"
    metadata = action.get("_model_metadata") if isinstance(action.get("_model_metadata"), dict) else {}
    text = " ".join(
        str(part or "")
        for part in (action.get("error"), metadata.get("error"), action.get("failure_reason"))
    ).casefold()
    statuses = {
        int(group)
        for match in _PROVIDER_STATUS_PATTERN.finditer(text)
        for group in match.groups()
        if group
    }
    for key in ("status_code", "http_status"):
        try:
            statuses.add(int(metadata.get(key)))
        except (TypeError, ValueError):
            pass
    if "timeout" in text or "timed out" in text:
        return "transient"
    if statuses & _PROVIDER_NON_RETRYABLE_STATUSES or any(m in text for m in _PROVIDER_NON_RETRYABLE_MARKERS):
        return "non_retryable"
    if 429 in statuses or any(m in text for m in _PROVIDER_RATE_LIMIT_MARKERS):
        return "rate_limit"
    return "transient"


def _vision_attempt_record(
    action: dict[str, Any] | None,
    *,
    attempt: int,
    payload_mode: str,
    timeout_seconds: int | float | None = None,
    outer_timeout_seconds: int | float | None = None,
    provider: Any = None,
) -> dict[str, Any]:
    metadata = (action or {}).get("_model_metadata") if isinstance(action, dict) else {}
    effective_timeout_seconds = metadata.get("timeout_seconds") if isinstance(metadata, dict) else None
    if effective_timeout_seconds is None:
        effective_timeout_seconds = timeout_seconds
    provider_id = getattr(provider, "id", None)
    provider_type = _safe_trim(getattr(provider, "provider_type", ""), 60)
    provider_model = _safe_trim(getattr(provider, "model_name", ""), 255)
    return {
        "attempt": attempt,
        "payload_mode": payload_mode,
        "outcome_type": _vision_outcome_type(action),
        "failure_reason": _vision_failure_reason(action),
        "provider": (
            metadata.get("provider")
            if isinstance(metadata, dict) and metadata.get("provider")
            else provider_type or None
        ),
        "provider_id": provider_id,
        "provider_type": provider_type or None,
        "model": (
            metadata.get("model")
            if isinstance(metadata, dict) and metadata.get("model")
            else provider_model or None
        ),
        "parse_status": metadata.get("parse_status") if isinstance(metadata, dict) else None,
        "raw_output_empty": metadata.get("raw_output_empty") if isinstance(metadata, dict) else None,
        "raw_output_chars": metadata.get("raw_output_chars") if isinstance(metadata, dict) else None,
        "finish_reason": metadata.get("finish_reason") if isinstance(metadata, dict) else None,
        "max_tokens": metadata.get("max_tokens") if isinstance(metadata, dict) else None,
        "timeout_seconds": effective_timeout_seconds,
        "outer_timeout_seconds": outer_timeout_seconds,
        "error": ((action or {}).get("error") or (metadata.get("error") if isinstance(metadata, dict) else "")) if isinstance(action, dict) else "",
    }


def _percentile_seconds(values: list[float], percentile: float) -> float:
    if not values:
        return 0.0
    ordered = sorted(float(value) for value in values if value >= 0)
    if not ordered:
        return 0.0
    if len(ordered) == 1:
        return round(ordered[0], 3)
    rank = (len(ordered) - 1) * percentile
    lower = int(rank)
    upper = min(lower + 1, len(ordered) - 1)
    fraction = rank - lower
    return round(ordered[lower] + ((ordered[upper] - ordered[lower]) * fraction), 3)


def _timing_summary_payload(
    *,
    totals_ms: dict[str, float],
    decision_latencies: list[float],
    waste_seconds: dict[str, float],
    steps: int,
    executed_actions: int,
) -> dict[str, Any]:
    return {
        "totals_ms": {key: int(round(value)) for key, value in totals_ms.items()},
        "totals_seconds": {key.replace("_ms", "_seconds"): round(float(value) / 1000.0, 3) for key, value in totals_ms.items()},
        "decision_latency_seconds": {
            "p50": _percentile_seconds(decision_latencies, 0.50),
            "p95": _percentile_seconds(decision_latencies, 0.95),
            "count": len(decision_latencies),
        },
        "waste_seconds": {key: round(float(value), 3) for key, value in waste_seconds.items()},
        "steps": int(steps),
        "executed_actions": int(executed_actions),
        "runtime_build": _VISION_RUNTIME_BUILD,
    }


def _timing_summary_text(summary: dict[str, Any] | None) -> str:
    if not isinstance(summary, dict):
        return ""
    totals = summary.get("totals_seconds") if isinstance(summary.get("totals_seconds"), dict) else {}
    decision = summary.get("decision_latency_seconds") if isinstance(summary.get("decision_latency_seconds"), dict) else {}
    waste = summary.get("waste_seconds") if isinstance(summary.get("waste_seconds"), dict) else {}
    decide = float(totals.get("decide_seconds") or 0)
    observe = float(totals.get("observe_seconds") or 0)
    act = float(totals.get("act_seconds") or 0)
    verify = float(totals.get("verify_seconds") or 0)
    judge = float(totals.get("judge_seconds") or 0)
    p50 = float(decision.get("p50") or 0)
    p95 = float(decision.get("p95") or 0)
    waste_total = sum(float(waste.get(key) or 0) for key in ("timeout_tax", "empty_tax", "rejection_tax"))
    return (
        f"Timing: decide {decide:.1f}s (p50 {p50:.1f}s, p95 {p95:.1f}s), "
        f"observe {observe:.1f}s, act {act:.1f}s, verify {verify:.1f}s, judges {judge:.1f}s, retry waste {waste_total:.1f}s."
    )


def _safe_trim(value: Any, limit: int) -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    return text[:limit]


_NON_TEXT_INPUT_TYPES = frozenset(
    {"button", "checkbox", "color", "file", "hidden", "image", "radio", "range", "reset", "submit"}
)


def _control_takes_typed_text(control: dict[str, Any]) -> bool:
    """A raw control that holds a caret for typed text (textarea, text-like input, textbox role)."""
    tag = _safe_trim(control.get("tag"), 24).lower()
    if tag == "textarea":
        return True
    if tag == "input":
        return _safe_trim(control.get("type"), 24).lower() not in _NON_TEXT_INPUT_TYPES
    return _safe_trim(control.get("role"), 24).lower() == "textbox"


def _alnum_text(value: Any) -> str:
    return "".join(char for char in str(value or "").casefold() if char.isalnum())


def _reopen_read_backs_the_page_lost(
    page_evidence: dict[str, Any] | None,
    ledger: dict[str, dict[str, Any]],
    satisfied: dict[str, dict[str, Any]],
    *,
    acted_since_step: int | None = None,
) -> list[str]:
    """Reopen remembered read-backs the current observation contradicts.

    satisfied_controls promise a match with the CURRENT read-back, and the ledger tells the brain not
    to redo a verified control; neither was ever re-checked. v2_form_crucible's step timer wipes the
    form in place (same document), and both kept claiming the wiped values. Bookkeeping only: a
    remembered control found once on screen now (same identity) whose raw state no longer shows the
    verified value -- a text field that is empty or holds something else, a radio/checkbox that is no
    longer checked -- goes back to pending. Off-screen, ambiguous, redacted and select controls are
    left alone. Returns the labels reopened.

    A control the agent itself acted on since the last check (`last_step` after `acted_since_step`) is not
    "lost": its changed state is that action's own effect (an unchecked filter, a toggled radio), which the
    action's receipt reports. Its stale read-back is cleared quietly and never announced as a loss.
    """
    controls = [item for item in ((page_evidence or {}).get("controls") or []) if isinstance(item, dict)]
    by_signature: dict[str, list[dict[str, Any]]] = {}
    by_selector: dict[str, list[dict[str, Any]]] = {}
    for control in controls:
        signature = _control_signature(control)
        if signature:
            by_signature.setdefault(signature, []).append(control)
        selector = _safe_control_selector(control.get("selector"))
        if selector:
            by_selector.setdefault(selector, []).append(control)

    def live_control(key: str) -> dict[str, Any] | None:
        found = by_signature.get(key) or by_selector.get(key) or []
        return found[0] if len(found) == 1 else None

    def contradicts(control: dict[str, Any], value: Any) -> bool:
        # A redacted or sensitive field reads "[REDACTED]", not its value: nothing to compare.
        if control.get("value_redacted") or _control_has_sensitive_value_structure(control):
            return False
        tag = _safe_trim(control.get("tag"), 24).lower()
        kind = _safe_trim(control.get("type"), 24).lower()
        if tag == "input" and kind in {"radio", "checkbox"}:
            return control.get("checked") is False
        if not _control_takes_typed_text(control):
            return False
        expected, current = _alnum_text(value), _alnum_text(control.get("value"))
        if not expected:
            return False
        return not current or not (expected.startswith(current) or current.startswith(expected))

    def acted_on(signature: str) -> bool:
        if acted_since_step is None:
            return False
        last = (ledger.get(signature) or {}).get("last_step")
        return isinstance(last, int) and last > acted_since_step

    reopened: list[str] = []
    for signature, entry in ledger.items():
        value = entry.get("verified_value") if isinstance(entry, dict) else None
        if value in (None, "", "[REDACTED]") or entry.get("value_redacted"):
            continue
        control = live_control(signature)
        if control is not None and contradicts(control, "" if value in {"checked", "choice committed"} else value):
            entry["verified_value"] = None
            entry["verified"] = False
            if acted_on(signature):
                continue
            entry["last_outcome"] = "read_back_lost"
            reopened.append(_safe_trim(entry.get("label") or "control", 80))
    for scope in list(satisfied):
        entry = satisfied.get(scope) or {}
        control = live_control(scope)
        if control is not None and contradicts(control, entry.get("value")):
            satisfied.pop(scope, None)
            if acted_on(scope):
                continue
            label = _safe_trim(entry.get("control") or "control", 80)
            if label not in reopened:
                reopened.append(label)
    return reopened


def _model_facing_verification(verification: Any) -> Any:
    """A receipt's verification block as the brain reads it. `progress_made` means durable workflow
    progress (a value read back, a page transition), so every scroll and most button clicks carry
    false; brains in the seat read that as "the action failed" (a scroll that did exactly what was
    asked). Same fact, named for what it is."""
    bounded = _bounded_strings(verification if isinstance(verification, dict) else {}, 240)
    if isinstance(bounded, dict) and "progress_made" in bounded:
        bounded = {("durable_progress" if key == "progress_made" else key): value for key, value in bounded.items()}
    if isinstance(bounded, dict) and bounded.get("status") == "succeeded":
        # Only verified_succeeded receipts reach the model; their outcome already says it.
        bounded = {key: value for key, value in bounded.items() if key != "status"}
    return _model_facing_receipt_part(bounded)


# Execution bookkeeping whose false value only says a branch was not taken (review: dropping every false
# value hid findings such as a redacted field's active_value_matches_expected=false).
_RECEIPT_BOOKKEEPING_FALSE = frozenset({
    "page_fallback",
    "browser_mutation_attempted",
    "execution_outcome_unknown",
    "scroll_attempted",
    "trusted_key_attempted",
    "focus_attempted",
})
_OPAQUE_DIGEST_RE = re.compile(r"[0-9a-f]{16,64}")
_DIGEST_KEY_RE = re.compile(r"signature|digest|hash|fingerprint")


def _model_facing_receipt_part(value: Any) -> Any:
    """What happened, without the body's bookkeeping: empty values, false flags of execution bookkeeping, and
    opaque digests under digest-named keys (surface signatures) tell a model nothing. Measured on 1,540 receipts from the brain
    seat, those were over a third of the receipts' characters, and receipts 29% of each step's prompt."""
    if isinstance(value, dict):
        out: dict[str, Any] = {}
        for key, item in value.items():
            item = _model_facing_receipt_part(item)
            if item is None or item == "" or item == [] or item == {}:
                continue
            if item is False and key in _RECEIPT_BOOKKEEPING_FALSE:
                continue
            if isinstance(item, str) and _DIGEST_KEY_RE.search(str(key)) and _OPAQUE_DIGEST_RE.fullmatch(item):
                continue
            out[key] = item
        return out
    if isinstance(value, list):
        return [_model_facing_receipt_part(item) for item in value]
    return value


def _bounded_strings(value: Any, limit: int) -> Any:
    """Bound every string inside a JSON-like value, keeping its keys and structure."""
    if isinstance(value, str):
        return value if len(value) <= limit else value[:limit] + "…"
    if isinstance(value, dict):
        return {key: _bounded_strings(item, limit) for key, item in value.items()}
    if isinstance(value, list):
        return [_bounded_strings(item, limit) for item in value]
    return value


def _secret_classifier_control_evidence(control: dict[str, Any] | None) -> dict[str, Any]:
    """Project raw control identity/context while excluding every browser value field."""

    raw = control if isinstance(control, dict) else {}
    safe: dict[str, Any] = {}
    text_keys = (
        "tag",
        "role",
        "type",
        "input_type",
        "autocomplete",
        "name",
        "label",
        "aria_label",
        "placeholder",
        "context_text",
        "nearby_text",
        "section_text",
    )
    for key in text_keys:
        value = _safe_trim(raw.get(key), 500)
        if value:
            safe[key] = value
    # Screenshot observations expose rendered/accessibility control text separately from the
    # current value. Keep that raw evidence only when it is structurally distinct from editable
    # content; otherwise an ordinary control can lose its only visible label before the model
    # classifies it. The model still interprets what the text means.
    raw_text = _safe_trim(raw.get("text"), 500)
    current_values = {
        _safe_trim(raw.get(key), 500)
        for key in (
            "value",
            "active_value",
            "text_value",
            "selected_value",
            "aria_value_text",
        )
        if _safe_trim(raw.get(key), 500)
    }
    if (
        raw_text
        and not bool(raw.get("contenteditable"))
        and raw_text not in current_values
    ):
        safe["text"] = raw_text
    for key in ("index", "required", "disabled", "readonly", "contenteditable", "value_redacted"):
        if key in raw:
            safe[key] = raw.get(key)
    safe["browser_value_present"] = bool(
        any(raw.get(key) not in (None, "", [], {}) for key in ("value", "active_value", "text_value", "selected_value"))
    )
    return safe


def _secret_classifier_page_evidence(
    page_evidence: dict[str, Any] | None,
    *,
    control: dict[str, Any] | None,
) -> dict[str, Any]:
    """Keep rendered context useful for semantics without forwarding control values or URL secrets."""

    raw = page_evidence if isinstance(page_evidence, dict) else {}
    controls = raw.get("controls") if isinstance(raw.get("controls"), list) else []
    value_fragments: list[str] = []
    for item in controls[:80]:
        if not isinstance(item, dict):
            continue
        for key in ("value", "active_value", "text_value", "selected_value", "aria_value_text"):
            value = str(item.get(key) or "")
            if len(value.strip()) >= 3:
                value_fragments.append(value)
        if bool(item.get("contenteditable")):
            editable_text = str(item.get("text") or "")
            if len(editable_text.strip()) >= 3:
                value_fragments.append(editable_text)

    viewport_text = _safe_trim(raw.get("viewport_text"), 1800)
    for value in sorted(set(value_fragments), key=len, reverse=True):
        viewport_text = viewport_text.replace(value, "[REDACTED_CONTROL_VALUE]")
    try:
        from app.security import redact_otp_codes

        viewport_text = str(redact_otp_codes(viewport_text))
    except Exception:
        # The semantic classifier still receives no explicit control values if OTP redaction is unavailable.
        pass

    raw_url = str(raw.get("url") or "")
    try:
        parsed = urlparse(raw_url)
        page_host = parsed.hostname or ""
    except Exception:
        page_host = ""
    return {
        "title": _safe_trim(raw.get("title"), 300),
        "host": _safe_trim(page_host, 255),
        "execution_surface": _safe_trim(raw.get("execution_surface"), 24) or "browser",
        "viewport_text": viewport_text,
        "control_count": len(controls),
        "exact_control": _secret_classifier_control_evidence(control),
    }


_ANSWER_MAX_CHARS = 500


_EDITABLE_CONTROL_MARKERS = frozenset(
    {"input", "textarea", "textbox", "searchbox", "combobox", "contenteditable", "text", "email", "password", "search", "tel", "url", "number"}
)


def _answer_page_texts(page_evidence: Any, page_memory: Any) -> list[str]:
    """Observed page text for checking an answer: what the page itself rendered. Controls that are
    editable (inputs, textareas, contenteditable) are left out, since their text may be the agent's own typing."""
    evidence = dict(page_evidence) if isinstance(page_evidence, dict) else {}
    controls = evidence.get("controls") if isinstance(evidence.get("controls"), list) else []
    evidence["controls"] = [
        item
        for item in controls
        if not (
            isinstance(item, dict)
            and (
                item.get("editable") is True
                or item.get("contenteditable") is True
                or any(str(item.get(key) or "").lower() in _EDITABLE_CONTROL_MARKERS for key in ("tag", "role", "type", "kind"))
            )
        )
    ]
    return _page_texts_seen_this_run(evidence, page_memory)


def _alnum(text: Any) -> str:
    return re.sub(r"[\W_]+", "", str(text or "")).casefold()


def _answer_matches_secret(text: str, secret_texts: list[str] | tuple[str, ...]) -> bool:
    """Whether a done answer carries a value typed into a sensitive field this run (the answer-withholding
    rule, shared by the user-facing answer line and message history). Matched on alphanumerics, whole-token for
    a short secret. `text` is the whitespace-normalized answer."""
    answer_alnum = _alnum(text)
    for secret in secret_texts:
        needle = _alnum(secret)
        if len(needle) < 3:
            continue
        # A short secret ("Q3h", "file") is only a leak as a whole token of the answer: as a bare substring it
        # turns up inside unrelated words (a 4-char password inside "EasyFileSecrets2024"). A long secret is
        # matched on alphanumerics alone, so spacing or dashes cannot smuggle it out.
        whole_token = re.search(
            r"(?<![a-z0-9])" + re.escape(" ".join(str(secret).split()).casefold()) + r"(?![a-z0-9])", text.casefold()
        )
        if whole_token or (len(needle) >= 8 and needle in answer_alnum) or (len(answer_alnum) >= 4 and answer_alnum in needle):
            return True
    return False


def _answer_final_line(
    answer: Any,
    page_texts: list[str],
    secret_texts: list[str],
    typed_texts: list[str] | None = None,
    goal: str = "",
    completion_verdict: str = "",
) -> str:
    """The user-facing `Answer: ...` line for a done that carries an answer; "" without one. The tag is
    computed here, never by the model, and never claims verification: `(found on the page; not independently
    verified)` only when the exact answer (whitespace-normalized, case-sensitive, whole-token) is in page text
    after the agent's own typed values and the goal's wording are blanked out; `(not found on the page)`
    otherwise; `(not verified)` when the completion check did not confirm the run. An answer matching a
    value typed into a sensitive field (alphanumerics only) or an OTP-like code is withheld."""
    text = " ".join(str(answer or "").split())[:_ANSWER_MAX_CHARS]
    if not text:
        return ""
    withheld = "Answer: [withheld: it contains a sensitive value entered during this run]"
    if _answer_matches_secret(text, secret_texts):
        return withheld
    if _redact_otp_text(text) != text:
        return withheld
    if completion_verdict in {"incomplete", "unverified", "unavailable"}:
        return f"Answer: {text} (not verified)"
    own = [
        " ".join(str(item).split())
        for item in [*(typed_texts or []), goal]
        if len(" ".join(str(item or "").split())) >= 1
    ]
    # Wholly the agent's own typed value or the goal's wording: not page evidence.
    if any(text == item for item in own):
        return f"Answer: {text} (not found on the page)"
    pattern = re.compile(r"(?<!\w)" + re.escape(text) + r"(?!\w)")
    found = False
    for page in page_texts:
        cleaned = " ".join(str(page).split())
        for item in sorted(own, key=len, reverse=True):
            if len(item) >= 3:
                cleaned = cleaned.replace(item, " ")
        if pattern.search(cleaned):
            found = True
            break
    tag = "(found on the page; not independently verified)" if found else "(not found on the page)"
    return f"Answer: {text} {tag}"


def _message_with_answer_line(message: str, summary: dict[str, Any]) -> str:
    answer_line = str((summary or {}).get("answer_line") or "").strip()
    return f"{message.rstrip()} {answer_line}" if answer_line else message


def _local_time_line(now: float | None = None) -> str:
    """Local date, weekday, zone and UTC offset plus the UTC clock, e.g.
    `2026-10-07 Wed 03:52 EDT (UTC-4) / 07:52Z`."""
    moment = time.localtime(now)
    offset_seconds = -(time.altzone if moment.tm_isdst > 0 and time.daylight else time.timezone)
    sign = "+" if offset_seconds >= 0 else "-"
    hours, rem = divmod(abs(offset_seconds), 3600)
    minutes = rem // 60
    offset = f"UTC{sign}{hours}" + (f":{minutes:02d}" if minutes else "")
    zone = time.strftime("%Z", moment)
    if " " in zone:  # Windows spells the zone out ("Eastern Daylight Time"): use its initials
        zone = "".join(word[0] for word in zone.split()).upper()
    return (
        time.strftime("%Y-%m-%d %a %H:%M", moment)
        + f" {zone} ({offset}) / "
        + time.strftime("%H:%M", time.gmtime(now))
        + "Z"
    )


def _page_texts_seen_this_run(page_evidence: Any, page_memory: Any) -> list[str]:
    """Rendered text the agent has actually seen this run: current viewport text, visible control
    text, and the retained prior-page memory."""
    texts: list[str] = []
    evidence = page_evidence if isinstance(page_evidence, dict) else {}
    if evidence.get("viewport_text"):
        texts.append(str(evidence.get("viewport_text")))
    controls = evidence.get("controls") if isinstance(evidence.get("controls"), list) else []
    for item in controls[:120]:
        if isinstance(item, dict):
            for key in ("text", "label", "nearby_text", "section_heading"):
                if item.get(key):
                    texts.append(str(item.get(key)))
    for entry in (page_memory if isinstance(page_memory, list) else []):
        if isinstance(entry, dict) and entry.get("text"):
            texts.append(str(entry.get("text")))
    return texts

def _url_host(url: Any) -> str:
    try:
        return (urlparse(str(url or "")).hostname or "").lower()
    except Exception:  # noqa: BLE001
        return ""


def _page_text_sources_seen_this_run(page_evidence: Any, page_memory: Any, current_url: Any) -> list[tuple[str, str]]:
    """(host, text) for the current page and every retained earlier page of this run."""
    sources: list[tuple[str, str]] = []
    evidence = page_evidence if isinstance(page_evidence, dict) else {}
    if evidence.get("viewport_text"):
        sources.append((_url_host(current_url), str(evidence.get("viewport_text"))))
    for entry in (page_memory if isinstance(page_memory, list) else []):
        if isinstance(entry, dict) and entry.get("text"):
            sources.append((_url_host(entry.get("url")), str(entry.get("text"))))
    return sources


_USER_SOURCE_CONTEXT_KEYS = (
    "human_answers",
    "operator_instructions",
    "retrieved_candidate_facts",
    "latest_candidate_query_result",
    "profile",
    "resume_facts",
    "saved_answers",
)


def _user_source_texts(goal_text: Any, context: Any) -> list[str]:
    """Every string the user or their stored data supplied to this step (goal, answers,
    instructions, retrieved facts, profile, resume, saved answers) - never page content."""
    texts: list[str] = [str(goal_text or "")]

    def _walk(value: Any, depth: int = 0) -> None:
        if depth > 6 or len(texts) > 400:
            return
        if isinstance(value, str):
            if value.strip():
                texts.append(value)
        elif isinstance(value, dict):
            for item in value.values():
                _walk(item, depth + 1)
        elif isinstance(value, (list, tuple)):
            for item in value:
                _walk(item, depth + 1)

    if isinstance(context, dict):
        for key in _USER_SOURCE_CONTEXT_KEYS:
            _walk(context.get(key))
    return texts


def _shares_user_source_run(text: Any, user_source_texts: Any, *, run_length: int = 4) -> bool:
    """Whether any run of run_length+ letters/digits in text also occurs in a user-supplied source
    (value-free: only the boolean leaves this function)."""
    compact = re.sub(r"[\W_]+", "", str(text or "").casefold())
    if len(compact) < run_length:
        return bool(compact) and any(
            compact in re.sub(r"[\W_]+", "", str(source or "").casefold())
            for source in (user_source_texts or [])
        )
    sources = [re.sub(r"[\W_]+", "", str(source or "").casefold()) for source in (user_source_texts or [])]
    for start in range(0, len(compact) - run_length + 1):
        window = compact[start:start + run_length]
        if any(window in source for source in sources if source):
            return True
    return False


def _typed_text_composed_of_page_tokens(typed: Any, page_text: Any) -> bool:
    """Whether every letter/digit run (single characters included) of the typed text is a whole run of
    the page text, any letter case: a folder path the page names joined with a filename it names.

    Token-bounded: each run must equal one of the page's own runs, never sit inside a longer one, so a
    page cannot cover an arbitrary short code by showing a long digit string that happens to contain
    it. Value-free: only the boolean leaves this function."""
    tokens = re.findall(r"[^\W_]+", str(typed or ""))
    if not tokens or all(len(token) == 1 for token in tokens):
        # Lone characters appear on almost any page (step counters, dates): no proof of anything.
        return False
    page_tokens = {token.casefold() for token in re.findall(r"[^\W_]+", str(page_text or ""))}
    return all(token.casefold() in page_tokens for token in tokens)


def _typed_text_composition_windows(
    typed: Any, page_text: Any, window_lines: list[tuple[str, list[str]]]
) -> list[str] | None:
    """Whether the typed text is composed only of whole letter/digit runs this run saw on the task page's
    current screen or in native windows' own pixels; None when not, else the titles of EVERY window that
    shows any of its runs (empty: the page alone). Never for a code: it needs a letter run of 3+
    characters, and a digit-only run must come from the page alone (a window showing it refuses the
    claim, so a code reshaped from an authenticator keeps the unseen path). Token-bounded like
    _typed_text_composed_of_page_tokens. Value-free: only window titles leave it."""
    tokens = [token.casefold() for token in re.findall(r"[^\W_]+", str(typed or ""))]
    if not any(len(token) >= 3 and not token.isdigit() for token in tokens):
        return None
    page_tokens = {token.casefold() for token in re.findall(r"[^\W_]+", str(page_text or ""))}
    window_tokens = [
        (title, {token.casefold() for line in lines for token in re.findall(r"[^\W_]+", str(line or ""))})
        for title, lines in window_lines
    ]
    windows: list[str] = []
    for token in tokens:
        sources = [title for title, seen in window_tokens if token in seen]
        if sources and token.isdigit() and len(token) > 1:
            return None
        if not sources and token not in page_tokens:
            return None
        for title in sources:
            if title not in windows:
                windows.append(title)
    return windows


def _secret_classifier_action_evidence(
    action: dict[str, Any] | None,
    *,
    goal_text: str = "",
    page_texts: Any = (),
    page_text_sources: Any = (),
    current_url: Any = "",
    user_source_texts: Any = None,
) -> dict[str, Any]:
    """Describe an imminent ask/type without forwarding the proposed answer or typed value."""

    raw = action if isinstance(action, dict) else {}
    kind = str(raw.get("action") or "").strip().lower()
    typed_text = str(raw.get("text") or "")
    evidence: dict[str, Any] = {
        "action": kind,
        "control": _action_control_index(raw),
        "text_present": bool(str(raw.get("text") or "")),
        "text_length": len(str(raw.get("text") or "")),
        "proposed_answer_present": bool(str(raw.get("proposed_answer") or "")),
        "proposed_answer_length": len(str(raw.get("proposed_answer") or "")),
        "option_count": len(raw.get("options") or []) if isinstance(raw.get("options"), list) else 0,
        "grounding_source": _safe_trim(raw.get("grounding_source"), 40),
    }
    # Value-free provenance: whether the proposed typed text is copied verbatim from the
    # user's own written task instruction. The judge never receives the text itself, so
    # this is the only way it can distinguish user-dictated content from vault or
    # generated material on a free-text surface.
    if typed_text and goal_text:
        # A whole-token occurrence of 3+ characters: a lone digit "occurs" in any goal that names a
        # URL (v5_switchboard run 1739: a Billing count of one digit read as dictated by the user).
        goal_needle = " ".join(typed_text.split()).casefold()
        evidence["typed_text_verbatim_from_user_goal"] = bool(
            len(goal_needle) >= 3
            and re.search(
                r"(?<![^\W_])" + re.escape(goal_needle) + r"(?![^\W_])",
                " ".join(goal_text.split()).casefold(),
            )
        )
    if typed_text.strip():
        # Value-free shape of the typed text (never the text): a one- or two-digit number cannot be a
        # credential, code, or card number, and a Billing count must not read as one (run 1739).
        stripped = typed_text.strip()
        evidence["text_character_classes"] = (
            "digits only"
            if stripped.isdigit()
            else "letters only"
            if all(character.isalpha() or character.isspace() for character in stripped)
            else "letters and digits"
            if all(character.isalnum() or character.isspace() for character in stripped)
            else "letters, digits, and symbols"
        )
    # Value-free provenance, page side: the proposed text is copied verbatim from what the page
    # itself rendered during this run (a displayed PIN, reference code, or instruction). Typing
    # page-provided text back into the page discloses nothing the page did not already show.
    if typed_text:
        needle = " ".join(typed_text.split()).casefold()
        haystacks = [
            " ".join(str(item or "").split()).casefold()
            for item in (page_texts if isinstance(page_texts, (list, tuple)) else [])
        ]
        evidence["typed_text_verbatim_from_page"] = bool(
            needle and len(needle) >= 3 and any(needle in hay for hay in haystacks if hay)
        )
        # Where it was shown, so the judge can tell a same-site relay (a code read on one of the
        # site's own pages) from carrying one site's code into another site.
        if needle and isinstance(page_text_sources, (list, tuple)):
            # A 1-2 character text occurs in almost any page by chance; only longer texts are
            # located, while the hosts themselves never depend on the text.
            if len(needle) >= 3:
                evidence["typed_text_page_hosts"] = sorted(
                    {
                        host
                        for host, text in page_text_sources
                        if host and needle in " ".join(str(text or "").split()).casefold()
                    }
                )[:6]
            evidence["current_page_host"] = _url_host(current_url)
            evidence["run_visited_hosts"] = sorted(
                {host for host, _text in page_text_sources if host} | ({_url_host(current_url)} - {""})
            )[:6]
        # Value-free: whether the text appears anywhere the user or their stored data supplied it.
        # When it does not, and the run never left this host, it can only have been read off this
        # page (painted pixels, an image, a zoomed region) or composed by the agent (a computed
        # total, a written reply).
        if needle and isinstance(user_source_texts, (list, tuple)):
            evidence["typed_text_in_user_sources"] = any(
                needle in " ".join(str(text or "").split()).casefold()
                for text in user_source_texts
                if text
            )
    # An ask has no candidate answer yet, so its question is the minimum semantic evidence needed
    # for task-level clarifications that are not attached to a browser control.
    if kind == "ask_user":
        evidence["question"] = _safe_trim(raw.get("question"), 600)
    return evidence


